-- ============================================================
-- Ereb4a (1/3): Günə-özəl push bildirişlərinin AR tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d'::uuid, 'رحلة جديدة تبدأ! 🚀', 'يستعد جسمكِ لاحتضان معجزة عظيمة. هل أنتِ مستعدة؟'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'هل نسيتِ الفيتامينات؟ 💊', 'حمض الفوليك هو الآن أقرب صديق لكِ. ألقي نظرة على قسم التغذية لبناء أساس صحي لطفلكِ المستقبلي!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'كيف تشعرين اليوم؟ 🌈', 'قد تتغير مشاعركِ مع بداية هذه المرحلة الجديدة. دوّني مشاعركِ اليوم في مفكرة المزاج وتابعي حالتكِ.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'لا يزال مجهريًا في الوقت الحالي 🔬', 'تبدأ القصص العظيمة بجسيمات صغيرة. طفلكِ المستقبلي الآن أشبه بفكرة فحسب، لكن إمكاناته لا حدود لها!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'حان وقت التخلص من السموم! 🚫', 'التدخين أو المشروبات الكحولية أو الإفراط في الكافيين؟ حان الوقت تمامًا لتوديعها. أم بصحة جيدة = بداية صحية.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'هل زجاجة الماء بجانبكِ؟ 💧', 'الحفاظ على ترطيب جسمكِ الآن مهم أكثر من أي وقت مضى. لا تنسي شرب كمية الماء اليومية الموصى بها.'),
  ('1466cb19-fd27-4f75-a79c-d709e1623239', 'بحجم بذرة الخشخاش 🌱', 'بدأ طفلكِ يستقر في رحمكِ. وعلى الرغم من صغر حجمه، فإن قلبه بدأ بالتكوّن.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'حزمة الحمض النووي جاهزة! 🧬', 'لقد تحددت الشفرة الجينية للون عيني طفلكِ وشعره وجنسه. برأيكِ، بمن سيشبه؟'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'متعة التوت 🍓', 'توت العليق أم الفراولة؟ هذه الفواكه الغنية بمضادات الأكسدة ستعزز مناعتكِ.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'ثورة هادئة تحدث الآن 🤫', 'تنغرس البويضة المخصبة في رحمكِ. ورغم أنكِ لا تشعرين بذلك، فإن عملية مذهلة تجري الآن.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'الكالسيوم للعظام 🥛', 'حليب أم زبادي أم جبن؟ احرصي اليوم على تناول أحد منتجات الألبان لبناء الهيكل العظمي المستقبلي لطفلكِ.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'هل تشعرين بالإرهاق؟ هناك سبب لذلك 🥱', 'يرتفع مستوى هرمون البروجستيرون. إذا كان السرير يناديكِ، فلا ترفضي، بل استريحي!'),
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4', 'حان وقت الجوز واللوز 🥜', 'اختاري المكسرات بدلًا من رقائق البطاطس كوجبة خفيفة. فأوميغا 3 ضرورية لكِ ولطفلكِ المستقبلي.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'خصصي وقتًا لنفسكِ 💆‍♀️', 'لنطرد هرمونات التوتر! شاهدي اليوم فيلمًا تحبينه أو خذي حمّامًا دافئًا.'),
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3', 'أصغر بداية 🫧', 'لا يمكن رؤيته بالعين بعد. طفلكِ المستقبلي مجرد خلية واحدة، لكن لديه خطط كبيرة!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'هل حانت اللحظة السحرية؟ ✨', 'يحدث الإخصاب عادةً خلال هذه الأيام. ورغم أنكِ قد لا تشعرين به، فقد بدأت هذه العملية المذهلة.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'جرعة غنية بالبروتين 🍳', 'هل يتضمن فطوركِ البيض؟ البروتين ضروري لتجدد الخلايا. بالهناء والشفاء!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'هل نخرج للمشي؟ 👟', 'سيساعد الهواء النقي على تحسين مزاجكِ. اطلعي على برنامج المشي الخفيف في قسم التمارين.'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'هل نسيتِ الفيتامين؟ 😬', 'حمض الفوليك هو أساس عمودي الفقري المستقبلي! تحققي من مُذكِّر الأدوية، هل تناولتِ جرعة اليوم؟ ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'هل التبقّع الدموي طبيعي؟ 🩸', 'لا تقلقي، فقد يكون هذا نزيف الانغراس. إذا ساورتكِ الشكوك، فراجعي قسم الأطباء.'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'هل أنتِ سيدة حديدية؟ 🥩', 'سيزداد حجم دمكِ. تناولي اللحوم الحمراء أو العدس، وقولي لا لفقر الدم.'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'انتظار بلهفة... 🧘‍♀️', 'يقترب موعد الدورة الشهرية. استمعي إلى قسم الضوضاء البيضاء لتخفيف التوتر.'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'هل تحققتِ من التقويم؟ 🗓️', 'إذا تأخرت الدورة الشهرية، فربما حان وقت إجراء الاختبار؟ شاركينا الخبر السعيد!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'بحجم حبة سمسم! 🌱', 'يُسمّى الآن رسميًا جنينًا. إنه ينمو بسرعة، وأنتِ أيضًا تتغيرين.'),
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be', 'خططي للمستقبل 💭', 'ألا ترغبين في تحميل أول صورة «للبداية» إلى ألبوم الحمل؟'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'نضع الأساس 🏗️', 'يستعد جسمكِ لمعجزة جديدة، وتوشك الدورة الشهرية على الانتهاء. ويُعدّ مخزون حمض الفوليك (B9) ضروريًا لوضع أساس صحي لطفلكِ المستقبلي. هل اطّلعتِ على قائمة الأطعمة الغنية به في قسم التغذية؟ 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'النوم نعمة لذيذة 😴', 'تحتاجين إلى استعادة طاقتكِ. حاولي النوم 8 ساعات على الأقل يوميًا قبل أن تبدأ الليالي الخالية من النوم.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'فعّلي قوة الخضراوات! 🥦', 'السبانخ والبروكلي ليسا مجرد خضراوات، بل هما كنز طبيعي من الفيتامينات. احرصي اليوم على إضافة الخضراوات إلى قائمة طعامكِ.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'هل اخترتِ طبيبتكِ؟ 👩‍⚕️', 'ابدئي من الآن بالبحث عن الاختصاصية التي ستثقين بها. يمكنكِ الاطلاع على التقييمات في قسم الأطباء والعيادات لاتخاذ قراركِ النهائي.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'هل يرسل جسمكِ إشارات؟ 🌡️', 'تقترب فترة الإباضة. راقبي درجة حرارة جسمكِ، فهذه هي الأيام التي تكون فيها فرصكِ في الحمل في أعلى مستوياتها!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'معجزة ماء الليمون 🍋', 'يخفف الغثيان ويساعد على تنقية الجسم. قد يسبب الجفاف الصداع.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'هل تنفد بطاريتكِ؟ 🔋', 'قد تنفد طاقتكِ سريعًا. ستفيدكِ قيلولة قصيرة بعد الظهر كثيرًا.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'أحتاج إلى حوض سباحة! 🏊‍♀️', 'أنتِ من تصنعين الماء الذي أسبح فيه (السائل الأمنيوسي)، ماما. افتحي متتبّع الماء. هل شربتِ كوبًا من الماء؟ ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'أفعوانية المشاعر 🎢', 'تضحكين ثم تبكين... الهرمونات لم تفقدكِ صوابكِ، بل إنها تؤدي عملها فحسب.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'هل أنتِ حساسة تجاه الروائح؟ 👃', 'لا تجبري نفسكِ على تناول الأطعمة التي لا تحبينها. راجعي قسم التغذية لمعرفة البدائل.'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'الدماغ ينمو! 🧠', 'ينغلق الأنبوب العصبي. لا تتوقفي عن تناول حمض الفوليك، فالآن توضع أسس عبقري المستقبل!'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'شاي الزنجبيل للإنقاذ! 🍵', 'هل لا يزال الغثيان مستمرًا؟ يساعد الزنجبيل على تهدئة المعدة. ستجدين وصفات في قسم التغذية.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'هل بلغ التعب ذروته؟ 😴', 'يعمل جسمكِ كمصنع للطاقة. القيلولة القصيرة ظهرًا حقٌّ لكِ كأم!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'حبّة بازلاء صغيرة ولطيفة 🟢', 'يبلغ حجمه نحو 6 mm. تبدأ ذراعاه وساقاه بالظهور كبراعم صغيرة. يا له من سبّاح صغير!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'مثل سيارة سباق! 🏎️', 'ينبض قلبه من 100 إلى 160 مرة في الدقيقة، أي أسرع من قلبكِ بمرتين! سيبدو لكِ هذا الصوت كالموسيقى.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'حافظي على مستوى سكر الدم! 📉', 'يزداد الغثيان عندما تكون المعدة فارغة. احتفظي دائمًا في حقيبتكِ ببعض البسكويت المملح أو الفواكه المجففة.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'ماراثون الذهاب إلى الحمّام؟ 🚻', 'كثرة التبوّل أمر طبيعي، فكليتاكِ تعملان بجهد أكبر. لكن لا تقلّلي شرب الماء، بل زيديه!'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'هل تشعرين بالغثيان؟ 🤢', 'هل تعانين في الصباح؟ قد يساعدكِ شاي الزنجبيل أو الماء بالليمون. لا تتركي معدتكِ فارغة.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'أعمال بناء مهمة جارية! 🚧', 'يتشكّل الدماغ والعمود الفقري. واصلي تناول حمض الفوليك!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'هل تعانين من غثيان الصباح؟ 🤢', 'تناولي بسكويتًا مالحًا قبل النهوض من السرير. تناولي كميات صغيرة على فترات متقاربة للحفاظ على استقرار مستوى السكر في الدم.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'نبضة تلو الأخرى... هل تسمعين؟ 💓', 'بدأ قلبي ينبض! هل تتشوقين لسماع صوت هذا المحرك الصغير؟ دوّني موعد أول فحص بالموجات فوق الصوتية في التقويم! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'حان وقت التأكيد الرسمي! ✅', 'إذا لم تكوني قد ذهبتِ بعد، فاحجزي موعدًا مع الطبيب. ابحثي عن الطبيب المناسب لكِ في قسم الأطباء.'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'نبضات القلب الأولى 💓', 'رغم أنكِ لا تسمعينها، فقد بدأ ذلك القلب الصغير بالنبض بالفعل. إنه ينبض أكثر من 100 مرة في الدقيقة!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'هل تشعرين بالغثيان؟ آسف! 🥺', 'الهرمونات تقيم حفلة، وأنا السبب. هل أزعجكِ؟ ما رأيكِ أن نتناول بعض البسكويت المملح؟ 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'ملامح وجهه تتشكّل 👀', 'تتكوّن عيناه وأنفه وأذناه. تبدو الآن كنقاط سوداء، لكن ملامح وجهه بدأت ترتسم.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'أين يوجد فيتامين B6؟ 🍌', 'في الموز أو الأفوكادو أو لحم الدجاج... قد يساعد هذا الفيتامين على تخفيف الغثيان.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'حفلة رقص سرية! 💃', 'رغم أنكِ لا تشعرين به، فقد بدأ يتحرك بالفعل. حركاته الأولى تشبه مجرد ارتعاشات بسيطة.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'مخللات أم شوكولاتة؟ 🥒', 'الرغبة في أطعمة غريبة أمر طبيعي، لكن انتبهي إلى كمية السكر! توجد بدائل صحية يمكنكِ إدراجها في نظامكِ الغذائي.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'هل أصبح سروالكِ ضيقًا؟ 👖', 'هل سجّلتِ وزنكِ في بداية الحمل في متتبّع الوزن؟ 📈'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'كأنكِ مراهقة؟ 😳', 'قد تظهر بعض البثور على وجهكِ. إنها الهرمونات! حافظي على نظافة بشرتكِ ولا تستخدمي أي دواء من تلقاء نفسكِ.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'هل التقطتِ صورتنا الأولى؟ 🤰', 'حمّلي أول صورة لبطن حملكِ إلى معرض الصور! ✨'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'هل تعانين من الإمساك؟ 🚽', 'الماء الوفير والأطعمة الغنية بالألياف حليفان لكِ. قد يصنع الكيوي والمشمش المجفف العجائب.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'هل أضغط عليكِ؟ آسف!', 'حتى إن لم يزد وزنكِ، فأنا أوسّع منزلي. هيا نخلع ذلك البنطال الضيق ونرتدي شيئًا مريحًا. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'المخللات أم الشوكولاتة؟ 🍫', 'ألقي نظرة على قسم التغذية، ما الأطعمة المفيدة في قائمة اليوم؟ 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'بدأت حاسة التذوق تتكوّن 👅', 'تتكوّن براعم التذوق على لسان طفلكِ، وسيتمكن أيضًا من تذوّق نكهات الأطعمة التي تتناولينها.'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'هل قلّلتِ الكافيين؟ ☕', 'لا تتناولي أكثر من فنجان واحد يوميًا. جرّبي الشاي منزوع الكافيين أو شاي الأعشاب.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'أنا أرقص! 🕺', 'تنثني ذراعا طفلكِ وساقاه. إنه يؤدي حركات بهلوانية في رحمكِ، لكنكِ لا تشعرين بها بعد.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'حساء الخضروات؟ 🥣', 'إذا كانت معدتكِ لا تتقبل الأطعمة الثقيلة، فتناولي حساءً خفيفًا. فهو يمدكِ بالفيتامينات والسوائل معًا!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'حان وقت الحركة 🧘‍♀️', 'هل ترغبين في الحركة؟ لنرَ التمارين المناسبة لكِ في قسم التمارين.'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'أشركي الأب أيضًا 🗣️', 'هذه ليست مغامرتكِ وحدكِ. شاهدا معًا أول صورة بالموجات فوق الصوتية وتحدثا عن خططكما المستقبلية.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'لثتي لا تحكّني... ليس بعد! 😬', 'الحليب والزبادي والجبن... هل أدرجتِ هذه الأطعمة في قائمة غذائكِ اليوم؟ 🥛'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'لا تدعي الكالسيوم ينقص 🥛', 'تتكوّن براعم الأسنان. الجبن القريش أو الجبن أو الزبادي... كلها ضرورية لابتسامة طفلكِ المستقبلية!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'هل يؤلمكِ رأسكِ؟ 🤕', 'لا تتسرعي في تناول الدواء. قد تساعدكِ غرفة مظلمة أو كمادة باردة أو جلسة تدليك بشكل أفضل.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'دورتكِ الدموية في أوج نشاطها! 🌊', 'يزداد حجم الدم في أوعيتكِ، ويعمل قلبكِ بوتيرة أسرع. الماء ضروري للحفاظ على توازن هذا النظام. لا تنسي شرب الماء لتجنب الدوار! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'أعمال البناء جارية! 🏗️', 'يحتاج طفلكِ إلى الكالسيوم! اطّلعي على منتجات الألبان في قسم التغذية. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'يوم السمك! 🐟', 'اختاري سمكًا منخفض الزئبق. فأوميغا-3 ضروري لنمو الدماغ.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'قولي لا لعلامات التمدد! 🧴', 'رطّبي بشرتكِ حتى لو لم يظهر بطنكِ بعد. يساعد زيت اللوز أو جوز الهند أيضًا على تخفيف الحكة.'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'هل تنفرين من رائحة اللحم؟ 🥩', 'أنتِ بحاجة إلى البروتين! إذا لم تستطيعي تناول اللحم، فاستبدليه بالعدس أو الحمص أو المكسرات.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'هل أصبحت حمالة صدركِ ضيقة؟ 👙', 'ثدياكِ يكبران ويصبحان أكثر حساسية. حان الوقت لاختيار حمالة صدر مريحة ورياضية ومن دون أسلاك.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'جسمكِ يحتاج إلى الماء! 💧', 'قد يسبب الجفاف الصداع. افتحي متتبّع المياه واشربي كوبًا من الماء! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'لقد أصبحت ملامحه بشرية! 👶', 'وماذا عن توهّج الحمل الشهير على وجهكِ؟ ✨ خلّدي هذا الجمال في المعرض!'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'دفعة قوية من فيتامين C 🍊', 'البرتقال أو الكيوي أو الفلفل... حافظي على مناعتكِ قوية كالحديد، فلا مجال للمرض!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'بدأت الكليتان العمل! 🚽', 'أمر مذهل، لكنه أصبح يتبوّل بالفعل. يبتلع السائل الأمنيوسي ثم يطرحه. لقد بدأت الدورة!'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'أصبح بحجم ثمرة جريب فروت! 🍊', 'قد يزداد محيط خصركِ. هل تغيّرت الأرقام؟ سجّليها في متتبّع الوزن! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'هل حان موعد الفحص المزدوج؟ 🗓️', 'الفترة بين الأسبوعين 11-14 مهمة. تحدّثي مع طبيبكِ للتحقق من خطر الإصابة بمتلازمة داون.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'هل أنتِ جائعة أم عطشى؟ 🤔', 'أحيانًا يخلط الدماغ بين الجوع والعطش. اشربي أولًا كوبًا من الماء، وإذا ظللتِ جائعة، فقد حان وقت تناول الطعام.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'حان وقت الجمباز! 🤸', 'أصبح طفلكِ الآن يقبض يديه ويفتح فمه. قد لا تشعرين بذلك، لكن الأولمبياد قائم في الداخل!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'طفل ذكي في الطريق! 🧠', 'اليود ضروري لنمو الدماغ. هل يحتوي نظامكِ الغذائي على الملح المُيودَن أو السمك أو منتجات الألبان؟'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'أنا أتمطّى! 🤸', 'لا تبقي ساكنة أنتِ أيضًا، ماما. هل نلقي نظرة على حركات اليوغا الخفيفة في قسم التمارين؟'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'هل حان وقت الكشف عن السر؟ 📢', 'أوشك الثلث الأول على الانتهاء، وقد انخفضت المخاطر. هل أنتِ مستعدة لمشاركة الخبر السعيد مع أصدقائكِ؟'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'الهيكل العظمي يزداد صلابة! 🦴', 'تتحول الغضاريف اللينة إلى عظام. احرصي على الحصول على ما يكفي من الكالسيوم ليصبح صغيركِ قويًا!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'أنتِ تصنعين محيطًا! 🌊', 'يتجدد السائل الأمنيوسي. لا تنسي شرب الكثير من الماء ليستمتع طفلكِ بالسباحة في حوض نظيف.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'هل تشعرين بحكة في بطنكِ؟ 🌵', 'الحكة أمر طبيعي مع تمدد الجلد. ضعي زيت اللوز أو كريمًا مخصصًا لتشعري بالراحة.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'هل عادت طاقتكِ؟ 🔋', 'كيف تشعرين اليوم؟ دوّني ذلك في مفكرة الأعراض! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'سأناديكِ ماما... 🥺', 'تتكوّن أحبالي الصوتية. أنا صامت الآن، لكن هل تتخيلين اليوم الذي سأناديكِ فيه لأول مرة؟ أنا أتخيله...'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'الأطعمة الغنية بالألياف بطلة 🌾', 'لتحسين الهضم، اختاري الشوفان والخضراوات والفواكه. ستجدين سلطات لذيذة في قسم التغذية.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'هل ترفعين الأثقال؟ 🏋️‍♀️', 'بدأ طفلكِ بالفعل بتكوين طبقة من الدهون، ويزداد هيكله العظمي صلابة. إننا نكتسب الوزن بسرعة!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'تسارع تدفق المغذيات!', 'ما الطعام الصحي الذي تناولتِه اليوم؟ راجعي قائمة التغذية! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'يمص إصبعه! 👍', 'قد ترينه في فحص الموجات فوق الصوتية وهو يمص إبهامه. إنه يتدرّب على منعكس المص الذي سيحتاج إليه بعد الولادة.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'هل تحبين السباحة؟ 🏊‍♀️', 'إنه يعيش في الماء. ولكي يبقى السائل الأمنيوسي نقيًا ووفيرًا، عليكِ أيضًا شرب الكثير من الماء على مدار اليوم.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'ارفعي صوتكِ! 🗣️', 'أصبح طفلكِ يسمع صوتكِ ونبضات قلبكِ بوضوح. ابدئي بغناء تهويدة له، فهذا يهدّئه. 🎶'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'قوة الجوز والبندق 🐿️', 'أوميغا-3 ضروري لنمو الدماغ. احملي معكِ بعض المكسرات في حقيبتكِ؛ فهي تمنحكِ الشبع وتغذي ذكاء طفلكِ أيضًا.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'بدأت المرحلة الذهبية! ✨', 'تهانينا! لقد دخلتِ الثلث الثاني من الحمل. تزداد طاقتكِ وتقل المخاطر. حان الوقت الآن للاستمتاع بحملكِ.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'تحتاجين إلى دفعة من الطاقة 💥', 'ينمو طفلكِ بسرعة. اللحوم الحمراء أو البيض أو البقوليات... لا تنسي تجديد مخزونكِ من الحديد والبروتين.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'أصبح بحجم حبة ليمون! 🍋', 'يبلغ طوله نحو 7-8 سم. أصبح الآن قادرًا على إدارة رأسه والعبوس. وتعابير وجهه آخذة في التطور!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'ألقي نظرة على خزانة ملابسكِ 👗', 'هل لم تعد الأزرار تُغلق؟ ضعي السراويل الضيقة جانبًا، وانتقلي إلى ملابس فضفاضة ومريحة مصنوعة من أقمشة طبيعية.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'بنت أم ولد؟ 🩷💙', 'تتشكّل الأعضاء التناسلية بالكامل. ورغم أنه قد يصعب تمييزها في التصوير بالموجات فوق الصوتية، فإن طفلكِ يعرف بالفعل من يكون! ما توقعكِ؟'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'أنتِ المرأة الحديدية! 🦸‍♀️', 'تناولي اللحوم الحمراء أو العدس لتجنب الدوار. ستجدين وصفات في قسم التغذية.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'بحجم تفاحة 🍎', 'لا بأس في أن تفكي زر سروالكِ، استرخي! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'هل تنزف لثتكِ؟ 😬', 'تجعل الهرمونات اللثة حساسة. استخدمي فرشاة ناعمة وتمضمضي بالماء المالح.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'أسمعكِ يا ماما! 👂', 'تزداد عظام الأذن صلابة. وأصبح طفلكِ الآن يميّز نبرة صوتكِ وضحكتكِ ونبضات قلبكِ.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'يشتدّ الهيكل العظمي لطفلكِ🦴', 'تناولي الحليب أو الزبادي أو اللوز حتى لا يستنزف طفلكِ مخزونكِ من الكالسيوم.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'نامي على جانبكِ الأيسر 🛌', 'قد يؤدي النوم على الظهر إلى إعاقة الدورة الدموية. ويوفر النوم على الجانب الأيسر مزيدًا من الأكسجين لكِ ولطفلكِ.'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'هل حان يوم السبا؟ ✨', 'تُغطّى بشرة طفلكِ بطبقة واقية خاصة حتى لا تتجعّد في السائل المحيط به. وماذا عنكِ؟ خصّصي اليوم بعض الوقت لنفسكِ! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'رأيتُ الضوء! 💡', 'رغم أن جفنيه مغلقان، فإنه يشعر بالضوء القوي. إذا سلّطتِ مصباحًا على بطنكِ، فقد يدير وجهه بعيدًا.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'تجنّبي الإمساك 🏃‍♀️', 'بدلًا من الأدوية، اشربي الكثير من الماء وتناولي البرقوق المجفف والكيوي.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'أين المفتاح؟ 🔑', 'النسيان أمر طبيعي. فعقلكِ منشغل الآن بمهمة أهم: صنع إنسان! ابدئي بإعداد قوائم لمهامكِ.'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'هل تعانين من تشنجات الساقين؟ 🦵', 'قد يكون السبب نقص المغنيسيوم والكالسيوم. تناولي الموز أو اللوز أو الزبادي، ولا تنسي شرب الكثير من الماء!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'إنه بحجم حبة كمثرى! 🍐', 'يزداد طوله ويستقيم جسمه. وأصبح الآن قادرًا على إبقاء رأسه منتصبًا تمامًا. هو يكبر، وأنتِ تزدادين جمالًا!'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'هل تشعرين بشدّ في بطنكِ؟ 😣', 'لا تتحركي فجأة. قد يساعد الاستحمام بماء فاتر أو التدليك الخفيف على تخفيف الألم.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'بصمات الأصابع جاهزة! 🖐️', 'لقد تشكّلت بالفعل تلك الأنماط الفريدة التي لا يمتلكها أي شخص آخر في العالم. أصبح طفلكِ منذ الآن فردًا مميزًا. أليس هذا رائعًا؟'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'هل تشعرين بالجوع سريعًا؟ 😋', 'زيادة شهيتكِ أمر رائع، لكن تناول الطعام عن شخصين مجرد خرافة. اختاري مصادر عالية الجودة للسعرات الحرارية، مثل المكسرات والفواكه والخضراوات.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'هل أنفكِ مسدود؟ 🤧', 'أنتِ لستِ مريضة، بل هذا التهاب أنف الحمل. استخدمي بخاخ المحلول الملحي ورطّبي هواء الغرفة.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'توصيل سريع! 🚚', 'عندما أشعر بالجوع، قد أبدأ بدفعكِ برفق. ما الأطعمة المفيدة المقترحة لليوم في قسم التغذية؟ 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'تتكوّن طبقة دهنية 🧸', 'يبدأ طفلكِ بتخزين الدهون للحفاظ على دفء جسمه.'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'من صديق الحديد؟ 🍊', 'إذا كنتِ تتناولين الحديد، فاحرصي على تناوله مع فيتامين C. فهذا يساعد جسمكِ على امتصاص الحديد بشكل أفضل.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'هل يؤلمكِ ظهركِ؟ 👠', 'ضعي الأحذية ذات الكعب العالي في الخزانة، فقد حان وقت الراحة! اختاري حذاءً طبيًا مريحًا.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'هل تشعرين بشدّ في جانبي بطنكِ؟ ⚡', 'قد تشعرين بوخز مفاجئ، فلا تقلقي، أنا فقط أوسّع منزلي! جرّبي الحركات المريحة في قسم التمارين. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'جواز سفره جاهز! 🛂', 'اكتملت بصمات أصابعه تمامًا. أصبحت لديه الآن تلك النقوش التي لا يملكها أي شخص آخر في العالم. شخص فريد في طريقه إليكِ!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'الماء بلا مذاق؟ 💧', 'إذا كان شربه صعبًا، فجرّبي الماء المنكّه بالخيار أو البطيخ أو النعناع. الجفاف يسبب الصداع.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'ماما، أسمعكِ! 👂', 'يصلني صوتكِ كأنه تهويدة، أما نبضات قلبكِ فهي أجمل إيقاع. تحدّثي معي أكثر، فأنا أريد أن أتعرّف إليكِ.'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'ألا يزول الإمساك؟ 🚽', 'الأطعمة الغنية بالألياف وشرب الكثير من الماء هما أفضل علاج. لا تبقي دون حركة، فالمشي يوميًا ينشّط الأمعاء.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'العظام تزداد صلابة! 🦴', 'تتحول الغضاريف اللينة كالمطاط إلى عظام. احرصي على الحصول على ما يكفي من الكالسيوم ليصبح هيكل طفلكِ العظمي قويًا كالحديد!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'وداعًا للدوار! 🛑', 'مع ازدياد حجم الدم في جسمكِ، تزداد حاجتكِ إلى الحديد. السبانخ أو الحنطة السوداء أو اللحوم الحمراء... احرصي على إضافتها إلى قائمة طعامكِ!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'هل هناك حفل راقص في بطنكِ؟ 💃', 'أتعلّم هنا في الداخل كيف أقوم بشقلبة! هل شعرتِ بي؟'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'هل ترين أحلامًا غريبة؟ 😴', 'قد تحوّل الهرمونات لياليكِ إلى أفلام. لا تقلقي، فهذا طبيعي. دوّني أحلامكِ في مفكرة الحالة المزاجية!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'يضع كريمًا طبيعيًا! 🧴', 'يُغطّى جلده بمادة بيضاء شبيهة بالجبن تُسمى الطلاء الجبني، لحمايته من التجعّد. إنه كريم الطبيعة الواقي!'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'الزنك: البطل الخفي 🛡️', 'تنقسم خلاياي بسرعة. أحتاج إلى مواد للبناء! هل تتضمن قائمة طعامكِ اللحوم الحمراء أو الجبن أو المكسرات؟'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'أصبحت بحجم ثمرة مانجو! 🥭', 'يبلغ طولي نحو 15 سم. لا يزال جلدي رقيقًا، لكن بدأت تتكوّن لديّ طبقة دهنية. أبدو الآن أكثر امتلاءً يا ماما!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'هل شعرتِ بها؟ ركلة! ⚽', 'ماما، أنا مستيقظ! تلك الرفرفة الخفيفة هي طريقتي في إلقاء التحية عليكِ. ضعي يدكِ على بطنكِ، فربما أفعلها مجددًا؟'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'صبي أم فتاة؟ 💙💗', 'اقترب موعد فحص الموجات فوق الصوتية لمعرفة جنسي. هل أنتِ متحمسة؟'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'لديّ لعبتي الأولى!', 'أمسك بالحبل السري وألعب به، وأضغط عليه أحيانًا. بدأت أصابعي تتعلم الإمساك بالأشياء.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'حان موعد اللقاء الكبير! 🗓️', 'الأسابيع 18-22 هي الوقت المناسب لإجراء أدق فحص بالموجات فوق الصوتية. سيفحصون أصابعي وقلبي وكل جزء مني. هل حجزتِ موعدًا مع الطبيبة؟'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'أحتاج إلى الحديد 🏗️', 'أنا منشغل بتكوين خلايا الدم الحمراء. ساعديني: تناولي لحم البقر أو السبانخ أو العدس.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'هل تتورم قدماكِ؟ 👠', 'قد يبدأ احتباس السوائل. ارفعي قدميكِ قدر الإمكان، سواء في العمل أو المنزل. واختاري حذاءً مريحًا!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'هق... هق... 🤭', 'هل تشعرين بأن بطنكِ يقفز بإيقاع منتظم؟ لا تخافي يا ماما، إنها مجرد حازوقة! أنا أدرّب حجابي الحاجز.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'يميّز النكهات! 👅', 'يتغير مذاق السائل الأمنيوسي بحسب ما تأكلينه. هل تناولتِ الفلفل الحار؟ سيشعر بطعمه!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'عيناي ترقصان...', 'رغم أن جفنيّ مغلقان، فإنني أحلم بالفعل. تُرى، ماذا يوجد في حلمي؟'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'هل تعانين من حرقة المعدة؟ 🔥', 'يضغط الرحم على المعدة. تناولي وجبات صغيرة ومتكررة. لا تستلقي مباشرة بعد تناول الطعام، بل اجلسي في وضع مستقيم.'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'بحجم موزة! 🍌', 'يبلغ طولي نحو 18-20 سم. والآن أُقاس من رأسي حتى قدميّ. يزداد طولي ويتناسق جسمي.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'هشش، أنا نائم 😴', 'لديّ أنا أيضًا نظام نوم خاص بي، ماما. عندما تمشين، تهدهدني حركتكِ فأنام، وعندما تستلقين أستيقظ وأقيم حفلة راقصة! سامحيني 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'قطعنا نصف الطريق! 🏁', 'تهانينا! لقد مضى 20 أسبوعًا. أنتِ الآن في منتصف رحلة الحمل. أنتِ رائعة، ويجب أن تحتفلي بذلك!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'جارٍ التحميل... 50% ⏳', 'تهانينا! لقد قطعنا نصف الطريق. صورة في المعرض ستكون رائعة للاحتفال بهذا اليوم المميز! ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'هل سيشعر بي أبي؟', 'إذا وضع يده على بطنكِ، فربما ألقي عليه التحية أيضًا.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'هل ترين أحلامًا ملوّنة؟', 'تبدو أحلام الحمل كالأفلام، أليس كذلك؟ هل أظهر أنا أيضًا في أحلامكِ؟ 😴'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'يوم للعناية بنفسكِ 💅', 'إذا ظهرت لديكِ تصبغات الحمل، فاحمي نفسكِ من الشمس. ما رأيكِ في وضع قناع للوجه اليوم؟'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'يستكشف وجهه! 👶', 'يلمس بيديه وجهه وأنفه، وحتى حبله السري. تتطور حاسة اللمس لديه، وهو يتعرف إلى نفسه!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'مخللات وآيس كريم؟ 🥒🍦', 'هل تشتهين خلطات غريبة؟ إنها إشارات من جسمكِ. لكن حاولي أن تحافظي على تناول السكر والملح ضمن الحدود المعتدلة.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'بحجم ثمرة جوز هند! 🥥', 'يبلغ طوله نحو 28 سم، وقد تجاوز وزنه نصف كيلوغرام! والآن أصبحت ركلاته أقوى.'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'هل نشغّل بعض الموسيقى؟ 🎶', 'ماما، أسمع الأصوات في الخارج! وأنا أيضًا أحب الأغاني التي تحبينها. هل نرقص معًا؟'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'هل برزت سرتكِ؟ 🔘', 'مع نمو بطنكِ، قد تبرز سرتكِ إلى الخارج. لا تقلقي، ستعود إلى طبيعتها بعد الولادة!'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'ما ذلك الصوت يا ماما؟ 🔊', 'أفزع من الأصوات المفاجئة. عندما تكونين هادئة، أكون هادئًا أيضًا. هل يمكنكِ أن تغني لي تهويدة؟'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'أنتِ مهدي... 💤', 'عندما تمشين، أتمايل وأنام. لكن عندما تتوقفين، أستيقظ! هل نواصل المشي بخفة لتساعديني على النوم؟ 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'هل شربتِ محلول الجلوكوز؟ 🥤', 'فحص سكري الحمل مهم. احرصي على إجرائه حفاظًا على صحتي وصحتكِ.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'هل ظهر خط على بطنكِ؟ ➖', 'الخط الأسود ناتج عن الهرمونات. لا تقلقي، سيختفي بعد الولادة. أنتِ جميلة في كل حالاتكِ!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'ازدادت فرصتي في البقاء على قيد الحياة! 🌟', 'بلغتُ الأسبوع الرابع والعشرين! من الناحية الطبية، أصبحتُ الآن قادرًا على البقاء على قيد الحياة خارج الرحم. إنها مرحلة مهمة جدًا يا ماما.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'هل تشعرين بحرقة المعدة؟ 🔥', 'ليست بسبب نمو شعري، بل لأن الرحم يضغط على المعدة. لا تستلقي بعد الأكل مباشرة، بل اجلسي في وضع مستقيم.'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'مخاض أم انقباضات تدريبية؟ 🤔', 'هل تشعرين بأن بطنكِ يتصلّب؟ قد تكون هذه انقباضات كاذبة؛ فالرحم يتدرّب استعدادًا للولادة. إذا كانت غير مؤلمة، فهذا طبيعي.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'تجنّبي الأطعمة المالحة 🧂', 'إذا كانت قدماكِ متورمتين، فقلّلي الملح. قد يساعدكِ شرب الكثير من الماء وتناول البقدونس. هل أصبح خاتمكِ ضيقًا على إصبعكِ؟'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'بدأ المصنع الصغير بالعمل! 🏭', 'لم يعد كبدي، بل نخاع عظمي الآن هو الذي ينتج خلايا الدم. ما الأطعمة الغنية بالحديد في قسم التغذية والتي يمكنكِ تناولها لمساعدتي؟'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'ششش، أنا نائم... 🤫', 'ماما، لماذا لا أتحرك؟ لأنني أنام معظم اليوم. عندما أنام، استريحي أنتِ أيضًا.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'حان وقت التمرين السرّي! 🧘‍♀️', 'لا تنسي تمارين كيجل. وأنتِ جالسة، اقبضي عضلات قاع الحوض ثم أَرخيها. ستحتاجين إليها أثناء الولادة!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'تمارين التنفس الأولى! 🫁', 'تتكوّن في رئتيّ المادة الخافضة للتوتر السطحي. ستساعدني هذه المادة على أخذ نَفَسي الأول عند ولادتي. أنا أتدرّب!'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'ماما، أشعر بالملل! 🤸', 'عندما تهدئين، أستيقظ أنا. داعبي بطنكِ، فقد أرد عليكِ بركلة صغيرة!'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'أصبحت بحجم حبّة شمّام! 🍈', 'أزن نحو 600 غرام. بدأت المساحة تضيق عليّ قليلًا الآن. قد تصبح ركلاتي أقوى، فسامحيني! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'هل أصبح حذاؤكِ ضيقًا؟ 👟', 'قد يزداد مقاس قدميكِ. الراحة أهم من الأناقة الآن. اختاري حذاءً رياضيًا واسعًا!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'بدأ شعري يكتسب لونه! 🎨', 'بدأت اليانصيب الجيني. أشقر أم أسود أم أحمر؟ بدأت صبغة شعري بالتكوّن. برأيكِ، بمن سأشبه؟'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'هل سئمتِ التورّم؟ 🎈', 'من المفارقات أن شرب الماء يساعد على تقليل الوذمة. كما قد تفيدكِ الأطعمة الغنية بالماء، مثل الخيار والبطيخ. ابتعدي عن الملح.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'بدأ لوني يحمرّ...', 'لم تعد بشرتي شفافة كالزجاج! تمتلئ شعيراتي الدموية بالدم، ويصبح لوني ورديًا. لا تنسي شرب الماء عبر متتبّع الماء لدعم دورتكِ الدموية! 🥤'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'أوه! ما ذلك الصوت؟ 😳', 'فزعتُ عندما أُغلق الباب بقوة. حاسة سمعي قوية جدًا يا ماما. شغّلي موسيقى هادئة ولنسترخِ معًا.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'انفتحت فتحتا أنفي! 👃', 'كانت فتحتا أنفي مسدودتين، وقد انفتحتا الآن. أتدرّب على التنفس.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'هل أصبح الهضم بطيئًا؟ 🐌', 'يُبطّئ البروجسترون حركة الأمعاء. قد يكون المشمش المجفف والبرقوق المجفف وخبز النخالة طوق نجاتكِ.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'ابني قلعة من الوسائد! 🏰', 'ألا تستطيعين النوم براحة؟ ضعي وسادة بين ساقيكِ وأخرى تحت بطنكِ. الدعم ضروري!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'أنا بارع في اليوغا! 🦶', 'لن تصدّقي، لكنني أستطيع الإمساك بإصبع قدمي ووضعه في فمي! أنا مرن جدًا. أما أنتِ، فهل تجدين صعوبة في الانحناء؟'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'فتحتُ عينيّ! 👀', 'ماما، لن تصدّقي، لكنني فتحتُ جفنيّ. رغم أن الظلام يحيط بي، فإن نظراتي بدأت تتشكّل. لم يبقَ الكثير حتى أراكِ!'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'هل أسمع أبي؟ 🗣️', 'صوت الرجل أعمق، ويمكنني سماعه بشكل أفضل. تحدّثي مع أبي، ودعيه يقرأ لي قصة.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'أنتِ درعي!', 'يتكوّن جهازي المناعي، وتنتقل إليّ الأجسام المضادة منكِ. أنتِ تحمينني من الأمراض، ماما. ❤️'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'هل تصيبكِ تشنجات؟ 🦶', 'هل تتشنج ربلة ساقكِ ليلًا؟ قد يكون السبب نقص المغنيسيوم. الموز أو اللوز أو الزبادي... عضلاتكِ بحاجة إلى الاسترخاء.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'فتحت عينيّ! 👀', 'رغم الظلام، أصبح بإمكاني الآن فتح جفنيّ. وأرمش برموشي. لم يتبقَّ الكثير حتى اليوم الذي سأرى فيه العالم!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'الضوء يصل إليّ، ماما! ☀️', 'أنا أرمش بعينيّ! إذا سطعت الشمس على بطنكِ، يمكنني رؤية ذلك الضوء. تُرى، ما لون العالم؟'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'حان وقت الترطيب 🧴', 'ينمو بطنكِ بسرعة ويتمدد جلدكِ. ضعي مرطبًا كل يوم للوقاية من الحكة.'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'أنا هنا يا ماما! 👋', 'أحيانًا أهدأ، وأحيانًا أرقص. هل تعدين ركلاتي؟ كل شيء على ما يرام، لكن المساحة تضيق حولي فحسب.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'هل توجد شبكة على ساقيكِ؟ 🕸️', 'قد تظهر الدوالي الوريدية. لا تقفي لفترات طويلة. في المساء، استلقي وارفعِي ساقيكِ مستندتين إلى الحائط.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'بدأ مصنع الدم عمله 🩸', 'كان الكبد ينتج خلايا الدم حتى الآن، أما الآن فقد بدأ نخاع العظم بإنتاجها. إنه استعداد للحياة المستقلة!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'ثنائي الحديد وفيتامين C 🥩🍊', 'للحد من خطر الإصابة بفقر الدم: اشربي عصير البرتقال عند تناول اللحوم. يزيد فيتامين C امتصاص الحديد بمقدار 2 ضعف.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'ثمرة ملفوف كبيرة 🥬', 'أصبحت بشرتي أكثر نعومة وامتلأ خدّاي. لا أطيق الانتظار لرؤيتكِ!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'هل يصعب عليكِ التنفس؟ 😮‍💨', 'كلما ارتفعتُ إلى أعلى، ضغطتُ على حجابكِ الحاجز. حاولي أن تتنفسي بعمق يا ماما. لم يتبقَّ الكثير، وسأنزل إلى أسفل قريبًا.'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'هل تشعرين أن معدتكِ تحترق؟ 🔥', 'يضغط الرحم على المعدة إلى أعلى. قد يساعد شرب الحليب أو تناول حفنة من اللوز النيئ على إطفاء الحرقة.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'بحجم حزمة من البروكلي 🥦', 'تزداد الآن طبقة الدهون لديّ، وتصبح ذراعاي وساقاي أكثر امتلاءً.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'هل نجهّز عشي؟ 🐣', 'سريري وملابسي الصغيرة... أعدّي القائمة مع أبي في قسم التسوق المشترك! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'هل عامل ريسوس لديكِ سلبي؟ 🩸', 'هذا أسبوع مهم للأمهات ذوات عامل ريسوس السلبي. قد تحتاجين إلى حقنة الغلوبولين المناعي. تحدّثي مع طبيبكِ!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'أصبحت رموشي أطول! 👁️', 'أفتح عينيّ وأغمضهما، وأميّز بين الضوء والظلام. إذا سلّطتِ مصباحًا على بطنكِ، فسأدير وجهي. هل تريدين التجربة؟'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'السمك، السمك، السمك! 🐟', 'يمرّ دماغي الآن بأسرع مراحل نموه. أحتاج إلى أوميغا-3. هل تتناولين السمك مرتين أسبوعيًا؟'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'كيف ستكون شخصيتي؟ ✨', 'هل سأكون عنيدًا أم عاطفيًا؟ ماذا يقول برجي وفقًا لتاريخ ولادتي؟ وهل يتوافق مع برجكِ؟ هيا نطالع الأبراج! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'هل تؤلمكِ أضلاعكِ؟ 🥊', 'سامحيني يا ماما، فالمكان لديّ ضيق. عندما أمدّ ساقيّ، أصطدم بأضلاعكِ. قد يساعدكِ الجلوس باستقامة.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'هل تعدين ركلاتي؟ 🦶', 'بدأ نمط حركتي يتشكّل بالفعل. ادخلي إلى عدّاد الركلات وتابعي نشاطي. هل كل شيء على ما يرام؟'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'تتكوّن طيّات دماغي! 🧠', 'كان أملس في البداية، أما الآن فتتكوّن فيه الطيّات والأخاديد. وهذا يعني أن مليارات الخلايا العصبية بدأت تعمل. العبقري قادم!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'هل يرهقكِ الارتجاع؟ 🔥', 'هل يصل حمض المعدة إلى حلقكِ؟ قد يساعدكِ مضغ العلكة أو شرب الحليب الدافئ بعد تناول الطعام.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'أصبحت بحجم ثمرة يقطين! 🎃', 'يبلغ طولي نحو 39-40 sm، وبلغ وزني 1.2 kq! هل أصبحت ثقيلًا عليكِ؟ سامحيني يا ماما، لكن يجب أن أزداد وزنًا.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'أول لقاح منكِ 🛡️', 'تنتقل أجسامكِ المضادة إليه، وستحميه خلال الأشهر الأولى بعد الولادة.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'مخلل الخيار؟ لا! 🚫', 'إذا كانت قدماكِ متورمتين، فقلّلي الملح إلى أدنى حد. المخللات لذيذة، لكنها تسبب الوذمة. استبدليها بالماء مع الليمون.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'العالم صاخب جدًا... 🔊', 'أصبحت أذناي حساستين لدرجة أنني أسمع حتى أصوات أبواق السيارات في الخارج. هل نهدأ قليلًا؟ شغّلي لي صوت المطر من الأصوات البيضاء، ولنغفُ معًا. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'أواكب الإيقاع 🥁', 'ينبض قلبي بانتظام، وأتدرّب على التنفس. وأُصاب بالفواق أحيانًا.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'تقترب المرحلة الأخيرة! 🏁', 'هذه هي الأيام الأخيرة من الثلث 2. نامي جيدًا قبل بدء المرحلة 3!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', 'مرحبًا بكِ في الثلث 3! 🏁', 'بدأت المرحلة الأخيرة! سيصبح جسمكِ الآن أثقل، لكن خط النهاية بات واضحًا. تحلّي بالصبر يا ماما!'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'هل فكرتِ في حقيبتكِ؟ 👜', 'ليس الوقت مبكرًا! ألقي نظرة على قائمة حقيبة المستشفى. تجهيز ما ينقصكِ من الآن سيخفف التوتر.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'هل أخبركِ بسر؟ 🤫', 'عندما تنامين، أغفو وأنا أتخيل صوتكِ. برأيكِ، من أرى في أحلامي؟ أنتِ بالطبع! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'هل كانت تلك شوكولاتة؟ 🍫', 'ممم، وصلت لذتها إليّ هنا! الآن أنا مفعم بالطاقة. هيا نرقص يا ماما! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'أصبحت بحجم ثمرة يقطين! 🎃', 'خدّاي يمتلئان لدرجة أنكِ سترغبين في قضمهما! المكان ضيق، لكن من الجميل أن أكون قريبًا منكِ.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'أقف رأسًا على عقب! 🙃', 'من الممتع رؤية الحياة بالمقلوب! أستعد للولادة يا ماما. في هذه الوضعية أكون أقرب إليكِ.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'هل تشعرين بتصلب بطنكِ؟ 🤰', 'لا تقلقي يا ملاكي! إنها مجرد تقلصات تدريبية. نحن نستعد معًا كفريق لذلك اليوم الكبير!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'أظافري جاهزة للمانيكير!', 'لن تصدّقي، لقد وصلت أظافري بالفعل إلى أطراف أصابعي.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'تزداد زيارات الطبيب! 🩺', 'هل حدّدتِ المستشفى والطبيب للولادة؟ ألقي نظرة على قائمة الأطباء والعيادات! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'أتضحكين تارةً وتبكين تارةً أخرى؟', 'إنها الهرمونات تعبث بمشاعركِ مجددًا. الخوف من الولادة وفرحة اللقاء يجتمعان في قلبكِ. أفرغي ما في قلبكِ في يوميات المزاج واستريحي. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'تنتقل إليّ منكِ قوة خارقة! 🛡️', 'لا تمرضي يا ماما! فمناعتكِ ستكون درعي الأول. نحن فريق لا يُقهر! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'هل جافاكِ النوم مجددًا؟ 🥺', 'أما أنا فأنام بعمق وهدوء. أغمضي عينيكِ وتخيّليني... لعلّنا نلتقي في الحلم؟ 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'عظامي تزداد صلابة! 🦴', 'لكنني أستعير مخزونكِ من الكالسيوم من أجل ذلك... سامحيني! 🙈 هل نتصالح إذا شربتِ كوبًا من الحليب؟ 🥛'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'وصلني صوت أبي! 🧔', 'عندما أسمع صوته، ينبض قلبي بقوة أكبر. قولي له إنني هنا أيضًا وألقي عليه التحية! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'قوّي عظامي! 💪', 'أحتاج إلى الكالسيوم يا ماما. إذا شربتِ كوبًا من الحليب أو اللبن، فسنصبح كلانا قويين جدًا! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'طق طق! من هناك؟ ✊', 'هل تؤلمكِ ركلاتي أحيانًا؟ آسف 🥺 كل ما في الأمر أنني أريد أن ألمسكِ.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'هل تشعرين بضيق في التنفس؟ 😮‍💨', 'لقد صعدتُ إلى الأعلى قليلًا، وأضغط على رئتيكِ. سامحيني يا ماما، سأنزل إلى الأسفل قريبًا وستتنفسين براحة! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'سأشم رائحتكِ...', 'هل تفكرين في تلك اللحظة التي ستضمينني فيها إلى حضنكِ؟ أنا أكبر كل يوم وأنا أحلم بتلك اللحظة يا ماما! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'بيتي يضيق... 🏠', 'بدأت حركاتي تتحول إلى ضربات بقبضتي ومرفقيّ. هل كل شيء على ما يرام؟ هيا نتحقق معًا من عداد الركلات!'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'تحتاجين إلى بعض الهواء 🌿', 'ما رأيكِ أن نخرج اليوم من المنزل ونشرب الشاي في مكان هادئ ذي هواء نقي؟ تصفّحي الأماكن الصديقة للأمهات!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'ذلك اليوم الكبير... ✨', 'لا داعي للاستعجال، لكن لنبدأ بتجهيز حقيبتنا رويدًا رويدًا. هل نطّلع على محتويات قائمة حقيبة المستشفى؟'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'ششش... أنا نائم 😴', 'ينمو دماغي بسرعة كبيرة لدرجة أنني أقضي معظم وقتي نائمًا. استريحي أنتِ أيضًا يا ماما.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'ماذا ستسمّينني؟ 👶', 'إذا لم تكوني قد قررتِ بعد، فألقي أنتِ وأبي نظرة على قائمة أسماء الأطفال. أي اسم يليق بي أكثر؟'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'غرفتي، سريري، وأغراضي الصغيرة... 🐣', 'هل اشتريتِ كل ما نحتاج إليه؟ تصفّحي المنتجات الموصى بها، فربما نسيتِ شيئًا.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'تستعد عضلات الرحم للولادة.', 'لا تخافي، فهذه مجرد تقلصات تدريبية. إذا تكرر الألم كثيرًا، فتحققي من الفواصل الزمنية باستخدام مؤقت الانقباضات!'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'غنّي تلك الأغنية مرة أخرى! 🎶', 'صوتكِ يمنحني راحة كبيرة... عندما تغنّين، أرقص في الداخل، هل تشعرين بي؟ 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'الجدران تضيق عليّ! 🏠', 'أصبحت مساحتي ضيقة جدًا يا ماما. أمدّ ساقي فتصطدم بأضلاعكِ... إن آلمتكِ، فهل تكفي قبلة مني ليزول الألم؟ 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'هل كويتِ ملابسي؟ 👗', 'أكاد أشمّ رائحتها من الآن. أعلم أنكِ لا تطيقين صبرًا لرؤيتي مرتديًا تلك الملابس! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'ماء حوضي يتناقص... 💧', 'أحب السباحة في مياه نظيفة ووفيرة. هل تشربين كوبًا من الماء من أجلي؟ 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'أتفقّد الطريق! 🔦', 'رأسي إلى الأسفل وأنا أنظر نحو بوابة الخروج. ما عليكِ سوى أن تتنفّسي بعمق، وسيكون كل شيء على ما يرام!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'يد مَن الدافئة هذه؟ 🖐️', 'هل هي يد أبي؟ أشعر بالهدوء عندما أحسّ بلمسته. قولي له إنني وضعت يدي أيضًا، فلنتصافح بالكفّ! ✋'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'فتحتُ عينيّ على اتساعهما! 👀', 'رغم الظلام، أراقب كل شيء. تُرى، هل أشبهكِ أم أشبه أبي؟ هل راهنتِ معه على ذلك؟ 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'ششش... أنا نائم! 😴', 'ينمو دماغي بسرعة كبيرة لدرجة أنني أحتاج إلى الكثير من النوم. نامي معي أنتِ أيضًا يا ماما؟ 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'هل تُجرين تغييرات في المنزل؟ 🌪️', 'ترغبين في تنظيف كل مكان وترتيب الخزائن... إنها غريزة التعشيش! لكن لا ترهقي نفسكِ، فأنا بحاجة إلى أم مرتاحة.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'المكان هنا ضيّق جدًا! 🏠', 'أريد أن أستدير، لكن لا توجد مساحة كافية. إذا أخرجتُ مرفقي، فسيبدو بطنكِ مائلًا. ستنظرين إليه وتضحكين! 😄'),
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8', 'أحتاج إلى الدهون! 🥑', 'الأفوكادو أو الجوز أو زيت الزيتون... بيدكِ أن تجعلي جسمي ممتلئًا!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'نبض قلبكِ تهويدتي... 💓', 'رأسي إلى الأسفل، وأذني أقرب إلى قلبكِ. هذا الإيقاع هو الموسيقى الوحيدة التي تهدّئني.'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'أنا أستجمع قوتي! ⚡', 'ألا أتحرك كثيرًا؟ لا تخافي. أحتاج إلى النوم الآن. إنني أدّخر طاقتي لليوم الكبير. استريحي أنتِ أيضًا! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'هل شعرتِ بمرفقي؟ 💪', 'آسف يا ماما! أريد أن أتمطّى، لكن لا توجد مساحة كافية. هل تضحكين عندما يبدو بطنكِ متعرجًا؟ 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'هل تمشين مثل البطريق؟ 🤭', 'تغيّرت مشيتكِ لأنني نزلت إلى الأسفل. لكنكِ في كل حالاتكِ وبكل خطواتكِ أجمل أم في العالم! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'هق... هق... 😲', 'أصابني الفواق مجددًا! إنني أدرّب حجابي الحاجز. إذا كان بطنكِ يتحرك بإيقاع منتظم، فاعلمي أنني السبب!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800'::uuid, 'هل التقينا بالطبيبة؟ 👩‍⚕️', 'عندما يلامس ذلك الهلام البارد بطنكِ، أشعر بالدغدغة! 🙈 لكنني أعلم أن سماع نبضات قلبي يبعث الطمأنينة في نفسكِ.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'نحن فريق واحد! 🤝', 'لا تخافي عندما تبدأ الانقباضات. خذي نفسًا عميقًا. سننجح معًا، أعدكِ!'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'هل غرفتي جاهزة؟ 🧸', 'هل تنظرين إلى مهدي وتسرحين في أحلامكِ؟ لا أطيق الانتظار حتى أعانق اللعبة التي وضعتِها هناك! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'إنني أنزل إلى أسفل، هل تشعرين بذلك؟ ⬇️', 'أستقر الآن بين عظام حوضكِ. ستتنفسين بسهولة أكبر، لكنكِ ستذهبين إلى الحمام كثيرًا! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'مناعتي تزداد قوة 🛡️', 'الأجسام المضادة التي تنتقل منكِ إليّ تهيئني لمواجهة عالم الميكروبات. كما سيحميني حليبكِ يا ماما!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'أين ملابسي الأولى؟ 👕', 'هل جهزتِ حقيبة المستشفى؟ مرّري يدكِ بحنان على ذلك الرداء الصغير الذي ستُلبسينني إياه...'),
  ('deba1190-6096-4dec-88eb-70e669fb3ccb', 'أريد أن أراكِ! 👀', 'عيناي مفتوحتان، لكن المكان مظلم هنا. أعدّ الأيام حتى أرى وجهكِ وابتسامتكِ. لم يتبقَّ الكثير! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'بشرتي تصبح أكثر نعومة! 🧖‍♀️', 'يتساقط الزغب عن جسمي، وتزداد طبقة الدهون لديّ. أستعد للمستكِ الرقيقة يا ماما. سأكون ناعمًا كالغيوم! ☁️'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'هل الحقائب عند الباب؟ 🎒', 'قد أفاجئكِ في أي لحظة! هل وضعتِ في الحقيبة تلك القبعة الأولى التي ستُلبسينني إياها؟ لا أريد أن أشعر بالبرد. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'اقتربنا من خط النهاية! 🏆', 'يكتمل الأسبوع 37! لقد دخلنا الآن مرحلة تمام الحمل المبكرة. وهذا يعني أن رئتَيّ مستعدتان للتنفس حتى لو وُلدتُ اليوم!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'رأيتكِ في حلمي... 💤', 'صوتكِ، رائحتكِ، دفؤكِ... لا أطيق الانتظار حتى أستيقظ وأحتضنكِ حقًا يا أمي!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'هل تصلّب بطنكِ؟ 🤰', 'هل هذه مجرد انقباضات تدريبية، أم أنني قادم؟ إذا ساوركِ الشك، فافتحي مؤقّت الانقباضات. سيخبركِ بدقة: هل تتوجهين إلى المستشفى أم إلى السرير؟'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'ما زلتُ هنا! 👋', 'المكان ضيق جدًا، لذلك أتحرك قليلًا. لكن إذا كنتِ قلقة، فافتحي عدّاد الركلات. هيا نعدّ معًا! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'هل وضعتِ جواربي؟ 🧦', 'لا أريد أن أشعر بالبرد يا أمي! راجعي قائمة حقيبة المستشفى للمرة الأخيرة. هل أول بدلة لي موجودة هناك؟ 🥰'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'ألا تستطيعين النوم؟ 🥺', 'أما زلتِ مستيقظة؟ تعالي نستمع من الآن إلى الأصوات التي ستشغّلينها لي بعد ولادتي. فقسم الضوضاء البيضاء سيهدّئنا معًا. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'حزمتُ حقيبتي وأنتظر عند الباب! 🚪', '38 أسبوعًا! أصبحتُ الآن مستعدًا رسميًا للولادة. رئتاي ودماغي وكل أعضائي قد اكتملت.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'ماذا ستفعلين إذا نزل ماء الجنين؟ 💦', 'لا داعي للذعر! اقرئي مقال «العلامات الثلاث الرئيسية لبدء الولادة» في قسم المدونة.'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'إنني أنزل إلى الأسفل... ⬇️', 'أعلم أنني أضغط على عظام حوضكِ، لكن هذا هو طريقي الوحيد للقائكِ. يا أمي الصبورة! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'ليالٍ بلا نوم؟ 🥱', 'قد يصبح الخلود إلى النوم أكثر صعوبة مع اقتراب موعد الولادة. هكذا يهيئكِ جسمكِ لنمط الحياة مع طفلكِ.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'كيف ينبض قلبي؟ 💓', 'عندما تشتاقين إليّ، ضعي يدكِ على بطنكِ. قلبانا ينبضان كقلب واحد. كل شيء على ما يرام، نحن فقط ننتظر يوم لقائنا. 🗓️'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'مساعدة طبيعية 🍍', 'يُقال إن التمر والأناناس يساعدان على تليين عنق الرحم. أضيفيهما اليوم إلى قائمة طعامكِ في قسم التغذية. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'نبضات القلب... ❤️', 'بعد تجاوز الأسبوع 40، من المهم إجراء فحص KTG (NST) للاطمئنان على حالة المشيمة. تأكدي من أن كل شيء على ما يرام.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'هل نصعد الدرج؟ 🪜', 'أرشديني إلى الطريق! قد يساعد صعود الدرج أو أداء تمارين القرفصاء على نزولي إلى الأسفل. ألقي نظرة على قسم التمارين.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'الجو هنا رائع جدًا 🌡️', 'دافئ ومظلم ومريح... لن تغضبي مني إن قلت إنني لا أريد الخروج، أليس كذلك؟ 🥺 أنا أمزح، أنا قادم!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'كيف ينبض قلبي؟ 💓', 'هل نحن عند الطبيب لإجراء فحص NST؟ كم تشعرين بالاطمئنان عندما تسمعين صوت نبضاتي...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'هل تأكلين التمر؟ 🌴', 'إنها محاولة طبيعية ولذيذة تستحق التجربة استعدادًا للولادة!'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'هل قلّت ركلاتي؟ 🦶', 'لم يعد لديّ متّسع يا ماما! لكن يجب أن تشعري بحركاتي. إذا ساوركِ الشك، فتناولي شيئًا حلوًا وادخلي إلى عدّاد الركلات.'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'هل جميع المستندات جاهزة؟ 📄', 'بطاقة الهوية، نتائج التحاليل... تحقّقي من حقيبتكِ للمرة الأخيرة. هل وضعتِ علامة صح بجانب كل شيء في قائمة حقيبة المستشفى؟ ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'أغمضي عينيكِ... 😌', 'لا تخافي من الولادة. تخيّلي فقط تلك اللحظة التي ستضمّينني فيها للمرة الأولى. ستُنسيكِ رائحتي كل الآلام.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'عنق الرحم 🗝️', 'هناك عمل خفي يجري! يلين عنق الرحم ويترقّق ويتّسع. حتى إن لم تشعري بذلك، فإن جسدكِ يفتح لي الباب.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'هل اليوم هو اليوم المنتظر؟ 🗓️', 'اكتملت 40 أسبوعًا! والتقويم يشير إلى هذا اليوم. هل آتي الآن، أم أُدلّل نفسي قليلًا بعد؟ قد أفاجئكِ في أي لحظة! كوني مستعدة! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'لم أتأخر! 👑', 'فالنجوم لا تصعد إلى المسرح إلا أخيرًا يا ماما! سأتدلّل قليلًا بعد، ثم سآتي. تحلّي بالصبر! 😌'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'طق طق، هذا أنا! ✊', 'هل تشعرين بانقباضات تأتي وتذهب في بطنكِ؟ لا تضيّعي الوقت، واضغطي على زر مؤقّت الانقباضات. إذا بدأت الفواصل بينها تقصر، فهذا يعني أن اليوم هو اليوم المنتظر! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'هل وصل الحليب الذهبي؟ ✨', 'قد يخرج من ثدييكِ سائل مائل إلى الصفرة يُسمّى اللبأ، وهو بمنزلة أول لقاح لطفلكِ. اقرئي عن الرضاعة الطبيعية في المدوّنات. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'انقباضات كاذبة أم حقيقية؟ 🤔', 'هل تشعرين بأن بطنكِ يتصلّب ثم يرتخي؟ إذا كانت الانقباضات غير منتظمة، فهي انقباضات كاذبة. للتأكّد، افتحي مؤقّت الانقباضات وجرّبيه!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'هل خرجت السدادة المخاطية؟ 🩸', 'إذا خرجت إفرازات كثيفة، فقد يعني ذلك أن عنق الرحم بدأ بالتوسّع. لا تخافي، فهذه مجرد إشارة للاستعداد.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'طرطشة! ما هذا الصوت؟ 💦', 'إذا نزل ماء الجنين، فلا تفزعي. خذي نفسًا عميقًا وأخبري طبيبكِ. أنا قادم! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'حان وقت التخلّص من التوتر! 😮‍💨', 'هل تشعرين بالقلق؟ تعلّمي من الآن تقنيات التنفّس أثناء الولادة في قسم التمارين. ستحتاجين إليها كثيرًا خلال الانقباضات.'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'لكنني أزداد وزنًا! ⚖️', 'مع كل يوم أبقى فيه هنا، أصبح أكثر امتلاءً. تزداد وجنتاي حلاوة، لكن مهمتكِ تصبح أصعب. سامحيني! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'هل وضعتِ وجبة خفيفة في الحقيبة؟ 🍫', 'ستشعرين بجوع شديد بعد الولادة! أضيفي البسكويت أو الشوكولاتة التي تحبينها إلى حقيبة المستشفى.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'هل تشيخ المشيمة؟ 🍂', 'هل يتحقق الطبيب من كمية السائل الأمنيوسي؟ ما دام الأكسجين لا يزال يصل إليّ، فلا توجد مشكلة. إنها مجرد أيامنا الأخيرة قبل أن نلتقي.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'هل بدأت الانقباضات ليلًا؟ 🌙', 'ذلك الألم الذي أيقظكِ من النوم... هل هو مخاض حقيقي؟ لا تضيّعي الوقت، وشغّلي مؤقت الانقباضات. لعل هذه الليلة هي الليلة المنتظرة! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'هل حان وقت إخلائي؟ 📢', 'هل يقترح الطبيب تحفيز المخاض؟ لا تخافي. الأهم أن أصل إلى حضنكِ سالمًا معافى. لا يهم كيف أصل!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'صورتكِ الأخيرة في الحمل... 📸', 'ألقي نظرة أخيرة على هذا البطن. فقد أكون بين ذراعيكِ غدًا. افتخري بجسدكِ المذهل هذا، ماما!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('3258a482-400c-485d-af7c-ccb221416732'::uuid, 'هل ترهقكِ الاستيقاظات الليلية؟ 😴', 'دوّني مشاعركِ اليوم في مفكرة المزاج، ودعي Anacan AI يقدم لكِ نصائح مفيدة.'),
  ('80a2cd79-a6d6-4c87-b540-c42931228485', 'معدة طفلكِ تكبر. 🍒', 'سجّلي الكمية التي تناولها باستخدام أداة متابعة التغذية، وتحققي من احتياجه اليومي.'),
  ('cdd7b6ae-f340-479e-9d33-221c6775ebb3', 'لا تقمّطي طفلكِ بإحكام، ودعيه يتحرك بحرية! 🚫', 'تصفحي مدوناتنا لقراءة المزيد عن المعلومات المفيدة والأساليب الحديثة.'),
  ('1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'يتحول حليبكِ الآن إلى حليب ناضج غني بالسعرات الحرارية. 🥛', 'شغّلي مؤقت الرضاعة، وقيسي بدقة مقدار ما تناوله طفلكِ اليوم!'),
  ('9a18572b-e386-4df8-ba20-b5eb78b8f99f', 'كيف مرت الأيام الـ10 الأولى؟ 📸', 'قلة النوم، والمخاوف، والدموع أحيانًا، وعاصفة كبيرة من الحب... لقد اجتزتِ بالفعل الأيام الـ10 الأولى، أي أصعب مرحلة في البداية! أنتِ رائعة.'),
  ('ffd7ff0c-bf80-4552-8a28-8d30f0674b07', 'خصصي اليوم 15 دقيقة على الأقل لنفسكِ فقط. 🛁', 'خذي حمامًا دافئًا، وكافئي نفسكِ بوصفات صحية من التطبيق.'),
  ('092f30cd-002d-4c4e-a83e-0b13c38cc743', 'تزداد رؤية طفلكِ وضوحًا! 👀', 'أصبح الآن يميّز وجهكِ بشكل أفضل. دوّني في مفكرة المزاج المشاعر التي تثيرها فيكِ هذه اللحظات الجميلة.'),
  ('20684bd3-d3fb-479e-89f1-9adf84e485af', 'كيف يسير روتين التغذية؟ 🤱', 'شغّلي المؤقت في التطبيق، وتابعي احتياجه الغذائي بسهولة باستخدام أداة متابعة التغذية.'),
  ('7797557a-9277-450c-98b3-b0fa58923513', 'حان وقت النوم بعد حمّام المساء! 🛁', 'يساعد تحميم طفلكِ قبل النوم ليلًا كثيرًا على أن يخلد إلى النوم بهدوء.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'هل تتابعين عدد الحفاضات يوميًا؟ 🧷', 'الحفاضات هي أفضل مؤشر على أن طفلكِ يحصل على كفايته من الحليب. لا تنسي تسجيلها في Anacan عند كل تغيير!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'لنحلّل نمط نوم طفلكِ. ⏱️', 'شغّلي مؤقت النوم عندما ينام، وتابعي عبر الرسم البياني مدى حصول طفلكِ على حاجته اليومية من النوم.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'خيار شهي ومفيد للأمهات! 🍲', 'اطّلعي على قسم الوصفات الصحية التي ستعزز طاقتكِ، واعتني بنفسكِ جيدًا.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'طفلكِ ينمو بسرعة! ⚖', '️ أدخلي وزنه الأسبوعي في متتبّع النمو، وتابعي منحنى نموه الصحي عبر التطبيق.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'هل لديكِ أي سؤال؟ 🤖', 'Anacan AI معكِ حتى في ساعات الليل! اطرحي الأسئلة التي تشغل بالكِ واحصلي على الدعم فورًا.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'نزهاتكما الأولى معًا! 🌳', 'إذا كان الطقس جميلًا، فاخرجي مع طفلكِ. من المهم والمفيد جدًا أن يستنشق طفلكِ الهواء النقي كل يوم.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'خلّدي اللحظة! 📸', 'حمّلي لحظات اليوم الجميلة إلى ألبوم الطفل، واصنعي ذكريات ستنظرين إليها وتبتسمين في المستقبل.'),
  ('1af46170-3a5b-41ea-bb18-ce899698f996', 'يومكِ الأول مبارك! 🥳', 'ابدئي باستخدام المؤقت في تطبيق Anacan لمتابعة نمط نوم طفلكِ وتغذيته.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'استريحي أنتِ أيضًا عندما ينام طفلكِ! 😴', 'لا تنسي تسجيل شعوركِ اليوم في يوميات المزاج.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'اللبأ هو اللقاح الأول! 🤱', 'سجّلي نمط تغذيتكِ بسهولة باستخدام أداة متابعة التغذية في التطبيق.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', 'لا تحزني ظنًا منكِ أن حليبكِ قليل! 🥛', 'لا تزال معدة طفلكِ بحجم حبة الكرز. يمكنكِ متابعة إحصاءات التغذية اليومية في التطبيق.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'خصّصي وقتًا لنفسكِ. 💆‍♀', '️ تتعافى عضلات رحمكِ. استرخي من خلال تسجيل مشاعركِ اليوم في يوميات المزاج.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'الطبقة البيضاء على بشرة طفلكِ تحميه. 👶 لا تقلقي.', 'لا تنسي تسجيل تغيير الحفاض في Anacan والتحقق من المعدلات الطبيعية!'),
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c', 'منعكس المص لدى طفلكِ قوي جدًا! 🍼', 'تابعي مدة كل رضعة باستخدام المؤقت للتأكد من حصوله على كفايته من الحليب.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'هل تشعرين برغبة في البكاء من دون سبب؟ 😢', 'هذا طبيعي تمامًا! يمكنكِ مشاركة مشاعركِ والحصول على الدعم عبر Anacan AI أو مجتمعنا.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'التوازن بين النوم والرضاعة. 📚', 'هل قرأتِ أحدث مقالاتنا عن نمو حديثي الولادة في قسم المدونات؟'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'تهانينا، لقد بلغ طفلكِ أسبوعين! 🎈', 'للاحتفال بهذه المناسبة الصغيرة، استخدمي الأفكار المميزة في قسم جلسات تصوير الأطفال.'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'قد تستغرق الرضاعة وقتًا أطول أحيانًا. 🍼', 'استخدمي المؤقت لتحليل العملية. الأهم أن تشعرا أنتِ وطفلكِ بالراحة.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'كيف تشعرين؟ 🧘‍♀', '️ الأمومة جميلة ومتعبة في آنٍ واحد. افتحي مفكرة المزاج وقيّمي شعوركِ اليوم.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'ما الذي ينقصكِ للعناية بطفلكِ؟ 🧴', 'اكتشفي في قسم المنتجات الموصى بها منتجات جرّبتها أمهات أخريات ونالت إعجابهن.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'أصبح تغيير الحفاض روتينًا الآن! 👶', 'اطمئني على صحة طفلكِ بتسجيل عدد مرات التبول والتبرز يوميًا في متتبع الحفاضات.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'تحتاج الأم إلى الراحة أيضًا! 🛋', '️ إذا كنتِ قد سجلتِ نمط نوم طفلكِ باستخدام المؤقت، فقد حان دوركِ الآن. حضّري لنفسكِ كوبًا من الشاي واسترخي.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'هل بدأت نوبات المغص والغازات؟ 🌪️', 'لا تقلقي. دلّكي بطن طفلكِ برفق وشغّلي الضوضاء البيضاء في الخلفية لتشتيت انتباهه.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'هل تواجهين صعوبة في تنويم طفلكِ؟ 🎶', 'شغّلي أداة الضوضاء البيضاء في تطبيقنا، لينعم طفلكِ بنوم عميق كما كان في رحمكِ.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'يجب أن تبقى سُرّة طفلكِ جافة ونظيفة. ⏱️', 'إذا ابتلّت سُرّة طفلكِ، فيجب تجفيفها جيدًا واستخدام المحلول المطهّر الذي وصفه الطبيب يوميًا.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'من المهم جدًا أن تتناولي أطعمة غنية بالفيتامينات! 🥗', 'تصفّحي قسم الوصفات الصحية واستعيدي قوتكِ.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'إنه يتعرّف إليكِ من رائحتكِ وصوتكِ! 👃', 'لذلك، عندما تغادرين الغرفة، قد يشعر طفلكِ بالقلق وعدم الأمان.'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', 'لا تصدّقي خرافة أن طفلكِ سيعتاد على الحمل بين ذراعيكِ! 🤗', 'أكثري من احتضانه؛ فهذا سيقوّي الرابطة بينكما ويساعد أيضًا على زيادة إدرار حليبكِ.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'هل اختلط عليكِ الليل والنهار؟ 🛌', 'تابعي نمط النوم والمعدلات اليومية عبر التطبيق، وأغمضي عينيكِ أنتِ أيضًا عندما ينام طفلكِ.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'تبدأ الفحوصات الدورية. 💉', 'أدخلي بيانات طول طفلكِ ووزنه في متتبّع النمو لإنشاء مخطط نمو خاص به!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'المؤقّت هنا كي لا تنسي الفواصل الزمنية. 🍼', 'نظّمي مواعيد تغيير الحفاض والرضاعة بسهولة مع Anacan.'),
  ('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c', 'لستِ مضطرة لأن تكوني أمًا خارقة! 🦸‍♀', '️ لا تترددي في طلب المساعدة. ولتعزيز حافزكِ، اقرئي المقالات الموجودة في قسم المدونات لدينا.'),
  ('ded576fe-d3fa-4078-9b83-36eaf5b495d5', 'تابعي نموه خطوة بخطوة. 📏', 'هل نسيتِ إدخال بيانات محيط الرأس والطول والوزن في متتبّع الوزن؟ سجّليها الآن.'),
  ('0240c7db-30e2-4d5b-86a4-0b27f230557c', 'ذراعا الأب 🫂', 'لقد تسلّل إرهاق الأسبوع الأول إلى أعماقكِ. دعي الأب هذا المساء يُنيم الطفل على صدره ويشغّل الأصوات البيضاء. أما أنتِ، فخذي حمامًا دافئًا، وانسي كل شيء خلف الباب وتحت الماء لمدة 15 دقيقة فقط. أنتِ قادرة على ذلك.'),
  ('7449500c-dd2f-4529-a9a7-67ddeee4fe31', 'حان وقت الاستلقاء على البطن! 🐢', 'ضعيه على بطنه لمدة 1-2 دقيقة في أثناء استيقاظه لتقوية عضلاته.'),
  ('74dae015-c762-4d96-ad34-7d706065ef5f', 'تهانينا، لقد مرّ أسبوع على أمومتكِ! 🥳', 'تهانينا، لقد مرّ أسبوع على أمومتكِ! 🥳 استعيني بقسم جلسة تصوير طفلكِ لإنشاء صورة تذكارية لهذا اليوم المميز.'),
  ('7c7a5fbe-09ea-4f4c-a054-883ad490f939', 'هل نلقي نظرة على إحصاءات الأسبوع الأول؟ 📊', 'هل ترغبين في الاطّلاع على إحصاءات النوم والحفاضات والتغذية الأسبوعية في تطبيق Anacan؟'),
  ('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c', 'التعافي الجسدي 🩹', 'لا يزال جسدكِ في مرحلة التعافي، وربما تؤلمكِ الغرز أيضًا. لا تطالبي نفسكِ بالكمال.'),
  ('d83a6f20-2dc5-45c9-9550-38fedec5c042', 'بدأت البكتيريا النافعة في أمعائه بالتكوّن! 🦠', 'إذا بدأت تقلصات الغازات، فستساعده الإيقاعات الموجودة في قسم الأصوات البيضاء في Anacan على الهدوء.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'تقريركِ اليومي جاهز! 📊', 'ادخلي إلى تطبيق Anacan واطّلعي على تحليل مخططات نوم طفلكِ وتغذيته وتغيير حفاضاته اليوم.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'لنتابع مرحلة النمو! 📏', 'يقترب الشهر التالي. ادخلي إلى قسم متابعة النمو في التطبيق وتأكدي من تحديث البيانات.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'مرّ ٢٠ يومًا على وجودكما معًا! 🥰', 'أنتِ أم رائعة! خلّدي هذا اليوم بصورة جميلة باستخدام أداة جلسة تصوير الطفل.'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'مشاعر إيجابية فقط اليوم! ✨', 'افتحي يوميات مزاجكِ ودوّني اللحظة التي أضحككِ فيها طفلكِ أكثر من غيرها. Anacan AI يستمع إليكِ!'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'فترة طفرة في النمو! 📈', 'قد يشعر طفلكِ بالجوع بوتيرة أكبر. تابعي رضعاته باستخدام مؤقت التغذية.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'هل يزداد الانزعاج مساءً؟ 🎶', 'قد يكون السبب مغص الغازات أو التعب. هدّئي طفلكِ بأصوات الطبيعة الموجودة في قسم الضوضاء البيضاء.'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'أتمّ ٣ أسابيع بالضبط! 🎉', 'احتفلي بهذه المناسبة الصغيرة لطفلكِ وخلّدي لحظة لطيفة باستخدام قسم جلسة تصوير الطفل.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'لا تنسي نفسكِ! 🥗', 'صحتكِ من صحة طفلكِ. اختاري من الوصفات الصحية للنساء وجبة خفيفة تساعدكِ على استعادة طاقتكِ.'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'اقرئي وتعلّمي كلما سنحت لكِ الفرصة. 📚', 'تنتظركِ في قسم المدوّنات أكثر المقالات فائدة حول نمو حديثي الولادة والعناية بهم.'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'يقترب موعد فحص الشهر الأول. ⚖️', 'تأكدي من تسجيل زيادة وزن طفلكِ وطوله حتى الآن في قسم تتبّع النمو.'),
  ('eabf6802-121e-4850-8036-ab2dbabaf84e', 'لا تترددي في مشاركة مشاعركِ. 📝', 'هل تشعرين بالتعب أم بالسعادة؟ لا يهم، دوّني مشاعركِ اليوم في مفكرة المزاج لتشعري بالارتياح.'),
  ('2b4adff1-6ebf-471c-9dc4-e4e39cc16323', 'انتباهه يزداد! 👀', 'أصبح الآن أكثر قدرة على تمييز الألوان المتباينة بالأبيض والأسود. لا تنسي استخدام بطاقات تنمية الذكاء خلال وقت الاستلقاء على البطن.'),
  ('5e1b47e3-2994-433f-a7c8-b1e6a121de30', 'هل نسيتِ من أي ثدي أرضعتِ طفلكِ؟ 🤱', 'سجّلي باستخدام المؤقت ما إذا كنتِ ترضعين من الثدي الأيمن أم الأيسر، ودعي أداة تتبّع الرضاعة تتذكر كل شيء!'),
  ('8152dc55-7f72-41b2-bb12-02cf7745f75a', 'نُشرك الآباء أيضًا في هذه الرحلة! 👨‍🍼', 'من خلال وضع الشريك، يمكن للآباء أيضًا متابعة نمو الطفل.'),
  ('77ad5a07-cc0a-4fb4-b323-d177412300b1', 'إحصاءاتكِ الأسبوعية جاهزة! 📊', 'افتحي التطبيق لتحليل مدى التزامكِ خلال الأيام الأخيرة بمعدلات النوم والرضاعة الموصى بها.'),
  ('8fac7e6d-3d63-4646-99a7-c927a088e849', 'الهواء النقي يفتح الشهية! 🌳', 'احرصي على اصطحاب طفلكِ إلى الهواء الطلق يوميًا. فهذا مفيد جدًا لكِ ولطفلكِ على حد سواء.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'حان وقت الاستلقاء على البطن! 🐢', 'يساعد الاستلقاء على البطن بضع دقائق يوميًا على تقوية عضلات رقبة طفلكِ.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'الاستعداد للنوم ليلًا. 🌙', 'اضبطي درجة حرارة الغرفة قبل النوم وشغّلي مؤقت النوم في Anacan.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'أسرار تساعد على زيادة إدرار حليبكِ! 🥛', 'تنتظركِ في قسم الوصفات الصحية أطعمة طبيعية تساعد على زيادة إدرار الحليب ووصفات للعصائر المخفوقة.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'قد تكون طفرة في النمو. 📈', 'هل يصرخ طفلكِ ويبكي من دون سبب واضح؟ تتزامن طفرة النمو في الأسبوع الثالث أيضًا مع بلوغ مغص الغازات ذروته. لا تقلقي.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'لا يفارق حضنكِ 🛋️', 'هل يستيقظ طفلكِ ويبكي بمجرد أن تضعيه في مكانه؟ قد تشعرين اليوم بأنكِ عالقة بين أربعة جدران ولا تستطيعين إنزاله من حضنكِ. لكن تذكّري أن حضنكِ هو المكان الأكثر أمانًا لطفلكِ. تحلّي بالصبر.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'أشركي زوجكِ أيضًا في هذه المرحلة. 👨‍👩‍👦', 'دعيه يتولى هذا المساء مهمة تغيير الحفاض أو تنويم طفلكِ باستخدام الضوضاء البيضاء، وخذي أنتِ قسطًا من الراحة.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'حان وقت العناية بالبشرة. 🛁', 'هل تبحثين عن كريمات تناسب بشرة طفلكِ الحساسة؟ ستساعدكِ قائمة المنتجات الموصى بها.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'ردود الفعل الانعكاسية تتطور! 🖐️', 'هل لاحظتِ مدى قوة إمساك طفلكِ بإصبعكِ؟ اكتشفي مقالاتنا في قسم المدونات لمعرفة المزيد عن ذلك.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'معدل النوم اليومي مهم. 😴', 'شغّلي مؤقت النوم عندما ينام رضيعكِ، وتحققي من مدى توافق نومه مع المعدل اليومي.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'يحاول رفع رأسه! 🐢', 'أضيفي إلى ألبوم طفلكِ مقطع فيديو لحركاته أثناء استلقائه على بطنه (tummy time).'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'هل لديكِ سؤال؟ 🤖', 'Anacan AI مستعد دائمًا لمساعدتكِ في الإجابة عن الأسئلة التي تشغل بالكِ، مثل: لماذا يستيقظ كثيرًا ليلًا؟'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'كيف هو معدل تغيير الحفاض اليومي؟ 🧷', 'تُعدّ سجلات تغيير الحفاض أسهل طريقة لمعرفة ما إذا كان رضيعكِ يحصل على تغذية كافية. سجّليها الآن في التطبيق!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'ابتسامته الأولى تقترب! 😊', 'لا تفوّتي اللحظات التي يتأمل فيها وجهكِ باهتمام. اكتبي في يوميات المزاج المشاعر التي تمنحكِ إياها هذه اللحظات.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'لنبدأ بإنشاء روتين! 🌙', 'حمّميه وأرضعيه في الموعد نفسه، ثم شغّلي الضوضاء البيضاء وابدئي مؤقت النوم.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'لا تنسي احتياجاتكِ كأم. 🛍', '️سيساعدكِ استخدام كريم الحلمات ووسادات الثدي على الشعور براحة أكبر وتوفير الحماية اللازمة.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'حان وقت التنزه في الهواء الطلق! ☀️', 'هل تبحثين عن مكان مناسب للذهاب إليه مع طفلكِ والاسترخاء براحة؟ لا تفوّتي الاطلاع على مدونتنا عن الأماكن الصديقة للأمهات.'),
  ('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124', 'حسّني جودة حليبكِ. 🍲', 'للاستمتاع بغذاء صحي ولذيذ، اطّلعي على قسم الوصفات الصحية في التطبيق.'),
  ('15d59560-fd44-4273-9de7-62fd70c1a0dd', 'قياسات عمر الشهر الأول! 📏', 'أضيفي بيانات الطول والوزن الجديدة إلى متتبّع النمو، وشاهدي مخطط النمو الصحي بكل فخر.'),
  ('22b47ac3-665d-4f67-b497-67efe6238be4', 'تهانينا، لقد بلغنا شهرًا واحدًا! 🥳', 'للاحتفال بهذا اليوم المميز، أنشئي صورًا ممتعة في قسم جلسة تصوير الطفل.'),
  ('ed8acfc1-dd31-48da-a8f2-04bd91f60de7', 'اشكري نفسكِ! 💖', 'لقد اجتزتِ الشهر الأول والأصعب. ادخلي إلى مفكرة المزاج ودوّني إنجازكِ البطولي خلال هذا الشهر.'),
  ('2037f6e8-905d-4847-8172-fdba3ba09cf5', 'هل يختل الروتين المسائي؟ 🌙', 'لا تقلقي. اختاري صوت نبضات القلب من قسم الضوضاء البيضاء ليشعر طفلكِ بالأمان كما كان في رحمكِ.'),
  ('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8', 'أحيانًا نحتاج فقط إلى استراحة. ☕', 'عندما ينام طفلكِ، فعّلي مؤقت النوم وخصّصي لنفسكِ بعض الوقت الهادئ.'),
  ('b61a8e62-d1c0-449f-9d5b-6bb72079c512', 'تزداد مدة البقاء مستيقظًا. ⏱️', 'اقرئي اقتراحات الألعاب في قسم المدونات لتلعبي معه وتدعمي نموه.'),
  ('111e6f27-8aef-4cfb-a5ab-60fea52474e0', 'الاستعداد للشهر المقبل. 🛒', 'إذا كنتِ تبحثين عن حفاضات ومنتجات عناية مناسبة للشهر الجديد، فستجدين بالتأكيد ما يساعدكِ في قسم المنتجات الموصى بها.'),
  ('713d2aac-0316-483d-9c46-781631bb7e21', 'أنتِ أمّ رائعة! ✨', 'لقد مضى على وجودكما معًا 30 يومًا. أضيفي إلى ألبوم طفلكِ صورة مجمّعة تُظهر الفرق بين يومه الأول واليوم.'),
  ('ef07a5ff-817b-4b0a-ad2a-706e799bad22', 'شهر جديد، صفحة جديدة. 📊', 'اطّلعي على إحصاءات الرضاعة والنوم والحفاضات الشهرية، وشاهدي كيف نجحتِ في تنظيم روتين طفلكِ بشكل رائع!'),
  ('282baeb2-eb26-44cb-9eff-2eb2d88677a2', 'تخلّصي من إرهاق اليوم. 🛁', 'خصّصي بعض الوقت لنفسكِ واسترخي بتدوين مشاعركِ اليوم في مفكرة المزاج.'),
  ('5366cee2-8491-4a45-8d5c-88d78aa6eee0', 'لقد دخلنا الشهر الثاني! 🎊', 'تحدّثي إلى طفلكِ على مدار اليوم لدعم نموه وتطوره.'),
  ('c5b12eaa-4012-417b-bf89-d5bd9d26aee9', 'قد يتغير نمط الرضاعة. 🍼', 'شغّلي مؤقت Anacan لمتابعة شهية طفلكِ والتحقق من كميته اليومية المعتادة.'),
