  ('b67a89c9-d8cf-40c2-97a2-43b27081ed44', 'مجال رؤيته يتّسع! 👀', 'أصبح الآن قادرًا على تتبّع الأشياء بعينيه بشكل أفضل.'),
  ('917836b6-b023-4945-8e64-bc144ba97f42', 'يكتشف أصواتًا جديدة! 🗣️', 'سجّلي مناغاته اللطيفة. واقرئي المدوّنات لمعرفة المزيد عن تطوّر اللغة.'),
  ('d31b874f-e957-475e-a461-b294c96db59f', 'هل ما زال يستيقظ ليلًا؟ ⏱️', 'سجّلي كل مرة يستيقظ فيها باستخدام مؤقّت النوم لتحليل نمط نومه العام ومعدّله اليومي.'),
  ('d491dc2d-f6b9-49dd-8461-5cbffee476e5', 'لا تنسي نفسكِ! 🥗', 'طاقة الأم مهمة جدًا. اختاري وجبة غنية بالفيتامينات من وصفاتنا الصحية للنساء واستعيدي نشاطكِ.'),
  ('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c', 'ما الذي يقلقكِ؟ 🤖', 'اطرحي أي سؤال على مساعدنا Anacan AI، حتى خلال ساعات الليل، واحصلي على دعم متخصص.'),
  ('f710f746-b942-4fd7-a8ca-dd9b5a248195', 'لنراجع متتبّع الحفاضات. 🧷', 'سجّلي عدد الحفاضات اليومي في Anacan للتأكد من أن رضيعكِ يحصل على تغذية كافية.'),
  ('fa5fc8d8-4263-4a99-9f46-297b1d6ea219', 'أصبح يرفع رأسه بثبات أكبر! 🐢', 'حوّلي تمارين الاستلقاء على البطن إلى وقت ممتع.'),
  ('42ca0f3b-8083-4338-bf16-9998a33b15c6', 'حان وقت الهواء الطلق! 🌳', 'افتحي خريطة الأماكن الملائمة للأمهات واعثري على المكان الأكثر راحة للذهاب إليه برفقة طفلكِ.'),
  ('7fc52d97-b36d-4c5e-a169-0eadba238b0e', 'متابعة الوزن والطول. 📏', 'كيف ينمو طفلكِ؟ أدخلي البيانات الجديدة في متتبع الوزن وتابعي مخطط نموه الشخصي.'),
  ('df56b34d-b5f8-476f-a65e-11a244242a2f', 'روتين ما قبل النوم. 🛁', 'حمّمي طفلكِ، وأرضعيه، وشغّلي مؤقت النوم. دعي كل شيء يسير بسلاسة وراحة وفق الخطة!'),
  ('0c1e843a-b2dc-4995-89cf-7af4230d574e', 'يكتشف يديه! 👐', 'أصبح الآن ينظر إلى أصابعه ويضعها في فمه.'),
  ('3cf29d40-9703-4e58-8a17-b7e68f86c3fa', 'هل تبحثين عن مستلزمات العناية أم لعبة؟ 🧸', 'اعثري بسهولة على منتجات آمنة تدعم نموه ضمن قائمة المنتجات الموصى بها.'),
  ('e6e49938-5987-45e7-8021-a8d016100be4', 'كيف تشعرين؟ 💖', 'هل شعرتِ بالتعب طوال اليوم أم كنتِ مفعمة بالنشاط؟ افتحي مفكرة المزاج وسجّلي كيف مضى يومكِ.'),
  ('814305c3-77b7-491e-ae0f-134875923d1a', 'من أي جهة أرضعتِ طفلكِ؟ 🤱', 'يتذكر مؤقت Anacan نيابةً عنكِ ما إذا كانت الرضاعة من الثدي الأيمن أو الأيسر. ابدئي جلسة الرضاعة الآن!'),
  ('910b6936-83b0-441d-abe5-33c85153dffe', 'ابتسامة الصباح! 😊', 'تضفي ابتساماته الاجتماعية جمالًا على يومكِ. خلّدي هذه الفرحة في ذاكرتكِ من خلال جلسة تصوير لطفلكِ.'),
  ('fcecf920-146e-4152-abc5-066ce8392fd8', 'أصوات مهدئة. 🎶', 'إذا كان طفلكِ يعاني من مغص الغازات أو التعب، فسيهدئه صوت دقات القلب ضمن الضوضاء البيضاء فورًا، كما لو كان في رحم أمه.'),
  ('2776b020-9972-4e23-acb7-6a529664582d', 'يبحث عن صوتكِ! 👂', 'تحدّثي معه كثيرًا وتواصلي معه بصريًا. تعرّفي في قسم المدونات على أنشطة متنوعة تدعم نموه.'),
  ('72abc90e-b301-468a-9629-3f3bb7949709', 'هل لديكِ تساؤلات حول رعاية رضيعكِ؟ 🤖', 'سيستمع إليكِ مجتمع Anacan دون إصدار أحكام، وسيقدّم لكِ النصيحة الأنسب.'),
  ('816ef2cf-32b6-4eba-b12b-4e8f7936a78f', 'ادعمي إدرار حليبكِ. 🥛', 'لا تنسي شرب الكثير من الماء! ويمكنكِ أيضًا تحضير مشروب مُدرّ للحليب من قسم الوصفات الصحية للنساء.'),
  ('1501b0ff-9742-40e2-9aae-ff2e8f8e5188', 'حان وقت نزهة عائلية! ☕', 'لاستثمار وقت فراغكِ جيدًا، اختاري مقهى أو مطعمًا مريحًا من قسم الأماكن الصديقة للأمهات.'),
  ('427917df-21f2-46c9-a030-52d511e37ce5', 'التقرير اليومي. 📊', 'كم ساعة نام اليوم، وكم مرة رضع؟ اطّلعي على الإحصاءات الإجمالية لليوم في الرسوم البيانية داخل التطبيق.'),
  ('c555165e-a5c9-4e8c-9a72-cf4d0a16a367', 'لا ننسى الآباء أيضًا! 👨‍🍼', 'استمتعي باللحظات اللطيفة والمرحة التي يقضيها طفلكِ في اللعب مع والده.'),
  ('052bbdef-be6b-4b3f-bf88-905af0d4abc5', 'تحتاجين إلى الراحة أحيانًا. 🛋', '️ فعّلي مؤقت النوم عندما ينام، وخصّصي وقتًا لنفسكِ فحسب دون القيام بأي عمل.'),
  ('1053981f-f622-407a-ade7-529fc27bb2ff', 'نتابع مرحلة نموه! ⚖️', 'يوشك الشهر الثاني على الانتهاء. ادخلي إلى قسم متابعة الوزن في التطبيق وتأكدي من تحديث أحدث البيانات.'),
  ('8f5fde4a-3542-4bb1-be02-6df262d75b50', 'هل كل شيء على ما يرام؟ 📝', 'كيف حالكِ؟ هل تشعرين بالتعب أم بالنشاط؟ مفكرة المزاج من Anacan هي أفضل رفيقة رقمية تحفظ أسراركِ.'),
  ('292a637a-a0ca-4e58-8523-7b2c8b754743', 'نهاية شهر جميل. ✨', 'خفّفي إضاءة الغرفة، وشغّلي الضوضاء البيضاء، وافخري بطفلكِ وهو نائم. أنتِ أم مثالية!'),
  ('39c9a98b-8f4e-4896-9385-5588121bd72d', 'تهانينا، لقد أتممنا شهرين بالضبط! 🎈', 'أنشئي صورة تذكارية في جلسة تصوير الطفل للاحتفال بهذه اللحظة الرائعة!'),
  ('3c5f5d9f-939f-4c7e-9bc8-1feef640d854', 'تقرير نمو الشهرين. 📈', 'اطّلعي على متتبّع الوزن وإحصاءات الحفاضات والتغذية، وشاهدي كيف نما طفلكِ بصحة جيدة خلال هذه الأيام الـ60.'),
  ('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae', 'تخلّصي من إرهاق اليوم. 🛁', 'خصّصي وقتًا لنفسكِ، واشعري بالراحة من خلال تدوين مشاعركِ الداخلية اليوم في مفكرة المزاج.'),
  ('59aa01c0-7e8d-4375-9fcd-733a242d640c', 'لنحافظ على نظام التغذية. 🍼', 'قد تزداد شهية طفلكِ. شغّلي مؤقت Anacan وتحقّقي من كمية التغذية المناسبة باستخدام أداة متابعة التغذية.'),
  ('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a', 'اليوم الأول من الشهر الثالث! 🎉', 'أصبح طفلكِ الآن يراقب ما حوله بوعي أكبر.'),
  ('8d26cab1-ebfd-469f-9ae0-aa66e0f36761', 'هل أصبح الاستغراق في النوم أصعب؟ 🌙', 'أظلمي الغرفة، واختاري صوت أمواج المحيط من الضوضاء البيضاء لتهيئة طفلكِ لنوم عميق.'),
  ('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4', 'حان وقت التنزه في الهواء الطلق. 🌳', 'التنزه في الهواء الطلق مهم جدًا لنمو طفلكِ وراحته.'),
  ('b6825824-6eff-4740-b6c1-dc607b41b996', 'يمد يديه نحو الألعاب! 🧸', 'ما أمتع متابعة هذه الاكتشافات الصغيرة! حمّلي مقاطع الفيديو التي تصورينها أثناء اللعب معه إلى ألبوم الطفل.'),
  ('1ed5f326-68dd-494e-a31c-2d3466644cd0', 'مصدر للطاقة للأمهات! 🥗', 'اختاري وصفة غنية بالفيتامينات من قسم الوصفات الصحية لمساعدتكِ على التعافي ودعم إدرار الحليب.'),
  ('59041ede-10ec-4754-8f5f-31f415db3701', 'تزداد أصوات المناغاة «آغو»! 🗣️', 'تزداد محاولات طفلكِ للتواصل معكِ. اقرئي المقالات في قسم المدونات لدعم تطور مهاراته اللغوية.'),
  ('d7b0c908-0d97-40c6-a82a-c5283f30a1d8', 'تابعي معدلات نومه. ⏱️', 'شغّلي مؤقت النوم عندما ينام طفلكِ، وتحققي مما إذا كان يحصل على معدل نومه اليومي.'),
  ('5309698d-6050-4993-9a68-ab592375ed60', 'بدأت الغدد اللعابية بالعمل! 💧', 'قد يفرز طفلكِ الآن كمية أكبر من اللعاب.'),
  ('83d11db6-0443-4d69-8d55-9ea20f0cf905', 'لنتابع مرحلة نموه! 📏', 'حدّثي مخطط نموه الشخصي بإدخال بيانات الوزن والطول للأسبوع المقبل في متتبع الوزن.'),
  ('ca5bc974-1377-4065-9dfa-50549135eb55', 'هل هناك ما يقلقكِ؟ 🤖', 'اطرحي أسئلتكِ مثل «لماذا كانت مدة نومه قصيرة اليوم؟» على مساعد Anacan AI حتى في ساعات الليل.'),
  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'الابتسامات الاجتماعية! 😊', 'ابتسامته اللطيفة تُنسيكِ كل تعبكِ.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'إحصاءاتكِ الأسبوعية جاهزة! 📊', 'ادخلي إلى التطبيق لتحليل مدى التزامكِ خلال الأيام الأخيرة بمواعيد النوم والرضاعة.'),
  ('aba537d3-5a0f-4b17-b02b-4754b93f711f', 'هل نسيتِ من أي ثدي أرضعتِ طفلكِ؟ 🤱', 'سجّلي باستخدام المؤقت ما إذا كنتِ ترضعين من الثدي الأيمن أو الأيسر، ودعي Anacan يتذكّر كل شيء نيابةً عنكِ!'),
  ('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8', 'تتغير القيلولات النهارية. ⏱️', 'أنشئي روتينًا جديدًا من خلال قياس مدة الاستيقاظ والفواصل باستخدام متتبّع الرضاعة ومؤقتات النوم.'),
  ('32ff20f3-f1f8-47fd-b3be-c14bea1452a2', 'العلاج الصوتي للتهدئة. 🎶', 'إذا كان رضيعكِ منزعجًا هذا المساء، فشغّلي صوت نبضات القلب من قسم الضوضاء البيضاء لتشتيت انتباهه وتهدئته.'),
  ('a061022a-6a47-4aae-8590-2f0f328fbf09', 'حان وقت اللعب! 🎈', 'اقرئي نصائح الألعاب التنموية في قسم المدونات لتتعرّفي إلى كيفية قضاء وقت ممتع ومفيد معه.'),
  ('b95ca7be-8491-4bbc-afb0-321f795780ea', 'هل تحتاجين إلى التسوق؟ 🛍', 'اعثري بسهولة في قائمة المنتجات الموصى بها على ألعاب ومستلزمات آمنة ومناسبة لعمر طفلكِ في هذا الشهر.'),
  ('633e342d-82b1-442c-9da8-5c5326907322', 'تحليل اليوم. 📈', 'حلّلي بيانات متتبّع الرضاعة ومخططات النوم، وشاهدي كيف يتشكّل روتينكِ بصورة رائعة.'),
  ('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc', 'تقاسما رعاية طفلكِ مع الأب. 👨‍🍼', 'بعد الرضعة المسائية، دعي الأب يتولى مساعدة طفلكِ على التجشؤ ووضعه للنوم، وخذي أنتِ قسطًا من الراحة.'),
  ('a6843443-e0f6-4ec7-a4ec-03cb5d81d392', 'تمارين الاستلقاء على البطن تصبح أسهل. 🐢', 'أصبح طفلكِ الآن قادرًا على إبقاء رأسه مرفوعًا باستقامة مدة أطول. أدرجي هذا النشاط ضمن روتينكما اليومي.'),
  ('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d', 'لنتابع عدد الحفاضات يوميًا. 🧷', 'للتأكد من أن طفلكِ يحصل على ما يكفي من الغذاء، واصلي تسجيل كل مرة تغيّرين فيها حفاضه في Anacan.'),
  ('7764e41d-176a-41d8-8f87-2a21677a36ee', 'لنُنشئ روتينًا ثابتًا. 🛁', 'حمّمي طفلكِ وأرضعيه في الموعد نفسه كل مساء، وشغّلي مؤقت النوم لتساعديه على تكوين نمط نوم صحي.'),
  ('9754280d-c633-46e8-94c9-6f16ff032551', 'لا تنسي نفسكِ يا عزيزتي! 🍲', 'تصفّحي قسم الوصفات الصحية في تطبيق Anacan، وحضّري لنفسكِ اليوم طبقًا شهيًا.'),
  ('c1c4c9b0-cdd8-4321-a494-3bb43739df94', 'إنه يعرفكِ ويميّز صوتكِ! 😍', 'لاحظي مدى سعادته عندما تدخلين الغرفة. 😊'),
  ('149e95b1-a682-4369-8b74-5827cc5d31dc', 'لا تترددي في التعبير عن مشاعركِ. 📝', 'هل تشعرين بالتعب أم بالنشاط؟ لا يهم، دوّني مشاعركِ اليوم في مفكرة المزاج لتشعري بالارتياح.'),
  ('79b7fb29-fa37-4176-9ae5-409d73ee982e', 'راحة حتى خارج المنزل. ☕', 'هل ترغبين في احتساء القهوة مع صديقاتكِ؟ لا تغادري المنزل قبل الاطلاع على خريطة الأماكن الملائمة للأمهات.'),
  ('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a', 'نحن فريق واحد! 💪', 'هل تشعرين أحيانًا بالوحدة وبأن لا أحد يفهمكِ؟ انضمي إلى مجتمع Anacan، حيث توجد آلاف الأمهات اللواتي يشاركنكِ المشاعر نفسها. شاركيهن اليوم إحدى تجاربكِ.'),
  ('60059890-bf5b-4e0b-ba41-fedc82fa6a43', 'حان دور الأب 👨‍🍼', 'تخلّصي من إرهاق اليوم. أعطي طفلكِ لوالده ودعيه يتولى تنويمه هذا المساء، بينما تحضّرين لنفسكِ كوبًا من الشاي الدافئ وتستمتعين بمشاهدة هذا المنظر.'),
  ('b1778419-cb70-4711-96e0-a612732e8575', 'ابتسامات مليئة باللعاب 🤤', 'هل يسيل لعاب طفلكِ كثيرًا ويضع يديه في فمه طوال الوقت؟ ابدئي بتسجيل ملاحظاتكِ الأولى في متتبّع التسنين. نعم، تبدأ هذه الاستعدادات المثيرة مبكرًا!'),
  ('0eb4da19-cb98-497a-a36b-a4934f47e071', 'مراقبة الهدوء 🤫', 'هل نام طفلكِ للتو، لكنكِ تخشين أن توقظه ضوضاء المنزل؟ فعّلي أداة قياس الصوت وراقبي مستوى الديسيبل في الغرفة لحماية نومه.'),
  ('9cab0c58-8a4f-4869-b607-be3e284373f0', 'هل لديكِ سؤال؟ 🤖', 'هل يشغل بالكِ أمر ما وسط مسؤولياتكِ اليومية؟ التغذية أو النوم أو الغازات... أيًا كان، اسألي Anacan AI فورًا واحصلي على إجابة علمية دقيقة.'),
  ('e6d33eab-abbe-4eca-94e9-c05138d06c07', 'انظري، أنا هنا! 👀', 'أصبح الآن يتابعكِ باهتمام حتى من الطرف الآخر للغرفة. سجّلي هذا التقدم الرائع في التواصل البصري ضمن متتبّع النمو، وافتخري بتطوّره!'),
  ('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa', 'أحلام مرصّعة بالنجوم 🌌', 'يحب الأطفال الروتين. أنشئي له حكاية خاصة في قسم الحكايات الذكية.'),
  ('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9', 'أنتِ رائعة! 🌸', 'هل تشعرين أحيانًا بأنكِ لا تستطيعين إنجاز أي شيء؟ لكن انظري إلى طفلكِ وهو يتنفس بهدوء وعافية... أنتِ تبذلين قصارى جهدكِ!'),
  ('faace99e-5074-497e-b5c0-f25a9880f5b0', 'طاقة الأم 🍲', 'وسط انشغالاتكِ اليومية، هل تذكّرتِ تناول طعامكِ؟ اختاري من قسم الوصفات الصحية وصفة شوربة سريعة تساعدكِ على استعادة طاقتكِ وزيادة إدرار الحليب.'),
  ('1cd41578-3422-4bf8-9401-e9a058dcad6f', '١٥ دقيقة فقط 🛁', 'هل نام طفلكِ؟ وجّهي الآن جميع الإشعارات إلى شريككِ عبر وضع الشريك، ثم ادخلي الحمّام واستمتعي بـ١٥ دقيقة من الماء الدافئ والهدوء.'),
  ('73a10da9-aef9-4c21-b8d7-bca1f62e8528', 'مشاركة التجارب 💬', 'ما الحركة التي يفعلها طفلكِ وتضحككِ أكثر في الأيام الأخيرة؟ ادخلي إلى مجتمع Anacan وشاركي هذه اللحظة في منشور. ستشعرين أيضًا بالراحة عند قراءة قصص الأمهات الأخريات.'),
  ('acfd33be-87a0-41a3-858d-d5921f61d9a4', 'اكتشاف اليدين 👋', 'هل بدأ طفلكِ يكتشف يديه ويتأملهما لساعات؟ لا تفوّتي هذه اللحظة الطريفة والمذهلة من مراحل نموه، والتقطيها فورًا وخلّديها باستخدام جلسة تصوير الطفل!'),
  ('36b1e2d3-b43a-467e-b08f-870a612d1bb5', 'شفرة البكاء 🧩', 'طفلكِ ليس جائعًا وحفاضه نظيف، لكنه لا يزال منزعجًا؟ إذا كنتِ تجدين صعوبة في معرفة السبب، فاستخدمي تحليل البكاء لتكتشفي الحاجة الحقيقية وراء هذا الصوت.'),
  ('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee', 'التصالح مع التعب 💖', 'المنزل فوضوي والطعام طُلب عبر الإنترنت؟ لا بأس إطلاقًا. لستِ وحدكِ في هذه الرحلة.'),
  ('8f6c6637-de06-4b9d-8e44-d9e85864f3c8', 'تمارين الصباح 🐢', 'أصبح طفلكِ الآن يرفع رأسه بثبات أكبر! حوّلي وقت الاستلقاء على البطن إلى وقت ممتع. ضعيه أمام المرآة وراقبي ردود فعله تجاه صورته المنعكسة.'),
  ('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74', 'قائمة التذكير 📝', 'لا تنتهي احتياجات المنزل. لا ترهقي ذهنكِ بمحاولة تذكّرها؛ افتحي قائمة التسوق ودوّني فيها ما تحتاجين إليه، ثم شاركي القائمة مع شريككِ بلمسة واحدة.'),
  ('8655d498-c5d9-40f8-bd47-346f815d3e75', 'نهاية حلوة ليوم جميل. 🌙', 'خفّفي إضاءة الغرفة، وشغّلي صوت الرحم من قسم الضوضاء البيضاء، واستمتعي بمشاهدة طفلكِ وهو يغطّ في نوم هادئ.'),
  ('97e88a0b-26cf-486d-a17f-2c34cfc6b47d', 'أنتما معًا منذ 70 يومًا بالضبط! ✨', 'أنتِ أم رائعة! أضيفي إلى ألبوم طفلكِ صورة مجمّعة تُظهر الفرق بين يومه الأول واليوم.'),
  ('05925891-b678-4a87-8f54-39f692aa9143', 'هل توشك المستلزمات على النفاد؟ 🛒', 'هل أوشكت الحفاضات أو المناديل المبللة على النفاد؟ لستِ مضطرة إلى تذكّر كل شيء. أضيفيها الآن إلى قائمة التسوق ليشتريها شريككِ في طريق عودته مساءً.'),
  ('41007feb-f415-4088-b094-428b2275abbf', 'عالم الأصوات الساحر 📖', 'أضيفي لمسة مختلفة إلى الروتين المسائي. أنشئي له حكاية مهدئة باستخدام الحكايات الذكية، واجعلي انتقاله إلى النوم أسرع وأسهل لكليكما.'),
  ('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03', 'حفل الصباح 🎶', 'هل بدأ طفلكِ بإصدار مناغاته الأولى؟ تحدّثي معه بلغته واستجيبي لأصواته. استمتعي اليوم بهذه اللحظة الجميلة فحسب، ولا تتعجلي الذهاب إلى أي مكان.'),
  ('62fbb893-6a1c-4847-a99e-981afea8fa87', 'أنواع مختلفة من البكاء 😭', 'هل يبكي من الجوع أم لقلة النوم؟ لا تقلقي، فلنكتشف معًا خلال ثوانٍ ما الذي تحاول هذه الأصوات التعبير عنه باستخدام أداة تحليل البكاء.'),
  ('83a0ab90-d44d-4758-bd3f-c7126ae6e20f', 'كوني صادقة مع نفسكِ 📝', 'هل أنتِ متعبة جدًا اليوم؟ اكتبي مشاعركِ بصدق في يوميات الحالة المزاجية. لستِ مضطرة إلى أن تكوني مثالية كل يوم، فأنتِ بشر في النهاية.'),
  ('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c', 'ماذا سأُلبس طفلي؟ ⛅', 'هل الطقس متقلب وتخشين أن يشعر طفلكِ بالبرد أو يتعرق؟ تحققي فورًا من أداة الطقس والملابس لتتعرّفي إلى أنسب مجموعة ملابس لطقس اليوم.'),
  ('12a076b6-d8dc-4bec-a8af-ddc523182bad', 'وقت الحكاية 📖', 'من الآن تبدأ رحلة طفلكِ ليصبح واسع الخيال في المستقبل. أنشئي حكاية ساحرة باستخدام الحكايات الذكية، واقرئيها له، وشاهدي عينيه تنغلقان ببطء.'),
  ('58ce6bd9-90fd-4e98-a133-ddfda6d59177', 'طبيب الأطفال في جيبكِ 🤖', 'هل يزداد وزنه جيدًا؟ هل تغيّر لون برازه؟ قبل أن تقلقي، اكتبي إلى Anacan AI، وتعرّفي إلى طبيعة المشكلة، واحصلي على معلومات مطمئنة.'),
  ('5543e602-8610-44ac-8995-56ec74a0576e', 'الهدوء الذكي 🤫', 'من المهم مراقبة مستوى الهدوء في الغرفة للحد من نوبات البكاء المسائية. شغّلي مقياس الصوت، وتجنّبي الأجواء الصاخبة جدًا، وهيّئي طفلكِ للاسترخاء.'),
  ('81600590-d6f0-495d-b852-9afcf35b137a', 'ملابس المستكشف ⛅', 'هل ترغبين في الخروج للتنزّه، لكن حالة الطقس غير واضحة تمامًا؟ استعيني بمساعد الطقس والملابس للعثور خلال ثوانٍ على الإطلالة الأنسب لدرجة حرارة اليوم.'),
  ('fbf2b91a-0a2a-4aa9-9404-589ba5628b25', 'ابتسامة الصباح ☀️', 'هل نظر إليكِ وابتسم ابتسامة عريضة فور أن فتح عينيه؟ لقد حصلتِ على أغلى هدية في العالم. حافظي اليوم على إيجابيتكِ بمجرد التفكير في هذه اللحظة.'),
  ('1f2c4967-df72-43b6-91d0-25ece4f2331b', 'بقي 10 أيام على الحفلة! 🎂', 'استعدّي، فلم يتبقَّ سوى 10 أيام على إتمام الشهر الثالث! إحدى أولى المناسبات الكبيرة تقترب. إنه الوقت المثالي لاختيار فكرة جميلة والبدء بطلب الكعكة!'),
  ('488e046f-44fb-4fcc-80e0-064c20288a56', 'احتفال الفريق 🥂', 'هذا المساء، تبادلي الشكر مع شريككِ على ما بذلتماه من جهد طوال 80 يومًا. لقد نجحتما!'),
  ('720785a0-3423-4036-a26d-bba9419b8cb2', 'اليوم الـ80 الرائع! 🎉', 'لقد مضى على وجودكما معًا 80 يومًا بالتمام! ادخلي إلى قسم جلسة تصوير الطفل، وخلّدي هذا الرقم بملصقات اليوم الـ80 المميزة، وشاركيه في المجتمع كذكرى!'),
  ('42bfdf13-2735-49dc-b527-89506330c670', 'كتفا الأب 👨‍👧', 'هل نفد صبركِ وتعبت ذراعاكِ؟ فعّلي وضع الشريك هذا المساء. فمهمة مساعدة طفلكِ على التجشؤ وحمله والتجول به في الغرفة تقع بالكامل على عاتق الأب. أما أنتِ، فاستريحي على الأريكة فحسب.'),
  ('3d2a21ef-6e5b-4f36-9011-f9c3474762a4', 'ليس جائعًا، فلماذا يبكي؟ 🧩', 'ألا يهدأ مهما فعلتِ، وتبدو نبرة بكائه مختلفة؟ توقفي عن التخمين، ودعي ميزة تحليل البكاء تستمع إلى صوته لتعرفي فورًا ما إذا كانت المشكلة غازات أم قلة نوم.'),
  ('b092d275-f2d6-47ce-b8d0-3f8ced210589', 'سماعات وقهوة 🎧', 'كان اليوم شاقًا حقًا. أفرغي مشاعركِ في مفكرة المزاج. ثم ضعي سماعاتكِ، وشغّلي موسيقاكِ المفضلة، واستمتعي بمشروب ساخن يحتوي على الكافيين وسط هدوء حقيقي لمدة 10 دقائق.'),
  ('c6fb2576-7fa6-4e01-b8a4-ec89ac753089', 'فيضان الصباح 💩', 'هل فتحتِ عينيكِ لتجدي رضيعكِ غارقًا حتى رقبته، وملاءات تحتاج إلى التغيير؟ سجّلي هذه الكارثة الكبرى في متتبع الحفاضات بابتسامة. نعم، هذه أيضًا من تفاصيل الأمومة!'),
  ('022a6d7a-76fe-47e7-aae6-a35dad3d3555', 'احسبي الوقت ⏱️', 'هل ترهقكِ الرضعات غير المنتظمة؟ استخدمي مؤقت تتبع الرضاعة لقياس المدة التي يقضيها طفلكِ على الثدي أو زجاجة الرضاعة، وتعرّفي إلى روتينه الجديد الذي بدأ يتشكل.'),
  ('62da6149-1edf-4e2a-abc6-d69d21a43fa4', 'رفض التمرين الصباحي 🐢', 'هل يرفض الاستلقاء على بطنه (Tummy time) ويبكي؟ لا تجبريه. اسألي Anacan AI: “كيف أجعل وقت الاستلقاء على البطن ممتعًا لطفل يبلغ من العمر 3 أشهر؟” واحصلي على نصائح سريعة.'),
  ('938dd21f-e30f-4b2b-b3e0-d79140f44b59', 'لنبتكر حكاية أخرى! 🪄', 'لنعطِ الحكايات الذكية هذه المرة فكرة أكثر طرافة: “حكاية القزم المختبئ في لحية أبيه”. اطلبي من شريككِ أن يروي هذه الحكاية التي ابتكرها الذكاء الاصطناعي، ولتملأ الضحكات الغرفة.'),
  ('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc', 'الهروب من بين أربعة جدران 🏃‍♀️', 'هل تشعرين بالاختناق في المنزل، لكنكِ لا تعرفين إلى أين تذهبين مع طفلكِ؟ استخدمي ميزة الأماكن الملائمة للأمهات للعثور على أقرب مقهى يسهل دخوله بعربة الأطفال ويضم غرفة للرضاعة، واخرجي لقضاء بعض الوقت والتواصل مع الآخرين.'),
  ('7d54b8de-cc42-4891-b97a-5856eefffe9d', 'حكايتكِ الخاصة تُنسج الآن 🪄', 'ليكن طفلكِ بطل حكاية هذا المساء! ادخلي إلى أداة الحكايات الذكية واكتبي موضوعًا: «مغامرة الفارس الصغير الذي لا يريد النوم ليلًا». دعي الذكاء الاصطناعي يبتكر لكِ وحدكِ قصة فريدة ولطيفة.'),
  ('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a', 'هل أنتِ مستعدة للحوار؟ 🗣️', 'لم يعد طفلكِ يكتفي بإصدار الأصوات، بل يحاول الرد على صوتكِ بنبرات مختلفة! افتحي متتبّع النمو، وسجّلي هذه القفزة المذهلة في مهارات التواصل، وتحدّثي معه بلغته.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('f027a882-3827-4905-9807-216432d88e53'::uuid, 'ضباب ذاكرة الأم 🌫️', 'ألا تتذكرين ما تناولتِه بالأمس؟ نسيان الأمومة (Baby brain) أمر حقيقي تمامًا. لا ترهقي ذهنكِ، واكتبي كل ما يحتاج إليه المنزل في قائمة التسوق، ودعي شريككِ يتولى الأمر.'),
  ('2e536117-6f18-4388-b1bd-29587c89d3cb', 'حقيقة الشعر المتساقط 💇‍♀️', 'هل يُخيفكِ تساقط شعركِ عندما تنظرين في المرآة؟ إنها إحدى أكثر حقائق فترة ما بعد الولادة إزعاجًا! لستِ وحدكِ، انضمي فورًا إلى مجتمع Anacan واقرئي كيف تتعامل الأمهات الأخريات مع هذه المشكلة.'),
  ('41393920-01a7-42fe-a049-e26e1148a375', 'البحث عن الهدوء 🤫', 'أحيانًا تمنع الضوضاء المنزلية طفلكِ من النوم من دون أن تنتبهي. فعّلي مقياس الصوت، وتحققي من أجواء الغرفة الصوتية، ووفّري له بيئة هادئة ومثالية للنوم.'),
  ('acb2ca22-b3e3-4ac0-b344-a63734056dfa', 'هل يعاني من حكة في اللثة؟ 🦷', 'هل يضع طفلكِ كل شيء في فمه، وخصوصًا يديه؟ هل بدأ سيلان اللعاب؟ سجّلي الأعراض الأولى فورًا في متتبّع التسنين، واستعدي لهذه المرحلة الطويلة.'),
  ('357bed80-6ac0-481c-9f5b-22bc1c97e3fe', 'اكتشاف اليدين 🤲', 'هل يحاول طفلكِ مدّ يديه عمدًا نحو الألعاب المعلّقة؟ إن مهاراته الحركية تتطور. تصفّحي قسم المنتجات الموصى بها للاطلاع على ألعاب إمساك آمنة تدعم اهتمامه الجديد.'),
  ('3c4bae00-6309-4214-a502-aa8dcb398a77', 'مفاجآت الطقس ⛅', 'هل تريدين الخروج، لكنكِ لا تستطيعين تحديد حالة الطقس بالنظر من النافذة؟ لا تُلبسي طفلكِ طبقات كثيرة فتجعليه يتعرق. دعي أداة الطقس والملابس تخبركِ خلال ثوانٍ بالملابس الأنسب لدرجة حرارة اليوم.'),
  ('132d4620-5085-4072-ac1e-81f46dc4e74c', 'احمي نوم طفلكِ بمقياس الصوت 🤫', 'أنتِ متحمسة، والاستعدادات جارية في المنزل، لكن يجب ألا يتأثر نوم طفلكِ. اتركي مقياس الصوت مفعّلًا في الغرفة لتعرفي فورًا عند تجاوز الضوضاء الحد المسموح به.'),
  ('32bd9b1c-365c-405d-addd-9a30d6295abc', 'لا تنظيف اليوم! 🛑', 'لستِ مضطرة إلى ترتيب كل شيء. فعّلي وضع الشريك: تنظيف المنزل وطلب الطعام اليوم من مسؤولية شريككِ. وما عليكِ سوى التخطيط لجلسة تصوير الغد بمناسبة إتمام طفلكِ 3 أشهر.'),
  ('a4183b3c-1979-434f-a71f-64b50e2e618c', 'حان وقت الاستعداد! 🎂', 'انتبهي! غدًا هو اليوم الكبير، إذ يتمّ طفلكِ 3 أشهر كاملة! لا تنسي طلب كعكة أو إعداد فكرة بسيطة لإضفاء أجواء مميزة على اليوم الـ90. أسرعي!'),
  ('10a571b7-6bc2-4092-a70f-a265883d71ba', '3 أشهر كاملة! 90 يومًا بالتمام! 🎉', 'لقد نجحتِ! رغم قلة النوم والأزمات والمخاوف، قدّمتما معًا عملًا جماعيًا رائعًا طوال 90 يومًا كاملة. افتحي أداة تصوير طفلكِ، واختاري ملصق 3 أشهر، وشاركي هذه الفرحة فورًا مع الأمهات الأخريات في مجتمع Anacan!'),
  ('9877e456-4a5e-45a3-aee9-e9703be5cf91', 'تهانينا! 🥂', 'راجعي جميع ملاحظاتكِ ومخططات النمو. شاهدي كم كبر طفلكِ وكم أصبحتِ أقوى. لقد حان الوقت لتفخري بنفسكِ!'),
  ('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e', 'لحظة انتصار الفريق 💖', 'لقد ساعدتِ طفلكِ على النوم باستخدام مؤقت النوم المميز. والآن اجلسي وجهًا لوجه مع شريككِ. اشكرا بعضكما على كل لحظة من هذه الأيام الـ90. فهذه ليست 3 أشهر من عمر طفلكما فحسب، بل 3 أشهر من رحلتكما في الأمومة والأبوة أيضًا!'),
  ('5c67089a-581e-455d-b113-f87f427babb2', 'حكايتكِ الخاصة 🪄', 'لنمنح أداة الحكايات الذكية هذا المساء موضوعًا لطيفًا: «حكاية أحلى نجمة هبطت من السماء». دعي صوت هذه الحكاية وحده يملأ الغرفة وسط سكون تام.'),
  ('66bd508e-0413-4d01-9ea7-c369b0d8cafa', 'حان دور الأب 👨‍👧', 'هل نفد صبركِ؟ سلّمي نوبة الأمومة اليوم إلى شريككِ لفترة قصيرة. دعيهما يقضيان بعض الوقت معًا، بينما تمدّدين ساقيكِ وتستريحين فحسب.'),
  ('55bafaf5-82ef-4f88-880d-836cf89145d0', 'قوة الأصوات 🌊', 'نوبات البكاء المسائية التي تبدأ بلا سبب واضح مُرهقة. خذي رضيعكِ إلى الغرفة، واختاري من الضوضاء البيضاء صوت أمواج المحيط أو مجفف الشعر لتهدئة الأجواء فورًا.'),
  ('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87', 'أين طاقة الأم؟ 🔋', 'لا تلومي نفسكِ عندما تنظرين إلى عينيكِ المتعبتين في المرآة. هل تهتمين بتغذيتكِ؟ اختاري من الوصفات الصحية مشروب سموذي للأمهات غنيًا بالحديد ويمكن تحضيره خلال 10 دقائق، واستعيدي طاقتكِ.'),
  ('13035ad4-af08-4b79-ba71-a42ceb60fe5b', 'نقاش الفريق 🛋️', 'بعد أن ينام طفلكِ، راجعي إحصاءاتكِ الأسبوعية في مفكرة المزاج مع شريككِ. في أي الأيام شعرتِ بتوتر أكبر؟ وما الذي يمكنكما فعله بطريقة مختلفة؟ أنتما فريق واحد!'),
  ('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6', 'انظري إلى الأسفل! 👣', 'لقد بدأ طفلكِ يكتشف قدميه! لا تفوّتي تلك اللحظة الطريفة واللطيفة التي يحاول فيها الإمساك بأصابع قدميه. افتحي جلسة تصوير طفلكِ، وزيّني الصورة بالملصقات ووثّقي هذه المحطة المهمة في نموه.'),
  ('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8', 'البحث عن عضّاضة 🦷', 'هل لا يتوقف سيلان لعابه ويعضّ كل شيء؟ يُنبّهكِ متتبّع التسنين إلى ذلك. لقد حان الوقت تمامًا لاستكشاف العضّاضات المصنوعة من السيليكون النظيف أو الخشب في قسم المنتجات الموصى بها.'),
  ('0d132ba6-d6e9-44f6-a85d-e139c66b9760', 'محادثة سريعة 🤖', 'لماذا يرفض طفلكِ فجأة أخذ قيلولته النهارية؟ ليس لديكِ وقت لقراءة مقالات طويلة. اكتبي سؤالكِ مباشرةً إلى Anacan AI، واحصلي على إجابة محددة ومختصرة حول تراجع النوم في عمر 3 أشهر.'),
  ('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198', 'فلسفة الحكايات 🪄', 'عادت الحكايات الذكية إلى العمل من جديد! اكتبي في النظام: “حكاية الجنية التي تتعب من اللعب نهارًا وترى أحلامًا جميلة ليلًا”. وربما تغفين أنتِ أيضًا أثناء القراءة.'),
  ('6c6289cf-6e7c-4e83-a178-d01d67cef488', 'ملابس محيّرة 👗', 'هل تخشين أحيانًا أن يشعر طفلكِ بالبرد، وفي أحيان أخرى تلبسينه ملابس دافئة أكثر من اللازم؟ لا تترددي. بدلًا من النظر عبر النافذة، تحققي فورًا من قسم الطقس والملابس، واطمئني مع اقتراح النظام للملابس المناسبة على شكل طبقات.'),
  ('8474a75e-7aaf-420e-b5ab-acd7d55ac51c', 'حان وقت الضحك! 😂', 'لم يعد يكتفي بالابتسام، بل أصبح يضحك بصوت عالٍ! العبي معه ودغدغي بطنه. هذا الصوت هو أجمل مكافأة على كل الليالي التي قضيتِها بلا نوم.'),
  ('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b', 'علامات النعاس 🥱', 'هل يفرك عينيه أو يشد أذنه أو يحدّق في الفراغ؟ لا تنتظري نوبة البكاء الليلية. ما إن تلاحظي هذه العلامات، فأعتِمي الغرفة وابدئي روتين النوم فورًا.'),
  ('1867104a-7fa8-428a-ad5d-dd10e6890f0f', 'استكشاف العالم بالفم 🤤', 'هل يضع يديه وألعابه وكل ما يجده في فمه مباشرةً؟ هذه طريقته في استكشاف العالم. لا تنتزعي كل شيء من يده، بل تأكدي فقط من نظافة الأشياء المحيطة به.'),
  ('4ad3cf84-0aac-46cb-bfdf-5a928764105a', 'لماذا يبدو المنزل بهذه الفوضى؟ 🌪️', 'هل تنظرين إلى كومة الألعاب في وسط الغرفة والأطباق غير المغسولة وتلومين نفسكِ؟ دعي تلك الأطباق مكانها اليوم. فتربية طفل مهمة كبيرة بما يكفي!'),
  ('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b', 'تمارين التقلّب 🤸‍♂️', 'إنه يحاول التقلّب من ظهره إلى بطنه! إنه تحدٍّ كبير لهذا الجسد الصغير. شجّعي محاولاته الطريفة، لكن احرصي تمامًا على حمايته قرب حواف السرير.'),
  ('91aad506-9119-4c1d-9011-ca750f77b2da', 'أنتِ كافية! 💖', 'هل نظرتِ إلى المرآة هذا الصباح وشعرتِ بالتعب، وربما بأنكِ لستِ على قدر المسؤولية؟ خذي نفسًا عميقًا. في عيني طفلكِ البريئتين اللتين تنظران إليكِ، أنتِ أروع إنسانة في العالم. أنتِ كافية!'),
  ('cc5d4a21-5a6c-4726-9656-04a48085588c', 'إلى أي حد نحن متعبون؟ 🛋️', 'نام طفلكِ، فماذا عنكِ؟ افتحي مفكرة المزاج، ودوّني مع زوجكِ فوضى هذا اليوم بروح مرحة. ستمر الأيام الصعبة، وستبقى روح الفريق.'),
  ('8557b605-4ddd-4ff9-9e9a-646d4a26ea63', 'هل انتكاسة النوم على الأبواب؟ 🤖', 'هل بدأ طفلكِ فجأة يستيقظ كثيرًا ليلًا؟ لا تقلقي، فقد اقتربت انتكاسة النوم في الشهر الرابع. احصلي فورًا من Anacan AI على معلومات موجزة ومطمئنة حول هذه العملية البيولوجية.'),
  ('88a16b76-764f-4acc-b335-0aa3f126d25a', 'حان وقت الخروج ⛅', 'قد يبدو ارتداء الملابس والاستعداد للخروج أمرًا شاقًا، لكن 20 دقيقة في الهواء الطلق ستنعكس بشكل رائع على طفلكِ وحالتكِ النفسية. تحققي من الطقس، واختاري ملابس مناسبة، ثم افتحي الباب بدلًا من النافذة!'),
  ('bb5697de-df9c-4558-a606-a7acef72c755', 'الأب بطل الليل 🦸‍♂️', 'أجمل قاعدة في الأشهر الأولى: يجب أن تتناوبا على مساعدة الرضيع على التجشؤ وتهدئته بالتهويدات! هذا المساء، طفلكِ بين ذراعي أبيه، بينما تضعين سماعاتكِ وتستمتعين بالموسيقى.'),
  ('4696c250-45bb-4765-b4bf-ee4e94f6361c', 'فنجان الأم ☕', 'ماذا فعلتِ لنفسكِ اليوم؟ لا شيء؟ ما إن ينام طفلكِ نهارًا، ضعي هاتفكِ جانبًا. حضّري لنفسكِ فنجانًا ساخنًا من القهوة (أو الشاي)، ولا تفكري في أي شيء لمدة 10 دقائق.'),
  ('7831318d-6b24-4373-9578-2c2a43ef02bf', 'فن شدّ الشعر 💇‍♀️', 'هل يشبك طفلكِ يديه مباشرة في شعركِ ويشده بقوة؟ لقد أصبح منعكس القبض لديه أقوى! احرصي على تصوير هذه المرحلة التطورية الطريفة والمؤلمة في آنٍ واحد، واحتفظي بالمقطع كتذكار.'),
  ('d66ea07a-276e-489b-bd8f-3ff80abe7258', 'معجزة التلامس الجسدي 🫂', 'هل يرفض النوم تمامًا ويصرخ بمجرد أن تضعيه في سريره؟ أحيانًا لا تحتاجين إلى أي وسيلة. ضعيه على صدركِ، واشعري كيف يهدئ التلامس المباشر بين بشرتكما كليكما.'),
  ('a99309cf-e0e5-4d40-9004-a8b08226861a', 'هل تبتل ياقة ملابسه كل 10 دقائق؟', 'بدأت تلك العلامات المبكرة في متتبع التسنين تتحول إلى واقع. تحسسي لثته السفلية باستمرار، فقد تكون اللؤلؤة البيضاء الأولى في طريقها للظهور!'),
  ('b14018ad-b2b5-4374-a785-9d281ebdd7e0', '15 دقيقة فقط من الهدوء 🤫', 'هل يكاد رأسكِ ينفجر من التعب طوال اليوم؟ عندما ينام طفلكِ، فعّلي مقياس الصوت لمراقبة الأجواء، واطلبي من الموجودين في المنزل التزام الهدوء، وأريحي ذهنكِ.'),
  ('c69510ed-a6e2-4456-a462-211d3917dec3', 'ماذا تفعل الأمهات الأخريات؟ 💬', 'هل تتساءلين: «هل طفلي وحده يتصرف هكذا؟» لستِ وحدكِ! انضمي إلى مجتمع Anacan، واقرئي تجارب الأمهات الحقيقية هناك، ثم تنفسي الصعداء.'),
  ('b8cf3d8c-2c7c-497e-8657-18fd989a1928', 'خطة للخروج من المنزل! 🌳', 'ألا تعرفين إلى أين يمكنكِ الذهاب مع طفلكِ؟ هل أصبح التنزه في الحديقة مرهقًا؟ اكتشفي ضمن الأماكن الصديقة للأمهات مكانًا يمكنكِ الجلوس فيه براحة مع طفلكِ والاستمتاع بفنجان من القهوة.'),
  ('1c648ce0-799c-41f0-964a-90e59cbddc3d', 'انتصار كبير وفخر مشترك 🥂', '100 ليلة و100 نهار... انظري إلى شريككِ الذي تقاسم معكِ هذا العبء الكبير. دوّني في مفكرة المزاج شعوركِ بالفخر في اليوم الـ100، وصفّقا لبعضكما وقوفًا. إنه انتصار فريقكما!'),
  ('52155593-73d7-4bb9-861d-d87a0ca100e9', 'معجزة عمرها 100 يوم! 🎉', 'نعم، لقد مرّ اليوم 100 يوم كاملة منذ أن تغيّرت حياتكِ من جذورها! أنتِ تقومين بعمل مذهل.'),
  ('7c63492d-1515-406a-bd31-b41ece7e0412', 'صفّقي لنفسكِ 👏', 'عندما تنظرين إلى الماضي، تدركين كم كانت الأيام الأولى مخيفة، وكم أصبحت الآن مليئة بالدروس. افتخري بنفسكِ. لم يكبر طفلكِ 100 يوم فحسب، بل نضجتِ أنتِ أيضًا طوال هذه الأيام الـ100.'),
  ('724659ec-f59f-4bfe-b20d-efdd3d977217', 'وقت للاسترخاء 🛋️', 'عندما يلعب طفلكِ بمفرده، لا تهرعي فورًا إلى إنجاز الأعمال. اجلسي وراقبيه من بعيد لمدة 5 دقائق فقط، واستمتعي بقهوتكِ.'),
  ('aaed3963-e8dd-47d4-93bd-9b307c2b65fd', 'طاقة الصباح ⚡', 'هل يبدأ طفلكِ بالمناغاة فور أن يفتح عينيه؟ إنه يريد التحدث إليكِ. ابتسمي له وأجيبيه، فهذا أساس تطور لغته.'),
  ('d1e64fb7-d149-4fd0-afca-834eed2264d1', 'انتكاسة في النوم؟ 🌙', 'هل بدأ طفلكِ يستيقظ كثيرًا ليلًا؟ قد تكون هذه علامات انتكاسة النوم في الشهر الـ4. تحلّي بالصبر، فهذه أيضًا مرحلة مؤقتة وستمر.'),
  ('13cad6d0-aa0a-426b-9515-1e96e73e716a', 'اكتشافات جديدة 🤲', 'هل يضع طفلكِ في فمه كل ما تقع عليه يداه؟ لا تقلقي، فهذه طريقته في استكشاف العالم. احرصي فقط على إبقاء محيطه نظيفًا.'),
  ('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'الصديق في المرآة 👀', 'احمليه أمام المرآة، وراقبي كيف ينظر إلى انعكاسه بدهشة وابتسامة. هو لا يعرف بعد أن من يراه في المرآة هو نفسه، لكن هذه اللعبة رائعة لنموه الذهني.'),
  ('6f416e63-4acf-4dd2-8216-6601a8c26df5', 'تخلّصي من الشعور بالذنب 🛑', 'هل نفد صبركِ اليوم، وربما شعرتِ ببعض الغضب، والآن يؤنبكِ ضميركِ؟ توقفي. هل أنتِ روبوت؟ لا. تقبّلي مشاعركِ، وسامحي نفسكِ، وابدئي غدًا يومًا جديدًا.'),
  ('d584b1c4-e42a-483d-b585-e83a9ab20c88', 'مخزون الطاقة للأم 🍲', 'هل انشغلتِ بإطعام رضيعكِ حتى نسيتِ تناول الطعام؟ حضّري وجبة خفيفة سهلة الهضم وغنية بالطاقة من قسم الوصفات الصحية. يجب أن تكوني قوية كي تمنحيه القوة أيضًا.'),
  ('014e3f07-72e8-47f8-b62e-ff583a9df29e', 'تحدّثي معي! 🗣️', 'هل ينظر إليكِ ويصدر مقاطع صوتية غريبة؟ استجيبي لأصواته وفترات صمته. إنه يجري معكِ الآن حوارًا حقيقيًا! وهذه إحدى أهم الخطوات الأساسية في تطور اللغة.'),
  ('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef', 'احتياجات غير ملحوظة 🛒', 'هل أوشك شيء ما على النفاد وسط انشغالاتكِ اليومية؟ ورق الحمام، أو حفاضات طفلكِ، أو الشامبو؟ أضيفيه الآن إلى قائمة التسوق قبل أن تنسي، ليصل إشعار إلى هاتف شريككِ.'),
  ('e8ec2cd2-3417-4383-8892-bb623cb07365', 'تجميد الزمن 📸', 'إنه يكبر بسرعة كبيرة... هذا المساء، تأمّلي ملامح وجهه بعناية وهو نائم. التقطي صورة ليديه الصغيرتين ووجهه باستخدام جلسة تصوير الطفل، وتحدّي مرور الزمن.'),
  ('2a23a61b-4ca6-48f6-8845-f47a357eed0f', 'ماذا يعني هذا الصوت؟ 🧩', 'هل يتذمّر ويبكي فور أن يفتح عينيه؟ إذا لم تتمكني من معرفة السبب، فاستخدمي تحليل البكاء خلال ثوانٍ لفكّ شفرة هذه النوبة.'),
  ('43fbc1cb-7e93-4983-b59f-f5bc67650d3e', 'الحكاية لا تنتهي 📖', 'هذا المساء، أعطي الحكايات الذكية مهمة أكثر إبداعًا: “حكاية الدب الصغير الذي يبحث عن رائحة أمه”. واختتمي الليلة بنهاية هادئة ومفعمة بالحب.'),
  ('bfab4a59-c162-47a2-9035-51b03b7fe911', 'يمكن للأعمال المنزلية الانتظار 🛑', 'لا تشعري بالتوتر عند رؤية الغرفة غير المرتبة. أنتِ ترعين إنسانًا صغيرًا، ولستِ مطالبة بأن تكوني ربة منزل مثالية.'),
  ('ca9affc4-d638-41a2-8dc7-75447d9ea222', 'حان دور الأب 👨‍🍼', 'هذا المساء، مهمة مساعدة الرضيع على التجشؤ وغناء التهويدة له تقع على عاتق الأب. أما أنتِ، فاذهبي وخذي قسطًا من الراحة.'),
  ('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e', 'لا تنسي نفسكِ 🍲', 'لقد شبع طفلكِ، فماذا عنكِ؟ عليكِ تناول طعام جيد لاستعادة طاقتكِ. اطلبي لنفسكِ اليوم وجبة لذيذة ومشبعة.'),
  ('957a90d0-61dc-45f5-a2da-ef7086521cd5', 'هل سمعتِ فجأة ضحكة عالية في الغرفة؟ 😂', 'نعم، لقد بدأ طفلكِ يضحك بصوت عالٍ! هذا الصوت يستحق كل ما تشعرين به من تعب.'),
  ('dd50206e-acee-43ac-8f19-c5dd29cf7e62', 'ملامسة الجلد للجلد 🫂', 'هل رضيعكِ شديد الانزعاج؟ إذا لم ينجح أي شيء، فضعيه على صدركِ. دقات قلبكِ هي أفضل ما يهدئه.'),
  ('2c73f922-1b22-4eb6-922b-215d8e623242', 'لعبة شد الشعر 💇‍♀️', 'هل يلف أصابعه حول شعركِ ويشده بقوة؟ إن منعكس الإمساك لديه في طور النمو. حاولي أن تضحكي على هذه المرحلة التطورية المؤلمة قليلًا.'),
  ('f32eaadc-b85c-4f36-b182-6f6665e1eaae', 'هدوء تام 🤫', 'هل يجد صعوبة في النوم؟ اجعلي الغرفة مظلمة تمامًا وأوقفي مصادر الضوضاء. الظلام والهدوء خير رفيقين لنومه.'),
  ('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b', 'هل بدأت الأسنان الأولى بالظهور؟ 🦷', 'هل ازداد سيلان لعابه؟ سجّلي ذلك في متتبع التسنين، واحتفظي بعضّاضات نظيفة في متناول يدكِ.'),
  ('e6ea83f7-b8a5-46f7-ba44-81c58175071e', 'انظري إلى الأسفل! 👣', 'لقد بدأ طفلكِ يكتشف أصابع قدميه! راقبي هذه اللحظة الطريفة والمذهلة بعناية، واستمتعي بمراحل نموه.'),
  ('53a91083-d8e0-4baf-9f90-46ce72a9291d', 'الصديق في المرآة 👀', 'ضعيه أمام المرآة. ستكون مشاهدة دهشته وضحكته وهو ينظر إلى انعكاسه نشاطًا ممتعًا للغاية.'),
  ('96d4756e-270f-426b-9e78-f2a573accdac', 'حان وقت الخروج 🌳', 'البقاء بين أربعة جدران يشعركِ بالاختناق. ضعيه في عربته واخرجا لاستنشاق الهواء النقي، ولو لمدة 15 دقيقة فقط. سيعود ذلك بالنفع عليكما كليكما.'),
  ('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41', 'بطل الليل 🦸‍♂️', 'هل أنهكتكِ استيقاظات الليل؟ لا تترددي في إيقاظ الأب. فالعمل كفريق يعني تقاسم المسؤوليات بالتساوي.'),
  ('07f48fa2-56fd-416e-adda-88c824f2bd6f', 'الاستعداد لنوم عميق 🛀', 'حمّام دافئ، وتدليك لطيف، وتعتيم الغرفة... الحفاظ على روتين النوم هو سر الليالي المتواصلة.'),
  ('828415f3-317f-4e76-8caf-753026dcf9f1', 'لا تشعري بالذنب 💖', 'هل تعتقدين أنكِ لا تقضين وقتًا كافيًا مع طفلكِ؟ إن 10 دقائق ممتعة ومليئة بالابتسامات أثمن من 1 ساعة يسودها التوتر.'),
  ('f4730701-e02f-4cf0-9730-df8b7e034297', 'سأمسكها بنفسي! 🧸', 'هل يمد يده نحو الألعاب المعلّقة بدقة؟ إن التناسق بين عينيه ويديه يزداد قوة. شجّعيه باستخدام أشياء مختلفة الألوان.'),
  ('70597740-ab51-4b20-b743-042bccb768a6', 'تمارين الصباح 🐢', 'يساعد الاستلقاء على البطن في تقوية عضلات الرقبة. واظبي على ذلك يوميًا، ولو لفترة قصيرة، حتى إن بكى.'),
  ('1e555e61-fac2-4756-83d5-5c2a2ceaa400', 'حكايتكما الخاصة 🪄', 'سهّلي الانتقال إلى النوم مساءً باستخدام القصص الذكية. ابتكري لطفلكِ قصة لطيفة وخاصة به واقرئيها له.'),
  ('a4146327-bb44-44e0-9860-d8e3c1abe5c4', 'نحن فريق واحد! 💪', 'هل تشعرين بالوحدة والإرهاق؟ خذي نفسًا عميقًا. أنتِ أقوى بطلة في هذه الأيام العاصفة.'),
  ('e3c0355b-40c6-476a-8c2d-f69c78debdb1', 'تقلّب رائع 🤸‍♂️', 'هل يحاول التقلّب من ظهره إلى بطنه؟ إنه يبذل جهدًا كبيرًا! راقبي هذه المحاولات، لكن لا تتركيه وحده على السرير أبدًا.'),
  ('532d58e2-50f3-422a-818a-36c88094bb87', 'ماذا أُلبسه؟ ⛅', 'لا تحتاري فيما ستُلبسينه لطفلكِ عند الخروج. اطّلعي على أداة الطقس والملابس، واعثري على الإطلالة المثالية خلال ثوانٍ.'),
  ('f37039a0-f7af-487a-827e-622e2d9e4d05', 'الشعور بالإنهاك طبيعي 🔋', 'عندما ينفد صبركِ، لا تشعري بأنكِ أم سيئة. هذا الإرهاق طبيعي. لا تترددي في طلب الدعم من شريككِ.'),
  ('f94cdd25-2b6b-47df-81dc-6e3cab221652', 'أنتِ كافية! 🌸', 'هل تسير الأمور كلها على نحو سيئ اليوم؟ لا بأس. لا يحتاج طفلكِ إلى أحد سواكِ. أنتِ كافية تمامًا بالنسبة إليه.'),
  ('18211145-ceeb-48f3-8053-1e2ff686e384', 'سحر الأصوات 🌊', 'إذا بدأت نوبات البكاء مساءً، فلا تقلقي. شغّلي الضوضاء البيضاء لطفلكِ لتغيّري أجواء الغرفة فورًا.'),
  ('49d00520-8368-4f13-9074-fbe894888b76', 'اسألي الذكاء الاصطناعي 🤖', 'هل تدور في ذهنكِ آلاف الأسئلة؟ لا تضيّعي وقتكِ في البحث، بل اسألي Anacan AI فورًا واحصلي على إجابة دقيقة وموثوقة علميًا.'),
  ('2226c745-19bb-4270-8e5c-a438c71816d4', 'ماذا تفعل الأمهات الأخريات؟ 💬', 'هل تشعرين بالقلق؟ انضمي إلى مجتمع Anacan واطرحي سؤالكِ. صدّقيني، جميع الأمهات يمررن بتجارب متشابهة.'),
  ('31bb23a0-6713-4c06-9f74-65b7a51a3dd9', 'صوت مهدّئ 📖', 'اقرئي لطفلكِ هذا المساء حكاية قصيرة بصوتكِ فقط. لا تحتاجين إلى أي أدوات، فصوت الأم هو السحر الأعظم.'),
  ('34253cb9-0e01-47a7-9def-03c3b3e05aba', 'ألعاب ممتعة 🎈', 'هل يستلقي ويحرك ساقيه في الهواء كأنه يركب دراجة؟ هذه تسليته الجديدة. شاركيه المرح ودغدغيه.'),
  ('4eb27952-4f25-4c0d-8e25-cf21169fe3eb', 'اعتني بنفسكِ 🥑', 'تصبح العظام والأسنان أكثر حساسية خلال فترة ما بعد الولادة. لا تنسي إضافة الكالسيوم إلى نظامكِ الغذائي. اعتني بنفسكِ جيدًا.'),
  ('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c', 'هل لا يرضيه شيء هذا الصباح؟ ☁️', 'قد يمر بطفرة نمو. احتضنيه أكثر فحسب واجعليه يشعر بالأمان.'),
  ('813f6345-1636-47fd-9a6b-aee16d069800', 'علامات النعاس 🥱', 'لا تنتظري حتى يفرك عينيه ويتثاءب. ابدئي روتين النوم فورًا بمجرد أن تصبح نظراته شاردة.'),
  ('088b061c-e51f-4931-8636-b06152d7eaff', 'هل هناك ما يحيّركِ؟ 🤖', 'بدلًا من قضاء ساعات في قراءة المنتديات، اطرحي سؤالكِ على Anacan AI واحصلي على إجابة سريعة.'),
  ('5e878638-6613-43f0-b734-dd308940758d', 'بقيت 5 أيام ليُكمل 4 أشهر! 🎂', 'إذا كان من تقاليدكِ التقاط صورة مع كعكة، فهذا هو الوقت المناسب تمامًا لطلبها.'),
  ('fb3d810e-9135-4194-bb47-9ce9e588d70c', 'كتفا الأب 👨‍👧', 'مهمة حمل طفلكِ والتجول به في الغرفة ومساعدته على إخراج الغازات هذا المساء تقع بالكامل على عاتق الأب.'),
  ('09081d67-84a7-403e-b876-3cc97106eb52', 'بارع في الإمساك 🧸', 'هل أصبح يمسك بالألعاب المعلقة بدقة تامة؟ مهاراته الحركية تتطور بشكل رائع. راقبي محاولاته هذه بحب وشجعيه.'),
  ('15b0ec22-2156-4080-ad64-7a588de85fc5', 'لا تتوتري بسبب فوضى المنزل. 🌪️', 'أولويتكِ ليست منزلًا مثاليًا، بل رضيعًا سليمًا وسعيدًا. استرخي.'),
  ('e8181dea-ccff-4ba2-ae33-93fa07ea8c28', 'هل لديكِ سؤال؟ 🤖', 'هل تشعرين بالحيرة بشأن النوم أو التغذية أو الغازات؟ لا تضيعي وقتكِ في المنتديات، فقط اكتبي إلى Anacan AI واحصلي على إجابة علمية محددة.'),
  ('0140116f-1e50-4656-93a0-277a1645b1ba', 'تنفيس عاطفي 📝', 'هل كان يومًا صعبًا؟ اكتبي بكل صدق عن كل ما تشعرين به من إرهاق في يوميات المزاج.'),
  ('1f632261-0ec6-4f1f-be74-71aaaaf4c706', 'هل توشك المستلزمات على النفاد؟ 🛒', 'هل توشك الحفاضات أو المناديل المبللة على النفاد؟ أضيفيها إلى قائمة التسوق قبل أن تنسي، ليصل إشعار إلى هاتف شريككِ.'),
  ('f2dc5d57-91a4-45de-b81b-0b2998a8593b', 'أصداء الضحكات 😂', 'هل يرد على حركاتكِ اللطيفة بضحكات عالية؟ احرصي على تسجيل هذا الصوت في مقطع فيديو.'),
  ('1c68be5f-505e-4c46-be58-571a7196e98d', 'شاركي تجربتكِ 💬', 'هل تتساءلين: «هل أنا وحدي أشعر هكذا؟» انضمي إلى مجتمع Anacan وتحدثي مع أمهات يمررن بمشاعر مشابهة.'),
  ('81a8fffa-561b-48b8-9be0-ff9b930a7bac', 'تنفيس عاطفي 📝', 'هل تشعرين أن كل شيء يضغط عليكِ اليوم؟ اكتبي كل الصعوبات والتعب في مفكرة المزاج. لا تكبتي مشاعركِ.'),
  ('87db18be-f6b3-443d-9d07-0e305836d90b', 'إنجاز اليوم 110! 🥂', 'لقد مضى 110 يومًا بالضبط وأنتِ تديرين حياة جديدة. تبادلي الشكر مع شريككِ واستمتعا بهدوء هذا المساء.'),
  ('1063f207-152c-4454-9267-2e05e30929d8', 'هدوء ذكي 🤫', 'هل توقظه الأصوات المفاجئة عندما يغفو؟ استخدمي مقياس الصوت لمراقبة مستوى الديسيبل في الغرفة.'),
  ('17c1a37e-ab5c-4032-afa2-27e4d0964076', 'جائع أم متعب؟ 😭', 'هل يبكي بلا سبب ويبدو صوته مختلفًا؟ قد لا يكون جائعًا، بل يعاني فقط من قلة النوم. راقبي نمط نومه بعناية.'),
  ('93512cbe-adab-49c7-8e82-4466bf0e00ad', '10 دقائق للأم ☕', 'لا تسرعي إلى الأعمال المنزلية فور نوم طفلكِ. اجلسي على الأريكة، واشربي قهوتكِ، وخذي 10 دقائق للراحة دون فعل أي شيء.'),
  ('8bc219eb-803c-491e-9625-0efec17a7dad', 'سلّمي المناوبة 🛋️', 'إذا كنتِ ترغبين في الاستلقاء والنوم فور نوم طفلكِ، ففوّضي المهام المنزلية الأخرى إلى شريككِ. صحتكِ أهم من كل شيء.'),
  ('924ff591-18ec-4c20-80af-4008cda2fc41', 'نبرات متنوعة 🗣️', 'بدأت مناغاته تصبح أعلى صوتًا وأكثر تنوعًا. أنصتي إليه وقلّديه لتُضحكيه.'),
  ('be9ad5fd-195c-40e7-99c6-7f5f91e01526', 'قائمة للتذكّر 🛒', 'هل أضعفت قلة النوم ذاكرتكِ؟ لا تحاولي تذكّر كل ما يحتاج إليه المنزل، بل دوّنيه في قائمة التسوق.'),
  ('616fd04c-b736-454a-9242-b3c011b0cdc5', 'نفد صبركِ وتعبت ذراعاكِ؟ 👨‍👧', 'هذا المساء، اتركي طفلكِ مع والده، وأغلقي الباب، وخصصي 15 دقيقة لنفسكِ.'),
  ('232de7cd-2ff6-4b62-8cee-002063d545fd', 'فوضى جميلة 🌪️', 'هل أغراض طفلكِ منتشرة في كل أرجاء المنزل؟ لا بأس. فوضى المنزل لا تعني أنكِ أم سيئة، بل تدل على أن طفلكِ هو أولويتكِ.'),
  ('2cbef83d-a5f1-4b69-858b-9d1310e2cac3', 'هل سئمتِ البقاء في المنزل؟ ☕', 'هل سئمتِ البقاء في المنزل؟ اختاري من الأماكن الصديقة للأمهات مقهى قريبًا يمكنكِ دخوله بسهولة بعربة طفلكِ.'),
  ('ff5950e2-aed4-41ca-bc9a-64a1b039968a', 'حان وقت الحكاية الذكية 🪄', 'أنشئي في الحكايات الذكية قصة خاصة لهذه الليلة: قصة الصغير الشجاع الذي ينام فوق السحاب.'),
  ('37346c6c-3239-4e07-bcc0-24af9be99f3f', 'نوبات سيلان اللعاب 🤤', 'هل تبتل ياقته بالكامل خلال ثوانٍ؟ لثته تستعد تدريجيًا لظهور الأسنان. المرايل المصنوعة من السيليكون هي أفضل حل.'),
  ('86a98c8a-884a-4567-83c1-4d206dccead9', 'الهواء النقي دواء 🌳', 'إذا كان طفلكِ شديد الانزعاج، فاصطحبيه فورًا إلى الهواء الطلق. فالهواء النقي أبسط وسيلة لتهدئة نوبات الانزعاج سريعًا.'),
  ('ae291c04-b5c7-4ff1-937e-2b2b6d502624', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتحدثا عما يثقل كاهلكما. دعم أحدكما للآخر يخفف العبء إلى النصف.'),
  ('5fcfd433-5086-40d6-89d5-0d756fb06e17', 'قوة الموسيقى 🎶', 'جرّبي تهدئة نوبات البكاء غير المبررة التي تبدأ في أواخر النهار بموسيقى كلاسيكية هادئة الإيقاع. غالبًا ما تنجح.'),
  ('b4113857-b164-4ab8-b41d-4e516341edad', 'إنه يحاول! 🤸‍♂️', 'عندما يكون مستلقيًا على بطنه، يستند إلى ذراعيه ويحاول رفع رأسه والنظر إلى الأعلى. تزداد عضلاته قوة يومًا بعد يوم، أحسنت يا صغيري!'),
  ('ec61705b-0071-49b5-a6b0-3849dfa461ac', 'أوقفي الزمن 📸', 'إنه يكبر بسرعة كبيرة... ألبسيه ملابس جميلة وخلّدي هذه اللحظة بجلسة تصوير لطفلكِ.'),
  ('72b166c9-a8f9-4dc5-be7f-5911ccda18ea', 'المزيد من الضحكات 😂', 'يستجيب بضحكات عالية لكل حركة طريفة تقومين بها. لا تنسي تصوير هذه اللحظة الرائعة بالفيديو!'),
  ('968ec1c9-36e5-4127-8374-922149e153dc', 'أساس النوم الصحي ⏱️', 'من المهم جدًا إرساء نظام نوم صحي في الشهر الرابع. التزمي بالروتين ولا تخلّي به كي تنعمي بليالٍ هادئة.'),
  ('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f', 'كل شيء على ما يرام ✔️', 'قد تشعرين أحيانًا بأنكِ لا تستطيعين فعل أي شيء. لكن انظري إلى ملابسه النظيفة وبطنه الممتلئ. أنتِ تقومين بعمل رائع!'),
  ('4f713889-2b51-4db7-8d5d-7ee8676555a4', '4 أشهر مذهلة! 🎉', 'هل تصدقين؟ لقد مضى 120 يومًا كاملًا وأنتما تخوضان هذه الرحلة الساحرة معًا! حوّلي هذه اللحظة إلى ذكرى خالدة بجلسة تصوير لطفلكِ!'),
  ('8d072236-96cb-4886-b83d-b2d8d6523abb', 'انظري إلى ما حققتِه 📈', 'تذكّري مخاوفكِ في الأيام الأولى، وانظري الآن كيف أصبحتِ أمًا متمرسة. افتخري بنفسكِ!'),
  ('cfb7b283-3b96-44ef-84b8-0eca1ae74852', 'احتفلي بفخر مرور 4 أشهر.  🥂', 'هذا المساء، بعد أن ينام طفلكِ، لا تنسي الاحتفال مع زوجكِ بالنجاح الذي حققتماه معًا كفريق!'),
  ('0fa7eced-c60c-4055-8da1-5df4e54ec1ce', 'أنا أتحدث! 🗣️', 'هل يردد مقاطع مثل «با-با» و«ما-ما»؟ افتحي متتبع النمو، وسجّلي هذه القفزة اللغوية الكبيرة، وأكثري من الحديث معه.'),
  ('19b9faef-1d59-42d5-bcb0-12290f627a1f', 'لحظة هدوء ☕', 'فوضى الغرفة لن تذهب إلى أي مكان. بينما يلعب طفلكِ بمفرده، استمتعي بقهوتكِ وهدوء الغرفة.'),
  ('65cb82a7-67e0-48b5-80b8-74e806b2980e', 'حكايتكما الخاصة 🪄', 'ادخلي هذا المساء إلى الحكايات الذكية، وأنشئي له حكاية خاصة واقرئيها له.'),
  ('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62', 'هل يبقى على بطنه مدة أطول؟  🐢', 'تزداد قوة عضلاته يومًا بعد يوم. اجعلي هذه المرحلة أكثر متعة بوضع لعبة ملوّنة أمامه.'),
  ('431c0c7a-2968-4edd-9882-df9a926adf72', 'شلال اللعاب 🤤', 'هل بدأت ياقة ملابسه تبتل كثيرًا؟ احرصي دائمًا على إبقاء عضّاضة سيليكون في متناول يدكِ.'),
  ('5817fca0-3cbb-4276-a47d-9383c042597d', 'مراقبة مستوى الضوضاء 🤫', 'هل يفزعكِ كل صوت في المنزل عندما ينام طفلكِ؟ فعّلي مقياس الصوت، وتحققي من مستوى الضوضاء في الغرفة لحماية نومه.'),
  ('df219eb3-fe33-48d7-81df-3e2d39df4620', 'كم أنتِ قادرة على فعل الكثير! 💖', 'انظري إلى عينيكِ المتعبتين في المرآة وابتسمي. أنتِ تربّين معجزة من دون أي دليل إرشادي!'),
  ('f8c399ff-a31e-4e77-a55d-5aab198bafaa', 'حان وقت الخروج ⛅', 'استخدمي أداة الطقس والملابس لاختيار الإطلالة الأنسب لحالة الطقس خلال ثوانٍ، واستنشقي بعض الهواء النقي.'),
  ('903de81c-9443-4b1e-8662-d8cbed1ca54e', 'بدأت عضّاضات التسنين عملها! 💧', 'يريد طفلكِ وضع كل شيء في فمه. تصفّحي المدونات لمعرفة المزيد عن السلامة والنمو.'),
  ('9dd94bee-b76e-43ec-94c9-51937e10ad6e', 'لا تنظيف اليوم 🛑', 'هل أنتِ متعبة؟ أخبري شريككِ. لا طعام منزلي ولا تنظيف اليوم؛ فهذا اليوم مخصص لراحة الأم فحسب!'),
  ('25015c8c-0ca6-43bc-a465-c8490ee6d808', 'إنه مولع بكِ! 🥰', 'هل يحدّق فيكِ أثناء الرضاعة أو تناول الطعام؟ إنه يكتشف ملامح وجهكِ ويحبكِ كثيرًا!'),
  ('565cbb4c-39dd-4c69-980a-b02d63f6cdb4', 'قليل من الراحة 🛋️', 'بعد يوم شاق، دوّني مشاعركِ في مفكرة المزاج. تذكّري أن الكتابة والبوح بما في داخلكِ أفضل علاج نفسي مجاني.'),
  ('f0338702-1ba5-495b-840d-9ad790085c24', 'طبيب أطفال في جيبكِ 🤖', 'هل تغيّر لون برازه أو ظهر طفح جلدي بسيط على جسمه؟ قبل أن تصابي بالذعر، اكتبي إلى Anacan AI لتتعرفي على الأسباب المحتملة.'),
  ('5996a5e8-c639-4f34-8f02-ccaebf8a96eb', 'اليدان تعملان بنشاط 👐', 'هل يحاول الإمساك بأشياء كبيرة بكلتا يديه في الوقت نفسه؟ سجّلي هذه الملاحظة في متتبع النمو واختبري قدرته بإعطائه كرة طرية.'),
  ('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee', 'هل يشعر بالبرد أم بالحر؟ ⛅', 'هل اختيار ملابسه مشكلة دائمة؟ دعي أداة الطقس والملابس تخبركِ بدقة بعدد طبقات الملابس المناسبة له، ولا ترهقي ذهنكِ.'),
  ('a1ca42ca-05ed-42dc-af4a-99af31043623', 'سحر صوت الأم 🎶', 'لا يمكن لأي تطبيق أن يحل محل تهويدة الأم. ضمّيه إلى صدركِ هذا المساء وغنّي له بهدوء تهويدته المفضلة.'),
  ('0ed5ca13-9d93-489b-99e3-a198862dd467', 'تراجع النوم؟ 🤖', 'هل زادت مرات الاستيقاظ ليلًا فجأة؟ قد تكون طفرة في النمو البيولوجي. احصلي من Anacan AI على معلومات حول تراجع النوم في عمر 4-5 أشهر.'),
  ('450e1ee4-0ee2-4568-acc9-22677b87903d', 'إنه ينظر إليّ! 📸', 'أينما كنتِ في الغرفة، يتتبعكِ بعينيه.'),
  ('696eaa28-30b3-4a02-87e3-0cd00d185f07', '10 دقائق فقط 🛀', 'نام طفلكِ، وحظيتِ أخيرًا ببعض الهدوء. بدلًا من تفريغ غسالة الصحون، قفي تحت الماء الدافئ واستمعي إلى صوته لمدة 10 دقائق.'),
  ('27873a53-69de-4c27-a20c-c15256739b9a', 'نحن فريق واحد! 🌟', 'هل أنهكتكِ مرات الاستيقاظ ليلًا؟ لا تترددي في إيقاظ الأب. فالعمل كفريق يعني تقاسم الأعباء بمحبة.'),
  ('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c', 'مفاجآت الطقس ⛅', 'عند الخروج في نزهة، لا تنخدعي بالطقس فتعرّضي طفلكِ للبرد. استعيني بمساعد الطقس والملابس لتختاري بسهولة ما يناسب الأجواء في الخارج.'),
  ('82b46290-c3d6-4ad5-8d94-600e0311ba33', 'إصراره على العناق 🛋️', 'ألا يريد النزول من حضنكِ؟ هذا ليس دلالًا، بل هو بحاجة إلى رائحتكِ. عانقيه بقوة، فهذه الأيام ستمر سريعًا.'),
  ('132a3a1b-1001-4fec-a775-7883117a6988', 'كيف يسير الروتين؟ 📈', 'حلّلي إحصاءات الأيام الأخيرة بالاطلاع على سجل التغذية ومؤقت النوم.'),
  ('61f15500-8617-42e1-b833-c482f6ae935c', 'هل يرمي ألعابه على الأرض كثيرًا؟ 🧸', 'إنه يتعلم بذلك العلاقة بين السبب والنتيجة. يمكنكِ الاطلاع على المنتجات الموصى بها لاختيار ألعاب جديدة.'),
  ('4b6ccde7-7cce-4142-8822-fa952592f465', 'علامات النعاس 🥱', 'هل يفرك عينيه أو يشد أذنه؟ لا تنتظري حتى يدخل في نوبة بكاء من شدة النعاس؛ خفّفي إضاءة الغرفة فورًا وابدئي روتين المساء.'),
  ('7b3662bc-d715-468b-a32f-326c023ef66e', 'بطل التقلّب 🤸‍♂️', 'هل يحاول التقلّب من ظهره إلى بطنه ومن بطنه إلى ظهره؟ لا تتركيه وحده على السرير أبدًا، واستمتعي بهذه المرحلة المليئة بالحركة.'),
  ('0aded6bb-b0fa-4cac-b297-4311bcd7f798', 'لستِ مضطرة إلى إنجاز كل شيء. 🌸', 'في عيني طفلكِ المحبتين اللتين تنظران إليكِ، أنتِ أروع إنسانة في العالم.'),
  ('658bd674-cc84-4d51-8a7e-822b9255b9d7', 'اكتشاف حكاية جديدة 📖', 'لنجعل هذه الليلة مختلفة. أنشئي في الحكايات الذكية قصة حورية بحر تنطلق في مغامرة لاستكشاف أعماق البحر، واملئي الغرفة بالسحر.'),
  ('b8b57297-f4b4-4473-87af-9acfeee74dd3', 'ليس جائعًا، فما السبب إذًا؟ 🧩', 'ألا يهدأ مهما فعلتِ؟ توقفي عن التخمين، ودعي ميزة تحليل البكاء تستمع إلى صوته لتكتشفي المشكلة فورًا.'),
  ('9ce62e84-5124-421b-bdd6-3fa7c590aa1a', 'عالم جديد من الألوان 👀', 'أصبح الآن يرى الألوان بوضوح أكبر وبصورة أكثر حيوية. أريه ألعابًا ذات ألوان متباينة.'),
  ('b42e7a75-4fab-45bd-89fe-f334b8181757', 'لا تنسي نفسكِ 🍲', 'إذا شبع طفلكِ، فقد حان دوركِ. اختاري من الوصفات الصحية وجبة خفيفة غنية بالطاقة تُحضَّر خلال 10 دقائق، واعتني بنفسكِ.'),
  ('cf65b961-f3be-4509-9af3-0b6c17f757e7', 'وقت الأب مع طفله 🫂', 'يحتاج الآباء أيضًا إلى التواصل الجسدي مع أطفالهم. اتركيهما معًا لبعض الوقت في المساء، ليقوّيا رابطتهما وتحصلي أنتِ على قسط من الراحة.'),
  ('1a9e3246-5c48-4c5d-9be8-b35243065267', 'ما الذي ينقص في المنزل؟ 🛒', 'هل نفد الشامبو أم زيت الأطفال؟ لا داعي للتفكير. املئي قائمة التسوق، واتركي الباقي لشريككِ.'),
  ('6e836ffa-475e-446a-bc5a-eddbd0eeeec4', 'صفّي الأصوات 🤫', 'قد تعيق أصوات الشارع النوم العميق. تحققي من مقياس الضوضاء، واستخدمي الضوضاء البيضاء في الخلفية عند الحاجة.'),
  ('e31b222d-5c34-45e3-b291-c3f8c8989d13', 'جميلة وحقيقية 💇‍♀️', 'قد تكون هناك بقعة على قميصكِ، وقد يكون شعركِ غير مرتب. لكنكِ في عيني طفلكِ أجمل من في العالم. فلا تلومي نفسكِ.'),
  ('29aebaa9-a1ae-4a00-8854-a771800bf560', 'لننظّم الفواصل الزمنية. 🍼', 'أنشئي روتينًا مثاليًا من خلال تتبّع أوقات الرضاعة والاستيقاظ باستخدام أداة متابعة الرضاعة.'),
  ('3942c763-be60-481b-bb4e-1a53687a8d34', 'تفاني الأب 💖', 'لقد عمل طوال اليوم أيضًا، لكن حان الآن دوره كأب. شاهديه من بعيد وهو يساعد طفلكِ على النوم بكل عناية، واستمتعي بهذه السعادة.'),
  ('3cd07d9d-076c-4523-8ba1-47b8737d6bbf', 'أنا هنا! 👀', 'نادِي طفلكِ باسمه من إحدى زوايا الغرفة. سترين أنه سيلتفت فورًا نحو الصوت وينظر إليكِ. سمعه وانتباهه ممتازان!'),
  ('b0613bc2-510c-4582-8829-fd09f1ed2898', 'هل يهتم بالنكهات؟ 🍽️', 'هل يراقب طبقكِ وفمكِ باهتمام وأنتِ تتناولين الطعام؟ إن اهتمامه بالأطعمة الصلبة (الأغذية التكميلية) يبدأ تدريجيًا!'),
  ('cd2a678b-9234-4910-9725-95b0b9e3443e', 'الروتين المسائي هو تذكرة قطار النوم.🚂', 'حمّام دافئ، وتدليك، وتعتيم الغرفة... لا تغيّري هذا الروتين أبدًا.'),
  ('92d9f590-3160-4e15-966d-3ee82f9db1d0', 'الاستكشاف بالفم 🦷', 'هل يمضغ طفلكِ كل شيء بشدة، وخاصة أصابعه؟ ينبهكِ متتبع التسنين! حان الوقت لتحضير حلقات تسنين نظيفة.'),
  ('02654c5d-e5dc-4168-b20f-e995771e2a24', 'قوة التضامن 💬', 'ادخلي إلى مجتمع Anacan هذا المساء، وشاركي مراحل تطور طفلكِ وناقشيها مع الأمهات اللواتي أنجبن في الشهر نفسه.'),
  ('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3', 'افتخري بنفسكِ 👏', 'انظري حولكِ وفكري في مدى التقدم الذي أحرزتِه. لقد تحول خوف الأسابيع الأولى إلى ثقة أم راسخة. أنتِ رائعة!'),
  ('50a6a489-6955-49c4-9f2c-e768f813dd17', 'أصابع القدم في الفم 👣', 'لقد اكتشف طفلكِ قدميه ويحاول وضعهما في فمه! احرصي على تصوير هذه اللحظة الطريفة والرائعة من مراحل تطوره لمشاركتها مع أحبائكِ.'),
  ('4a91e0c3-a4cb-4e5c-b68a-474b7d153369', 'واصلي عدّ الحفاضات! 🧷', 'سجّلي عدد الحفاضات يوميًا في Anacan للتأكد من أن رضيعكِ يحصل على كفايته من الحليب.'),
  ('4d4822a8-2d08-4775-b1d8-71202fa22509', 'طاقة للأم 🔋', 'يحرق جسمكِ السعرات الحرارية مع كل رضعة يتناولها طفلكِ. جرّبي الآن من قسم الوصفات الصحية وصفة حساء خفيفة تساعد على إدرار الحليب.'),
  ('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7', 'نتابع زيادة الطول والوزن! 📏', 'حدّثي أحدث القياسات في قسم متتبع النمو، وشاهدي مخطط النمو الصحي لطفلكِ بكل فخر.'),
  ('648c9f9b-15f6-49e6-933c-3da395b58c88', 'محاولات لا تعرف الاستسلام 🐢', 'هل يحاول طفلكِ الزحف إلى الأمام أثناء استلقائه على بطنه ثم يشعر بالانزعاج؟ إنه يريد التحرك بالفعل! شجّعيه على سحب نفسه إلى الأمام بوضع الألعاب أمامه.'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'لا تتناولي الغداء على عجل وسط مشاغل يومكِ. 🥑', 'حضّري سلطة سهلة من بين الوصفات الصحية، واجلسي لتتناوليها بكل استمتاع.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'لقطة ضحكة مرحة 📸', 'إنه يضحك أكثر كل يوم! افتحي جلسة تصوير طفلكِ والتقطي اليوم صورة لضحكته المرحة التي تبدّد كل المشاعر السلبية.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'حكاية تبعث على الطمأنينة 🪄', 'ابتكري في الحكايات الذكية قصة بطل صغير يستعد لإتمام شهره 5، وأضفي على الغرفة أجواءً دافئة وحلوة.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', 'نحو الشهر 5! 🎂', 'انتبهي! لم يتبقَّ سوى 10 أيام على اليوم الكبير، يوم إتمام الشهر 5! هل تذكّرتِ طلب كعكة مميزة أو التخطيط لفكرة الاحتفال؟ ابدئي الاستعدادات من الآن!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'طفلكِ لا يهدأ وأنتِ مرهقة للغاية؟  🛑', 'ضعي طفلكِ بأمان في سريره وانتقلي إلى غرفة أخرى لمدة 5 دقائق. من حقكِ أنتِ أيضًا أن تلتقطي أنفاسكِ.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'محلّل الأصوات 😭', 'عدتِ إلى الغرفة وما زال يبكي. لا تنهاري! شغّلي صوته فورًا في محلّل البكاء، ثم لبّي احتياجه الصحيح لتهدئته.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'لا يخرج يديه من فمه 🦷', 'هل يعضّ كل شيء بقوة؟ ستساعد قطع القماش النظيفة والفاترة على تهدئة لثته.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'أبطال الليل 🦸‍♀️', 'نعلم أن الاستيقاظ ليلًا يستنزف طاقتكِ. دوّني شعوركِ بالتعب في مفكرة المزاج، واطلبي من شريككِ أن يدعمكِ.'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'صفّقي لنفسكِ 👏', 'عودي إلى جميع ملاحظاتكِ ومخططات تطوّره، وانظري كم كبر طفلكِ وكم أصبحتِ أكثر خبرة!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'أمسية الانتصار 🪄', 'شغّلي هذا المساء حكاية مفعمة بالحب من الحكايات الذكية، واحتفلي مع شريككِ بانتصاركما كفريق!'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', '10 دقائق للأم ☕', 'فوضى المنزل لن تذهب إلى أي مكان. لا تسارعي إلى إنجاز الأعمال فور نوم طفلكِ، بل حضّري لنفسكِ فنجان قهوة ساخنًا واسترخي لمدة 10 دقائق، حتى لو اكتفيتِ بالنظر إلى الحائط.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'اكتشاف النقل من يد إلى أخرى 🧸', 'هل يستطيع نقل اللعبة من يد إلى أخرى؟ هذا دليل رائع على تناغم عمل نصفي الدماغ! سجّلي هذه المهارة المهمة في متتبّع التطوّر.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'شاركي حالتكِ المزاجية 📝', 'هل تشعرين اليوم بإرهاق شديد أم أنكِ مفعمة بالطاقة؟ اكتبي مشاعركِ بصدق في مفكرة الحالة المزاجية. سيساعدكِ التعبير عمّا بداخلكِ على الشعور بالتحسن.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'حكايات صوتية 🪄', 'لنضف هذا المساء سحرًا مختلفًا إلى الغرفة. أنشئي في الحكايات الذكية قصة عن قط شجاع يطير إلى القمر، واجعلي روتين النوم ممتعًا.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'مهدّئ طبيعي ⛅', 'هل طفلكِ شديد الانزعاج ولا يريد البقاء في المنزل؟ تحقّقي من حالة الطقس وملابسه، ثم اخرجا فورًا إلى الحديقة. فالهواء النقي أفضل دواء لكليكما.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'هل يضع في فمه كل ما تقع عليه يداه؟ 🤤', 'هذه طريقته في اكتشاف العالم. احرصي فقط على أن تكون الأشياء المحيطة به نظيفة وآمنة.'),
  ('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9', 'خزّني طاقتكِ 🍲', 'إذا كنتِ بصحة جيدة، فطفلكِ كذلك. اختاري من الوصفات الصحية وصفة كعكة لذيذة تمنحكِ الطاقة، واستمتعي بها مع القهوة.'),
  ('9ee15fcc-d37a-4d63-9556-1032868e91e8', 'هَلْ طَلَبْتِ الكَعْكَة؟ 🎂', 'لم يتبقَّ سوى 5 أيام ليُكمل صغيركِ شهره الخامس! أكملي طلبكِ الآن للحصول على كعكة مميزة أو ملابس بتصميم الشهر الخامس!'),
  ('d25e75e7-0029-43b9-b1e7-c401d6b9ca28', 'مؤلِّفة الحكايات الذكية 🪄', 'أنشئي الليلة في قسم الحكايات الذكية قصة خاصة ومؤثرة تروي مدى سرعة نمو صغيركِ واقترابه من شهره الخامس.'),
  ('6a21d9c4-96ab-4453-9d5f-d8979016e2cc', 'نحو الاستقلالية 🤸‍♂️', 'هل أصبح يتدحرج بسهولة من ظهره إلى بطنه؟ عضلاته تنمو بسرعة. ضعيه بانتظام على السجادة ليتمكن من الحركة بحرية.'),
  ('c057830d-8790-40ec-a09d-53a252d3ee15', 'تخلّصي من الشعور بالذنب 🛑', 'هل نفد صبركِ اليوم ورفعتِ صوتكِ؟ لا تلومي نفسكِ؛ فأنتِ لستِ روبوتًا لا يتعب. حاولي مجددًا غدًا.'),
  ('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a', 'لستِ وحدكِ 💬', 'اطّلعي على ما تكتبه أمهات الأطفال بعمر 5 أشهر في مجتمع Anacan. ففي كل منزل الفوضى نفسها، وقلة النوم نفسها، والحب نفسه!'),
  ('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5', 'لا تفوّتي إشارات النعاس 🥱', 'إذا أخذ يحدّق في الفراغ، فاتركي كل ما بيدكِ فورًا. خذيه إلى سريره قبل أن تفوتكِ نافذة نومه.'),
  ('0ecae509-0e89-4406-80e4-d01161b92754', 'عضّاضة الأسنان المنقذة 🦷', 'هل يحاول عضّ كل شيء؟ ستساعد عضّاضات السيليكون المبرّدة على تهدئة لثته فورًا.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'أترينني؟ 🧸', 'أخفي اللعبة إلى منتصفها تحت البطانية. هل يبحث عنها ويجدها؟ إنها خطوة تطورية رائعة نحو فهم مفهوم بقاء الأشياء!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'التنزه ضروري ⛅', 'تحققي من أداة الطقس والملابس، وألبسي رضيعكِ واخرجي للتنزه في الحديقة لمدة 20 دقيقة على الأقل. فهذا ضروري لكِ وله أيضًا.'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'بذكاء الطبيب 🤖', 'هل لاحظتِ شيئًا غريبًا في حركات طفلكِ؟ بدلًا من قراءة أخبار مخيفة على الإنترنت، احصلي على إجابة دقيقة من Anacan AI.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'تهويدة من الأب 👨‍🍼', 'فعّلي وضع الشريك لتصل الإشعارات إلى زوجكِ. دعيه يروي القصة ويغني التهويدة الليلة استعدادًا للنوم، واكتفي أنتِ بالمشاهدة.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'حفل الصباح 🎶', 'ينظر إليكِ وينطق مقاطع صوتية مختلفة بابتسامة عريضة. إنه يقدّم الآن أجمل حفل صباحي في الغرفة، فأصغي إليه باهتمام!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'هل لديكِ تساؤلات حول روتين النوم؟ 🤖', 'اكتبي أسئلتكِ عن تغيرات النوم مع اقتراب الشهر الخامس في مجتمع Anacan، واحصلي على الدعم من الأمهات الأخريات.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'مراقبة الضوضاء 🤫', 'قد يصبح الاستغراق في النوم أكثر صعوبة أحيانًا في نهاية الشهر الرابع. افتحي مقياس الضوضاء، وتحققي من الحد المسموح به، واحرصي على جعل الغرفة مظلمة تمامًا.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'أنتِ الأفضل! 💖', 'لا يوجد إنسان مثالي، لكنكِ أنتِ تحديدًا أفضل أم لطفلكِ.'),
  ('60bbb8df-cb46-4930-8422-5f0c6fa7daad', 'أعرفكِ! 🥰', 'هل يبتسم لكِ عند دخولكِ الغرفة ابتسامة خاصة وأكثر حماسًا ومختلفة؟ نعم، إنه يميّزكِ عن الجميع ويعشق رائحتكِ!'),
  ('adbfecc6-7186-41fe-a870-83cf6809ec00', 'خصّصي وقتًا لنفسكِ 🛋️', 'عندما ينام طفلكِ، خصّصي وقتًا لنفسكِ بدلًا من القيام بالأعمال المنزلية. لا بأس أن تبقى الغرفة غير مرتبة، لكن من الضروري أن تستعيدي طاقتكِ.'),
  ('ba61a641-e703-4b01-b161-601cf36add7a', 'سحر الطبيعة ⛅', 'هل طفلكِ شديد الانزعاج؟ ألا تفيد أي لعبة؟ تحققي من حالة الطقس وملابسه، ثم اصطحبيه فورًا إلى الهواء الطلق. فالطبيعة أفضل مهدّئ.'),
  ('e97550d4-794b-4a9e-94da-881338077d81', 'لماذا يبكي مجددًا؟ 😭', 'نوبات البكاء التي تعجزين عن معرفة سببها مرهقة للغاية. لا ترهقي نفسكِ، واستخدمي تحليل البكاء لاكتشاف الرسالة الخفية في صوته.'),
  ('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed', 'قوة الأمهات 🤖', 'انظري حولكِ وافتخري بوصولكِ إلى الشهر الخامس. إذا كان لديكِ أي مخاوف، فاكتبي إلى Anacan AI واحصلي على الدعم.'),
  ('792511a4-1d02-4324-a33c-59bacedb4645', 'بقي يوم واحد على الذكرى! 🎈', 'غدًا هو اليوم المنتظر! هل كعكة إتمام ٥ أشهر جاهزة والملابس مكوية؟ افتحي أداة جلسة تصوير الطفل والتقطي بعض الصور التجريبية من الآن!'),
  ('af763c83-7a14-4218-b3c2-49cdc7255b18', 'تحدّثي من القلب مع شريككِ 🥂', 'استعيدا هذا المساء ذكريات الأيام الأولى واضحكا معًا. لقد قطعتما شوطًا طويلًا!'),
  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', '٥ أشهر كاملة! 🎉', 'أمر لا يُصدّق! منذ ١٥٠ يومًا، أي ٥ أشهر كاملة، وأنتما تعملان كفريق واحد لرعاية هذه المعجزة وهي تكبر. افتحي فورًا أداة جلسة تصوير الطفل وخلّدي هذا اليوم المميز!'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'شفرة البكاء 😭', 'هل تذمّره الصباحي بسبب الجوع أم التسنين؟ لا تخمّني، دعي ميزة تحليل البكاء تستمع إلى صوته لتكتشفي حاجته فورًا.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'هل نفد صبركِ؟  👨‍👧', 'دعي الأب يتولى رعاية الطفل بالكامل هذا المساء، بينما تضعين سماعاتكِ وتستريحين.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'نحن فريق واحد! 🌟', 'هل تشعرين بالوحدة وبأن لا أحد يفهمكِ؟ خذي نفسًا عميقًا. أنتِ أقوى بطلة في هذه الأيام العاصفة، وتبلين بلاءً رائعًا.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'هدوء تام 🤫', 'هل أصبح النوم صعبًا؟ تحققي من مستوى الديسيبل في الغرفة باستخدام مقياس الصوت. أغلقي صوت التلفاز واجعلي الغرفة مظلمة تمامًا.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'حكة في اللثة؟ 🦷', 'هل يضع أصابعه في فمه باستمرار ويسيل لعابه بغزارة؟ حان وقت استخدام عضّاضات التسنين المبردة.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'لا تنسي نفسكِ 🥑', 'هل انشغلتِ بإطعام رضيعكِ حتى نسيتِ تناول الطعام؟ اختاري من الوصفات الصحية وجبةً غنية بالطاقة يمكن تحضيرها خلال 10 دقائق.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'تهويدة الليل 🎶', 'لا شيء يبعث على الطمأنينة مثل صوت الأم. ضمّيه إلى صدركِ هذا المساء وغنّي له تهويدته المفضلة بصوت خافت.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'هل الألعاب في كل مكان؟ 🌪️', 'هل الألعاب منتشرة في أرجاء الغرفة؟ لا تشعري بالتوتر لأن منزلكِ غير مرتب. أنتِ أم رائعة، وأولويتكِ هي طفلكِ لا التنظيف.'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'ماذا تفعل الأمهات الأخريات؟ 💬', 'هل تشعرين بالقلق؟ انضمي إلى مجتمع Anacan. ستشعرين بالطمأنينة عندما ترين أن الأمهات هناك يعشن الحرمان نفسه من النوم ويواجهن المشكلات ذاتها.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'المستلزمات توشك على النفاد 🛒', 'هل نفدت الحفاضات أو زيت الأطفال؟ لا ترهقي ذهنكِ بالتفاصيل الصغيرة؛ أضيفيها إلى قائمة التسوق ليشتريها زوجكِ في طريق عودته.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'هل لديكِ سؤال؟ 🤖', 'هل يدور في ذهنكِ آلاف الأسئلة حول نمو طفلكِ؟ بدلًا من قراءة المنتديات لساعات، اكتبي إلى Anacan AI واحصلي على إجابة علمية موجزة.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'نتابع عدد الحفاضات يوميًا. 🧷', 'للتأكد من أن رضيعكِ يحصل على تغذية كافية وللاطمئنان على جهازه الهضمي، سجّلي كل تغيير للحفاض في Anacan.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'قوة التضامن 🛋️', 'بعد يوم شاق، اجلسي مع زوجكِ وتحدّثا بصراحة عما يثقل كاهلكما. فدعم أحدكما للآخر والشعور بأنكما فريق واحد يخففان العبء إلى النصف.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'افتخري بنفسكِ 👏', 'عندما تنظرين إلى الوراء، تذكّري مدى خوفكِ في الأسابيع الأولى. وانظري الآن كيف تديرين كل شيء باحتراف! أنتِ رائعة!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'اقترب موعد الاكتشافات اللذيذة! 🥦', 'استعدّي للشهر المقبل بقراءة أفكار المهروسات الأولى في قسم الوصفات المخصّص للرضّع الذين يبدأون بتناول الأطعمة التكميلية.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'طبيب الأطفال في جيبكِ 🤖', 'هل تغيّر نمط نوم طفلكِ فجأة؟ قبل أن تقلقي، احصلي من Anacan AI على معلومات ونصائح حول تراجع النوم في عمر ٥ أشهر.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'أنتِ كافية! 💖', 'هل سارت الأمور اليوم بعكس ما أردتِ؟ لا تلومي نفسكِ. هل أنتِ روبوت؟ لا. تقبّلي مشاعركِ، وسامحي نفسكِ، وابتسمي.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'نحو إتمام نصف عام 📈', 'هل تصدقين؟ لم يتبقَّ سوى القليل على إتمام الشهر السادس! افتحي متتبّع النمو، وتأمّلي بفخر الرحلة المذهلة التي قطعتِها حتى هذا الشهر.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'سلّمي المناوبة 🛋️', 'إذا كنتِ ترغبين في الاستلقاء والنوم فور نوم طفلكِ، فأوكلي المهام المنزلية الأخرى إلى شريككِ.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'ضبابية الذاكرة 📝', 'النسيان جزء من مرحلة ما بعد الولادة. استخدمي قائمة التسوق بانتظام حتى لا يفوتكِ شيء.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'الصديق في المرآة 👀', 'خذي طفلكِ أمام المرآة. إن النظر إلى انعكاس صورته والمناغاة له نشاط ممتع ورائع لنموه الذهني.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'نقاش بين شريكين 🥂', 'افتحي مفكرة المزاج، واتركي سلبيات هذا اليوم خلفكِ، واستمتعي بروح الفريق مع شريككِ.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'البحث عن عضّاضة 🦷', 'يزداد سيلان اللعاب وحكة اللثة. حلقات التسنين النظيفة هي خير عون لكِ.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'هل ترينني؟ 🧸', 'أخفي اللعبة تحت البطانية. هل يبحث عنها طفلكِ ويجدها؟ إنها لحظة تطورية رائعة تساعده على فهم مفهوم بقاء الأشياء!'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'التقلب بشكل مستقل 🤸‍♂️', 'هل أصبح يتقلب بسهولة من ظهره إلى بطنه؟ ضعيه على بساط واسع ليتمكن من تحريك عضلاته بحرية.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'جمّدي اللحظة 📸', 'إنه يكبر بسرعة كبيرة... التقطي ملامح وجهه الهادئة واللطيفة في أثناء نومه من خلال جلسة تصوير لطفلكِ، واحتفظي بها ذكرى جميلة.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'لنجعل الاستيقاظ ليلًا جزءًا من الروتين 😴', 'لا تشغّلي الأضواء كلما استيقظ. أطعميه باستخدام مؤقت Anacan، ثم أعيديه إلى النوم بمساعدة الضوضاء البيضاء.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'لا تنظيف اليوم 🛑', 'هل أنتِ متعبة؟ أخبري شريككِ. لا طعام منزلي اليوم ولا تنظيف. اليوم هو يوم راحة الأم واحتساء القهوة!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'تحدّثي معي! 🗣️', 'هل يستمع إليكِ باهتمام ويصدر أصواتًا مختلفة؟ إنه يجري معكِ حوارًا حقيقيًا. استجيبي لأصواته وشجّعي هذا التواصل.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'المحاولات الأولى للجلوس 🪑', 'عندما تُجلسينه مع إسناده، هل يبقي رأسه وظهره أكثر استقامة؟ هذا يدل على أن عضلاته تزداد قوة. ابدئي بتمارين الجلوس مع الدعم لفترات قصيرة.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'اخرجي من بين الجدران الأربعة ☕', 'هل تشعرين بالاختناق من البقاء في المنزل؟ ابحثي عن أقرب مقهى يسهل دخوله بعربة الأطفال، واستمتعي بقهوتكِ في أجواء مختلفة.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'علامات النعاس 🥱', 'إذا كان يفرك عينيه ويحدّق في الفراغ، فلا تنتظري حتى يبدأ بالبكاء. أظلمي الغرفة فورًا وابدئي روتين النوم.'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'الأب بطل الليلة 🦸‍♂️', 'أجمل قاعدة في الأشهر الأولى: يجب أن تتناوبا على تهدئة طفلكِ لينام! هذا المساء طفلكِ بين ذراعي والده، وأنتِ تستريحين.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'حان وقت الخروج 🌳', 'ضعي طفلكِ في عربته واخرجي لاستنشاق الهواء النقي، ولو لمدة 15 دقيقة فقط. فكلاكما يحتاج إلى الهواء.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'حفلة الصباح 🎶', 'ينظر إليكِ ويصدر أصواتًا جديدة بابتسامة عريضة. إنه يقدّم الآن أجمل حفلة في الغرفة، فأنصتي إليه باهتمام!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'أساس النوم الجيد ⏱️', 'حمّام دافئ، وتدليك، وتعتيم الغرفة... لا تخلّي أبدًا بروتين النوم، لتنعمِي بليالٍ هادئة.'),
  ('ddef2887-0bec-40c8-91a4-05edb188b86b', 'بذكاء يضاهي الطبيب 🤖', 'بدلًا من قراءة أخبار مخيفة على الإنترنت، اطرحي على Anacan AI أسئلتكِ حول بدء تقديم الأغذية التكميلية واطمئني.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'هدوء ذكي 🤫', 'هل توقظه الأصوات المفاجئة عندما يخلد إلى النوم؟ استخدمي مقياس الصوت لمراقبة مستوى الديسيبل في الغرفة.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'ملابس محيّرة 👗', 'هل تلبسينه أحيانًا ملابس خفيفة جدًا وأحيانًا دافئة أكثر من اللازم؟ لا تحتاري. تحققي من الطقس والملابس، ثم ألبسيه بثقة.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'وليمة للأم 🥑', 'وسط انشغالاتكِ اليومية، لا تتناولي الغداء على عجل وأنتِ واقفة. حضّري سلطة سهلة من الوصفات الصحية، ثم اجلسي وتناوليها باستمتاع.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'جائع أم متعب؟ 🧩', 'لا يتوقف عن البكاء مهما فعلتِ؟ ربما يكون مرهقًا جدًا فحسب. وللتأكد، استخدمي ميزة تحليل البكاء لاكتشاف السبب وراء صوته.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'مراقبة الصوت 🤫', 'هل توقظه الأصوات المفاجئة عندما يغفو؟ استخدمي مقياس الصوت للتحكم في مستوى الضوضاء داخل الغرفة.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'طاقة الأم 🔋', 'هل تنفد طاقتكِ في منتصف اليوم؟ تصفحي الوصفات الصحية واختاري وصفة سموذي تدعم إدرار حليبكِ وتمنحكِ النشاط في الوقت نفسه.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'قوة الموسيقى 🎶', 'حاولي تهدئة نوبات البكاء غير المبررة التي تبدأ في أواخر فترة ما بعد الظهر، بتشغيل موسيقى كلاسيكية هادئة أو ضوضاء بيضاء.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80'::uuid, 'مفاجآت الطقس ⛅', 'لا تدعي تقلبات الطقس تخدعكِ عند الخروج للتنزه فتعرّض رضيعكِ للبرد. استعيني بمساعد الطقس والملابس لاختيار ما يناسب الأجواء في الخارج.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'مهتم بالنكهات؟ 🍽️', 'ألا يرفع عينيه عن طبقكِ بينما تتناولين الطعام؟ بدأت تظهر علامات استعداده لتناول الأطعمة الصلبة. لكن لا تتعجلي بعد، وانتظري حتى الشهر السادس.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'مشاركة التجارب 💬', 'هل فاجأتكِ حركة جديدة قام بها طفلكِ؟ انضمي إلى مجتمع Anacan وناقشي هذا الاكتشاف مع الأمهات الأخريات.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'الحكاية لا تنتهي 📖', 'قدّمي هذا المساء إلى الحكايات الذكية فكرة جميلة: قصة الجنية التي تنام فوق قوس قزح.'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'اعتني بنفسكِ 🛋️', 'عندما ينام طفلكِ، خصّصي وقتًا لنفسكِ بدلًا من القيام بالأعمال المنزلية. لا بأس أن تبقى الغرفة غير مرتبة، لكن يجب أن تستعيدي طاقتكِ.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'هل يرمي ألعابه على الأرض ويراقبها؟ 🎯', 'إنه يفعل ذلك ليتعرف إلى الجاذبية والعلاقة بين السبب والنتيجة! أعيدي إليه اللعبة بصبر.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'لستِ وحدكِ 💬', 'هل تشعرين بالقلق؟ انضمي إلى مجتمع Anacan واطرحي سؤالكِ. ثقي أن جميع الأمهات يخضن تجارب مماثلة.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'الاستعداد لإدخال الأطعمة التكميلية 🥣', 'لم يتبقَّ الكثير حتى الشهر السادس. هل تودين معرفة المزيد عن الوجبات المهروسة الأولى؟ اسألي Anacan AI عن المعلومات الأساسية حول بدء إدخال الأطعمة التكميلية.'),
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776', 'قوة التضامن 🥂', 'تحدثي هذا المساء مع شريككِ عن رحلتكما للوصول إلى هذه المرحلة المهمة. لقد أنجزتما عملًا رائعًا كفريق.'),
  ('c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f', 'بقيت ١٠ أيام على بلوغ نصف عام! 🎂', 'استعدي! بعد ١٠ أيام بالضبط، سيبلغ صغيركِ ٦ أشهر، أي نصف عام! حان الوقت تمامًا لطلب كعكة هذه المناسبة واختيار ملابس مميزة!'),
  ('3259939c-e2bd-4126-abc3-d15439051dda', 'قوة الهواء النقي 🌳', 'إذا كان طفلكِ شديد الانزعاج، فاصطحبيه فورًا إلى الهواء الطلق. فالهواء النقي من أبسط الوسائل وأكثرها فاعلية لتهدئة نوبات البكاء.'),
  ('382370f5-d970-4100-b0bc-f8460c0758ae', 'بارع في الإمساك 👐', 'هل يحاول الإمساك بأشياء كبيرة بكلتا يديه في الوقت نفسه؟ اختبري ذلك بإعطائه كرة ناعمة.'),
  ('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d', 'قصص صوتية 🪄', 'أنشئي هذا المساء في قسم الحكايات الذكية قصة الفارس الشجاع الذي كبر وأصبح عمره 6 أشهر.'),
  ('0e21a1c5-4a15-41e9-abfe-8342adaebb92', 'لا وجود للكمال 🛑', 'هل نفد صبركِ اليوم، وربما شعرتِ بالغضب؟ لا تلومي نفسكِ. دوّني مشاعركِ في مفكرة المزاج لتشعري بالارتياح.'),
  ('31e88909-0b90-49e0-8727-857efb6836f3', 'تهويدة من الأب 👨‍🍼', 'فعّلي وضع الشريك لتصل الإشعارات إلى شريككِ. دعيه يغني لطفلكِ تهويدة النوم هذه الليلة.'),
  ('a24757f2-97fa-405f-9959-e4c715aa8ed8', 'أبحث عنكِ! 👀', 'هل يبحث عنكِ بعينيه ويبكي عندما تغادرين الغرفة؟ ربما يبدأ قلق الانفصال بالظهور تدريجيًا. امنحيه شعورًا بالأمان.'),
  ('989db48b-e318-47e6-9019-f4f957b60d59', 'نوبات البكاء التي لا تعرفين سببها مرهقة. 😭', 'لا ترهقي نفسكِ، استخدمي تحليل البكاء واكتشفي الرسالة الكامنة في صوته.'),
  ('a6d43603-e416-4760-8a3f-176e42bf2dc7', 'لعبة الغميضة هي المفضلة لديه! 🙈', 'غطّي وجهكِ بيديكِ ثم اكشفيه، وراقبي مدى سعادته. تعرّفي إلى مزيد من الألعاب المشابهة في قسم المدونات.'),
  ('a85c19d5-09d8-4302-9d52-6f63acdaebee', 'تهويدة المساء 🎶', 'لا يوجد صوت أكثر تهدئة من صوت الأم. ضمّيه إلى صدركِ هذا المساء وغنّي له بصوت خافت.'),
  ('2fc6e816-81b8-4662-85f5-ea7fd4e748a8', '10 دقائق للأم ☕', 'لن تذهب فوضى الغرفة إلى أي مكان. لا تبدئي بالأعمال فور نومه. حضّري لنفسكِ كوبًا من القهوة واستريحي لمدة 10 دقائق فقط.'),
  ('affd2ecc-89d1-4649-8b63-63dfe9a1ced9', 'أبحث عنكِ! 👀', 'هل يبدأ بالبكاء فور خروجكِ من الغرفة؟ لقد بدأ قلق الانفصال يتشكّل بوضوح. فهو يخشى ببساطة ألّا تعودي إليه. طمئنيه بصوتكِ.'),
  ('c4e8f9e9-c94b-41fc-a23a-61a8c7026386', 'تغيّرات في الجهاز الهضمي 🧷', 'سيتغيّر برازه مع بدء التغذية التكميلية. تابعي حالته عن كثب بتسجيل كل تغيير للحفاض في Anacan.'),
  ('3bd59fce-abbd-4e13-ab2d-4379b5c89cac', 'ألا يأكل الطعام المهروس ويبصقه؟', 'لا تشعري بأنكِ غير قادرة. فهذه تجربة جديدة تمامًا بالنسبة إليه، لذا تحلّي بالصبر.'),
  ('48005ac4-750b-4fca-b0cd-2711d3eb3c21', 'حكايات صوتية 🪄', 'اختتمي هذا اليوم بطريقة ممتعة عبر إنشاء حكاية في «الحكايات الذكية» هذا المساء.'),
  ('ae1cbea0-aaaf-49ff-9518-967813809e3b', 'حكة في اللثة؟ 🦷', 'قد تزداد أيضًا آلام التسنين خلال مرحلة التغذية التكميلية. استخدمي جل التسنين بعد استشارة الطبيب.'),
  ('4beff801-d69f-40c0-bed1-2e8938edb5f2', 'ماذا تفعل الأمهات الأخريات؟ 💬', 'ألا يحب طفلكِ هريس اليقطين؟ انضمّي إلى مجتمع Anacan للاطّلاع على تجارب الأمهات ووصفاتهن المختلفة.'),
  ('7df7f58f-05e6-4afb-aa2c-73438e6504d4', 'علامات النعاس 🥱', 'إذا كان يفرك عينيه ويحدّق في الفراغ، فلا تنتظري حتى يدخل في نوبة بكاء. أظلمي الغرفة فورًا وابدئي روتين النوم.'),
  ('8afe4995-9e98-44a1-a9cc-5c970d87a396', 'محاولات الجلوس دون دعم 🪑', 'هل أصبح يتّكئ على الوسائد بدرجة أقل؟ سيتمكّن قريبًا جدًا من الجلوس دون أي دعم!'),
  ('081951c6-0b7d-4045-b641-a4716f751a3d', 'على كتفي الأب 👨‍👧', 'هل نفد صبركِ؟ فعّلي وضع الشريك، ودعي الأب يتولى رعاية الطفل بالكامل هذا المساء.'),
  ('b099b3d8-9148-450c-8795-4ab16ea72b2c', 'هل بقي لديكِ أي سؤال؟ 🤖', 'بأي نوع من مهروس الخضراوات أبدأ أولًا؟ – اطرحي هذا السؤال وغيره من الأسئلة التي تشغل بالكِ على الذكاء الاصطناعي من Anacan واحصلي على معلومات دقيقة.'),
  ('e3aafd70-c5f0-4254-ba79-e24f4dca3567', 'شلال اللعاب 🤤', 'هل بدأت ياقة ملابسه تبتل كثيرًا؟ جهّزي عضّاضات التسنين المصنوعة من السيليكون.'),
  ('34eb8ef4-b7a5-4969-916d-abfccb27c775', 'مراقبة مستوى الديسيبل 🤫', 'هل يخيفكِ كل صوت في المنزل عندما ينام طفلكِ؟ فعّلي مقياس الصوت وتحققي من مستوى الضوضاء في الغرفة.'),
  ('da48ef6d-1a19-4a32-9bdc-d912779edf22', 'منزل فوضوي، طفل سعيد 🌪️', 'هل امتلأت الغرفة بالألعاب؟ 10 دقائق مرحة تقضينها معه أهم من التنظيف.'),
  ('ec6f8334-a2ec-4274-9ce3-07c0a3276622', 'التقلب باستقلالية 🤸‍♂️', 'هل أتقن تمامًا التقلب من ظهره إلى بطنه ومن بطنه إلى ظهره؟ سجّلي هذا الإنجاز في متتبع النمو!'),
  ('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d', 'إشارات النعاس 🥱', 'هل يفرك عينيه؟ لا تنتظري نوبة الإرهاق من شدة النعاس، بل أظلمي الغرفة فورًا وابدئي روتين المساء.'),
  ('a9165256-d8d7-431e-ac72-e7ef065f4e1f', 'طاقة للأم 🍲', 'تحتاجين إلى الطاقة من أجل احتفال الغد. اختاري وجبة خفيفة ومشبعة من الوصفات الصحية ثم استريحي.'),
  ('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df', 'رشّحي الأصوات 🤫', 'قد تعيق أصوات الشارع النوم العميق. تحقّقي من مقياس الضوضاء واستخدمي الضوضاء البيضاء عند الحاجة.'),
  ('9bb7f096-5daa-4e1c-9f5e-688698945f7a', 'هل الأسنان في طريقها للظهور؟ 🦷', 'هل توجد آلام أو تورّمات في اللثة السفلية؟ قد تبدأ الأسنان الأولى بالظهور قرابة الشهر السادس.'),
  ('2ecd0a8e-2817-4551-98e0-4276739c7da9', 'نحن فريق واحد! 💖', 'ساندتما بعضكما خلال الليالي التي حُرمتما فيها من النوم على مدار ٦ أشهر. افتحي يوميات الحالة المزاجية واشكري شريككِ على هذا العمل الجماعي.'),
  ('ce877206-0633-48d8-aa8f-9241cfab27c3', 'كرسي الطعام التكميلي 🪑', 'هل تفكرين في شراء كرسي إطعام؟ ألقِي نظرة على الكراسي المريحة وسهلة التنظيف في قسم المنتجات الموصى بها.'),
  ('e6e852b1-bfb4-4197-aa7b-70b6b2367f30', 'بقيت ٥ أيام على إتمام نصف عام! 🎈', 'لم يتبقَّ سوى ٥ أيام على إتمام نصف عام! هل طلب الكعكة جاهز؟ اختاري من الآن إطارات الشهر السادس المميزة في أداة جلسة تصوير طفلكِ وخططي لها.'),
  ('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd', 'اكتشفي حكاية جديدة 📖', 'لنجعل هذه الليلة مختلفة. أنشئي قصة خاصة في الحكايات الذكية واملئي الغرفة بسحرها.'),
  ('9d58451e-ede3-4a05-ba21-dd4e0b7f4086', 'نتابع محتوى الحفاضات يوميًا 🧷', 'سجّلي كل تغيير للحفاض في Anacan للتأكد من أن الجهاز الهضمي لطفلكِ يعمل جيدًا قبل البدء بالأطعمة التكميلية.'),
  ('edc6faba-a997-408a-a40b-e590a39a3721', 'أنا أجلس! 🪑', 'هل أصبح طفلكِ أكثر ثقة عند الجلوس بمساعدة؟ شجّعيه على الجلوس مع دعمه بالوسائد، ولكن لفترات قصيرة.'),
  ('d9470e5a-6317-45d8-9bd1-419a7827e3e6', 'لنحوّل الاستيقاظ ليلًا إلى روتين. 😴', 'لا تشغّلي الأضواء في كل مرة يستيقظ فيها طفلكِ. أطعميه باستخدام مؤقت Anacan، ثم ساعديه على النوم مجددًا باستخدام الضوضاء البيضاء.'),
  ('07efb31a-2639-41f8-b1c7-f3807d010a8f', 'جمّدي اللحظة 📸', 'إنه يكبر بسرعة كبيرة... التقطي ملامح وجهه اللطيفة والهادئة أثناء نومه باستخدام جلسة تصوير الطفل، واحتفظي بها ذكرى جميلة.'),
  ('7deb7b07-a963-4605-b27c-7714e980157d', 'هل لديكِ سؤال؟ 🤖', 'هل يدور في ذهنكِ آلاف الأسئلة حول تقديم الأطعمة التكميلية والماء؟ اكتبي إلى Anacan AI واحصلي على نصائح دقيقة من أطباء الأطفال.'),
  ('ab8df92e-4241-44fb-8ac7-10559ea60a6f', 'أنا أعرفكِ! 🥰', 'هل يلتجئ إليكِ عندما يأتي شخص غريب إلى المنزل؟ لا تقلقي، فقد أصبح قادرًا ببساطة على التمييز بين المألوفين والغرباء. وهذه علامة على نمو ذهني سليم.'),
  ('5378180a-aa43-4728-9384-08bbcf8838ee', 'تحدّثي معي! 🗣️', 'هل أصبح ينطق مقاطع مثل «با-با» و«ما-ما» بوضوح أكبر؟ استجيبي لأصواته وشجّعي هذا التواصل.'),
  ('a4be80bb-cd06-42ba-b875-78d5a32af3ba', 'جلسة حوار بينكما 🛋️', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتبادلا الحديث عمّا يثقل كاهلكما. فدعم أحدكما للآخر يخفف العبء إلى النصف.'),
  ('efa880a4-37d0-4521-93db-df2495a01243', 'افتخري بنفسكِ 👏', 'عندما تنظرين إلى الوراء، تذكّري مدى خوفكِ في الأسابيع الأولى. أما الآن، فقد أصبحتِ أمًّا محترفة في تحضير الطعام المهروس!'),
  ('5be2b9be-dabd-44b8-93f3-30aaaab56ccf', 'تهويدة ليلية 🎶', 'لا صوت يبعث الطمأنينة مثل صوت الأم. هذا المساء، ضمّيه إلى صدركِ وغنّي له بصوت خافت.'),
  ('febb037e-33e6-4760-bc42-cae9b6c70a8a', 'الاستعدادات الأخيرة! 📸', 'غدًا هو اليوم الكبير! هل كعكة إتمام نصف عام جاهزة؟ جهّزي أجمل الملابس لجلسة تصوير طفلكِ، فسنلتقط الكثير من الصور غدًا!'),
  ('1ac47b8c-1167-4ac1-a522-104b832c25b0', '6 أشهر كاملة! نصف عام! 🎉', 'تهانينا! لقد أمضيتِ 180 يومًا كاملًا في رعاية هذه المعجزة وتنشئتها. أنشئي فورًا صورة مميزة لهذا اليوم الخاص في جلسة تصوير طفلكِ وشاركيها في مجتمع Anacan!'),
  ('788697fe-7a57-4c4c-a3dc-514298d952ed', 'صفّقي لنفسكِ 👏', 'عودي إلى جميع ملاحظاتكِ وتأمّليها. انظري كم كبر طفلكِ، وكم أصبحتِ أكثر خبرة! أنتما فريق رائع.'),
  ('7f7b88ee-089c-4ccc-9849-c2f4117d4833', 'أمسية الاحتفال بالنصر 🥂', 'هذا المساء، بعد أن ينام طفلكِ، اجلسي وجهًا لوجه مع شريككِ. استشعرا معًا الفخر بهذه الأيام الـ180 وتعانقا!'),
  ('7d616a8c-c926-4291-9221-42ee50e15fd5', 'مرحلة جديدة: الأغذية التكميلية! 🥣', 'اكتملت 6 أشهر! حان الوقت الآن لتعريف طفلكِ إلى مهروس الخضراوات. احصلي من Anacan AI على معلومات حول قاعدة التجربة لمدة 3 أيام للتحقق من الحساسية.'),
  ('936424c3-1b30-4fc1-924e-920162d0d5bd', 'هدوء تام 🤫', 'هل أصبح الخلود إلى النوم أكثر صعوبة؟ تحققي من مستوى الديسيبل في الغرفة باستخدام مقياس الصوت، واجعلي الغرفة مظلمة تمامًا.'),
  ('e0613a64-c64f-491d-8c87-72276f72849e', 'ملابس ملطخة 👗', 'الأغذية التكميلية تعني اتساخ كل شيء. لا تنزعجي، واستخدمي المرايل المصنوعة من السيليكون، واستمتعي بهذه اللحظات الطريفة.'),
  ('6dad4f0a-8c98-4797-a95f-50aab81d4662', 'مفاجآت الطقس ⛅', 'عندما تخرجين للتنزه، لا تنخدعي بالطقس فتشعري بالبرد. استعيني بمساعد الطقس والملابس لاتخاذ القرار المناسب وفقًا للأجواء في الخارج.'),
  ('34c92908-0941-4c15-a946-75240f0ea7f7', 'شاركي حالتكِ المزاجية 📝', 'هل تشعرين بإرهاق شديد اليوم؟ اكتبي مشاعركِ بصدق في يوميات الحالة المزاجية. فالتعبير عمّا بداخلكِ سيساعدكِ على الشعور بالراحة.'),
  ('cd45d0d2-bf31-47be-adf8-84c3b1895339', 'هل يتألم أم يعاني من الغازات؟ 😭', 'قد يؤدي بدء إدخال الأطعمة التكميلية إلى الإمساك أو الغازات. إذا لم يهدأ مهما حاولتِ، فاستخدمي تحليل البكاء لمعرفة السبب الكامن وراء صوته.'),
  ('e67730b8-4981-4bba-b868-fe6cf9b7e3da', 'المؤن توشك على النفاد 🛒', 'هل تحتاجين إلى خضراوات جديدة لتحضير المهروس؟ أضيفيها إلى قائمة التسوق ليشتري شريككِ منتجات طازجة في طريق عودته من العمل.'),
  ('1f9cc7dc-a0b4-41a4-983b-794c5917ee08', 'استكشاف من يد إلى أخرى 🧸', 'هل ينقل اللعبة بحرية تامة من يد إلى أخرى؟ هذا يدل على أن نصفي دماغه يعملان بتناغم رائع. قدّمي له أشياء ذات ملمس متنوع.'),
  ('298934a2-9d12-42b8-8c9c-6098d3709ab4', 'الأحاديث تطول! 🗣️', 'تتردد في المنزل أصوات «دا-دا-دا، با-با-با». زوري قسم المدوّنات لقراءة المزيد عن تطور مهاراته اللغوية.'),
  ('89ff16e6-d11a-4deb-ae4f-1ba03e76271d', 'الأب بطل الليل 🦸‍♂️', 'أجمل قاعدة في الأشهر الأولى: يجب أن تتناوبا على تهدئة رضيعكما لينام! هذا المساء، طفلكِ بين ذراعي أبيه وأنتِ تستريحين.'),
  ('6f0575b2-9379-4dca-bf05-d518a93aead1', 'هل نسيتِ من أي ثدي أرضعتِ؟ 🤱', 'سجّلي باستخدام المؤقت ما إذا كنتِ قد أرضعتِ من الثدي الأيمن أم الأيسر، ودعي Anacan يتذكر كل شيء نيابةً عنكِ!'),
  ('a134dfa9-2e73-4246-a281-0577e4411534', 'دعيه يلعب بالطعام! 🥦', 'دعيه يلمس الطعام ويهرسه ويستكشفه. التقطي هذه اللحظات اللطيفة والفوضوية باستخدام جلسة تصوير الطفل واحتفظي بها كذكريات!'),
  ('05e938a0-adb4-413b-992b-19bbd78f0925', 'استعدّي للاحتفال! 🎂', 'بعد ٩ أيام فقط سيُكمل طفلكِ شهره السابع! هل فكرتِ في فكرة مختلفة أو كعكة مميزة لهذا الشهر؟ ابدئي التحضيرات من الآن كي لا تتراكم حتى اليوم الأخير.'),
  ('9c5c6958-af17-4420-aa80-95cd295c8995', 'اليدان حرتان 👐', 'هل يمدّ طفلكِ إحدى يديه نحو لعبة وهو مستلقٍ على بطنه، ويستند إلى اليد الأخرى؟ إن توازن عضلاته يتحسن باستمرار!'),
  ('acd2495b-eae5-4005-8f31-3fdfdc4738aa', 'حان دور الأب 👨‍👧', 'سلّمي مهمة رعاية طفلكِ اليوم إلى زوجكِ لبعض الوقت. دعيهما يلعبان، بينما تمدّين ساقيكِ وتستريحين قليلًا.'),
  ('094a764e-f3f1-4dd1-8a87-04126b16323f', 'لا تنسي نفسكِ 🍲', 'لقد تناول طفلكِ طعامه المهروس، فماذا عنكِ؟ عليكِ أن تتغذّي جيدًا لاستعادة طاقتكِ. اطلبي لنفسكِ اليوم وجبة مغذية ومشبعة.'),
  ('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6', 'أنا أعرفكِ 👀', 'هل يتشبث بكِ طفلكِ وينظر إلى الضيوف باستغراب عندما يزوركم أحد؟ لقد بدأ قلق الانفصال. فهو لا يشعر بالأمان إلا بجوار أمه، لذا احترمي مشاعره.'),
  ('740c028d-4797-4507-a894-816747e5301d', 'حكايتكما الخاصة 🪄', 'لنختر هذا المساء موضوعًا لطيفًا لأداة الحكايات الذكية: “حكاية أحلى نجمة سقطت من السماء”. ودعي صوت هذه الحكاية وحده يملأ الغرفة.'),
  ('21f7df85-0fd1-4e90-a27b-52045487116f', 'الاستيقاظ ليلًا 🌙', 'هل بدأ طفلكِ يستيقظ كثيرًا ليلًا مع اقتراب مرحلة التسنين؟ تحلّي بالصبر، فآلام اللثة تزعجه. أشعريه بأنكِ بجانبه.'),
  ('3ad2c870-178d-449f-aabd-6c01acacefd8', 'محاولات الحبو 🐢', 'هل يرتكز طفلكِ على ركبتيه ويتأرجح إلى الأمام والخلف؟ إنه يستعد للحبو!'),
  ('b80481ba-8798-458c-83d8-f359b3802548', 'لحظة هدوء ☕', 'فوضى الغرفة لن تذهب إلى أي مكان. عندما يلعب طفلكِ بمفرده، لا تسارعي فورًا إلى التنظيف. اجلسي على الأريكة ولا تفعلي شيئًا لمدة 10 دقائق.'),
  ('104420b5-a415-4abb-81d8-7f7b520d18bd', 'استكشاف اللثة 🦷', 'هل يمضغ طفلكِ كل شيء بقوة ويسيل لعابه؟ تابعي مراحل التسنين باستخدام متتبع التسنين. حلقات التسنين المبردة هي المنقذ في هذه الأيام.'),
  ('c9c8946d-7797-4bd6-8476-9f649f770a6e', 'نحن فريق واحد! 💪', 'هل تشعرين بالوحدة والإرهاق؟ خذي نفسًا عميقًا. أنتِ وشريككِ أقوى بطلين في هذه الأيام العاصفة.'),
  ('f8790842-2782-419a-aaaa-3c8c1fc497de', 'الطقس والملابس ⛅', 'لا تحتاري بشأن ما ستُلبسينه لطفلكِ عند الخروج. تحققي من أداة الطقس والملابس، واختاري الإطلالة المثالية في ثوانٍ، ثم اخرجا للاستمتاع بالهواء النقي.'),
  ('125f59de-0644-435e-8593-de05b7cc7065', 'حكايات بصوتكِ 🎶', 'لا يمكن لأي تطبيق أن يحل محل تهويدة الأم. هذا المساء، ضمّي طفلكِ إلى صدركِ وغنّي له بهدوء تهويدته المفضلة.'),
  ('63093c63-3ea0-4bb2-90bb-318617d51b7e', 'مهرجان المهروس 🥣', 'هل تلطخ وجه طفلكِ وأنفه وحتى شعره بالطعام؟ بدلًا من الانزعاج، خلّدي هذه اللحظة اللطيفة من خلال جلسة تصوير الطفل.'),
  ('9ff73499-a2bd-41b7-96fa-1ec2d780279f', 'لا تشعري بالذنب 💖', 'هل تظنين أنكِ لا تقضين وقتًا كافيًا مع طفلكِ، أو أنكِ لا تتمكنين من إنجاز الأعمال المنزلية؟ توقفي عن لوم نفسكِ. أنتِ تقومين بعمل رائع.'),
  ('5cafdda5-c60b-4328-9530-450093ed8026', 'هدوء تام 🤫', 'هل يواجه طفلكِ صعوبة في النوم؟ اجعلي الغرفة مظلمة تمامًا وأوقفي جميع الأصوات. الظلام والهدوء أفضل رفيقين لنومه.'),
  ('c2924eec-8b24-41b0-b28a-f63497f548c2', 'مشاركة التجارب 💬', 'هل تبحثين عن وصفات للأطعمة التكميلية؟ ادخلي إلى قسم الوصفات الصحية واستفيدي منه.'),
  ('2d910805-1ce0-44fc-88f6-f3f6dfe16cea', 'محاولات الحبو تتزايد! 🐢', 'هل يزحف طفلكِ إلى الخلف وهو مستلقٍ على بطنه، أو يحاول الارتكاز على ركبتيه؟ خلّدي لحظات التطور النشطة هذه في ألبوم الطفل.'),
  ('8f5769c4-aeb4-4cd1-acf0-052c7e0df753', 'حان وقت الحكاية الذكية 🪄', 'أنشئي في قسم الحكايات الذكية قصة مميزة لهذه الليلة.'),
  ('f175db80-862d-40e7-9aed-5b0a0c4423e3', 'لنُرسّخ عادة شرب الماء. 💧', 'لا تنسي تقديم الماء مع الأطعمة التكميلية.'),
  ('14f79c92-38f1-4965-a9d0-fbcb8e236840', 'نوبات سيلان اللعاب 🤤', 'هل تبتل ياقته بالكامل خلال ثوانٍ؟ لثته تستعد لظهور الأسنان. استخدمي مرايل السيليكون.'),
  ('173f7149-2567-449f-9693-a462d1148849', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي مع شريككِ وجهًا لوجه وتحدثا عما يثقل قلبيكما. دعمكما المتبادل يخفف العبء إلى النصف.'),
  ('1af66eec-0d7d-4dcd-9326-d4155d237a55', 'هل بدأ الخوف من الغرباء؟ 🙈', 'إذا كان طفلكِ يبكي عندما لا يراكِ أو عند رؤية شخص غريب، فهذا جزء من نموه. استشيري Anacan AI بشأن ذلك.'),
  ('23068177-6d18-4649-91f5-5ac9ecb37933', 'إجابات سريعة 🤖', 'هل هناك ما يحيّركِ؟ بدلًا من قضاء ساعات في قراءة المنتديات، اطرحي سؤالكِ على Anacan AI واحصلي على إجابة سريعة.'),
  ('52b2efdc-0a49-4bfa-8a7e-21a3342254cb', 'إنه يحاول! 🤸‍♂️', 'يحاول التقدم إلى الأمام أثناء استلقائه على بطنه. تزداد عضلاته قوة يومًا بعد يوم، فضعي لعبة أمامه لتشجيعه.'),
  ('97716c97-1bb3-4784-acfc-a5f0354d1864', 'قوة الموسيقى 🎶', 'جرّبي تهدئة نوبات البكاء غير المبررة التي تبدأ في أواخر النهار بتشغيل موسيقى كلاسيكية هادئة الإيقاع.'),
  ('21fef948-0fab-41a2-932d-5efc89cc4b78', 'أساس النوم ⏱️', 'من المهم جدًا وضع نظام نوم مناسب. لا تخلّي بهذا الروتين أبدًا لتنعمِي بليالٍ هادئة.'),
  ('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352', 'بقي يوم واحد على إتمام 200 يوم! 🎂', 'غدًا يُتم طفلكِ 200 يوم! هل فكرتِ في كيفية الاحتفال بهذا الرقم الكبير والجميل؟ ابدئي التحضيرات!'),
  ('76b44761-7bef-4f9c-b984-97e78f4d78cb', 'كل شيء على ما يرام ✔️', 'قد تشعرين أحيانًا بأنكِ لا تستطيعين فعل أي شيء. لكن انظري إلى ملابسه النظيفة وبطنه الممتلئ. أنتِ تقومين بعمل رائع!'),
  ('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2', 'تأمّلي ما حققتِه 📈', 'تذكّري مخاوفكِ في الأيام الأولى. وانظري الآن كيف أصبحتِ أمًا متمرسة في تقديم الأطعمة التكميلية. افتخري بنفسكِ!'),
  ('87133947-89a5-414b-a6d4-637285ff301e', '200 يوم مذهل! 🎉', 'هل تصدقين؟ لقد مضى 200 يوم كامل وأنتما تسيران معًا في هذه الرحلة الساحرة! احتفلي بهذه اللحظة بملصق مميز في جلسة تصوير طفلكِ وشاركيها في المجتمع!'),
  ('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169', 'استمتعي بفخر إتمام 200 يوم. 🥂', 'لا تنسي هذا المساء، بعد أن ينام طفلكِ، أن تحتفلي مع شريككِ بهذا الإنجاز الكبير الذي حققتماه معًا كفريق!'),
  ('98621899-f977-46d0-ba01-3a49123c5aef', 'محاولات الحبو! 🐢', 'هل يدور طفلكِ على بطنه، أو يزحف إلى الخلف، أو يحاول الارتكاز على ركبتيه؟ أضيفي لحظات التطور المميزة هذه فورًا إلى ألبوم طفلكِ.'),
  ('f5a121b8-a795-4ca6-87d9-f17351b40bec', 'هل لديكِ تساؤلات حول تطوره؟ 🤖', 'طفلي لا يحبو بعد، فهل هذا طبيعي؟ – اطرحي هذا السؤال وغيره على الذكاء الاصطناعي من Anacan واحصلي على إجابة متخصصة.'),
  ('17a57fd8-a4e1-4a40-b13f-cad6191dae2a', 'اكتشاف نكهات جديدة! 🍎', 'أي فاكهة أو خضار ستجربينها اليوم؟ لا تنسي الاطلاع على وصفات الرضع الذين بدؤوا بتناول الأطعمة التكميلية لاستلهام الأفكار.'),
  ('b98f5eb2-8b81-4c72-8526-61cc728e9e49', 'الحكايات لا تنتهي 📖', 'ابتكري هذا المساء في الحكايات الذكية قصة طفل شجاع وذكي.'),
  ('baf623af-022a-4483-b233-e77e915f194b', 'صاحب الشهية الكبيرة 🥣', 'هل أصبح يأكل الطعام المهروس بشهية؟ إنه يكبر!'),
  ('0ced9920-5225-4ffc-81ba-de83e31f1bd2', 'الحفل الصباحي 🎶', 'ينظر إليكِ ويبتكر مقاطع صوتية مختلفة. إنه يقدم الآن أجمل حفل صباحي في الغرفة، فأنصتي إليه باهتمام!'),
  ('db243270-0483-44d0-9aef-b63565c06a9e', 'بذكاء الطبيب 🤖', 'هل تغير برازه بعد البدء بتناول الأطعمة الصلبة؟ بدلًا من القلق، اسألي الذكاء الاصطناعي من Anacan عمّا إذا كان ذلك طبيعيًا.'),
  ('f06a8dcb-51df-4b58-a9ac-01e5154e736a', 'أساس النوم ⏱️', 'حمام دافئ، وتدليك، وتعتيم الغرفة... حافظي دائمًا على روتين النوم لتنعمِي بليالٍ هادئة.'),
  ('0e6fe355-3307-4562-8e24-f479625f3ff6', 'الهواء النقي مفيد لكليكما. 🌳', 'اختاري أقرب حديقة واستمتعي بيومكِ.'),
  ('4085929a-ec71-4c5c-a693-62bb796910ba', 'ملابس لا تناسب الطقس 👗', 'هل يرتدي طفلكِ أحيانًا ملابس خفيفة تجعله يشعر بالبرد، وأحيانًا تثقلين عليه بالملابس؟ لا تحتاري. تحققي من الطقس والملابس وألبسيه بثقة.'),
  ('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba', 'هدوء ذكي 🤫', 'هل توقظه الأصوات المفاجئة عندما يغفو؟ استخدمي مقياس الصوت لمراقبة مستوى الديسيبل في الغرفة.'),
  ('3e7220fc-a665-4ed2-8b95-f202d84e92a8', 'سأمسكها بنفسي! 🧸', 'هل يمد يده نحو الألعاب المعلقة بدقة متناهية؟ إن التناسق بين عينيه ويديه يزداد قوة. شجعيه باستخدام أشياء مختلفة الألوان.'),
  ('747238a1-853b-4e40-a51e-30b2b6d818ac', 'لا تشعري بالذنب 💖', 'هل تعتقدين أنكِ لا تقضين وقتًا كافيًا مع طفلكِ؟ 10 دقائق ممتعة مليئة بالابتسامات أثمن من 1 ساعة يسودها التوتر.'),
  ('a8ca5021-abaf-413e-abe5-95d715e5127d', 'الاستعداد لنوم عميق 🛀', 'حمّام دافئ وتدليك لطيف وتعتيم الغرفة... روتين النوم قاعدة ذهبية.'),
  ('19aba970-f2bf-4842-9b69-4aed1781aeec', 'انظري إلى الأسفل! 👣', 'لقد اكتشف أصابع قدميه وبدأ يضعها في فمه! احرصي على مشاهدة هذه اللحظة الطريفة واستمتعي بتطوره.'),
  ('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d', 'لا يزال حليب الأم هو الأساس! 🍼', 'رغم البدء بالأطعمة التكميلية، شغّلي مؤقت الرضاعة للتأكد من تلبية احتياجه اليومي من الحليب.'),
  ('4335b974-a43c-4ba3-b369-2006056301ed', 'الجلوس من دون دعم 🪑', 'هل أصبح طفلكِ يجلس منتصبًا ولو لفترة قصيرة من دون الحاجة إلى الوسائد؟ وفّري له الحماية وراقبي تطور عضلاته بعناية.'),
  ('5bc047d7-1539-47af-a21f-c1df4aa3461d', 'لا تتناولي الغداء واقفة وعلى عجل. 🥑', 'حضّري لنفسكِ سلطة شهية وخصّصي 15 دقيقة لنفسكِ فقط.'),
  ('8d02cce6-aec5-439c-aadf-52670f1abd08', 'الاستعداد لنوم عميق 🛀', 'حمّام دافئ وتدليك لطيف وتعتيم الغرفة... الحفاظ على روتين النوم هو سر الليالي الهادئة بلا انقطاع.'),
  ('347526cf-7568-4464-ab1e-f2a4e4f4b799', '7 أشهر كاملة! 🎉', 'لا يُصدّق! لقد أمضيتما 7 أشهر كاملة تعملان كفريق على تنمية هذه المعجزة. خلّدي هذا اليوم الآن في جلسة تصوير طفلكِ وشاركيه في المجتمع!'),
  ('a649650d-baa3-4dab-9158-780252d27ef4', 'نهاية يوم جميل. ✨', 'أنتِ أم قوية جدًا! اكتبي في يوميات المزاج أنكِ فخورة بنفسكِ، واستمتعي بالسكينة مع الضوضاء البيضاء ثم نامي نومًا هانئًا.'),
  ('f5e18de7-aba2-4bda-84e9-b3a568ce950b', 'انظري إلى ما حققتِه 📈', 'تذكّري قلة خبرتكِ في الأيام الأولى. وانظري الآن كيف أصبحتِ أمًا خبيرة. كوني فخورة بنفسكِ!'),
  ('4650c8e1-3011-45f0-9997-0c6decd79a65', 'القائمة طوق نجاة 🛒', 'هل نسيتِ شيئًا وسط انشغالاتكِ اليومية؟ لا ترهقي ذهنكِ، واكتبي كل ما يحتاج إليه المنزل في قائمة التسوق.'),
  ('8c057f2d-32f2-4561-9ca5-5bc651edddcc', 'نتابع عملية الهضم. 🧷', 'تُغيّر الأطعمة الصلبة نمط التبرز. سجّلي كل مرة تغيّرين فيها الحفاض في Anacan لتحلّلي استجابة طفلكِ للأطعمة الجديدة.'),
  ('8ee71700-bb17-4782-940b-c0fc02328f1a', 'هل تغيّر لون البراز؟ 💩', 'من الطبيعي رؤية ألوان مختلفة مع بدء إدخال الأطعمة التكميلية. لكن إذا ساوركِ القلق، فاسألي Anacan AI عن السبب.'),
  ('9240cd01-c58e-42aa-be44-a4d2ac461bc2', 'من الطبيعي أن تشعري بالإرهاق 🔋', 'عندما ينفد صبركِ، لا تشعري بأنكِ أم سيئة. فهذا الإرهاق طبيعي.'),
  ('1175cce8-f8b8-4dcc-a8b2-c864d9349ad6', 'بقيت 3 أيام فقط على إتمام 7 أشهر! 🎂', 'هل طلبتِ الكعكة؟ هل اخترتِ الملابس؟ لم يتبقَّ سوى القليل حتى يتم طفلكِ 7 أشهر. خططي للاحتفال بهذه المناسبة الجميلة بجلسة تصوير صغيرة في المنزل!'),
  ('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf', 'الصديق في المرآة 👀', 'خذي طفلكِ أمام المرآة. إن مشاهدة دهشته وضحكه وهو ينظر إلى انعكاسه نشاط رائع ومهدئ.'),
  ('f998fac0-0a6b-42d2-b200-7a956f147c9a', 'حان دور الأب 👨‍🍼', 'هذا المساء، مهمة تحميم طفلكِ وتهيئته للنوم تقع على عاتق الأب.'),
  ('06cfdff1-da31-4945-b562-a0c104f43d15', 'أنا أسمعكِ 🗣️', 'هل يستمع إليكِ باهتمام ويحاول نطق مقاطع متشابهة (ما-ما، با-با)؟ إنه يتحدث إليكِ! بادليه بالكثير من الابتسامات.'),
  ('83caf542-3e86-4833-b9bd-0befb15b04d7', 'حان وقت الخروج 🌳', 'ضعي طفلكِ في عربته واخرجا لاستنشاق الهواء النقي لمدة 20 دقيقة. سيكون ذلك مفيدًا جدًا لكليكما.'),
  ('fca627d6-9c72-4d82-999a-3b13347100cd', 'بطل الليل 🦸‍♂️', 'هل أرهقتكِ الاستيقاظات الليلية؟ لا تترددي في إيقاظ الأب. فالعمل كفريق يعني تقاسم العبء بالتساوي.'),
  ('a2641bfd-0346-425a-86be-0a5a6822a3d8', 'نبرة صوت الأب 📖', 'لنصنع هذا المساء أجواءً مختلفة في الغرفة. ألّفا في الحكايات الذكية قصةً عن أحد سكان الغابة الشجعان، ودعي الأب يقرأها بصوته العميق المطمئن.'),
  ('ba28583a-a3f1-40f6-9657-b7b38af17c60', 'خارج الجدران الأربعة ☕', 'بدأ الروتين المنزلي يشعركِ بالاختناق. غيّري الأجواء اليوم. اختاري مقهًى قريبًا يسهل دخوله بعربة الأطفال، واستمتعي بمذاق القهوة.'),
  ('ea94213c-026e-4de0-be12-a192e4d22b19', 'طفلكِ يتطور يومًا بعد يوم🤏', 'هل يحاول التقاط أصغر بقعة أو فتات على الأرض بإبهامه وسبابته؟ مهاراته الحركية الدقيقة في أوج تطورها!'),
  ('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911', 'تسلّق الأثاث 🧗‍♂️', 'هل يمسك بالأريكة أو الكرسي ويسحب نفسه إلى الأعلى؟ تستعد عضلات ساقيه للوقوف مستقلًا. احميه، لكن لا تمنعي محاولات هذا المتسلق الصغير.'),
  ('82e71311-374a-4306-bcfc-4f69bc54da1b', 'عاصفة منتصف الليل 😭', 'هل استيقظ في منتصف الليل باكيًا من دون سبب واضح؟ استخدمي تحليل البكاء لمعرفة السبب وتهدئته.'),
  ('c7aadd23-e889-42f2-a761-3f955cb9600f', 'لا ترهقي ذهنكِ 🛒', 'هل أضعف الحرمان من النوم ذاكرتكِ، فأصبحتِ تنسين ما تحتاجين إلى شرائه من المتجر؟ اكتبي كل شيء في قائمة التسوق، ودعي شريككِ يتولى الأمر عند عودته.'),
  ('4d7eb303-e249-46ed-8460-db2f0a519240', 'الطبيعة أفضل دواء ⛅', 'هل طفلكِ منزعج جدًا ولا شيء يلهيه؟ افتحي أداة الطقس والملابس، وألبسيه بما يناسب حالة الطقس، ثم اصطحبيه فورًا في نزهة بالحديقة لمدة 20 دقيقة.'),
  ('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7', 'دموع صامتة 📝', 'هل تكالبت عليكِ الأمور اليوم وشعرتِ برغبة في البكاء؟ هذا طبيعي جدًا... دوّني كل تعبكِ في يوميات المزاج. فالتعبير عما بداخلكِ سيجعلكِ تشعرين بتحسن.'),
  ('e8e53d71-abc7-400d-80a7-8cf91f3339ab', 'تكرار المقاطع الأولى 🗣️', 'هل يكرر كثيرًا أصواتًا مثل «دا-دا» و«با-با»؟ إنه يختبر جهاز النطق لديه. كرري كل مقطع ينطقه وأنتِ مبتسمة، ليتعلم كيفية الحوار.'),
  ('27772b37-d653-4081-a4d8-e2d8e3036d19', 'تساؤلات حول صحة طفلكِ 🤖', 'هل من الطبيعي أن يضطرب نمط النوم مع اقتراب الشهر الثامن؟ بدلًا من البحث لساعات على الإنترنت، تعرّفي من Anacan AI إلى حقائق علمية محددة حول تراجع النوم في الشهر الثامن.'),
  ('e5b5ed3f-01d7-4566-8860-0dc049a710b5', 'لحن المساء 🎶', 'عندما يقاوم طفلكِ النوم، شغّلي موسيقى كلاسيكية هادئة في الغرفة. ستساعده أنغام الموسيقى على تهدئة جهازه العصبي المتوتر بلطف.'),
  ('ea452c1a-6484-41b5-9042-60a3abcf409d', 'بداية اللعب التخيلي 🧸', 'هل يحاول تقديم الماء لدبه المحشو أو دميته؟ إن خياله يتطور ومرحلة اللعب الرمزي تبدأ. استمتعي بمشاهدة هذا المخرج الصغير اللطيف من بعيد.'),
  ('3a7b24a5-41c6-4c5d-a602-8a4582791ae2', 'لا تتناولي غداءكِ على عجل وسط انشغالات اليوم. 🥑', 'أنتِ تفعلين كل ما بوسعكِ لإشباعه. ولكن ماذا عنكِ؟ أعدّي لنفسكِ طبقًا خاصًا مشبعًا وغنيًا بالحديد.'),
  ('61d3770b-ac23-4b61-a0c4-be4c333cc55a', 'مشاركة الأسرار 💬', 'هل تشعرين بالقلق وتتساءلين: «لماذا لم يبدأ طفلي بالحبو بعد؟» انضمي فورًا إلى مجتمع Anacan. اقرئي التجارب الواقعية لآلاف الأمهات أو اطرحي سؤالكِ، لتدركي أن كل طفل فريد من نوعه.'),
  ('a8ecb50a-232f-401a-97bc-3fbfc63cc92b', 'قلق الانفصال 🥺', 'هل يبكي خلفكِ عندما تغادرين الغرفة؟ إنه يظن أنكِ لن تعودي مرة أخرى. طمئنيه بصوتكِ وامنحيه شعورًا بالأمان بتكرار عبارة: «أنا هنا دائمًا».'),
  ('6666dee6-8da7-4982-b6e5-9cdc982b4a75', 'حكة اللثة مستمرة 🦷', 'هل يمضغ كل شيء بقوة ويسيل لعابه؟ ستكون عضّاضات التسنين الباردة المحفوظة في الثلاجة منقذًا حقيقيًا خلال هذه الأيام.'),
  ('74e14338-c8e1-4b5c-b426-24332f30b919', '10 دقائق للأم ☕', 'لا تسارعي إلى الأعمال المنزلية بمجرد أن ينام طفلكِ. اجلسي على الأريكة، واشربي قهوتكِ، واكتفي بالنظر إلى الحائط والتنفس لمدة 10 دقائق.'),
  ('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f', 'صباحات متقلبة المزاج ☁️', 'ألا يرضيه شيء هذا الصباح؟ قد يكون السبب ألم التسنين أو طفرة في النمو. احتضنيه أكثر فحسب، واجعليه يشعر بالأمان.'),
  ('6ac03f7c-34a8-46f5-96a4-c1aa521476a5', 'لعبة بقاء الأشياء! 🧸', 'أخفي لعبته تحت غطاء ودعيه يعثر عليها. وفي أثناء لعب هذه اللعبة الذهنية، التقطي فرحته من خلال جلسة تصوير الطفل.'),
  ('746b1115-b7ff-4fd7-b04a-46935d1a6f43', 'هل أغراض طفلكِ منتشرة في كل أنحاء المنزل؟ 🌪️', 'هل أغراض طفلكِ منتشرة في كل أنحاء المنزل؟ لا بأس. فالمنزل غير المرتب لا يعني أنكِ أم سيئة، بل يدل على أن طفلكِ هو أولويتكِ.'),
  ('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292', 'العلاج بالصوت لمواجهة القلق. 🎶', 'إذا لم يستطع طفلكِ النوم هذا المساء بسبب حماسه لمهاراته الجديدة، فشغّلي له صوت الرحم من قسم الضوضاء البيضاء.'),
  ('5b09b018-664d-4b58-86b9-31b6e1d3baf2', 'عناد «إنه لي» 🛑', 'هل يغضب عندما تأخذين من يده أي غرض خطير؟ بدلًا من منعه مباشرةً، وجّهي انتباهه إلى لعبة أخرى أكثر إصدارًا للأصوات وأكثر ألوانًا، لتتجاوزي نوبات الغضب الصغيرة هذه.'),
  ('698ffa60-da73-4003-9656-db865993d1b5', 'تحفة فنية في الطبق 🥦', 'ألا يأكل ذلك المهروس؟ أحيانًا لا تكمن المشكلة في المذاق، بل في الشكل. استخدمي الوصفات الصحية واصنعي وجوهًا مرحة بالخضراوات الملونة لفتح شهيته.'),
  ('eec20c49-b219-4211-8916-1e602a8ceafb', 'النوم الحساس 🤫', 'هل يفزع من أدنى صوت بمجرد أن يغفو؟ تحققي من مستوى الضوضاء في الغرفة باستخدام مقياس الصوت، وشغّلي الضوضاء البيضاء لحجب الأصوات القادمة من النافذة.'),
  ('9fc39323-52a1-4045-aa65-bf5c16fac78f', 'جائع أم متعب؟ 😭', 'هل يبكي بلا سبب ويبدو صوته مختلفًا؟ لا داعي للقلق. أسمعي صوته فورًا لأداة تحليل البكاء واكتشفي السبب الحقيقي للمشكلة.'),
  ('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6', 'تدابير السلامة المنزلية! 🛡', '️ كلما ازدادت حركته، زادت المخاطر أيضًا. اطّلعي على قائمة المنتجات الموصى بها لاختيار أقفال حماية الأطفال وواقيات الزوايا.'),
  ('a0d08200-8263-43d9-90a3-313dda8dadc9', 'هل حان وقت الأطعمة التي تؤكل بالأصابع؟ 🥦', 'هل أصبح يرغب في إمساك الطعام بنفسه؟ تصفّحي وصفاتنا للرضّع الذين يبدأون تناول الأطعمة التكميلية للاطّلاع على خيارات آمنة.'),
  ('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96', 'تمارين الحبو! 🐢', 'هل يزحف إلى الخلف وهو مستلقٍ على بطنه، أو يحاول الارتكاز على ركبتيه؟ اسألي Anacan AI عن التمارين المفيدة التي تساعده على الحبو.'),
  ('52134c06-b272-4f5f-93b6-cf014fc0e867', 'لا يزال حليب الأم هو الغذاء الأساسي! 🍼', 'على الرغم من بدء الأطعمة التكميلية، شغّلي مؤقت الرضاعة للتأكد من تلبية احتياجاته اليومية من الحليب.'),
  ('62cb9c93-e0de-4d15-8d33-e81c1723d1db', 'جرعة من الطاقة للأمهات! 🥗', 'من الضروري أن تتناولي طعامًا صحيًا أنتِ أيضًا! حضّري من وصفاتنا الصحية سلطة غنية بالفيتامينات أو عصير سموذي يمنحكِ مزيدًا من الطاقة.'),
  ('f25f7637-e945-4232-a1c1-f7594c81a0b3', 'صوت مهدّئ 📖', 'اقرئي لطفلكِ هذا المساء حكاية قصيرة بصوتكِ فقط. فصوت الأم هو الموسيقى المفضلة لدى طفلها.'),
  ('2a37fc3a-8b98-420a-99ba-c491a8c0f435', 'إشارات النعاس 🥱', 'لا تنتظري حتى يفرك عينيه ويتثاءب. ابدئي روتين النوم فورًا بمجرد أن تصبح نظراته شاردة.'),
  ('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d', 'اجتماع الفريق 🥂', 'لقد اجتزتما يومًا شاقًا. بعد أن ينام طفلكِ، لا تنسيا أن تصبّا كوبًا من الشاي وتُعبّرا عن تقديركما لبعضكما قائلين: نحن حقًا فريق رائع.'),
  ('579d5966-d49f-4125-a264-8acd785d0a8d', 'الصديق في المرآة 👀', 'احملي طفلكِ أمام المرآة، وراقبي كيف ينظر بدهشة إلى انعكاسه ويحاول لمسه. إنه نشاط رائع يساعده على إدراك ذاته.'),
  ('9099f274-aa9c-4fe9-8624-5cd611699d2d', 'تسوّق سريع 🛒', 'هل أوشك زيت الأطفال أو المناديل المبللة على النفاد؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني احتياجاتكِ فيها ليشتريها شريككِ في طريق عودته من العمل.'),
  ('1d706879-d02b-44cf-bac5-4f53776477d3', 'مفاجآت الطقس ⛅', 'عند الخروج في نزهة، لا تنخدعي بالطقس فتعرّضي طفلكِ للبرد. لا تتخذي قراركِ بمجرد النظر من النافذة، بل استخدمي مساعد الطقس والملابس لاختيار الأنسب بدقة وفقًا للأجواء في الخارج.'),
  ('acd7fb31-0c36-4f0b-9849-cf983e0b0e95', 'سآكل بنفسي! 🥦', 'هل أصبح طفلكِ يفضّل إمساك الخضراوات بيده وتناولها بدلًا من أكل الطعام المهروس بالملعقة؟ شجّعي استقلاليته. نعم، ستتسخ الأشياء من حوله، لكن ذلك سيسرّع تطوره.'),
  ('e1819391-1d2d-450e-ac14-9ecfa65465d4', 'عالم الحكايات الساحر 🪄', 'جرّبي هذا المساء شيئًا مختلفًا تمامًا في الحكايات الذكية. غيّري نبرة صوتكِ بما يتناسب مع إيقاع الحكاية.'),
  ('aff9ba8d-8d8a-4d80-9363-09474c73609e', 'المستكشف الصغير 👣', 'لقد اكتشف طفلكِ أصابع قدميه، ويحاول الآن وضعها في فمه!'),
  ('d79d065c-4399-4ac9-8bd9-d4970a686fba', 'مناوبة الأب الليلية 👨‍🍼', 'يكفيكِ ما تشعرين به من إرهاق خلال النهار. أوكلي إلى الأب في المساء مهمة تحضير طفلكِ للنوم وإلباسه ملابس النوم، واكتفي بالمشاهدة من بعيد.'),
  ('bedd9e86-f764-4777-9e49-e315e75433fd', 'مسؤولية الأب 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا بمفردكِ تمامًا. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم هذه المسؤولية بالتساوي.'),
  ('c36dcca2-2b51-424c-b39c-c98f7988d549', 'وجدتُكِ! 🙈', 'هل يضحك طفلكِ بصوت عالٍ عندما تغطّين وجهكِ بيديكِ ثم تكشفينه في لعبة الغمّيضة؟ إن مفهوم بقاء الأشياء لديه في طور الاكتمال. اجعلي هذه اللعبة جزءًا من روتينكما اليومي.'),
  ('3f339310-d600-43dc-81a3-1b609288885e', 'البقع العنيدة 👗', 'مرحلة التغذية التكميلية تعني أن المنزل والملابس سيتلطخان باستمرار. لا تنزعجي من ذلك. استخدمي المرايل المصنوعة من السيليكون، واستمتعي فحسب بهذه اللحظات الطريفة والملوّنة.'),
  ('60071670-7fa4-4f9f-829f-892d281a9741', 'توقّفي عن لوم نفسكِ. 🛑', 'هل طال وقت استخدام الشاشات اليوم، أو بقي المنزل فوضويًا؟ أنتِ مجرد إنسانة متعبة، وتبذلين قصارى جهدكِ.'),
  ('fe5cb47e-9f22-41f9-a236-1db4b224e518', 'لعبة رمي الأشياء على الأرض 🥄', 'هل يرمي طفلكِ لعبته من كرسي الطعام وينتظر منكِ التقاطها؟ إنه يكتشف الجاذبية والعلاقة بين السبب والنتيجة. تحلّي بالصبر وابتسمي.'),
  ('28d590c8-c8a6-4c89-b78b-e70f2f482c0d', 'الاعتياد على الظلام 🌙', 'لمساعدة طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية والشاشات في الغرفة. لا يتسارع إفراز هرمون الميلاتونين إلا في بيئة هادئة ومظلمة.'),
  ('31783568-6230-449d-98c8-e7b1b046a34e', 'صباحات متقلّبة المزاج ☁️', 'هل يبكي طفلكِ من كل شيء فور أن يفتح عينيه ولا يرضيه شيء؟ ربما يكون في خضم طفرة نمو. أكثري من احتضانه وامنحيه الشعور بالأمان.'),
  ('38c7f3dd-4cf4-4758-8006-37d59832bac8', 'لا تسارعي إلى تفريغ غسالة الصحون فور نوم طفلكِ! 🛋️', 'استلقي على الأريكة، وأغمضي عينيكِ، واستسلمي لمدة 15 دقيقة لذلك الهدوء التام والنادر في المنزل.'),
  ('ea309314-6720-4ddf-9fe1-7a4fb805b43f', 'لديكِ سؤال؟ 🤖', 'هل يقلقكِ مخطط طول طفلكِ ووزنه مع اقترابه من الشهر الثامن؟ بدلًا من قراءة مقالات مخيفة على الإنترنت، اطلبي من Anacan AI جدولًا دقيقًا يستند إلى أسس علمية.'),
  ('1c1e068a-2609-422f-991f-68ad50839ea3', 'استعيدي طاقتكِ 🍲', 'هل بلغ منكِ التعب حدًّا لا يُطاق؟ اختاري من بين الوصفات الصحية وصفة سموذي مميزة تُحضَّر خلال 10 دقائق، وتساعد على دعم إدرار حليبكِ واستعادة نشاطكِ.'),
  ('51badc42-c8bc-4aa3-b0b8-ec576b19fa07', 'تخلّصي من الضوضاء 🤫', 'تكون أول نصف ساعة بعد خلوده إلى النوم الفترة الأكثر حساسية. تحققي من المكان باستخدام مقياس مستوى الصوت، وامتنعي عن أي ضوضاء مفاجئة آتية من الغرفة المجاورة أو التلفاز.'),
  ('69f05aef-6a67-462b-8173-638d2cb174d5', 'الحبو نحو الهدف 🐢', 'أصبح طفلكِ يختار هدفه ويحبو نحوه بسرعة. أزيلي فورًا من مستوى الأرض جميع الأغراض الصغيرة والخطِرة التي يمكن ابتلاعها في الغرفة.'),
  ('7405692f-45e1-45fa-9dd9-b527045b5e7d', 'شاركي تجربتكِ 💬', 'هل أخافتكِ حركة جديدة يقوم بها طفلكِ، مثل ضرب رأسه بالحائط؟ اكتبي في مجتمع Anacan، واقرئي كيف اجتازت أمهات أخريات هذه المرحلة أيضًا.'),
  ('cad415e5-9ff2-468b-bfee-aaed538d25a0', 'خطوات جريئة 🧗‍♂️', 'هل يتشبث بالأريكة ويحاول رفع إحدى يديه عنها؟ يتطور إحساسه بالتوازن بسرعة. راقبي محاولاته الجريئة مبتسمةً، مع البقاء على مسافة قريبة لحمايته.'),
  ('e2523211-afd7-48c7-8227-2ec7b0b2f0f7', 'أطلقي العنان لمشاعركِ 📝', 'هل تشعرين بوحدة شديدة وبأن الآخرين لا يفهمونكِ؟ هذا شعور طبيعي تمامًا. دوّني مشاعركِ بصدق ومن دون أي تنقيح في يوميات الحالة المزاجية.'),
  ('16c8c619-fdcd-4a82-a21a-ff965106a15f', 'فوضى المنزل 🌪️', 'هل تمتلئ الغرفة بالألعاب؟ عشر دقائق مرحة تقضينها معه أهم من التنظيف. ستبقى الألعاب هناك غدًا أيضًا، فلا ترهقي نفسكِ.'),
  ('4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773', 'استعدّي للشهر الثامن! 🎂', 'انتبهي! لم يتبقَّ سوى ١٠ أيام حتى يُتمّ صغيركِ شهره الثامن! ألقي نظرة على رحلتكما في متتبّع النمو. وفكّري من الآن في طلب كعكة صغيرة من Anacan للاحتفال بهذه المناسبة المميزة.'),
  ('724d9097-f64c-406e-8895-2982258b710d', 'الاستعداد للنوم مع الموسيقى 🛀', 'هل أصبح الروتين المسائي صعبًا؟ شغّلي موسيقى هادئة في الخلفية أثناء استحمام طفلكِ بماء فاتر. فتناغم الماء والموسيقى يهدّئ حتى أكثر الأطفال عنادًا.'),
  ('12b2ddaa-17a1-4692-8574-725c962b0e1b', 'نوبات البكاء مجهولة السبب مُرهقة. 😭', 'نوبات البكاء التي لا تعرفين سببها مُرهقة. توقّفي عن التخمين واستخدمي تحليل البكاء لاكتشاف الرسالة الخفية وراء الصوت فورًا، مثل الألم أو التعب.'),
  ('19b095ff-5334-4011-abd1-b8df6c79520c', 'حان وقت الخروج 🌳', 'البقاء بين أربعة جدران يخنقكِ. ضعي طفلكِ في عربته واخرجا لاستنشاق الهواء النقي، ولو لمدة ٢٠ دقيقة فقط. فسكون الطبيعة سيؤثر إيجابيًا في رضيعكِ وفي حالتكِ النفسية أيضًا.'),
  ('b6194099-d4e6-4061-b3f2-d6bc5cce0529', 'الإشارة بالإصبع ☝️', 'هل يشير بإصبعه إلى شيء بعيد ثم ينظر إليكِ؟ إنه يقول لكِ: انظري إليّ، أو أريد هذا. إنها قفزة كبيرة في مهارات التواصل! أخبريه باسم الشيء.'),
  ('b78498d9-706c-458c-aa0f-d6081c7746c6', 'تهويدة الليل 🎶', 'لا يمكن لأي تطبيق أو صوت أن يحلّ محل تهويدة الأم. ضمّيه إلى صدركِ هذا المساء وغنّي له بهدوء تهويدته المفضلة التي تمنحه الشعور بالأمان.'),
  ('d08b308d-00d3-45c9-9840-df7ac1047703', 'وقت التصفيق 👏', 'هل يعبّر عن فرحته بالتصفيق؟ ما إن تري هذا الإنجاز الحركي الرائع، احتفلي برقصة انتصار صغيرة في المنزل وشاركيه فرحته!'),
  ('dd6cc7ba-db6f-403b-93e6-2447dbb967dc', 'القائمة ليست خيارًا، بل ضرورة 🛒', 'لا تنسي الزينة اللازمة لحفلة إتمام الشهر الثامن! لا ترهقي ذهنكِ، بل دوّني كل شيء فورًا في قائمة التسوق ونسّقي المهام مع شريككِ.'),
  ('7227b833-2ecd-472c-a074-7273a66732d9', 'وجوه مألوفة 🥰', 'هل رأيتِ تلك الابتسامة الكبيرة والمميزة على وجهه عندما دخلتِ الغرفة؟ إنه يميزكِ أنتِ وشريككِ عن الجميع. حبه الصادق هذا هو أكبر حافز لكِ.'),
  ('90341333-a47d-4dc8-b1bb-8fcf07c769b0', 'تعابير الأب المضحكة 🤡', 'أسرع طريقة لإضحاك طفلكِ هي أن يصدر والده أصواتًا غريبة ويقلّد تعابير مضحكة. استرخي في الخلفية هذا المساء واستمتعي بسماع قهقهاته المرحة.'),
  ('d4f1084b-2a25-422f-954c-038d4cf53bd2', 'لا تضيعي وقتكِ في المنتدى 🤖', 'هل تتساءلين بشأن الأطعمة التكميلية: هل يمكنني تقديم هذا لطفلي؟ لا تقضي ساعات في البحث، ودعي Anacan AI يجيب عن أسئلتكِ كأنه طبيب أطفال رقمي في جيبكِ.'),
  ('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc', 'مساحة للأم ☕', 'هل استنزف البقاء في المنزل طاقتكِ؟ اختاري من الأماكن الصديقة للأمهات مقهًى هادئًا يمكنكِ الجلوس فيه براحة مع عربة طفلكِ، ونظّمي لنفسكِ موعدًا صغيرًا وممتعًا.'),
  ('66c8660e-b8ca-4046-9e3f-578e25572ec7', 'استكشاف المهملات 🗑️', 'يتفحّص باهتمام شديد كل ما يجده على الأرض أو عند حافة السجادة. لا تنزعجي وتأخذي كل شيء من يده، فهو مستكشف صغير. فقط انتبهي إلى الأشياء التي يمكنه ابتلاعها.'),
  ('8d417480-194b-431c-987a-b0b5216ea151', 'اليوم في الحكايات الذكية 🪄', 'أنشئي في الحكايات الذكية قصة بطلنا الكبير الذي سيبلغ عمره 8 أشهر بعد أيام قليلة فقط. ودعي هذه الحكاية الساحرة وحدها تملأ سكون الليل.'),
  ('5d8608e7-e1cb-4a71-9c73-7f6dde65adfe', 'بقيت 5 أيام على إتمام الشهر الثامن! 🎈', 'الحماس يتزايد! بعد 5 أيام فقط سيبلغ صغيركِ 8 أشهر! إذا كنتِ تفكرين في طلب كعكة مميزة أو التخطيط لفكرة خاصة للاحتفال، فلا تؤجلي ذلك إلى اليوم الأخير.'),
  ('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05', 'الهدوء والقهوة 🤫', 'لقد نام! بدلًا من تفريغ الغسالة الآن، اجلسي في الغرفة المعتمة. فعّلي مقياس الضوضاء لمراقبة المكان، واستمتعي بقيمة 15 دقيقة من الهدوء.'),
  ('f72fbb7e-431d-4f4b-9a73-06637ff7bd68', 'لا وجود للكمال 🛑', 'ألم يَسِر أي شيء اليوم وفق الخطة؟ لا تلومي نفسكِ. أنتِ أم حقيقية، ولستِ وهمًا منمقًا بفلاتر وسائل التواصل الاجتماعي. طفلكِ لا يحتاج إلا إليكِ.'),
  ('61ffa498-18cc-4858-987c-676f525f467c', 'تخلّصي من العبء العاطفي 📝', 'هل كان يومًا صعبًا؟ أفرغي ما في داخلكِ بكتابة كل الضغوط والمشاعر السلبية التي عشتِها اليوم في يوميات المزاج. جميع الأمهات يمررن بهذه الأزمات، وأنتِ لستِ وحدكِ أبدًا.'),
  ('856b771b-5997-4eed-bc26-8b35541184c6', 'استكشاف الطقس ⛅', 'هل الطقس في الخارج غير واضح تمامًا؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا تظهر من النافذة وبالملابس المناسبة، واخرجي للتنزه بلا تردد.'),
  ('c82d9568-ae94-4492-9789-4621c2dbcabc', 'لن أعطيكِ لعبتي! 🧸', 'هل يعترض طفلكِ ويبكي بصوت عالٍ عندما تأخذين شيئًا من يده؟ إن إحساسه بالملكية والاستقلالية آخذ في التطور. هذه مرحلة نفسية طبيعية جدًا، فلا تحاولي مقاومتها.'),
  ('bc11c415-3d46-43c3-a8ed-0a204516e9ce', 'أم بصحة جيدة، ورضيع بصحة جيدة 🥑', 'لقد استُنزفت مخزونات الحديد والكالسيوم لديكِ. كافئي نفسكِ بتحضير وجبة غنية بالطاقة من الوصفات الصحية، تكون سريعة التحضير وتساعدكِ على الحفاظ على نشاطكِ.'),
  ('e386c8f2-240d-4f0f-adaf-e43ea496b8b2', 'عقل يتصفح الكتب 📖', 'هل يقلّب طفلكِ صفحات الكتب ذات الأوراق السميكة بمفرده ويتفاعل مع الصور؟ ذاكرته البصرية تعمل بصورة ممتازة. اقرئي معه واذكري أسماء الحيوانات الموجودة في الصور.'),
  ('e418c384-8ae3-455b-af14-a223e6595751', 'لقطة توقف الزمن 📸', 'بينما يلعب طفلكِ بلطف في الغرفة، افتحي فورًا جلسة تصوير الطفل، وخلّدي بموضوع مميز ملامحه المختلفة والناضجة وهو يقترب من شهره الثامن.'),
  ('4068a45c-e5fe-4a82-8c4b-a81d556f97cc', 'تحتاجين إلى الفضفضة 💬', 'هل تغمركِ المشاعر وأنتِ تفكرين: «لا أصدق أنه سيبلغ شهره الثامن قريبًا»؟ شاركي هذا الشعور الجميل والمرهف مع الأمهات في مجتمع Anacan.'),
  ('90c5ba08-9d91-4669-8b26-99e0b48d4cf2', 'المحاولة والخطأ 🧱', 'يحاول طفلكِ وضع مكعبين فوق بعضهما، لكنهما يسقطان. ثم يعيد المحاولة بتركيز. راقبي بهدوء وفخر محاولاته الهندسية وتجاربه الصغيرة هذه.'),
  ('ed75b4ae-9703-498c-a857-64016faef6cc', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل موعد النوم بساعة واحدة. يُفرَز الميلاتونين بسرعة في بيئة هادئة وخافتة الإضاءة.'),
  ('695238eb-b88d-4ffe-800b-82d23636ceb9', 'من سيقوم بالأعمال المنزلية؟ 🌪️', 'هل بقيت أعمال يجب إنجازها من أجل احتفال الغد الصغير؟ دعيها جانبًا. اطلبي من شريككِ تولّي الأعمال المنزلية اليوم، واستريحي أنتِ استعدادًا للغد.'),
  ('c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8', 'حان وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي مع شريككِ تدليك الكتفين للتخلص من ضغوط اليوم. احرصا على استعادة طاقتكما استعدادًا لإنجاز الغد الجميل!'),
  ('d3b0f81b-e9b4-4b00-883d-9e8bb86131bc', 'غدًا يُكمل ٨ أشهر! 📸', 'هل أنتِ مستعدة؟ غدًا هو اليوم المنتظر! سيُكمل طفلكِ ٨ أشهر بالتمام! أفرغي بعض المساحة في ذاكرة هاتفكِ، فستحتاجين غدًا إلى مساحة كبيرة لجلسة تصوير طفلكِ. واكوي الملابس من الآن.'),
  ('393a7a2a-b162-45e4-9577-0e4f2d088bf3', 'رقصة الانتصار 🥂', 'احتفلي هذا المساء مع شريككِ بكل ما حملته الأشهر الثمانية من تعب ودموع وفرح. أشعلا شمعة على المائدة وصفّقا لانتصار فريقكما الذي لا يُقهر!'),
  ('4419f2fd-8e6f-4837-aa0e-9d571aac3895', 'نظرة إلى الوراء 📈', 'كم قطع طفلكِ من شوط طويل! لقد تحوّل ذلك الخوف الهش في الأيام الأولى إلى ثقة هائلة. اجتزتِ هذه الأشهر الثمانية بكل فخر! أنتِ رائعة حقًا!'),
  ('b4769acb-82a0-480e-b58f-3017d46b37a4', '٨ أشهر رائعة! 🎉🎂', 'تهانينا! لقد قطعتما معًا هذا الطريق المذهل طوال ٢٤٠ يومًا! أصبح طفلكِ الآن في عمر ٨ أشهر كاملة. احتفلي بهذا اليوم المميز فورًا وشاركيه بفخر في مجتمع Anacan!'),
  ('19dff725-11f8-467a-b784-f2971b302ba0', 'استعدّي لليوم 250! 🌟', 'غدًا نصل إلى رقم كبير! 250 يومًا بالتمام! أضفي أجواء احتفالية صغيرة في المنزل واستعدّي للشعور بالفخر بهذا الإنجاز.'),
  ('c304b9f3-2045-4d2f-b423-1096223f0f83', 'لا تنظيف اليوم 🛑', 'هل أنتِ متعبة؟ أخبري شريككِ. لا طعام منزلي اليوم. فهذا يوم راحة الأم!'),
  ('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d', 'الحكاية لا تنتهي 📖', 'اخلقي هذا المساء أجواءً هادئة من خلال تأليف قصة عن طفل شجاع وذكي في «الحكايات الذكية».'),
  ('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2', 'احتفلي بفخر مرور 250 يومًا🥂', 'لا تنسي هذا المساء، بعد أن ينام طفلكِ، أن تحتفلي مع شريككِ بهذا الإنجاز الجماعي الرائع!'),
  ('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218', '250 يومًا مذهلًا! 🎉', 'هل تصدقين؟ لقد قطعتما معًا 250 يومًا بالتمام في هذه الرحلة العاصفة والساحرة! خلّدي هذه اللحظة بملصق مميز في جلسة تصوير طفلكِ!'),
  ('e0e283b4-8f62-4d84-98d9-c186d1f67042', 'انظري إلى ما حققتِه 📈', 'تذكّري مخاوفكِ في الأيام الأولى. والآن أنتِ أم لطفل يحاول الوقوف! افتخري بنفسكِ!'),
  ('01890bf6-ab5a-403c-96d2-696020ff0863', 'المخاطر على الأرض 🧸', 'أصبحت الغرف الآن مساحات للاستكشاف بالنسبة إليه. فهو يزحف ويصل إلى كل مكان. حان الوقت تمامًا لتفقّد سلامة المنزل.'),
  ('64b9a99f-59f6-4495-b5ab-9a4825037afc', 'اختبار الجاذبية 🥄', 'هل يرمي ما في يده عمدًا على الأرض ثم ينظر إليكِ؟ إنه يتعلّم ببساطة علاقة السبب بالنتيجة. تحلّي بالصبر وشاركيه اللعب.'),
  ('2e5279b4-ad3c-4da7-866e-49a5932c0601', 'هل يصرخ عندما تأخذين اللعبة من يده؟🧸', 'يتنامى لديه الشعور بالملكية. وهذا جزء مهم من تكوّن شخصيته.'),
  ('d2ac515d-c34a-47d7-a082-82f89c2863e8', 'حليب الأم لا يزال الغذاء الأساسي! 🍼', 'رغم إدخال الأطعمة التكميلية، شغّلي مؤقت الرضاعة للتأكد من تلبية احتياجات طفلكِ اليومية من الحليب.'),
  ('31a887b1-fde3-4a67-a32c-13cc6764d41e', 'اقرآ الكتب معًا! 📖', 'تجذب الكتب الصوتية والملونة انتباهه كثيرًا. اجعلي لحظات التعلّم أثناء القراءة أكثر ثراءً بالاستعانة بالنصائح الموجودة في المدونات.'),
  ('a82a604d-9504-4486-86ea-c38998236871', 'هل نسيتِ من أي ثدي أرضعتِ طفلكِ؟ 🤱', 'يتذكر مؤقت Anacan الثدي الأيمن أو الأيسر بدلًا منكِ. ابدئي الرضاعة الآن باستخدام المؤقت!'),
  ('d7cab28d-37d6-4301-8e4d-28dfd96b83ab', 'نكتسب عادة شرب الماء. 💧', 'لا تنسي تقديم الماء مع الأطعمة التكميلية. تعرّفي إلى أكواب الشرب الأنسب ضمن قسم المنتجات الموصى بها.'),
  ('6122dba2-692e-45e2-8027-9ab67ba2bf07', 'تعالَ، تعالَ 👏', 'هل يصفق بيديه أو يمد ذراعيه نحوكِ؟ هذه طريقة رائعة للتواصل. عانقيه.'),
  ('a73ae95c-98a0-4201-9af1-960893ecd116', 'تجميد اللحظة 📸', 'إنه يكبر بسرعة كبيرة... التقطي صورة لملامحه اللطيفة والهادئة أثناء نومه واحتفظي بها ذكرى.'),
  ('b8c9eaea-1257-487d-8647-7c1cb6d70a3a', 'هل لديكِ سؤال؟ 🤖', 'هل يدور في ذهنكِ آلاف الأسئلة حول نمو طفلكِ؟ اكتبي إلى Anacan AI واحصلي على إرشادات دقيقة من أطباء الأطفال.'),
  ('075bea5d-3ab7-4404-af70-89a3de20a0ff', 'قائمة سريعة 🛒', 'هل نفدت جميع مؤن المنزل بالأمس؟ افتحي قائمة التسوق، ودوّني الحليب والفواكه وغيرها من النواقص خلال ثوانٍ، ثم أرسليها إلى هاتف زوجكِ.'),
  ('3c7f679a-b11a-4f67-a3ae-5f350e93a451', 'حكاية خاصة 🪄', 'أنشئي ضمن الحكايات الذكية قصة مميزة يكون طفلكِ بطلها.'),
  ('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8', 'فوضى ما بعد الاحتفال 🌪️', 'هل يعمّ المنزلَ الفوضى بعد حفلة إتمام طفلكِ 8 أشهر بالأمس؟ لا تتعجلي التنظيف. خصّصي هذا اليوم للراحة واستكشاف الألعاب الجديدة مع طفلكِ الذي أتمّ شهره الثامن.'),
  ('2c9fa500-5618-49b8-a232-965da7b82ef7', 'التحكم في الأصوات 🤫', 'النصف ساعة الأولى بعد خلوده إلى النوم هي الفترة الأكثر حساسية. تحققي من المحيط باستخدام مقياس الصوت، وتجنبي الضوضاء المفاجئة وأصوات التلفاز أو الشارع.'),
  ('87a20850-e59a-4ee2-81e8-79c4b5808e7b', 'أنا أسمعكِ 🗣️', 'هل ينصت إليكِ باهتمام ويحاول إصدار مقاطع صوتية مشابهة؟ إنه يتحدث إليكِ! بادليه بالكثير من الابتسامات وشجعي هذا التواصل.'),
  ('9c963f32-b147-4e84-aa9a-af699e50681f', 'هل نفد صبركِ اليوم، وربما شعرتِ بالغضب؟  🛑', 'لا تشعري بالسوء. ابتعدي عن الصور المثالية الوهمية على الإنترنت. أنتِ أم حقيقية، ومن حقكِ أن تعيشي مشاعركِ.'),
  ('0cf5cff8-d958-4ec0-b6df-6f78457976fd', 'بذكاء الطبيب 🤖', 'هل لديكِ شكوك بشأن معايير النمو بعد عمر 8 أشهر؟ لا تتيهي في الإنترنت، واحصلي من Anacan AI على إجابات موثوقة ومستندة إلى أسس علمية ومعتمدة من أطباء الأطفال.'),
  ('77b45217-21e4-402a-b5dd-d0ee28c29f05', 'تناول الطعام بالأصابع 🥦', 'لم يعد يريد الطعام المهروس، بل يرغب في إمساك الخضراوات بيده! شجعي محاولاته لتناول الطعام بنفسه، وابقي بجانبه وراقبيه دائمًا، حتى لو اتسخ المكان من حوله.'),
  ('dd6d5f01-5a48-4f85-953e-c5e21662ae95', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا بمفردكِ تمامًا. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي. والليلة، مهمة تنويم طفلكِ تقع على عاتقه.'),
  ('918fe7fd-3c85-49ee-b337-c52aba217614', 'هل يستيقظ صارخًا في منتصف الليل ولا يهدأ؟  😭', 'دعي ميزة تحليل البكاء تستمع إلى صوته لتحددي ما إذا كان السبب مجرد رعب ليلي أم ألمًا جسديًا.'),
  ('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b', 'الرقص على الموسيقى 🎶', 'هل يتمايل مع الإيقاع عند تشغيل موسيقى مرحة؟ هذا دليل رائع على تطور التنسيق بين السمع والحركة! شغّلي أغنية مرحة وارقصي معه في الغرفة.'),
  ('deba3d42-726a-4e83-bbbd-900d2aee20ad', 'ما دام قد شبع، فقد حان دوركِ.', 'اختاري وجبة خفيفة تمنحكِ الطاقة من بين الوصفات الصحية، واستلقي على الأريكة لمدة 10 دقائق على الأقل لاستعادة طاقتكِ.'),
  ('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6', 'مذكّرة المشاعر 📝', 'عندما تشعرين بالوحدة والإرهاق، دوّني مشاعركِ في مذكّرة المزاج. تمرّ جميع النساء بهذه المراحل العاصفة؛ أنتِ قوية وقادرة على تجاوزها!'),
  ('90ae683e-61a6-4dd5-b894-186c95367ff3', 'هل ما زالت لثته تؤلمه؟ 🦷', 'هل يضع أصابعه في فمه باستمرار ويسيل لعابه بغزارة؟ حان الوقت لاستخدام عضّاضات التسنين المبرّدة في الثلاجة من جديد.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('b9bfa71c-cf95-4768-adc9-c82fe1e676ac'::uuid, 'الهواء النقي دواء 🌳', 'هل ظل يبكي ويشعر بالانزعاج طوال اليوم؟ الحل بسيط جدًا: تحقّقي من الطقس والملابس، وضعيه في عربة الأطفال واخرجي فورًا إلى الحديقة. فالطبيعة أسرع وسيلة للتهدئة.'),
  ('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d', 'لعبة بقاء الأشياء! 🧸', 'أخفي لعبته تحت غطاء ودعيه يعثر عليها.'),
  ('b34bf0e6-4ffb-4b59-90eb-68d99299dee1', 'واقع القهوة الباردة ☕', 'هل بردت قهوتكِ اليوم أيضًا؟ لا بأس، فأنتِ بطلة لا تتوقف عن الحركة. دوّني فوضى اليوم بروح مرحة في مفكرة المزاج.'),
  ('026d603e-c612-41a2-9525-f4d00f730669', 'رفاهية الاستحمام على انفراد 🛀', 'لقد أتعب ذراعيكِ الركض خلف طفلكِ طوال اليوم. سلّمي المهمة إلى شريككِ وامنحي نفسكِ 15 دقيقة من العلاج بالماء بلا انقطاع.'),
  ('1c49ef6a-c84a-47c7-a1bc-352a17833a3d', 'خطوات بمحاذاة الأريكة 🛋️', 'هل ينهض طفلكِ مستندًا إلى الأثاث ويخطو بمحاذاته؟ إنها خطوة كبيرة نحو الاستقلالية. احرصي على تسجيل هذه اللحظة في متتبع النمو.'),
  ('b5c1158f-415c-414a-b3ec-c9879bf6e9d9', 'يتعرّف إلى اسمه! 🗣️', 'هل يلتفت طفلكِ وينظر إليكِ عندما تنادينه باسمه من غرفة أخرى؟ إن سمعه واستيعابه يتطوران باستمرار. تحدثي معه كثيرًا واذكري اسمه أثناء الحوار.'),
  ('bb4b0ba8-0880-4332-8a97-7715f01a7ba8', 'محققو الخزائن 🕵️‍♂️', 'هل خزائن المطبخ هي هدف طفلكِ المفضل؟ ضعي الأواني الآمنة في خزانة سفلية، ودعيه يكتشف كنزه ويلعب به لساعات.'),
  ('bf07c6c2-b84c-44ed-9459-f26c37f0e099', 'محترف لعبة الغميضة 🙈', 'أصبحت لعبة تغطية وجهه بيديه ثم كشفه فجأة نشاطه المسائي المفضل.'),
  ('c24149f4-cca2-46bd-ba68-2442b259ab90', 'أنتِ امرأة أيضًا 💄', 'أنتِ أم وحامية، لكنكِ أيضًا إنسانة لها كيانها الخاص. انظري إلى نفسكِ في المرآة وابتسمي، وقدّمي لنفسكِ اليوم لفتة صغيرة.'),
  ('4283eae1-f0b6-489a-be21-28cec6201152', 'لا تتوهي في المنتديات 🤖', 'هل لديكِ شك بشأن جانب ما من روتين التغذية؟ لا تمضي ساعات في البحث، ودعي Anacan AI يجيب عن أسئلتكِ بمنطق طبيب أطفال في متناول يدكِ.'),
  ('72a32149-c4d7-4a45-b296-5cc7c5b673ad', 'فحص سريع 🤖', 'ما هي مراحل النمو المتوقعة في عمر 9 أشهر؟ دعيكِ من المقالات الطويلة. اطرحي سؤالكِ مباشرةً على Anacan AI واحصلي على إجابة بدقة طبيب الأطفال.'),
  ('df74b674-d83b-4306-a6c3-1477bd965efe', 'الاستعداد للنوم 🛀', 'الحمّام الدافئ مفيد دائمًا. لا تغيّري الروتين المسائي أبدًا، لأنه يرسل إلى دماغ طفلكِ إشارة بأن وقت النوم قد حان.'),
  ('3c29a397-ae21-4b66-9ae6-c3001d2f3e36', 'إنه ينظر إليكِ 👀', 'أينما كنتِ في الغرفة، تظل عيناه عليكِ. أنتِ مصدر أمانه. عندما ينفد صبركِ، تذكّري حبه الخالص لكِ.'),
  ('b3560b09-ab82-494c-a5e9-d6be5d4cb35a', 'فن الفوضى 🌪️', 'ينثر كل ما يلعب به في أرجاء المكان. راحتكِ أهم من الترتيب. ستبقى الألعاب مكانها غدًا، لكن طفلكِ يحتاج الآن إلى أم مفعمة بالنشاط.'),
  ('fe563692-e0de-40b2-aa34-9d6335348a54', 'هدوء الليل 🤫', 'إذا كانت أصوات السيارات أو الضوضاء الخارجية تزعجه، فاحرصي على تشغيل مصدر ثابت للضوضاء البيضاء في الخلفية.'),
  ('268d0edd-f8c9-45fd-af24-4b1bd27e458d', 'صالون تدليك الأب 💆‍♀️', 'دعي زوجكِ يتولى تنويم طفلكِ، ثم ليمنح عضلات رقبتكِ المتشنجة تدليكًا لمدة 5 دقائق!'),
  ('38581365-03a6-48aa-a7b4-923dde40764d', 'شغف السلالم 🧗‍♂️', 'إذا كانت هناك سلالم أو أماكن مرتفعة في المنزل، فسيسعى طفلكِ للوصول إليها. لقد حان الوقت فعلًا لتركيب بوابات الأمان.'),
  ('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf', 'معارك الطعام 🥣', 'هل يدفع الطعام المهروس بعيدًا؟ لا تجبريه على الأكل. حوّلي وقت الطعام إلى لعبة حتى لا تتأثر علاقته بالطعام سلبًا، واطّلعي على وصفات بديلة في المجتمع.'),
  ('288682cf-7f40-402e-a594-adaf2cbbed34', 'استكشافات حافية القدمين 👣', 'ألا يحب التجول في المنزل بالجوارب؟ إن تلامس الأعصاب الموجودة في باطن قدميه مع الأرض ممتاز لنمو الدماغ. دعيه يتحرك بحرية!'),
  ('2951ca5f-9454-4562-9820-3bfb3531edfd', 'القائمة تنقذ الموقف 🛒', 'أما زال ضباب الذاكرة يلازمكِ؟ هل نفد الصابون أو أوشكت الفاكهة على النفاد؟ اكتبي ما تحتاجينه في قائمة التسوق قبل أن تنسي، ودعي زوجكِ يتولى الأمر.'),
  ('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13', 'اجتماع الفريق 🥂', 'هذا المساء، بعد أن ينام طفلكِ، افتحي سجل الحالة المزاجية مع زوجكِ واضحكا معًا على فوضى هذا الأسبوع.'),
  ('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1', 'الأسنان تهاجم من جديد 🦷', 'قد يكون البكاء من دون سبب واضح ناتجًا عن الضغط في اللثة. حدّثي متتبع التسنين وأخرجي حلقات التسنين المبرّدة.'),
  ('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af', 'صوتيات الغرفة 🤫', 'هل يستيقظ عند أدنى صوت بعد أن يغفو؟ تحققي من الغرفة باستخدام مقياس الصوت، وساعديه على النوم بتشغيل ضوضاء بيضاء ثابتة.'),
  ('cefb8b22-0318-4268-adf8-8f7052ad66cc', 'هل يشير بإصبعه إلى شيء بعيد ويصدر أصواتًا؟ ☝️', 'إنه يقول لكِ: انظري إليّ، أو أريد هذا. إنها قفزة كبيرة في تطور التواصل!'),
  ('0c385e87-5c02-4870-85f8-9ab052891af8', 'فيتامين للأم 🥑', 'تفعلين كل ما بوسعكِ لإشباعه. وماذا عنكِ؟ اختاري من قسم الوصفات الصحية وجبة غداء خفيفة غنية بالحديد والكالسيوم.'),
  ('bda4f100-98ac-4f09-9fa3-a50d4e42eedd', 'انتبهي! لم يتبقَّ سوى 10 أيام على إتمام 9 أشهر!  🎂', 'حان الوقت من الآن للتفكير في كعكة صغيرة أو فكرة عائلية للاحتفال بهذه المناسبة المميزة.'),
  ('effeac28-8d9e-4d0e-b754-fb4004990432', 'ابتعدي عن الشاشات 📱', 'أطفئي جميع أجهزة التلفاز والشاشات في المنزل قبل ساعة من النوم ليلًا. لا يتسارع إفراز الميلاتونين إلا في بيئة هادئة ومظلمة.'),
  ('47fc8d5e-d99d-4104-9258-c8e18ad15266', 'ما موضوع هذا المساء؟🪄', 'دعي الذكاء الاصطناعي يكتب حكاية هذا المساء: السنجاب الصغير الذي يبحث عن ألعابه. ولا يكسر سكون الليل سوى صوتكِ الحنون.'),
  ('856e1374-a46f-4ac4-b093-11e46392180f', 'الببغاء المقلّد 🦜', 'هل يقلّد سعالكِ أو ضحكتكِ أو حركات يديكِ؟ أنتِ أفضل مرآة في الغرفة. علّميه أجمل تعابير الوجه!'),
  ('e263bb82-67f5-4f23-9107-f117b8634a27', 'أطلقي العنان لمشاعركِ 📝', 'هل ترغبين أحيانًا في إغلاق الباب والبكاء فحسب؟ هذا طبيعي جدًا... ستساعدكِ الكتابة على الشعور بالتحسن. دوّني مشاعركِ في يوميات المزاج.'),
  ('73d0b947-9db1-4d57-a222-c8c22a2a895b', 'شخصيته تتشكّل 🌟', 'لقد أصبح يعبّر بوضوح عمّا يحبه وما لا يريده إطلاقًا. عندما يرهقكِ عناده، تذكّري أن ذلك جزء من بناء شخصيته.'),
  ('9596d063-607c-465f-9e92-b73f9f6f0ece', 'صداقة الأمهات 💬', 'مشاركة الصعوبات تخفّف العبء. في مجتمع Anacan آلاف النساء اللواتي يشاركنكِ المشاعر نفسها. والفضفضة مجانية.'),
  ('fb27143e-60bd-4519-b45e-80c5584417a4', 'مواساة الأب 🫂', 'لا تحاولي التعامل مع نوبات البكاء الليلية بمفردكِ. أشركي شريككِ أيضًا في الأمر. فأحيانًا تساعد رائحة مختلفة وحضن مختلف على تهدئة رضيعكِ فورًا.'),
  ('4e869b86-0b42-4c4a-86f7-22a0999a3387', 'فريق التصفيق 👏', 'هل يعبّر عن فرحته بالتصفيق؟ سجّلي هذا الإنجاز الحركي الرائع في متتبّع التطور، واحتفلا في المنزل برقصة انتصار صغيرة.'),
  ('743ea03a-9755-40d4-b4aa-1eb6cf8a7495', 'وقت القراءة مع الأب 📖', 'أنشئي هذا المساء في الحكايات الذكية قصة الماعز الشجاع الذي تسلّق الجبال. دعي والده يقرأها، واستمتعي أنتِ بهذه اللحظات الهادئة.'),
  ('fc594ad6-91bd-4ee2-a759-0d1e76e468c0', 'تناول الطعام بالأصابع 🥦', 'لم يعد طفلكِ يريد الطعام المهروس، بل يرغب في إمساك الخضروات بيده! شجّعي محاولاته لتناول الطعام بنفسه، لكن احرصي على البقاء بجانبه دائمًا.'),
  ('2e4d0e7a-db8d-4408-9d88-01d37ed8b303', 'نافذة النوم تضيق 🥱', 'هل أنهكتكِ استيقاظاته الليلية؟ ربما يمر بمرحلة الانتقال من 3 قيلولات إلى قيلولتين. أعيدي النظر في الفترات الفاصلة بين قيلولاته النهارية.'),
  ('b19774b6-01ed-4a77-8052-5a03aef4ba22', 'الطعام المهروس في شعره 🤦‍♀️', 'هل يتحول وقت الطعام إلى ساحة معركة؟ إن لمس طفلكِ للطعام واستكشافه جزء من نموه الحسي. لا تقلقي بشأن البقع.'),
  ('f1d99477-a71b-4368-b9eb-c5c699e49b39', 'الطبيعة تنقذ الموقف 🌳', 'هل طفلكِ كثير التذمر ولا يهدأ في المنزل؟ استعيني بمساعد الطقس والملابس، ثم انطلقي فورًا في نزهة سريعة إلى الحديقة لمدة 20 دقيقة.'),
  ('2958c07b-39da-4ecb-ac79-c0f1640a7d1a', 'لا تقارني نفسكِ بغيركِ 🛑', 'انسي عبارة «طفل فلانة بدأ يمشي بالفعل». لكل طفل وتيرته الفريدة في النمو. شاركي همومكِ مع أمهات يفكرن مثلكِ في مجتمع Anacan.'),
  ('da431940-9d6b-4ed8-a933-fd80b83687d9', 'في انتظار كلمة ماما 🥰', 'بدأ طفلكِ ينطق مقاطع صوتية مختلفة. ولم يعد يفصله الكثير عن قول أول كلمة واعية، مثل «ماما» أو «بابا»! شجّعيه بالتفاعل مع صوته بحب.'),
  ('f40e6c18-873e-481a-ba28-76a5634b977a', 'الموسيقى غذاء الروح 🎶', 'جرّبي تهدئة نوبات الانزعاج المفاجئة في آخر النهار بتشغيل موسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة المعجزات.'),
  ('5626563e-1119-4751-a2d2-ad651cb7961b', '9 أشهر و5 أيام! 🎈', 'لم يتبقَّ سوى القليل على الاحتفال! كعكة، وزينة بسيطة، أو حتى أجمل الملابس الموجودة في المنزل... أسرعي في التحضير لجلسة تصوير طفلكِ.'),
  ('5e8f6838-89c2-40a6-940e-2ef8b752a179', 'ذكريات مشتركة 📸', 'يا لها من ابتسامة جميلة! التقطي صورة لوجهه البريء قبل النوم، فهذه اللحظات لن تتكرر.'),
  ('912ca02c-47d0-4e27-8bdb-7afe9ba868be', 'مخزون الحديد 🥩', 'قد يؤثر فقر الدم في شهية طفلكِ وطاقته. راجعي نظامه الغذائي، واسألي Anacan AI عند الحاجة عن الأطعمة الغنية بالحديد.'),
  ('0135df6f-fe6e-4faf-9136-dc65b2b29e33', 'وقت قول «باي باي» 👋', 'هل يلوّح بيده مودعًا عندما يغادر أحدهم المنزل؟ هذه علامة لطيفة جدًا على تطوره الاجتماعي! شجعيه كثيرًا.'),
  ('44260d05-153e-4b6b-b9dd-6f07fb02c462', 'البحث عن الهدوء ⛅', 'عندما يزداد التوتر، قد يكون الخروج من المنزل أفضل حل. تحققي من حالة الطقس، وضعي طفلكِ في عربته، وصفّي ذهنكِ بالمشي قليلًا.'),
  ('67247d93-ddf7-4fcc-adef-5828dde725b4', 'وهم الكمال 🛑', 'ألم يسر أي شيء اليوم وفق الخطة؟ لا تلومي نفسكِ. أنتِ أم حقيقية، ولستِ صورة مثالية مصفّاة على وسائل التواصل الاجتماعي.'),
  ('4e8edba3-fd16-4c28-a7ff-08ff9853211e', 'قد تُنسى الاحتياجات اليومية الصغيرة. 🛒', 'هل نفدت الحفاضات أم المناديل المبللة؟ أضيفيها إلى قائمة التسوق، ودعي زوجكِ يتولى الأمر عند عودته من المتجر.'),
  ('5f49ad4f-107b-4550-adae-e4aab3aa9d5b', 'الانتقال إلى قيلولتين 🥱', 'هل بدأ طفلكِ، الذي اعتاد النوم 3 مرات نهارًا، يرفض القيلولة الأخيرة؟ إنه يكبر! حان الوقت لتعديل جدول نومه ليتضمن قيلولتين.'),
  ('8750f5ee-e089-418c-9d9b-a881ca3441c3', 'عالم الحكايات الساحر 🪄', 'أنشئي في «الحكايات الذكية» قصة بطلكِ الصغير الذي سيُتمّ 9 أشهر بعد 5 أيام فقط.'),
  ('7ee44a70-ee6e-4b49-a487-76ff5581f580', 'خطوات جريئة 🧗‍♂️', 'هل يحاول طفلكِ ترك إحدى يديه أثناء التمسك بالأثاث؟ إن إحساسه بالتوازن يتطور. أمسكي بيده وامنحيه قليلًا من الثقة.'),
  ('97d44a72-2ca4-4c0f-b997-91c31aeabbef', 'حديث من القلب 🥂', 'افتحي مفكرة المزاج وناقشي مع شريككِ كيف غيّرتكما هذه الأشهر. العمل بروح الفريق هو أعظم قوة.'),
  ('ff86bc54-face-4f54-a1de-cc0ec9cccbc2', 'كل شيء على ما يرام ✔️', 'هل تغلبكِ المخاوف أحيانًا؟ انظري إلى ملابسه النظيفة وبطنه الممتلئ وعينيه المبتسمتين لكِ. أنتِ تقومين بعمل رائع!'),
  ('55476184-e000-441a-91f6-32b219ce5489', 'غدًا هو اليوم المنتظر! 🎉', '9 أشهر كاملة! هل جهّزتِ الملابس؟ أفرغي مساحة في ذاكرة هاتفكِ، فغدًا ستحتاجين إلى مساحة كبيرة لجلسة تصوير طفلكِ!'),
  ('801186a2-f617-44a4-bfbe-39fa8b84707d', 'تهويدة المساء 🎶', 'اجعلي الغرفة مظلمة تمامًا هذا المساء. لا أجهزة تقنية، بل صوتكِ الهامس فقط.'),
  ('bcabe7b8-3e78-42a9-bdf0-3f1883219079', 'هل يتألم أم يشعر بالتعب؟ 😭', 'لا تفقدي هدوءكِ عندما يبكي بلا سبب واضح. استعيني بتحليل البكاء لتحديد المشكلة وحلّها بسرعة.'),
  ('327e6e73-14c5-44c7-86f9-1b01671cc4cc', 'نظرة إلى الوراء 📈', 'كم قطع طفلكِ من شوط؟ لقد حلّت الثقة محل قلق الأيام الأولى. لقد قطعتِ هذه الرحلة بانتصار عظيم!'),
  ('00632cb5-4d20-4f2d-9bf8-82242042667b', 'ساعة الحكاية الذكية 🪄', 'لتكن حكاية هذا المساء مختلفة: السحابة السحرية التي تحب الخلود إلى النوم. اخفضي نبرة صوتكِ وهيّئي الأجواء.'),
  ('61c9e192-532e-41bc-9ebb-f2c296bb0670', 'شاركي العبء النفسي 💬', 'انضمي إلى مجتمع Anacan. أحيانًا تمنحكِ قراءة تعليق كتبته أم لا تعرفينها طاقةً أكبر من فنجان قهوة.'),
  ('92c6be75-a837-4908-b755-b4ae97896380', 'الوصول إلى مناطق الخطر ⚡', 'تجذب المقابس والأسلاك انتباه طفلكِ. حدّدي بوضوح المناطق الممنوعة في المنزل وراجعي إجراءات السلامة مرة أخرى.'),
  ('159ac401-c76f-42ec-b9e1-bb1a6d73130e', 'اكتشافات بقبضة الملقط 🤏', 'يجد طفلكِ حتى أصغر فتات على الأرض ويلتقطه بأطراف أصابعه! مهاراته الحركية الدقيقة في أوجها.'),
  ('306f7e64-ae54-408a-95b9-ac4f9c3c6684', 'سكينة الليل 🛀', 'لا تغيّري الروتين. فالحمّام المعتاد نفسه، وزيت التدليك نفسه، والغرفة المظلمة نفسها هي المفتاح الذهبي للنوم.'),
  ('f3512bb1-5e87-4250-8249-5c396829b593', 'متلازمة الجدران الأربعة ☕', 'هل تشعرين بالاختناق من البقاء في المنزل؟ ابحثي ضمن الأماكن الصديقة للأمهات عن أقرب مكان يمكنكِ فيه استنشاق بعض الهواء ويشعر فيه رضيعكِ بالراحة.'),
  ('1835b0bb-3338-4b12-9da9-167cd1643dc6', 'من سيقوم بالأعمال المنزلية؟ 🌪️', 'هل يخيفه صوت المكنسة الكهربائية فتتراكم الأعمال؟ دعيها تتراكم. اطلبي من شريككِ أن يتولى الأعمال المنزلية اليوم.'),
  ('be2205ed-6711-45b7-b2f3-ab21216eef54', 'مذكّرات المشاعر 📝', 'عندما تشعرين بالوحدة، دوّني مشاعركِ في مذكّرات الحالة المزاجية. جميع النساء يمررن بهذه التجارب، وأنتِ قوية.'),
  ('cd0245fe-8c0d-4f3e-ad23-05cff2186013', 'استكشاف القمامة 🗑️', 'يتفحّص باهتمام كبير كل ما يجده على الأرض. لا تنزعجي وأنتِ تأخذين الأشياء من يده، فهو مستكشف صغير. ما عليكِ سوى مراقبته.'),
  ('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638', 'حنان الأب المطمئن 🫂', 'عندما يستيقظ ليلًا، تناوبي مع زوجكِ على النهوض إليه. فأحيانًا لا يهدّئ طفلكِ سوى لمسات أبيه الإيقاعية.'),
  ('77c04114-1662-45d9-9778-494a99f15f4f', 'لا تنخدعي بمظهر الطقس ⛅', 'عند الخروج للتنزه، لا تتخذي قراركِ بمجرد النظر من النافذة. استخدمي أداة الطقس والملابس لتحقيق التوازن المثالي في عدد طبقات ملابس طفلكِ.'),
  ('b630415b-1d8a-4088-bd37-659e6494cb2c', 'لن أعطيكِ لعبتي! 🧸', 'هل يعترض ويبكي عندما تأخذين شيئًا من يده؟ إن إحساسه بالملكية والاستقلالية آخذ في التطور. وهذه مرحلة نفسية طبيعية جدًا.'),
  ('5c4470d4-31c9-42e6-98b2-6ebad58cdce5', 'ألا تستطيعين فهم سبب غرابة صوته؟  😭', 'دعي أداة تحليل البكاء تستمع إليه فورًا، واكتشفي ما إذا كان السبب التسنين أم الغازات لتطمئني.'),
  ('906becee-91c7-4860-a453-bec23a80f855', 'الحاجة إلى الهدوء 🤫', 'حافظي على هدوء الغرفة باستخدام مقياس الصوت. فتقطّع النوم ليلًا يفسد مزاجه ومزاجكِ في الصباح.'),
  ('93f3b238-cc16-44a9-888c-f9d77043f372', 'الرقص على أنغام الموسيقى 🎶', 'هل يتمايل مع الإيقاع عند سماع موسيقى مرحة؟ هذا يعني أن الترابط بين السمع والحركة بدأ يتكوّن! شغّلي أغنية مرحة وارقصي معه.'),
  ('334464c1-4599-4dd4-83dd-d57c384eb650', 'يقلّب صفحات الكتب 📖', 'هل يحاول تقليب صفحات الكتب ذات الأوراق السميكة؟ وفّري له الكثير من كتب الحكايات الملوّنة التي يمكن لمسها واستكشافها.'),
  ('4b865d9a-0f66-4cb0-98d0-deaa6f061766', 'قليل من الرومانسية 💖', 'احتفلي هذا المساء على ضوء الشموع مع شريككِ بتعب الأشهر التسعة وفخرها. أنتما فريق رائع!'),
  ('8be43b5a-b4b9-49ba-b74f-59b204783156', 'تسعة أشهر كاملة! 🎂', 'تهانينا! مرّت تسعة أشهر كاملة منذ الولادة. لقد نما طفلكِ تسعة أشهر في رحمكِ وتسعة أشهر بين ذراعيكِ! احتفلي بهذه اللحظة الرائعة وشاركي ذكراها مع المجتمع!'),
  ('334b387f-4019-4208-b951-95f53c679a8b', 'حاجتكِ إلى الطاقة 🍲', 'لقد تسلّل الإرهاق إلى عظامكِ. اختاري من الوصفات الصحية وجبة غداء غنية بالحديد والبروتين، تُحضَّر خلال 10 دقائق، واستعيدي طاقتكِ.'),
  ('495a74f3-0952-464a-80e0-08b1cc46205c', 'تحكّمي في الأصوات 🤫', 'تُزعج ضوضاء المنزل نومه العميق. حافظي على ثبات مستوى الأصوات الخلفية باستخدام مقياس الصوت، لكي تنعمي أنتِ أيضًا براحة هادئة.'),
  ('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1', 'قوة كلمة «لا» 🛑', 'هل بدأ يُبعد الطعام الذي لا يحبه ويهز رأسه قائلًا «لا»؟ شخصيته تتكوّن! احترمي إرادته.'),
  ('5238f2b7-2892-49ff-9220-f07d0cf3221d', 'يكفيكِ تعب النهار. 👨‍🍼', 'في المساء، تصبح مسؤولية الأب وحده أن يتدحرج مع طفلكِ على أرض الغرفة ويلعب معه.'),
  ('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede', 'البحث عن الكنز 🧺', 'تفريغ سلة الملابس أو العبث بمحتويات الخزائن هو أكبر متعة له. دعيه يلعب بحرية، فهذا يعزز مهاراته الحركية.'),
  ('f0057ec1-cc62-4ea5-9364-5327660ddc30', 'لا تترددي في السؤال 🤖', 'ما التوابل المسموح بإضافتها إلى طعام الأطفال؟ اسألي Anacan AI فورًا عن كل ما يثير ترددكِ واطمئني.'),
  ('d7009029-eb30-44cd-bedc-77f2ddcbdbe4', 'من الأطعمة المهروسة إلى الأطعمة ذات القوام المتكتل! 🍲', 'هل أصبح طفلكِ قادرًا على تناول أطعمة تحتاج إلى المضغ؟ جرّبي في تطبيقنا وصفات المهروسات والشوربات بقوامات مختلفة من قسم الأطفال الذين بدأوا تناول الأطعمة التكميلية.'),
  ('f5716668-d412-4d80-9c29-0a69a23f4f4e', 'قائمة التسوق 🛒', 'هل نفد البروكلي أو الشوفان المخصص للوجبات؟ أضيفيهما فورًا إلى قائمة التسوق وأرسلي الطلبات إلى هاتف شريككِ.'),
  ('16369cf1-7620-428e-8c38-c6f5104fb5ab', 'يُخرج ألعابه من الصندوق! 🧸', 'يحب طفلكِ إخراج الأشياء من الصندوق واحدًا تلو الآخر ورميها. وثّقي لحظة الاستكشاف الممتعة والفوضوية هذه من خلال جلسة تصوير الطفل، لتتذكريها لاحقًا بابتسامة.'),
  ('912a7ba7-5cb9-41f1-9daa-dc1c800036eb', 'هل اقتربت خطواته الأولى؟ 🧗‍♂️', 'هل لم يعد طفلكِ يكتفي بالاستناد إلى الأريكة للوقوف، بل بدأ يتحرك بمحاذاة الجدار أيضًا؟ ضاعفي تدابير السلامة.'),
  ('ec70551b-eda4-4e87-86a9-151235d2eb3e', 'ينام على وقع الحكايات 🪄', 'أنشئي في الحكايات الذكية قصصًا عن حيوانات شجاعة ولطيفة، وحوّلي الغرفة إلى مكان ساحر.'),
  ('39498b75-8a2a-463e-a232-aa6ed7188810', 'يفهم نبرة صوتكِ 🗣️', 'هل يتوقف وينظر إليكِ عندما تقولين «لا» بنبرة جادة؟ لقد بدأ بالفعل في فهم المشاعر والمحظورات!'),
  ('6d030e22-f99a-4fa8-829a-d62a50ce76e0', 'فحص النمو 🤖', 'هل تعتقدين أن لدى طفلكِ تأخرًا في حركاته الجسدية؟ احصلي من Anacan AI على معلومات واضحة حول المهارات الحركية في عمر ٩ أشهر.'),
  ('e607d1aa-9be0-4388-9790-764a5c1e94da', 'نتابع عملية الهضم. 🧷', 'تغيّر الأطعمة الصلبة نمط التبرز. سجّلي كل مرة تغيّرين فيها الحفاض في Anacan لتحليل صحة طفلكِ.'),
  ('fa0817a9-00d2-41fc-bdcb-8fdae95932ff', 'يتعلّم أسماء الأشياء 🧸', 'عندما تسألينه: أين الكرة؟ هل يبحث عنها بعينيه ويجدها؟ إن قدرته على الفهم تتطور! العبي معه ألعابًا تذكرين فيها أسماء الأشياء.'),
  ('93f4fd0f-1f45-436c-b46b-7acc69d1b899', 'التوازن على القدمين 🤸‍♂️', 'عندما تمسكين به من تحت إبطيه، هل يقف على قدميه باستقامة وقوة أكبر؟ احرصي على تسجيل منعكس الخطو الأساسي هذا في متتبّع النمو!'),
  ('b0bdf4f4-2902-43a5-876f-e99b39aef4f9', 'ساعة الحكايات الساحرة 🪄', 'أضيفي لمسة مميزة إلى روتين المساء مع قصة «أسرار نوم البطل الصغير» في قسم الحكايات الذكية.'),
  ('c6da7887-a402-4a11-8fbf-8de4d7696325', 'القائمة تنقذ الموقف 🛒', 'احتياجات المنزل اليومية لا تنتهي. لا ترهقي ذهنكِ، املئي قائمة التسوق وانتظري الأب العائد من العمل لينقذ الموقف.'),
  ('1b15944e-9198-4fc4-b86d-0b17af6cdd00', 'ماذا أسأل الطبيب؟ 🤖', 'ألا تعرفين ما الذي ينبغي أن تسألي عنه قبل الذهاب إلى الفحص الشهري؟ اطلبي من Anacan AI قائمة الفحص الخاصة بعمر 9 أشهر.'),
  ('1eda7621-0a6a-4ff0-8efe-ec931b28a106', 'مساعد المنزل الصغير 🧺', 'هل يأتي ليساعدكِ على طريقته، فيبعثر الملابس بينما تطوينها؟ لا تبعديه عن هذه المهمة، بل أعطيه منشفة.'),
  ('59e058ca-af20-4537-9c74-8aa7eb175af6', 'أطلقي العنان لمشاعركِ 📝', 'حضّري قهوتكِ في المساء، ثم اكتبي ملاحظة قصيرة في مفكرة المزاج تقارنين فيها بين مشاعركِ خلال الأشهر الماضية ومشاعركِ الآن.'),
  ('30a7e68c-862a-436f-a801-8270fce13b90', 'اعتني بنفسكِ 🍲', 'حين تكونين بصحة جيدة، يكون طفلكِ كذلك. اختاري من الوصفات الصحية سلطة خفيفة للأمهات تُحضّر في 10 دقائق وتناوليها.'),
  ('32607011-b168-4558-b64b-8c8947e8d9a9', 'حمّام دافئ، وتدليك، وتعتيم الغرفة. 🛀', 'الحفاظ على روتين النوم هو السر الأساسي لليالٍ هادئة بلا انقطاع.'),
  ('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08', 'مقاطع صوتية متنوعة ومحاولات لتكوين جمل كاملة 🗣️', 'يتحدث طفلكِ طويلًا بلغته الخاصة، وكأنه يكوّن جملة كاملة. أنصتي باهتمام إلى ألطف مذيع في الغرفة!'),
  ('3908e4ee-6364-4b5e-bf19-9883638e23db', 'صوت الغرفة 🤫', 'هل أصبح الخلود إلى النوم صعبًا؟ تحققي من مستوى الديسيبل في الغرفة باستخدام مقياس الصوت، واخفضي صوت التلفاز ليبقى في الخلفية.'),
  ('ce7b77f8-95b5-4071-bf35-61b06d785d85', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتحدثا عما يثقل قلبيكما. فدعم أحدكما للآخر يخفف العبء إلى النصف.'),
  ('fab0e5e3-a0d0-40d0-843b-ff548b4b816f', 'فريق «تعالَ إليّ» 👏', 'هل تعلّم طفلكِ الإشارة بيديه بمعنى «تعالَ إليّ»؟ احرصي على تصوير هذه المحاكاة اللطيفة بالفيديو وإضافتها إلى ألبوم ذكرياتكِ.'),
  ('0b91a5b0-1518-4473-b0bb-59cec89d7f6f', 'الأحاديث تزداد تنوعًا! 🗣', '️ اقرئي نصائح تطور النطق في قسم المدونات، لتحوّلي حوارات طفلكِ اللطيفة بمقاطع «ما-ما» و«با-با» إلى تجربة تعليمية.'),
  ('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5', 'أطعمة تدعم إدرار حليبكِ. 🍲', 'جرّبي اليوم أنواع الحساء المعززة لإدرار الحليب في قسم الوصفات الصحية للنساء، وامنحي جسمكِ مزيدًا من القوة.'),
  ('db929314-83ca-4372-8890-03ef676e68e5', 'نوبات البكاء التي لا تعرفين سببها مرهقة للغاية. 😭', 'لا ترهقي نفسكِ، استخدمي ميزة تحليل البكاء واكتشفي السبب الجذري للمشكلة.'),
  ('57fa0aeb-432f-4b34-915b-98422c100236', 'آلام التسنين 🦷', 'هل احمرّت لثته مجددًا ولا يتوقف سيلان لعابه؟ جهّزي عضّاضات الأسنان الباردة.'),
  ('bda23a3e-0646-4246-a5dc-febd245b2bb1', 'هل نسيتِ من أي ثدي أرضعتِ طفلكِ؟ 🤱', 'يتذكّر مؤقت Anacan نيابةً عنكِ ما إذا كنتِ قد أرضعتِ طفلكِ من الثدي الأيمن أم الأيسر. ابدئي جلسة الرضاعة الآن باستخدام المؤقت!'),
  ('e2296439-aad7-4bdf-a627-05d1e066a3d8', 'تابعي معدلات النوم. ⏱️', 'شغّلي مؤقت النوم عندما ينام رضيعكِ، وتحققي من الرسم البياني مما إذا كان يحصل على معدل النوم اليومي المناسب لطفل بعمر 9 أشهر.'),
  ('13322f59-d734-452d-8178-1ffb4e5e9f78', 'التسلق على الكرسي 🧗‍♂️', 'ألم يعد المشي على الأرض كافيًا له، فأصبح يحاول تسلق الأثاث؟ يا له من إصرار على تطوير مهاراته الحركية! احرصي على مراقبته دائمًا.'),
  ('b349c13b-d822-42ec-876c-d41ccb790846', 'الهواء النقي دواء 🌳', 'هل بكى طوال اليوم وكان منزعجًا؟ الحل بسيط جدًا: تحققي من الطقس والملابس المناسبة، ثم ضعيه في عربة الأطفال واخرجي فورًا إلى الحديقة.'),
  ('e46eb59c-0196-4f8a-b3f3-e86458e1f828', 'هدوء الغرفة 🤫', 'حتى الصوت الخافت قد يوقظه أثناء نومه. حلّلي مستوى الضوضاء في المكان باستخدام مقياس الصوت، ووفّري له هدوءًا متواصلًا.'),
  ('3ab1636f-ed5f-47f5-93d7-4ac521edd386', 'هل تشعرين بأنكِ لستِ أمًا جيدة بما يكفي؟ 💬', 'انضمي فورًا إلى مجتمع Anacan، واقرئي تعليقات الأمهات الداعمة لتشعري بالراحة.'),
  ('62964d86-1e07-4c7f-a135-52c48581ffc5', 'هل سارت الأمور اليوم على غير ما يرام؟', 'لا بأس، ما دام طفلكِ شبعان ونظيفًا، فأنتِ أفضل أم في العالم.'),
  ('c0c6e209-b8c8-4325-bc8e-9d4231949abd', 'آلام التسنين 🦷', 'هل احمرّت لثته مجددًا ولا يتوقف سيلان لعابه؟ جهّزي ألعاب التسنين الباردة.'),
  ('65f53c0c-e8ea-4257-8798-e79b9ed847be', 'يريد ما تأكلينه أيضًا 🥣', 'هل يمدّ يده نحو كل ما في طبقكِ؟ بلغ اهتمامه بالطعام ذروته. قدّمي له قطعًا صغيرة من الطعام يستطيع تناولها بأصابعه.'),
  ('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4', 'يوميات المشاعر 📝', 'عندما تشعرين بالوحدة، دوّني مشاعركِ في يوميات المزاج. ستساعدكِ الكتابة على الشعور بالتحسن.'),
  ('d2c3bcc6-5492-42b4-857f-d6ad8a442199', 'متابعة التطور 🤖', 'هل لديكِ أسئلة حول الأغذية التكميلية؟ اطلبي من Anacan AI معلومات عن قائمة طعام لطفل بعمر 9 أشهر.'),
  ('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6', 'وقت الحكاية الساحرة 🪄', 'اجعلي حكاية هذا المساء مختلفة: السحابة السحرية التي تحب النوم. اخفضي نبرة صوتكِ وهيّئي الأجواء.'),
  ('ae31e811-95f5-438c-9d8f-7b39b14eed84', 'محاولة إعادة الأشياء إلى مكانها 🧸', 'هل يضع اللعبة في الصندوق ثم يخرجها مجددًا؟ إنه يكتشف مفهومَي الداخل والخارج.'),
  ('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981', 'لنكتسب عادة شرب الماء. 💧', 'لا تنسي تقديم الماء مع الأغذية التكميلية. يمكنكِ بسهولة العثور على أكواب الشرب الأنسب ضمن المنتجات الموصى بها.'),
  ('0b7b3ea8-6539-4606-ac0b-b0428466ace0', 'ببغاء صغير يقلّدكِ 🦜', 'هل يقلّد سعالكِ وضحكتكِ؟ أنتِ أفضل مرآة في الغرفة. علّميه أجمل تعابير الوجه!'),
  ('72b7b721-7f37-4054-90fd-05ac29f9ff3c', 'العلاج الصوتي للقلق 🎶', 'إذا كان رضيعكِ متوترًا هذا المساء، فهدّئيه فورًا بتشغيل صوت الرحم من الأصوات البيضاء.'),
  ('761f9ba9-87d1-4b16-a40a-f1ec2385a5fd', 'استعدّي لإتمام 10 أشهر! 🎂', 'انتبهي! لم يتبقَّ سوى 10 أيام ليُكمل صغيركِ شهره العاشر! لا تنسي طلب كعكة مميزة احتفالًا بالانتقال إلى عمر من رقمين بالأشهر!'),
  ('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9', 'نوم هانئ مع حكاية 🪄', 'ابتكري في الحكايات الذكية قصصًا عن حيوانات شجاعة ولطيفة، وحوّلي الغرفة إلى مكان ساحر.'),
  ('19eac11a-ecf7-498d-85e1-95d4f484d466', 'بقي 10 أيام على إتمام 10 أشهر! 🎈', 'بقي 10 أيام على هذه المناسبة المميزة! اختاري من الآن الإطارات الخاصة في أداة جلسة تصوير طفلكِ وخطّطي لها.'),
  ('36d1de0a-5eb5-4e0f-98ce-a583a10b254e', 'لا تنخدعي بالطقس ⛅', 'لا تعتمدي على النظر من النافذة عند اتخاذ قرار الخروج في نزهة. استخدمي أداة الطقس والملابس لإيجاد التوازن المثالي في إلباس طفلكِ طبقات متعددة.'),
  ('ea9b5851-8f4a-4a19-990c-97e725808bb5', 'تهويدة من الأب 👨‍🍼', 'الليلة، دعي الأب يتولى غناء جميع التهويدات وقراءة الحكايات استعدادًا للنوم.'),
  ('14c6187e-df8b-47e8-b44f-9bc87c4b9143', 'سكون الليل 🤫', 'إذا كانت أصوات السيارات أو الضوضاء الخارجية تزعجه، فاحرصي على تشغيل مصدر مستمر للضوضاء البيضاء في الخلفية.'),
  ('36c8e54c-04ef-4b47-9a2f-c0754b0990c9', 'التعلّم بالمحاولة والسقوط 🧗‍♂️', 'هل يمشي مستندًا إلى الأريكة، ثم يسقط على مؤخرته وينهض مجددًا؟ إنه يتعلم المثابرة. شجّعيه من دون هلع.'),
  ('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6', 'خصّصي وقتًا لنفسكِ. 🛁', 'أثناء نوم طفلكِ، اعتني بشعركِ وبشرتكِ وخذي قسطًا من الراحة.'),
  ('87dbc3cb-466d-4628-b1df-07cce718a3ab', 'يستمتع بتناول الطعام بنفسه! 🥦', 'حضّري للرضّع الذين بدأوا بتناول الأطعمة التكميلية أطعمة أصابع صحية وسهلة الإمساك، بالاستعانة بقسم الوصفات.'),
  ('9b804616-ae80-4d37-b6a9-76004e3e5506', 'يفهم التعليمات البسيطة! 🧠', 'هل يناولكِ اللعبة عندما تقولين له: أعطني إياها؟ اقرئي المقالات التطويرية في قسم المدوّنات لدعم هذه القفزة الذهنية.'),
  ('dffa4555-16c2-4705-a09e-e04f9ae6d25d', 'هل ما زالت هناك أعمال؟ دعيها لوقت لاحق.  🌪️', 'اطلبي من زوجكِ أن يتولى الأعمال المنزلية اليوم. واستريحي أنتِ.'),
  ('f2c9cd05-6f08-42dc-b88f-310abadaba89', 'سكينة الليل 🛀', 'حمّام دافئ وتدليك وتعتيم الغرفة. الحفاظ على روتين النوم هو السر الأساسي لليالٍ متواصلة دون انقطاع.'),
  ('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85', 'يتفحّص باهتمام كبير كل ما يجده على الأرض.  🗑️', 'لا تغضبي وتأخذي كل شيء من يده، فهو مستكشف صغير. ما عليكِ سوى مراقبته.'),
  ('7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'هل هو جائع أم متعب؟ 😭', 'لا تفقدي هدوءكِ عندما يبكي دون سبب واضح. استعيني بتحليل البكاء لتحديد المشكلة وحلّها بسرعة.'),
  ('cc7b8905-a439-46c1-8d92-ea81667052be', 'راحة يمنحها الأب 🫂', 'عند الاستيقاظ ليلًا، انهضي أنتِ مرة وزوجكِ مرة أخرى. واقتسما العبء بالتساوي تمامًا كفريق واحد.'),
  ('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2', 'قنبلة طاقة للأمهات! 🥗', 'الركض خلف طفلكِ كثير الحركة يتطلب طاقة! حضّري سلطة غنية بالفيتامينات أو سموذي من وصفاتنا الصحية للنساء.'),
  ('a261deac-e213-48df-a6bd-e43793de79c9', 'صالون تدليك الأب 💆‍♀️', 'دعي زوجكِ يتولى تنويم الطفل، ثم يقدّم لكِ تدليكًا للكتفين لمدة 5 دقائق لإرخاء عضلات رقبتكِ المتشنجة!'),
  ('3995ea79-4422-4b71-b376-6426966b7d85', 'الهواء النقي دواء 🌳', 'هل بكى طوال اليوم وكان مضطربًا؟ الحل بسيط جدًا: تحققي من الطقس وملابسه، وضعيه في عربة الأطفال، وتوجهي فورًا إلى الحديقة.'),
  ('b67edfc6-e141-41a3-866c-78583fe5c77b', '5 أيام فقط ليُكمل 10 أشهر! 🎂', 'لم يتبقَّ سوى القليل لبلوغ هذا الرقم الكبير! حان الوقت تمامًا لتحضير كعكة إتمامه 10 أشهر وملابسه. تقتربان خطوة بخطوة من عيد ميلاده الأول!'),
  ('da354848-a7ac-41ba-9616-ccf0b8799a86', 'علامات النعاس 🥱', 'إذا كان يفرك عينيه ويحدّق في الفراغ، فلا تنتظري حتى يدخل في نوبة بكاء. أظلمي الغرفة فورًا وابدئي روتين النوم.'),
  ('049b837c-5a26-4c32-95e4-e745b4a3443b', 'هل يعترض ويبكي عندما تأخذين شيئًا من يده؟ 🧸', 'يتطور لديه الشعور بالملكية والاستقلالية. وهذه مرحلة نفسية طبيعية جدًا.'),
  ('06a37325-84f4-4012-b4a0-ff317ba78e4c', 'نلوّح مودّعين! 👋', 'هل تعلّم التلويح بيده لمن يغادرون؟ احتفظي فورًا بذكرى هذه الحركة الواعية واللطيفة من خلال جلسة تصوير لطفلكِ.'),
  ('69b02f6b-1a0a-4f09-860a-f56dfb370b0a', 'تدابير السلامة في المنزل! 🛡', '️ تزداد المخاطر كلما حاول الوقوف. احرصي على الاطلاع على قائمة المنتجات الموصى بها لدينا لاختيار أقفال حماية الأطفال وواقيات الزوايا.'),
  ('df82eb33-3f1e-407f-b436-e4b5c122a87e', 'حماس 300 يوم! 🌟', 'غدًا ذكرى مزدوجة ومميزة! 10 أشهر و300 يوم! اصنعي أجواء احتفالية صغيرة في المنزل، وأفرغي مساحة في ذاكرة هاتفكِ.'),
  ('19b97cb2-c4a1-4649-a316-a7b34bb3eed4', 'كم قطع طفلكِ من مشوار!  📈', 'حلّت الثقة محل قلق الأيام الأولى. لقد قطعتِ هذا الطريق بانتصار عظيم، أنتِ رائعة!'),
  ('1d119442-bc5b-4f46-a607-68533220e425', 'هل لديكِ سؤال؟ 🤖', 'يمكنكِ سؤال مساعد Anacan AI عن أي جانب من جوانب النمو يثير قلقكِ، حتى في ساعات الليل، والحصول على دعم متخصص.'),
  ('dd2f968e-d28b-4ab1-9758-59cda94c35f6', '10 أشهر و300 يوم رائعة! 🎉', 'تهانينا! لقد أمضيتِ 300 يوم كامل، أي 10 أشهر بالتمام، وأنتِ ترعين هذه المعجزة وتنمّينها.'),
  ('249e422f-5203-4598-a063-3032744aab4c', 'الإصرار على شرب الماء 💧', 'هل يريد طفلكِ إمساك كوبه والشرب بمفرده، لكن معظم الماء ينسكب عليه؟ شجّعي محاولاته للاستقلالية، فالمناديل المبللة وُجدت لمثل هذه المواقف.'),
  ('88ed955b-e80f-4226-9234-7112a99a4951', 'وقت شحن طاقة شريككِ 🔋', 'لقد منحتِ طفلكِ كل طاقتكِ خلال النهار. دعي شريككِ يقضي هذا المساء مع الطفل، وخذي أنتِ استراحة بعيدًا عن الإنترنت.'),
  ('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb', 'الثواني الأولى دون مساعدة 🧗‍♂️', 'هل يترك طفلكِ يديه فجأة أثناء وقوفه مستندًا إلى الأريكة؟ إنه يتعلم الحفاظ على توازنه! ابقي قريبة منه لحمايته خلال هذه الثواني القصيرة والمثيرة.'),
  ('80ecdccb-340a-49ab-94a9-ff073855c0a0', 'حيرة ماذا أطبخ 🍲', 'هل نفدت أفكاركِ لقائمة الأطعمة التكميلية؟ لا تتوهي في الإنترنت. اطلبي من Anacan AI قائمة بأطعمة سهلة يمكن لطفل في عمر 10 أشهر تناولها بأصابعه.'),
  ('b8e6e605-baf6-44b6-9e44-842e0b7a0af0', 'يشارك في الحديث 🗣️', 'هل يبدأ طفلكِ بالمناغاة بلغته الخاصة ويرفع صوته حين تتحدثين عبر الهاتف؟ مهاراته في التواصل تتطور بسرعة، وأصبح في الغرفة متحدث آخر!'),
  ('c9db13f9-8aff-4b71-a7fa-bdce47336917', 'هل استيقظ فجأة وهو يصرخ؟ 😭', 'قد يكون ذلك بداية نوبات الذعر الليلي. دعي ميزة تحليل البكاء تستمع إلى صوته لتحديد ما إذا كان السبب جسديًا أم نفسيًا.'),
  ('63090d6e-b5fb-4db8-bce4-2e5749468a34', 'الاهتمام بالكتب 📖', 'أدخلي الكتب الورقية ضمن روتين المساء. فقد أصبح طفلكِ يحاول تقليب الصفحات بنفسه. وغيّري نبرة صوتكِ بما يتناسب مع إيقاع القصة.'),
  ('64ab60a5-a744-4f7e-a8a1-28b04eede9d6', 'انهار برج الطعام 🥣', 'هل يتعمّد إسقاط الملعقة أو الطعام من كرسيه على الأرض، ثم ينظر إليكِ؟ إنه يختبر الحدود وقوة الجاذبية. تحلّي بالصبر.'),
  ('cd288f90-d6da-4851-9b9a-2a8e15ba81fb', 'جسدكِ المتغيّر 👗', 'هل تشعرين بالحزن حين تنظرين إلى ملامح جسدكِ في المرآة؟ لقد صنعتِ بهذا الجسد إنسانًا. اكتبي في مفكرة المزاج رسالة شكر لنفسكِ.'),
  ('0e1a794c-f019-4037-b108-0a10db7b5f9f', 'البطلة الصامتة 🤫', 'ما إن يغطّ طفلكِ في النوم، حتى يبدو كل صوت في المنزل كأنه انفجار قنبلة. وبينما تضبطين الحد المناسب لمستوى الضوضاء في الغرفة باستخدام مقياس الصوت، حاولي أيضًا أن تخففي وقع خطواتكِ.'),
  ('cb2d76e0-4e92-41f1-9153-3b4a29404a17', 'محققة الخزائن 🕵️‍♀️', 'هل أصبحت جميع أواني المطبخ على الأرض؟ دعي طفلكِ يلعب بالأغراض الآمنة، فهذا ينمّي لديه التفكير المنطقي. فقط أبعدي الأدوات الحادة عن متناوله.'),
  ('d194240e-ae66-4f32-83ef-39ade449ccb6', 'فضفضة الأمهات 💬', 'هل تشغلكِ أسئلة مثل: «لماذا لم يبدأ طفلي بالحبو بعد؟» اكتبي في مجتمع Anacan، وستدركين أن لكل طفل وتيرته المثالية الخاصة.'),
  ('29cc3dd1-d28b-45c9-93d7-58bfda48629c', 'السبابة نشطة ☝️', 'يشير بإصبعه إلى القطة أو اللعبة البعيدة ويتفاعل معها. وهذه مرحلة متقدمة جدًا من توجيه الانتباه.'),
  ('6eab5294-c731-4890-971d-ad01e35f7d7c', 'الحديقة أم المنزل؟ ⛅', 'ترغبين في الخروج، لكن الجو عاصف. دعي مساعد الطقس والملابس يخبركِ ليس فقط بدرجة الحرارة، بل أيضًا بما ينبغي أن تُلبسيه لطفلكِ لحمايته من الرياح.'),
  ('edfb2fd4-70c3-4b15-b2d1-0fc891b31501', 'وجوه الأب المضحكة 🤡', 'أفضل طريقة لإضحاك رضيعكِ هي أن يصدر الأب أصواتًا غريبة. خلّدي لحظات المرح هذا المساء باستخدام جلسة تصوير الطفل.'),
  ('9b064bbe-67b8-4d62-b3a0-30f79dc81515', 'إصراره على البقاء بقرب أمه 🥰', 'حتى عندما تذهبين إلى الحمّام، ينتظركِ خلف الباب ويبكي. بلغ قلق الانفصال ذروته. طمئنيه في كل مرة بقولكِ: أنا هنا.'),
  ('e77deeee-d612-4dac-bea4-ec9f16608958', 'اليوم في الحكاية الذكية 🪄', 'أنشئي ضمن الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: صغير يتعب نهارًا ويحلّق نحو النجوم ليلًا.'),
  ('f0ba97cb-8dd2-4486-865e-1d22a5e551a6', 'القائمة في جيبكِ 🛒', 'هل نفد التفاح اللازم لتحضير هريس الفاكهة؟ أوكلي مهمة إعداد القائمة إلى شريككِ. اكتبي ما تحتاجين إليه في قائمة التسوق، ودعي شراءه من المتجر عليه.'),
  ('26bb2530-b202-43eb-9226-30863365843e', 'نتابع عملية الهضم. 🧷', 'تؤثر الأطعمة الصلبة المختلفة في عملية التبرز. سجّلي كل تغيير للحفاض في Anacan لتحليل صحة رضيعكِ.'),
  ('32966fee-53d4-4975-ad1e-195457a2fa5c', 'ليالٍ عنيدة 🥱', 'هل يقاوم النوم بكل قوته؟ ربما حان الوقت لإلغاء إحدى قيلولات النهار. راجعي روتينه اليومي.'),
  ('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777', 'الاستغراق في النوم مع الحكايات 🪄', 'أنشئي في الحكايات الذكية خلفية خاصة تتكوّن فقط من الموسيقى وأصوات الطبيعة. لا كلمات، بل هدوء وسكينة فحسب.'),
  ('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac', 'صداقة الحديقة 🌳', 'هل يشعر طفلكِ بالملل من التنزّه في عربة الأطفال؟ تحقّقي من الطقس وملابسه، ثم دعيه يستكشف بحرية ويلمس العشب والأوراق على أرض الحديقة.'),
  ('d3bac322-3971-4b22-8636-d789ac7ce8db', 'يمشي مستندًا إلى الجدار 🧗‍♀️', 'أصبح السير بخطوات جانبية مستندًا إلى حواف الأثاث تمرينه المفضّل. حان الوقت تمامًا لإعادة التحقّق من وسائل الحماية والحواف الحادة.'),
  ('6498b35b-aa8e-416f-9da1-2596c74b14d0', 'نلوّح مودّعين 👋', 'عندما يغادر أحدهم من الباب، يلوّح طفلكِ بيده مودّعًا من تلقاء نفسه! إنها استجابة اجتماعية رائعة.'),
  ('b49f5612-c3e4-4568-8a0e-3494499a88d1', 'هل استيقظ في منتصف الليل وهو يبكي بلا سبب وبلا انقطاع؟ 😭', 'احتضنيه بهدوء ولا تحاولي إيقاظه. شغّلي صوته في ميزة تحليل البكاء للاطمئنان.'),
  ('fd05df6d-36c8-4c59-9212-7542837f9f4c', 'تحتاجين إلى البوح بما في داخلكِ 💬', 'هل تخنقكِ فكرة أنكِ لن تعودي أبدًا كما كنتِ؟ شاركي هذا الشعور العابر مع الأمهات في مجتمع Anacan، فأنتِ لستِ وحدكِ.'),
  ('188836b2-55a8-4b14-87fe-653f4e05ae3e', 'هل انزعجتِ من كل شيء اليوم؟', 'عندما ينام طفلكِ، اكتبي مشاعركِ في مفكرة المزاج. غدًا يوم جديد وأجمل.'),
  ('4d566d24-14b9-45b0-be5d-1940c1563ed9', 'تسوّق سريع 🛒', 'هل شريككِ على وشك مغادرة العمل؟ افتحي قائمة التسوّق فورًا، وأرسلي إليه خلال ثوانٍ ما ينقص المنزل من الحليب والفاكهة وغيرها.'),
  ('b5660557-30c8-45a9-9c75-69616076d9ce', 'مكان للأم ☕', 'لقد استنزف البقاء في المنزل طاقتكِ. اختاري من الأماكن الصديقة للأمهات مقهًى يقدم قائمة طعام للأطفال ويوفر جلسات مريحة، وخصصي بعض الوقت لنفسكِ.'),
  ('221ab24d-c8af-4cca-b9d8-b4eae15499d0', 'قدّري نفسكِ 👏', 'لا تنظري إلى فوضى الغرفة، بل إلى مدى سعادته اليوم. أنتِ أم رائعة بطريقة لا يمكن لأي كتاب أن يعلّمكِ إياها.'),
  ('cdf44716-8a24-472d-9ff5-449bcc14a7fe', 'جسم يرقص على الموسيقى 🎶', 'ما إن يسمع إيقاعًا موسيقيًا من التلفاز أو الهاتف حتى يبدأ بهزّ مؤخرته. لقد بدأ إدراكه للموسيقى يتطور، فانضمي إليه وارقصا معًا!'),
  ('d3e69c0c-c087-4266-8819-3e9aa9fc132a', 'حان وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، نظّمي مع شريككِ جلسة لتدليك الكتفين والتخلص من ضغوط اليوم. أنتما فريق واحد!'),
  ('12c2a250-54bd-4e0d-a366-20c820596148', 'طبيب أطفال سريع 🤖', 'هل توجد بقع حمراء صغيرة على جسم طفلكِ؟ قبل زيارة الطبيب، احصلي من Anacan AI على معلومات سريعة حول علامات حساسية الطعام.'),
  ('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec', 'الاستجابة لاسمه 🗣️', 'عندما تنادينه، لا يكتفي بالنظر إليكِ، بل يترك ما يفعله ويحاول التوجه نحوكِ.'),
  ('c7423d2f-6f9f-452c-9de2-5dea29b29f93', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل النوم بساعة واحدة. لا يُفرَز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('100bd53c-84e3-4c7e-8a31-2a287a02c440', 'تخلّصي من الشعور بالذنب 📝', 'هل تشعرين بأنكِ لم تلعبي معه بما يكفي اليوم؟ 10 دقائق ممتعة وثرية أفضل من ساعة تقضينها معه وأنتِ متعبة.'),
  ('fd0252a6-07bf-4750-bd4b-be91888e16f6', 'تقليد الكبار 🧹', 'هل يأخذ قطعة قماش ويحاول تقليدكِ عندما تنظفين المنزل؟ إنه مرآة لكِ! فهو يقلّد كل ما تفعلينه.'),
  ('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75', 'دعم الشريك 🥂', 'لتزيلا عن كاهلكما تعب اليوم بأكمله، اشربي الشاي مع شريككِ وقولا لبعضكما: لقد نجحنا اليوم أيضًا.'),
  ('ac527e8b-ca16-4272-b6ba-964f15ba419b', 'استفسارات طب الأطفال 🤖', 'ما حجم الحصة المناسب لطفل عمره 10 أشهر؟ لا ترهقي نفسكِ، واطلبي من Anacan AI جدولًا دقيقًا ومعتمدًا من أطباء الأطفال.'),
  ('e38208ca-c817-4de4-ba96-5a5ca4752901', 'حكة اللثة مستمرة 🦷', 'هل يضع أصابعه في فمه باستمرار ويقضم كل شيء؟ قد تكون الأضراس في طريقها إلى الظهور. سجّلي حالته في متتبّع التسنين.'),
  ('0535564e-f2c8-4264-bd71-a94e3154d928', 'استكشاف الطقس ⛅', 'هل الطقس في الخارج غير واضح تمامًا؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا تظهر من النافذة وبالملابس المناسبة.'),
  ('51cec612-e243-435d-9b60-1e3269d69cee', 'أمسيات موسيقية 🎶', 'أسهل طريقة لتهدئة نوبات التذمر في المساء هي تشغيل أغنية يحبها واحتضانه والرقص معه.'),
  ('533a4ec1-68c0-4cf3-92cd-723b3f8c0979', 'يخلع حذاءه بنفسه 👟', 'هل أصبح إلباسه أشبه بمباراة مصارعة؟ إنه يشد جواربه وحذاءه ويخلعهما بنفسه. أُعجبي بمهاراته الحركية!'),
  ('7bbccad8-a83a-493c-82e1-d823d261e04b', 'ألعاب المنطق 🧩', 'هل يضع الألعاب داخل الصندوق ثم يفرغها كلها؟ هكذا يتطور فهمه لمفهومي الداخل والخارج. لا تعيقي هذا النشاط.'),
  ('42ea49cf-0e72-4699-aaf4-7633e9ea6a82', 'لقطة توقف الزمن 📸', 'يبدو طفلكِ كل يوم أقرب إلى طفل أكبر، وتتلاشى ملامح الرضيع تدريجيًا. افتحي جلسة تصوير الطفل فورًا والتقطي صورًا توثّق هذا التغيّر.'),
  ('a0c5dfe0-02f0-4961-8b06-219cd57dde9d', 'الإشارات الأولى لاقتراب الشهر 11! 🎈', 'انتبهي! بعد 20 يومًا فقط سيُكمل طفلكِ شهره 11، وسنبدأ العدّ التنازلي الكبير نحو عامه 1. ابتسمي!'),
  ('6032f94e-69e7-4802-b291-44567c9f71d1', 'تهويدة الأب 👨‍🍼', 'هذا المساء، حان دور زوجكِ ليجرّب تنويم طفلكِ بمفرده في الغرفة.'),
  ('7b460d4a-b37e-465f-9c70-e137f59bcc07', 'التنظيف أم الراحة؟ 🛋️', 'عندما ينام طفلكِ، لا تسرعي نحو غسالة الصحون. استلقي على تلك الأريكة، وأغمضي عينيكِ، واكتفي بالتنفس لمدة 15 دقيقة. هل أنتِ روبوت؟ لا.'),
  ('a1392cb5-508d-45a8-9d3d-1985c8d19958', 'بدأت معركة «لا» 🛑', 'عندما تعطينه شيئًا لا يحبه، يهز رأسه ويدفعه بعيدًا. بدأت إرادته تتشكّل. حاولي احترام قراراته الصغيرة.'),
  ('2cc5ac97-f2b1-4c92-8852-fec32f54b311', 'التحكم في الأصوات 🤫', 'تكون أول نصف ساعة بعد خلوده إلى النوم أكثر الأوقات حساسية. تحقّقي من مستوى الضوضاء باستخدام مقياس الصوت، واحذري الأصوات المفاجئة.'),
  ('e0b42cd5-f681-4866-a7ec-b0b890444381', 'أم بصحة جيدة، طفل بصحة جيدة 🥑', 'لقد استُنزفت مخزونات الحديد والكالسيوم لديكِ. اختاري من الوصفات الصحية سلطة سريعة التحضير وغنية بالطاقة لتساعدكِ على مواصلة يومكِ بنشاط.'),
  ('e83a5069-7214-47ea-9051-6406495d5723', 'إصرار «أعطِني لعبتي!» 🧸', 'عندما تأخذين شيئًا من يده، يرد بقوة ويبكي. بدأ شعوره بالملكية يتشكّل بوضوح. بدلًا من منعه، حاولي توجيه انتباهه إلى شيء آخر.'),
  ('84cdedf9-5de5-49c9-887b-6f8ccc988990', 'نوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ بالكامل. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('a4c45285-b9cc-4763-a80c-d694137bbb6a', 'اكتشفي مكانًا مناسبًا للأمهات ☕', 'وسط كل هذا التعب، تحتاجين أنتِ أيضًا إلى بعض الهواء وتغيير الأجواء. ابحثي في الأماكن الصديقة للأمهات عن مقهى هادئ قريب منكِ واذهبي إليه.'),
  ('37e8bf23-2dc4-4b8c-8c8f-49146922ba57', 'المحاولة والخطأ 🧱', 'يحاول طفلكِ وضع مكعّبين فوق بعضهما، لكنهما يسقطان. ثم يعيد المحاولة بعناية. راقبي بهدوء محاولاته الهندسية الصغيرة هذه.'),
  ('732cb07a-0e5f-4dc9-9d15-78470db05396', 'أفكار للطعام 🍲', 'هل سئمتِ من طهي الأطباق نفسها؟ تصفّحي الوصفات الصحية واكتشفي أطعمة أصابع جديدة ولذيذة للأطفال بعمر 10 أشهر.'),
  ('a387d51e-9e9d-455a-be61-4650ee6ffa63', 'غرفة هادئة، عقل هادئ 🤫', 'عند الاستعداد للنوم، من الضروري خفض مستوى الضوضاء في الغرفة. استخدمي مقياس الصوت للتحقق من مستوى صوتكِ والأصوات المحيطة.'),
  ('439ac8e3-ab5f-434a-bb69-d98dee8208cd', 'حكاية خاصة 🪄', 'املئي الغرفة بالسحر من خلال ابتكار قصة بطل سيكبر بعد 10 أيام فقط في الحكايات الذكية.'),
  ('e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769', 'بقي 10 أيام فقط على إتمام الشهر 11! 🎂', 'لا يُصدَّق! بعد 10 أيام بالضبط، سيُتمّ صغيركِ شهره 11. لقد حان الوقت لبدء التفكير في خطط عيد ميلاده الأول!'),
  ('ff800946-b6d3-4e88-8699-fe114e37b692', 'صورة للابتسامات 📸', 'يصبح طفلكِ كل يوم شخصًا أكثر تميّزًا ولطفًا. افتحي جلسة تصوير الطفل الآن، وزيّني الصورة بالملصقات لتخلّدي هذه اللحظة المرحة.'),
  ('16cae145-7589-4ff6-ae2c-368fe115d232', 'إدارة المشاعر 📝', 'هل أعصابكِ مشدودة وتشعرين أنكِ على وشك الانفجار في أي لحظة؟ أفرغي كل توتركِ في مفكرة المزاج وخذي نفسًا عميقًا.'),
  ('9b99e928-dd9a-40d6-9254-12459dac4a3d', 'مصالحة الظلام 🌙', 'أضيفي التعرّف إلى الظلام إلى روتين المساء لمساعدة طفلكِ على النوم بسرعة أكبر. أطفئي جميع الأضواء الإضافية في الغرفة.'),
  ('ee2e2e79-277e-4a7f-9473-05aa36068880', 'يتعرّف إلى أعضاء جسمه 👀', 'عندما تسألينه: «أين أنفك؟»، هل يلمسه بإصبعه ويشير إليه؟ قدرته على الاستيعاب الذهني في ذروتها!'),
  ('2cb20f11-aee5-456a-b969-c87733104c72', 'أمسية الاحتفال بالنصر 🥂', 'هذا المساء، بعد أن ينام طفلكِ، ارفعي نخب «نحن فريق رائع» مع شريككِ. إنكما حقًا تقومان بعمل مذهل!'),
  ('57b926b9-28cb-4c4e-8863-8ce72241c9fe', 'الاشتباه في الحساسية 🤖', 'هل قدّمتِ له طعامًا جديدًا ولاحظتِ احمرارًا على وجنتيه؟ قبل أن تقلقي، تعرّفي إلى الخطوات الأولى من Anacan AI.'),
  ('9c11d140-acfd-48e4-9fef-141a9e34586d', 'إصراره على تناول الطعام بنفسه 🥦', 'يريد أن يأخذ الملعقة من يدكِ. دعيه يأخذها. ستتسخ ملابسه، لكن شعوره بالاستقلالية مهم جدًا له.'),
  ('09817e37-4e65-43f6-968c-dd333358e01e', 'قائمة الاحتياجات لا تنتهي 🛒', 'هل نفد الشامبو أم الحفاضات وسط الفوضى اليومية؟ لا تعتمدي على ذاكرتكِ، بل دوّنيها في قائمة التسوق وزامنيها مع شريككِ.'),
  ('1f244347-1957-4238-988d-4563adba7bcd', 'مناوبة الأب الليلية 👨‍🍼', 'يكفيكِ إرهاق النهار. في المساء، يتولى الأب وحده مهمة تجهيز طفلكِ للنوم وقراءة قصة له.'),
  ('9f618083-9332-44d7-8a8f-8ad3af6c22ac', 'كل ما في المنزل لعبة 🥄', 'الأوعية البلاستيكية والملاعق الخشبية أكثر إثارة لاهتمام طفلكِ من أغلى الألعاب. دعيه يستكشف أدوات المطبخ بحرية.'),
  ('354e039c-3978-4aa3-a008-1a3a7bbe85a3', 'تحليل البكاء لمساعدتكِ 😭', 'هل استيقظ طفلكِ في منتصف الليل ولا يتوقف عن البكاء؟ توقفي عن التخمين واستخدمي تحليل البكاء لمعرفة السبب فورًا.'),
  ('8fb53566-815d-4365-b87c-c14288ebb122', 'الهواء النقي هو المنقذ 🌳', 'إذا بدأت نوبة طفلكِ تشتد في المنزل، فتحققي من الطقس وملابسه، وضعيه في عربة الأطفال وتوجهي فورًا إلى الحديقة. فالطبيعة من أسرع الطرق لتهدئته.'),
  ('c87df5f1-fbe2-4462-a617-a6649445ce77', 'ذروة التململ ☁️', 'هل لا يرضيه شيء ويبكي على كل شيء؟ قد يكون السبب طفرة في النمو أو آلام التسنين. ما عليكِ سوى احتضانه كثيرًا.'),
  ('7fd53d22-26ef-4c4c-83bb-d44647b94560', 'لنجد الحل معًا 💬', 'هل سئمتِ من التساؤل: لماذا يتصرف طفلي هكذا؟ انضمي إلى مجتمع Anacan، وسترين أن آلاف العائلات تمر بالتجربة نفسها تمامًا!'),
  ('a6ef3f7c-7550-4712-8fc9-23c742a51744', 'الاستعداد للنوم 🛀', 'الحمام الدافئ مفيد دائمًا. لا تغيّري روتين المساء أبدًا، لأنه يرسل إلى دماغ طفلكِ إشارة بأن وقت النوم قد حان.'),
  ('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb', 'يتعلم بالمحاولة والسقوط 🧗‍♂️', 'يسقط طفلكِ على مؤخرته في أثناء الوقوف، ثم يضحك ويحاول النهوض مجددًا. تساعده هذه السقطات على بناء الذاكرة العضلية، فلا تتدخلي أكثر من اللازم.'),
  ('25903ac8-0fd6-44f0-92d8-c3e1bee035e5', 'الحاجة إلى الهدوء 🤫', 'هل توقظ طفلكِ أدنى طقطقة عندما يخلد إلى النوم؟ حلّلي الأصوات المحيطة باستخدام مقياس الضوضاء، ووفّري له هدوءًا متواصلًا.'),
  ('932e2f32-ffee-4b5c-9d10-16c135453b42', 'غدًا هو اليوم الكبير! 🎉', 'هل أنتِ مستعدة؟ غدًا يُتمّ طفلكِ 11 شهرًا بالضبط! لم يتبقَّ سوى شهر واحد على بلوغه عامه الأول! حضّري ركنًا مميزًا وملابس مختلفة لجلسة تصوير طفلكِ.'),
  ('aac354e5-8061-403a-8cf7-d00ce05e4093', 'روح التضامن 🥂', 'افتحي مفكرة المزاج، واسترجعي مع شريككِ ذكريات الأيام الأولى واضحكا معًا. لم يكن الوصول إلى هذه المرحلة بعد 11 شهرًا أمرًا سهلًا!'),
  ('d24d332c-e00e-4b7f-8dac-28439e172c26', 'استراحة القهوة للأم ☕', 'لن تختفي فوضى الغرفة، لكن طاقتكِ قد تنفد. عندما يلعب طفلكِ بمفرده، لا تسرعي إلى أداء المهام. اجلسي واستمتعي بقهوتكِ.'),
  ('6ef8817b-2854-4da4-969a-fe13d344017a', 'رقصة النصر 💖', 'احتفلي هذا المساء مع شريككِ بتعب 11 شهرًا وفخرهما. أنتما الآن في المرحلة الأخيرة نحو عامه الأول!'),
  ('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b', 'حليب الأم لا يزال أساسيًا! 🍼', 'حليب الأم مهم حتى عمر سنة. شغّلي مؤقت الرضاعة للتأكد من تلبية احتياجات طفلكِ اليومية من الحليب.'),
  ('ad9c3e79-16bb-44a7-9f37-6f5935a4494c', '11 شهرًا بالضبط! 🎂', 'تهانينا! مرّ 11 شهرًا كاملًا منذ الولادة! اختاري الآن ملصق الشهر 11 من قسم جلسة تصوير الطفل، وشاركي هذه الفرحة في مجتمع Anacan!'),
  ('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f', 'الوصول إلى المناطق الخطرة ⚡', 'ازداد طول طفلكِ وأصبح قادرًا على الوصول إلى الرفوف التي لم يكن يبلغها من قبل. أعيدي تقييم سلامة المنزل، بما في ذلك الزوايا الحادة والأغراض الثقيلة.'),
  ('8a4a7da2-606f-4fbb-8668-101f2d47c03c', 'قوة الموسيقى 🎶', 'جرّبي تهدئة نوبات الانفعال المفاجئة في آخر النهار بتشغيل موسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة المعجزات.'),
  ('3a5c700f-e10c-4819-bba1-cddd9f951f4f', 'القوائم والنسيان 🛒', 'أما زال ضباب الذاكرة يلازمكِ؟ لا تشغلي بالكِ بمشتريات المنزل الصغيرة، بل أضيفيها فورًا إلى قائمة التسوق ودعي زوجكِ يتولى الأمر.'),
  ('47b342b1-9525-44b6-b917-2eb642240cb2', 'عناق «أحبكِ» 🫂', 'هل يأتي فجأة ليعانقكِ أو يداعب وجهكِ؟ لقد بدأ يعبّر عن حبه جسديًا. استمتعي بهذه اللحظة.'),
  ('361e96e8-a6ed-4fdf-a7bb-50e07abcec66', 'سكينة الليل 🪄', 'ابتكري في الحكايات الذكية قصصًا عن حيوانات شجاعة ومحبوبة، وحوّلي الغرفة إلى عالم ساحر.'),
  ('a4baaa67-c9fb-4208-aab7-e7515b21f64f', 'تفعلين كل شيء لإشباع طفلكِ. وماذا عنكِ؟', 'اختاري من قسم الوصفات الصحية وجبة غداء غنية بالحديد والبروتين، واستعيدي طاقتكِ.'),
  ('c58c8b30-4c95-4f60-98d7-d9580eb48a38', 'تُقلَب صفحات الكتاب 📖', 'هل يقلب صفحات الكتب ذات الصفحات السميكة بنفسه تمامًا؟ سجّلي هذا الإنجاز الحركي في متتبع النمو.'),
  ('2631ed9f-967a-4f12-9097-1f619f7f1e5f', 'ألم يَسِر أي شيء وفق الخطة اليوم؟', 'عندما ينام طفلكِ، لا تشعري بالذنب. أنتِ أم حقيقية، وأنتِ مثالية.'),
  ('34415812-3e31-43f2-99de-a1dd76bb1d9e', 'رميات هادفة ⚾', 'يحاول عمدًا رمي اللعبة التي في يده نحو هدف محدد. يتطور التناسق بين العين واليد لديه بسرعة.'),
  ('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4', 'طبيب أطفال سريع 🤖', 'كم ينبغي أن تستغرق القيلولة النهارية لطفل يبلغ من العمر 11 شهرًا؟ اسألي Anacan AI فورًا عن كل ما يثير حيرتكِ واطمئني.'),
  ('a70ebacf-44d0-4367-babf-09742bda8fa8', 'بدأت تحضيرات عيد الميلاد الأول! 🎈', 'لقد أكملنا 11 شهرًا. لم يتبقَّ سوى 30 يومًا على عيد الميلاد الأول! هل تختارين فكرة وديكورًا مميزين، أم مكانًا للاحتفال، أم تكتفين بالاحتفال في المنزل؟ ابدئي التخطيط على مهل.'),
  ('0387bc9b-1c64-4eae-ac49-660cb56552f8', 'أجد لعبتي بنفسي 🧸', 'هل يذهب طفلكِ ليجد اللعبة التي أبعدتِها عن نظره وأخفيتِها خلف شيء ما؟ لقد أدرك تمامًا أن الأشياء تظل موجودة حتى عندما لا يراها!'),
  ('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ طوال الوقت. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('89a2b668-b451-4cfe-a183-3183fc159297', 'أطلقي العنان لمشاعركِ 📝', 'مع اقتراب طفلكِ من عمر 1 سنة، هل بدأ يتسلل إليكِ حزن غريب وشعور بأنه كبر بسرعة؟ دوّني هذه المشاعر في مفكرة المزاج.'),
  ('23c2a94e-cf0d-4f81-9604-79b4dcfb2460', 'الخروج من بين الجدران الأربعة ⛅', 'هل سئمتِ البقاء في المنزل؟ تحققي من الطقس وملابس طفلكِ، ثم دعيه يستكشف العشب والأوراق ويلمسها بحرية في الحديقة.'),
  ('77a8c135-4a26-4877-9f24-fc51c941fb7a', 'يساعدكِ عند ارتداء ملابسه 👕', 'هل يمدّ ذراعيه بنفسه عندما تلبسينه قميصه، أو يرفع قدمه لمساعدتكِ؟ إنه يتعاون معكِ. سجّلي هذه المساعدة الصغيرة في متتبّع النمو.'),
  ('9df28291-b590-4e7d-a861-feb0732398b2', 'التصالح مع الظلام 🌙', 'لمساعدته على النوم بسرعة أكبر، أضيفي التعرّف إلى الظلام ضمن روتينه المسائي. أطفئي جميع الأضواء الإضافية في الغرفة.'),
  ('72f5aeb4-94f9-40bc-943e-fa87664da32b', 'لا تضيعي بين صفحات المنتديات 🤖', 'هل لاحظتِ شيئًا غريبًا في حركة طفلكِ؟ لا تقضي ساعات في البحث على الإنترنت؛ اطرحي سؤالكِ مباشرةً على Anacan AI واطمئني.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e'::uuid, 'أم بصحة جيدة، طفل بصحة جيدة 🥑', 'لقد استُنزفت مخزونات الحديد والكالسيوم لديكِ. حضّري من وصفاتنا الصحية سلطة سريعة التحضير وغنية بالطاقة لتمنحكِ القوة والنشاط.'),
  ('7883fd83-494d-41a3-b42d-58d452de13d7', 'مرح الأب 🤡', 'أفضل طريقة لإضحاك طفلكِ هي أن يصدر والده أصواتًا غريبة. استمتعي معه بهذه اللحظات المرحة هذا المساء.'),
  ('981d8d60-ab26-4f64-a20b-eee1dc2fed12', 'الانتقال الكامل إلى الأطعمة المقطّعة إلى قطع صغيرة! 🍲', 'أصبح بإمكانه الآن تناول الأطعمة التي تتطلب المضغ. جرّبي قوامًا جديدًا من خلال وصفاتنا للرضّع الذين بدأوا تناول الأطعمة التكميلية في تطبيقنا.'),
  ('74f02405-1cdd-401e-bb47-01d87997f231', 'وقت اللعب المستقل 🧸', 'أصبح بإمكانه الآن الانشغال بألعابه بمفرده لمدة 10-15 دقيقة. وهذا دليل على تحسّن مدة تركيزه. راقبيه من بعيد واستمتعي بالهدوء.'),
  ('8d91b32b-a0f2-4a07-a181-da0b746268bc', 'الحديقة أم المنزل؟ ⛅', 'ترغبين في الخروج، لكن الجو عاصف. دعي مساعد الطقس والملابس يخبركِ ليس فقط بدرجة الحرارة، بل أيضًا بالملابس الواقية من الرياح التي ينبغي أن يرتديها طفلكِ.'),
  ('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e', 'ليالٍ عنيدة 🥱', 'هل يقاوم النوم بكل قوته؟ راجعي مواعيد قيلولاته النهارية وروتين نومه من جديد.'),
  ('2f4fbaac-dfe4-48b5-b844-6636c2bc201a', 'قائمة في جيبكِ 🛒', 'اطّلعي على خيارات الكعك في Anacan لطلب كعكة عيد ميلاده الأول.'),
  ('395ddd9b-9009-4fec-ba6f-816d156ad432', 'مشاعر كبيرة في جسد صغير 🛑', 'هل يرمي نفسه على الأرض أو يبكي عندما لا يحصل على ما يريد؟ إنه لا يستطيع التحكم في مشاعره بعد. انحني إلى مستواه وتحدثي إليه بهدوء لمساعدته على تجاوز نوبات الغضب.'),
  ('d02f135b-16bc-4fa9-978f-0e7d992c1ba4', 'التنظيف أم الراحة؟ 🛋️', 'عندما ينام طفلكِ، لا تسرعي نحو غسالة الصحون. تمدّدي على الأريكة، وأغمضي عينيكِ، وتنفسّي فحسب لمدة 15 دقيقة.'),
  ('f12c7751-b89f-4d12-a843-8e331c338393', 'يبني قلعة بالمكعبات 🧱', 'يحاول وضع مكعبين أو ثلاثة من مكعبات اللعب فوق بعضها. راقبي بصمت محاولاته الهندسية الصغيرة هذه وصفّقي له.'),
  ('35ab2e31-1937-4e58-b764-83729c6e330a', 'يجيب بلغة الجسد 🗣️', 'يرفع ذراعيه عندما تسألينه: هل نذهب؟ أو يهزّ رأسه عندما تقولين: لا. لقد تطورت قدرته على الفهم بشكل مذهل.'),
  ('65a36f4e-0f24-45fe-a038-a2e61c778c81', 'قدّري نفسكِ 👏', 'لا تنظري إلى فوضى الغرفة، بل إلى مدى سعادته اليوم. أنتِ أم رائعة على نحو لا يمكن لأي كتاب أن يعلّمكِ إياه.'),
  ('7b75b0ec-d253-4e5a-bfac-9ff801269b5f', 'اليوم في الحكاية الذكية 🪄', 'أنشئي في الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: الأسد الصغير الذي يستعد لإتمام عامه الأول.'),
  ('01302c3b-60e6-4b0a-8a88-e63349585527', 'هل تقلقكِ سنّ العام الأول؟ 💬', 'هل تشغل بالكِ أسئلة مثل: طفلي لم يمشِ بعد، فهل هو متأخر؟ اكتبي في مجتمع Anacan. سترين أن لكل طفل وتيرته المثالية الخاصة، وأنكِ لستِ وحدكِ.'),
  ('51d3f88a-4baa-4ed5-b62c-e84a750f8166', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ. أيقظي شريككِ أيضًا؛ فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('984d2a76-5fec-4059-86ef-85671516c9b6', 'استكشاف الطقس ⛅', 'هل الطقس في الخارج غير مستقر؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح والملابس المناسبة.'),
  ('c8b05bf8-0ed8-4eec-86f7-4cba168167e1', 'يعرف معاني الكلمات 🗣️', 'عندما تطلبين منه إحضار الكرة، يذهب فعلًا للبحث عنها. تزداد حصيلته من الكلمات التي يفهمها بسرعة. تحدّثي معه بجمل أكثر تعقيدًا.'),
  ('f8aae6d9-1b70-4333-a55c-1937c871c533', 'حان وقت الحكاية الذكية 🪄', 'أنشئي في الحكايات الذكية قصة بطل سيبلغ عامه الأول بعد 1 شهر فقط. ولتكن هذه الحكاية الصوت الوحيد الذي يكسر سكون الليل.'),
  ('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1', 'زينة وبالونات لازمة للاستعداد لعيد ميلاده الأول؟  🛒', 'لا ترهقي ذهنكِ، وابدئي من الآن بإعداد قائمة التسوق.'),
  ('519cad33-f5e8-4169-8f1d-93f4343568db', 'محاولات لا تعرف الاستسلام 🧗‍♂️', 'يحاول النهوض مستندًا إلى الأثاث حتى واللعبة في يده. لقد تطورت قدرته على التوازن بشكل مذهل. راقبيه من بعيد من دون تدخل.'),
  ('aa2fb7c9-acf7-4050-9102-4f2927091b95', 'البطل الصامت 🤫', 'ما إن يغطّ في النوم، حتى يبدو كل صوت في المنزل كأنه انفجار قنبلة. وبينما تضبطين الحد المناسب لضوضاء الغرفة باستخدام مقياس الصوت، اجعلي خطواتكِ أخف أيضًا.'),
  ('9cba5d69-92c6-472c-bb83-c5522d806018', 'أسرار الأمهات 💬', 'هل ترهقكِ فكرة «كيف أنظّم عيد ميلاده؟» اكتبي في مجتمع Anacan واحصلي من الأمهات على أفكار مبتكرة تناسب ميزانيتكِ.'),
  ('f558e782-e140-4835-8b11-1d5f01a717bf', 'لقطة توقف الزمن 📸', 'يبدو كل يوم أقرب قليلًا إلى طفل أكبر. افتحي جلسة تصوير الرضيع فورًا، وخلّدي لحظة رقصه العفوية هذه في ذاكرتكِ.'),
  ('f56842a9-3a83-4016-8e93-a096810c45d3', 'الرقص والإيقاعات 🎶', 'هل يبدأ بالرقص بمجرد سماع إيقاع من التلفاز أو الهاتف؟ لقد أصبح إدراكه للموسيقى نشطًا تمامًا، فانضمي إليه وارقصي معه!'),
  ('063ccb8e-7bd6-43e4-9c41-f30c172e10a7', 'أم بصحة جيدة، طفل بصحة جيدة 🥑', 'لقد استُنزفت مخزونات الحديد والكالسيوم لديكِ. حضّري من قسم الوصفات الصحية سلطة سريعة التحضير تمنحكِ الطاقة أيضًا.'),
  ('1bed0d5c-444a-48fc-8e21-35fd8fff35b5', 'بقي ٢٠ يومًا فقط على إتمام عامه الأول! 🎂', 'ما أسرع مرور الوقت! ابدئي بتدوين الملاحظات حول دعوات عيد الميلاد والقوائم والمفاجآت الصغيرة.'),
  ('caa0a9a0-1a0d-4362-a446-9f103d33e564', 'لقطة توقف الزمن 📸', 'بينما يلعب طفلكِ بلطف في الغرفة، افتحي جلسة تصوير الطفل فورًا والتقطي صورة تُظهر شخصيته كطفل كبير.'),
  ('3cc5a97d-281f-41bf-8747-fbb71f040e65', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل النوم بساعة. لا يُفرَز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('528b02c4-9d93-4cda-add4-eb9a04a4395a', 'أطعمة تدعم إدرار حليبكِ. 🍲', 'جرّبي اليوم الشوربات المعززة لإدرار الحليب في قسم الوصفات الصحية للنساء، وامنحي جسمكِ مزيدًا من القوة.'),
  ('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d', 'هل نسيتِ من أي ثدي أرضعتِ؟ 🤱', 'يتذكّر مؤقت Anacan نيابةً عنكِ الثدي الأيمن أو الأيسر. ابدئي جلسة الرضاعة الآن باستخدام المؤقت!'),
  ('5c42ea20-5a84-467a-b408-412bcaaf8374', 'هل تتغير قيلولته النهارية؟ 🥱', 'هل يقاوم إحدى قيلولتيه النهاريتين؟ مع اقترابه من عمر السنة، قد يكون الوقت قد حان لإعادة ضبط جدول نومه.'),
  ('b5252c17-b36e-4334-8221-0dc9210bbc77', 'له مكانه الخاص على مائدة العائلة! 🍲', 'أصبح يحب تناول الطعام معكم في الوقت نفسه. اكتشفي أطباقًا شهية تناسب جميع أفراد العائلة من قسم وصفات للأطفال الذين بدأوا تناول الأطعمة التكميلية في تطبيقنا.'),
  ('d824145b-4905-49d1-9f4f-46ade8a730f8', 'هل استيقظ فجأة وهو يصرخ؟ 😭', 'قد يكون ذلك رعبًا ليليًا. شغّلي صوته في ميزة تحليل البكاء لتتأكدي مما إذا كان السبب جسديًا أم نفسيًا.'),
  ('a7923459-9b74-4330-949d-00e94d185768', 'معنى كلمة «لا»! 🛑', 'هل أصبح طفلكِ يراقب رد فعلكِ عندما يفعل شيئًا لا ينبغي له فعله؟ استشيري Anacan AI بشأن الخطوات الأولى لتعليم الانضباط.'),
  ('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1', 'وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، خصّصي مع شريككِ جلسة لتدليك الكتفين والتخلص من ضغوط اليوم. أنتما فريق واحد!'),
  ('ef821341-2506-439d-8346-fbafb2b792ff', 'بقي 25 يومًا فقط على إتمام عامه الأول! 🎈', 'بدأ العد التنازلي رسميًا! هل فكرتِ في المكان والملابس لجلسة تصوير عيد ميلاده الأول؟ أسرعي في التحضيرات!'),
  ('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea', 'تدابير السلامة في المنزل! 🛡', '️ مع بدء طفلكِ في التحرك بحرية، تزداد المخاطر. احرصي على الاطلاع على قائمة المنتجات الموصى بها لأقفال حماية الأطفال وبوابات السلالم.'),
  ('959729c5-8ab6-4053-99ca-82aa5fdabc7e', 'حان وقت مشاركة الآباء في الرعاية. 👨‍🍼', 'بعد الرضعة المسائية، دعي الأب يتولى قراءة الكتاب ومساعدة طفلكِ على النوم، بينما تأخذين أنتِ غفوة قصيرة.'),
  ('a478b2eb-eaec-4b54-813a-6f2ba55a5d14', 'يشير إلى كل شيء بإصبعه السبابة! ☝', '️ بدلًا من أن يقول «ما هذا؟»، يشير إلى كل شيء بإصبعه. خلّدي هذا الفضول في ألبوم طفلكِ.'),
  ('97023662-0ba2-4bcd-aff7-bc7adf5883ba', 'التحكم في الأصوات 🤫', 'تكون أول نصف ساعة بعد أن يغطّ طفلكِ في النوم أكثر الأوقات حساسية. تحققي من المكان باستخدام مقياس الصوت واحذري الضوضاء المفاجئة.'),
  ('222d12a8-4347-4dce-afd7-4a0890721d0b', 'ليالٍ عنيدة 🥱', 'هل يقاوم النوم بكل قوته؟ ربما حان الوقت للاستغناء عن إحدى قيلولات النهار. راجعي روتينه.'),
  ('5047e51c-64dc-4fe5-bc38-0409a743d0f6', 'لنتحقق من نمو الطول والوزن! 📏', 'لم يتبقَّ الكثير على فحص عمر 1 سنة. حدّثي أحدث البيانات في قسم متابعة النمو، وشاهدي مخطط نموه الصحي بكل فخر.'),
  ('873f2996-36df-4d67-a2df-ec60f668be2f', 'انهار برج الطعام 🥣', 'هل يتعمّد إسقاط الملعقة على الأرض ثم ينظر إليكِ؟ إنه يختبر الجاذبية ورد فعلكِ. تحلّي بالصبر، فهذا نوع من اللعب.'),
  ('8cd57628-b75f-4445-8bc9-6b180e6572dc', 'اليوم في الحكاية الذكية 🪄', 'أنشئي في الحكايات الذكية قصة مميزة يكون طفلكِ بطلها.'),
  ('94b60a89-bc34-41d8-818c-174aa7ed663b', 'التنظيف أم الراحة؟ 🛋️', 'عندما ينام طفلكِ، لا تهرعي إلى غسالة الصحون. استلقي على تلك الأريكة، وأغمضي عينيكِ، واكتفي بالتنفس لمدة 15 دقيقة. هل أنتِ روبوت؟ لا.'),
  ('c7b84129-89ab-4610-b19f-84959d6194f9', 'مستكشف الخزانة 🕵️‍♀️', 'هل أصبحت جميع أواني المطبخ على الأرض؟ اللعب بالأشياء الآمنة ينمّي تفكيره المنطقي. دعيه يبحث عن الكنوز بحرية.'),
  ('11e743be-fb20-462f-8c74-07c143992d51', 'بقي 10 أيام على إتمام عامه الأول! 🎂', 'الحماس يزداد! كعكة عيد الميلاد، والملابس، وقائمة الضيوف... رتّبي أفكاركِ بتدوين كل شيء في قسم الملاحظات الخاصة في يوميات الحالة المزاجية.'),
  ('15436a4e-52bb-4539-9146-377403746da0', 'فضفضة الأمهات 💬', 'هل ترهقكِ أسئلة مثل: لماذا لم يبدأ طفلي المشي بعد؟ انضمي إلى مجتمع Anacan، وستدركين أن لكل طفل وتيرته الخاصة.'),
  ('ee88eee3-00d7-4463-b0db-60b939d85d4e', 'هل لديكِ سؤال؟ 🤖', 'يمكنكِ طرح أسئلتكِ المهمة، مثل: كيف أنتقل إلى حليب البقر بعد عمر ١ سنة؟ على مساعد Anacan بالذكاء الاصطناعي والحصول على الدعم حتى في ساعات الليل.'),
  ('48047d55-0e81-4b9a-976d-56b580b1a7b7', 'تساؤلات حول صحة طفلكِ 🤖', 'ما الذي يتغير في تغذية طفلكِ مع اقترابه من عمر ١ سنة؟ لا ترهقي نفسكِ، واطلبي من مساعد Anacan بالذكاء الاصطناعي قائمة دقيقة ومعتمدة من أطباء الأطفال.'),
  ('56284941-dca4-4067-9e31-d61fc4ebeb63', 'دعم الفريق 🥂', 'لتتخلصي من تعب اليوم كله، اشربي الشاي مع شريككِ وقولا لبعضكما: لقد نجحنا اليوم أيضًا.'),
  ('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e', 'ينفّذ التعليمات البسيطة بالكامل! 🧠', 'يفهمكِ عندما تقولين له: أعطني الكرة، أو تعال إلى هنا. ساعديه على تطوير هذه القفزة الذهنية أكثر من خلال مقالات المدونة.'),
  ('20db1e8e-1980-431d-800c-b7aa4ccf158b', 'محاولات الأكل بملعقته! 🥄', 'هل أصبح يمسك الملعقة ويحاول إيصالها إلى فمه؟ لدعم هذه اللحظات الممتعة، اختاري أطعمة مناسبة من قسم الأغذية التكميلية للرضع.'),
  ('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6', 'الاستغراق في النوم مع حكاية 🪄', 'أنشئي في الحكايات الذكية خلفية خاصة تتكوّن فقط من الموسيقى وأصوات الطبيعة. لا كلمات، بل سكينة فحسب.'),
  ('eca3e78d-00de-4e77-bade-43808f152e4f', 'قبلات مفعمة بالحب 🥰', 'عندما تقبّلينه، هل يميل نحوكِ ويمدّ شفتيه أو يبلّل خدكِ؟ قبلاته الصغيرة كفيلة بأن تمحو كل تعبكِ.'),
  ('863a6afb-427b-4143-a527-2e01fe303116', 'تعابير وجه الأب المضحكة 🤡', 'أفضل طريقة لإضحاك طفلكِ هي أن يصدر الأب أصواتًا غريبة. استمتعا مع طفلكما باللحظات المرحة هذا المساء.'),
  ('b4676fcf-2967-4b49-adbd-12ebe6a54334', 'بحاجة إلى الفضفضة 💬', 'هل تجعلكِ فكرة «لا أصدق أنه بلغ بالفعل عامه الأول» عاطفية؟ شاركي هذا الشعور الجميل مع الأمهات في مجتمع Anacan.'),
  ('b86239c1-4a1c-48b3-b49a-3fd4a012ebae', 'بقي 15 يومًا فقط على إتمام عامه الأول! 🎈', 'تهبّ نسمات الحنين! هل تتذكرين ذلك اليوم الأول الذي غادرتِ فيه مستشفى الولادة؟ والآن تستعدين للاحتفال بعامه الأول! ضعي صورته الأولى بجانب صورته الحالية في جلسة تصوير طفلكِ!'),
  ('152edc3c-3a8c-41ee-81bb-0df222f2c1ea', 'أسبوعان فقط! 🎈', 'بقي 14 يومًا فقط على عيد ميلاده! تهبّ نسمات الحنين... افتحي ألبوم صور طفلكِ، وضعي صورته يوم ولادته بجانب صورته اليوم لتشاهدي نموه المذهل.'),
  ('87c2d4c6-8130-43a1-8ff7-fa406c018013', 'مسؤولية الأب ليلًا 👨‍🍼', 'يكفيكِ ما تشعرين به من إرهاق خلال النهار. تجهيز طفلكِ للنوم وقراءة قصة له في المساء مسؤولية الأب. أما أنتِ، فما عليكِ سوى وضع سماعاتكِ.'),
  ('d1325a58-5701-4db5-a92f-ca67116c5c21', 'ثوانٍ من الوقوف دون مساعدة 🧗‍♂️', 'هل يُفلت يديه للحظات قصيرة حين يقف مستندًا إلى الأريكة؟ إنه يتعلم الحفاظ على توازنه.'),
  ('3beff563-1e72-4a1f-8490-4e977c8b0b7a', 'حيرة ماذا أطبخ 🍲', 'هل نفدت أفكاركِ لوجبات طفلكِ مع اقترابه من عامه الأول؟ اطلبي من Anacan AI قائمة بأطعمة أصابع سهلة يستطيع طفلكِ إمساكها وتناولها بنفسه.'),
  ('eebfea92-7f8e-43d7-a45c-4a10e720b24c', 'مصالحة الظلام 🌙', 'اجعلي الظلام جزءًا من روتين المساء لمساعدته على النوم بسرعة أكبر. أطفئي جميع الأضواء الإضافية والشاشات في الغرفة.'),
  ('f8f9e691-e184-414d-9abe-ae0a3969929a', 'يشارك في الحديث 🗣️', 'هل يقول شيئًا بلغته الخاصة ويرفع صوته حين تتحدثين؟ مهاراته في التواصل تتطور بسرعة، ولديكِ متحدث ثانٍ في الغرفة، فاحرصي على الاستماع إليه!'),
  ('21394622-dd96-488a-a90a-b8f72d718390', 'اختيار الحذاء الأول! 👟', 'بدأت خطواته تتسارع! احرصي على الاطلاع على قائمة المنتجات الموصى بها لاختيار حذائه الأول، بخصائص طبية ونعل ناعم يدعمان نمو قدميه.'),
  ('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1', 'إجراءات السلامة في المنزل! 🛡', '️ تزداد المخاطر مع بدء طفلكِ بالمشي بمفرده. اطّلعي على المنتجات الموصى بها، مثل أقفال حماية الأطفال وبوابات السلالم.'),
  ('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b', 'جسدكِ المتغيّر 👗', 'هل تشعرين بالحزن عندما تنظرين إلى ملامح جسدكِ في المرآة؟ لقد صنعتِ بهذا الجسد إنسانًا. عانقي نفسكِ وتذكّري كم أنتِ قوية.'),
  ('f38aba52-8d3a-44ad-96bf-7d9de570ef68', 'الإصرار على البقاء قرب أمه 🥰', 'حتى عندما تذهبين إلى الحمّام، ينتظركِ خلف الباب ويبكي. بلغ قلق الانفصال ذروته. طمئنيه في كل مرة بقولكِ: أنا هنا.'),
  ('03283459-7c0f-4d41-9c06-406552e1c477', 'وهم المثالية 🛑', 'ألم يسر أي شيء اليوم وفقًا للخطة؟ لا تلومي نفسكِ. أنتِ أم حقيقية، ولستِ صورة مثالية مُعدّلة بفلاتر وسائل التواصل الاجتماعي.'),
  ('3843a02f-a85f-47a9-97ba-0e63677749e2', 'البطلة الصامتة 🤫', 'ما إن ينام حتى يبدو كل صوت في المنزل كأنه انفجار. وبينما تضبطين مستوى الضوضاء في الغرفة باستخدام مقياس الصوت، خفّفي وقع خطواتكِ أيضًا.'),
  ('fde65599-b651-49fa-a50a-5b78bed58d9f', 'إصبع الإشارة يعمل بنشاط ☝️', 'يشير بإصبعه إلى غرض بعيد ويتفاعل معه. هذه أعلى مراحل توجيه الانتباه. انظري معه إلى ذلك الغرض.'),
  ('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6', 'هل يمكنني تقديم حليب البقر؟ 🥛', 'تتغيّر قائمة طعام طفلكِ مع اقترابه من عمر 1 سنة. إذا كانت لديكِ أسئلة حول الانتقال إلى حليب البقر أو تقديم أطعمة مثل العسل، فاسألي Anacan AI فورًا.'),
  ('6b37b92f-5c61-4852-9ace-caab2bda465b', 'نزهة عائلية وخطط ممتعة! ☕', 'لم يتبقَّ الكثير على عيد الميلاد! ابحثي في الأماكن الصديقة للأمهات عن مقاهٍ يمكنكِ دخولها بسهولة بعربة طفلكِ للقاء الأصدقاء والعائلة.'),
  ('fedb8c6b-7722-4e20-9134-1af5ae254e85', 'وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، خصّصي جلسة تدليك للكتفين مع شريككِ للتخلص من ضغوط اليوم. أنتما فريق واحد!'),
  ('51bb1e4c-965f-4d69-b6e7-c79da0dce45c', 'مكان مناسب للأم ☕', 'لقد استنزف البقاء في المنزل طاقتكِ. اختاري من الأماكن الصديقة للأمهات مقهًى يقدم قائمة طعام للأطفال ويوفر جلسات مريحة، وخصّصي بعض الوقت لنفسكِ.'),
  ('814176f3-c727-409b-b14a-fa62636170f1', 'الاهتمام بالكتب 📖', 'أدخلي الكتب الورقية ضمن الروتين المسائي. فقد بدأ طفلكِ يحاول تقليب الصفحات بنفسه. واءمي نبرة صوتكِ مع إيقاع القصة.'),
  ('f73c2769-0def-42bc-93e0-9a021c41b271', 'جسم يرقص على أنغام الموسيقى 🎶', 'ما إن يسمع طفلكِ إيقاعًا على التلفاز حتى يبدأ بهزّ مؤخرته. لقد بدأ حسّه الموسيقي بالتطور، فانضمي إليه واستمتعا معًا بهذه اللحظة الرائعة.'),
  ('4c628627-3074-421f-9cfc-318df363eaf0', 'هل نسيتِ من أي ثدي أرضعتِ طفلكِ؟ 🤱', 'يتذكر مؤقت Anacan نيابةً عنكِ ما إذا كانت الرضعة من الثدي الأيمن أم الأيسر. ابدئي تسجيل الرضعة باستخدام المؤقت الآن!'),
  ('99abcc3d-bec9-4537-89f9-92bfe6f4056c', 'نهاية يوم رائع. ✨', 'أنتِ أم مذهلة، وقد صنعتِ بطولات حقيقية طوال 1 عام! اكتبي في مفكرة المزاج أنكِ فخورة بنفسكِ، ثم نامي بهدوء.'),
  ('d58a373d-b464-4fff-9b8e-74a104499618', '5 أيام فقط حتى إتمام عامه الأول! 🎈', 'أوشك العد التنازلي على الانتهاء! عيد الميلاد الأول! الزينة والضيوف الصغار... انضمي إلى مجتمع Anacan واحصلي من الأمهات على أفكار مبتكرة لحفل عمر 1 عام.'),
  ('0549edc6-63d2-4caa-a43c-f029f7f39465', 'آلام التسنين 🦷', 'هل احمرّت لثته مجددًا ولا يتوقف سيلان لعابه؟ لعل أضراسه الأولى في طريقها للظهور.'),
  ('1c81021a-496b-49c0-86bc-4bde92ff779d', 'التحكم في الأصوات 🤫', 'النصف ساعة الأول بعد خلوده إلى النوم هو الوقت الأكثر حساسية. تحققي من مستوى الضوضاء باستخدام مقياس الصوت واحذري الأصوات المفاجئة.'),
  ('262cbb13-eb12-4831-9fe5-37ece168bdfa', 'الاستجابة بلغة الجسد 🗣️', 'يرفع ذراعيه عندما تقولين: «هل نذهب؟»، أو يهز رأسه عندما تقولين: «لا». لقد تطورت قدرته على الفهم بشكل مذهل!'),
  ('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8', 'الهواء النقي هو المنقذ 🌳', 'إذا اشتدت نوبة غضبه في المنزل، فتحققي من الطقس وملابسه، وضعيه في عربة الأطفال واخرجي فورًا إلى الحديقة. الطبيعة هي أسرع وسيلة لتهدئته.'),
  ('39697061-01f6-4b41-8098-183a43f25058', 'يبني قلعة بالمكعبات 🧱', 'يحاول وضع مكعبين أو ثلاثة من مكعبات اللعب فوق بعضها. راقبي محاولاته الهندسية الصغيرة بهدوء وصفّقي له.'),
  ('c5294433-a84c-4be9-ad57-5744718366c9', 'هل أزعجكِ كل شيء اليوم؟ 📝', 'عندما ينام طفلكِ، اكتبي مشاعركِ في مفكرة المزاج. غدًا يوم جديد وأجمل.'),
  ('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a', 'استعيدا معًا ذكريات الأيام الأولى واضحكا.', 'لم يكن الوصول إلى عمر 1 سنة أمرًا سهلًا! إنه انتصاركما كفريق.'),
  ('5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf', 'بقي يومان على اليوم المنتظر! 🗣', '️ أن يناديكما «ماما» أو «بابا» هو أجمل هدية. اقرئي النصائح في المدوّنات لدعم تطور كلماته الأولى.'),
  ('e7879bf6-3dca-4f0b-9981-d7f119d39235', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء القوية والشاشات في المنزل قبل النوم بساعة واحدة. لا يُفرَز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('14e209af-2489-4eb6-a1f0-be21be617768', 'الانتقال إلى النوم بقصة خيالية 🪄', 'أنشئي في القصص الذكية خلفية خاصة تتكوّن فقط من الموسيقى وأصوات الطبيعة. لا كلمات، بل هدوء وترقّب فحسب.'),
  ('a6e2ed87-38de-413e-9884-cda9afcbb191', 'الاستعدادات الأخيرة 📸', 'هل الشموع والكعكة والملابس جاهزة؟ أفرغي مساحة في ذاكرة هاتفكِ، فستحتاجين غدًا إلى مساحة كبيرة خلال جلسة تصوير طفلكِ!'),
  ('c639a352-3f59-4488-9ce0-2ba361a4790c', 'غدًا يتمّ عامه الأول! 🎉', 'يا لها من ذكريات جميلة! هل تتذكرين ذلك اليوم الأول الذي غادرتِ فيه مستشفى الولادة؟ افتحي مفكرة المشاعر واكتبي له الليلة رسالة مؤثرة ليقرأها في المستقبل.'),
  ('0eb89ca2-1605-4f92-8c61-0198a966afb1', 'رقصة الانتصار 💖', 'احتفلي هذا المساء على ضوء الشموع مع شريككِ بتعب عام كامل وبالفخر الذي تشعران به. أنتما فريق رائع!'),
  ('2e46d431-01ee-479e-a146-2b349cd7f234', 'عام كامل! عيد الميلاد الأول! 🎂🎉', 'أنتما مذهلان! 365 يومًا كاملة، وليالٍ بلا نوم، وضحكاته الأولى، وخطواته الأولى! لقد أصبح عمره الآن 1 سنة! افتحي جلسة تصوير طفلكِ وخلّدي هذا اليوم التاريخي بأجمل اللقطات!'),
  ('3c2fa886-d095-424c-ad68-b439a1ffc0b9', 'صفّقي لنفسكِ 👏', 'لقد نما 9 أشهر في رحمكِ وعامًا كاملًا بين ذراعيكِ! اليوم ليس عيد ميلاده وحده، بل هو أيضًا ذكرى ميلادكِ كأم. افتخري بنفسكِ!'),
  ('0944c4dc-3e95-4efb-97dc-8b4809d96d45', 'تبدأ مرحلة الطفولة المبكرة 🌟', 'انتهت مرحلة الرضاعة! لقد أصبح الآن طفلًا يعلن رسميًا عن استقلاليته ويصرّ على فعل كل شيء بنفسه. تبدأ مغامرة جديدة مليئة بالصبر والحب!'),
  ('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2', 'هل تحتاجين إلى الفضفضة؟ 💬', 'هل تخيفكِ تجارب من يقلن إن الأمر يصبح أصعب بعد عمر 1 سنة؟ اكتبي في مجتمع Anacan واقرئي تجارب حقيقية وإيجابية لأمهات أخريات.'),
  ('4c27d203-23f5-4e87-918e-d40df5e30875', 'هدوء الليل 🛀', 'حمّام دافئ، وتدليك، وتعتيم الغرفة. الحفاظ على روتين النوم هو السر الأساسي لليالٍ هادئة بلا انقطاع.'),
  ('6ad316f8-edd9-4dff-aac4-f3492d4a602a', 'ينفّذ التعليمات البسيطة 🧸', 'عندما تقولين له: «أعطني الكرة»، هل يجدها ويحضرها فعلًا؟ قدرته على فهم الكلمات في ذروتها! أشركيه أكثر في الألعاب.'),
  ('028a5b0d-04de-43dc-984d-eaf6e3427904', 'اختيار الحذاء الأول 👟', 'يستعد للمشي، ولكن هل ينبغي أن يرتدي حذاءً في المنزل؟ اسألي Anacan AI عن أحذية الخطوات الأولى وفوائد المشي حافي القدمين.'),
  ('5d68d6d5-05d2-43b4-bd93-e3f95983e445', 'القائمة تنقذ الموقف 🛒', 'تتغير قائمة الطعام بعد عمر 1 سنة. هل تحتاجين إلى حليب البقر أو أطعمة مختلفة في المنزل؟ املئي قائمة التسوق فورًا وأرسليها إلى شريككِ.'),
  ('9a073421-3e36-4699-bbbd-50a69e46f431', 'خصّصي وقتًا لنفسكِ. 🛁', 'ليس من السهل الركض طوال اليوم خلف طفل بدأ يمشي. دوّني شعوركِ بالتعب في مفكرة المزاج لتخففي عن نفسكِ، وخذي قسطًا من الراحة.'),
  ('2cdeb7df-f4f5-4a75-ae9b-552210a168fe', 'يقلّب صفحات الكتب 📖', 'هل يقلّب صفحات الكتب ذات الأوراق السميكة بنفسه تمامًا ويتفاعل مع الصور؟ اقرئي له الكثير من كتب الحكايات الملوّنة.'),
  ('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd', 'أولى خطواته المستقلة! 🧗‍♂', '️ هل يترك الأثاث ويقف بمفرده، وربما يخطو خطوته الأولى المنتظرة؟ لا تفوّتي هذه اللحظة التاريخية التي لا تُنسى، وحمّلي الفيديو فورًا إلى ألبوم الطفل.'),
  ('569602c0-f0cf-4229-b498-984bfdabf097', 'وقت الحكاية الذكية 🪄', 'واصلي الروتين بابتكار قصة في الحكايات الذكية، يكون بطلها الكبير قد أتم عامه الأول وبدأ يستكشف العالم.'),
  ('ae6d1371-ca56-433f-b6db-9c70c59094fb', 'نوبات الغضب تتغيّر 🛑', 'هل بدأت نوبات غضب جديدة، مثل الارتماء على الأرض؟ لا يزال طفلكِ غير قادر على التحكم في مشاعره. انحني إلى مستوى نظره وتحدّثي إليه بهدوء لتساعديه على تجاوزها.'),
  ('6e25898e-24d8-4ca6-8cbe-71a271993d6f', 'التحكم في الأصوات 🤫', 'النصف ساعة الأول بعد خلوده إلى النوم هو الوقت الأكثر حساسية. تحققي من المكان باستخدام مقياس الصوت واحذري الضوضاء المفاجئة.'),
  ('d5e35c42-03ad-4068-b27d-3efca55a35ad', 'الإصرار على الملعقة 🥄', 'يريد طفلكِ أن يمسك الملعقة ويأكل الطعام المهروس بنفسه. سيسكب الطعام وتتسخ ملابسه، لكن ذلك مهم جدًا لتنمية مهاراته الحركية. دعيه يحاول.'),
  ('f93e7290-30ca-44fe-a1e4-55044619c9a6', 'الحاجة إلى الطاقة 🍲', 'ازدادت وتيرة الركض والانشغال. اختاري من الوصفات الصحية وجبة غداء غنية بالحديد والبروتين لتمنحكِ القوة وتجدّدي طاقتكِ.'),
  ('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2', 'نوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ بالكامل. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('50b26349-9946-4708-aec2-e87f1b15952f', 'الخطوات الأولى المستقلة؟ 🧗‍♂️', 'ربما اليوم، وربما غدًا... لقد بدأ طفلكِ يحاول أن يخطو خطوة أو خطوتين من دون الاستناد إلى أي شيء. كوني مستعدة لتسجيل ذلك في متتبّع النمو!'),
  ('9407d96f-ca5a-4378-a7c6-ee00256c457a', 'استطلاع حالة الطقس ⛅', 'عند الخروج في نزهة، لا تتخذي قراركِ بمجرد النظر من النافذة. دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح والملابس المناسبة.'),
  ('beccb06c-7cf4-4f1a-9455-17d5b952ad96', 'أمسيات موسيقية 🎶', 'أسهل طريقة للتعامل مع نوبات التذمر في المساء هي تشغيل أغنيته المفضلة واحتضانه والرقص معه.'),
  ('0c97760a-2746-4ddf-ad12-5f44e1960612', 'الحاجة إلى الهدوء 🤫', 'حافظي على هدوء الغرفة باستخدام مقياس الصوت. فتقطّع النوم ليلًا يفسد مزاجكما في الصباح.'),
  ('61d67656-ab73-4417-b42d-5e55ecf64b87', 'قوة كلمة «لا» 🛑', 'لقد تعلّم أن يهزّ رأسه ويقول «لا» عندما تعرضين عليه شيئًا! هذا ليس عنادًا، بل طريقة للتعبير عن رأيه. ساعديه على الهدوء بمنحه بعض الخيارات.'),
  ('b58ae5cb-ec5b-400f-b490-16ff65c6cead', 'ألعاب المنطق 🧩', 'هل يضع الألعاب في الصندوق ثم يفرغها كلها؟ إنه يطوّر فهمه لمفهومي الداخل والخارج. لا تمنعيه من هذا النشاط.'),
  ('6b997061-a83d-4040-b848-d55a40a87a1a', 'أم بصحة جيدة 🥑', 'إذا شبع طفلكِ، فقد حان دوركِ. اختاري وجبة خفيفة تمنحكِ الطاقة من الوصفات الصحية، واستلقي على الأريكة لمدة 10 دقائق على الأقل.'),
  ('8d89c421-922f-4b8a-bc83-525a380ead88', 'الاهتمام بالسلالم 🧗‍♂️', 'هل لم يعد المشي على الأرض كافيًا له، وأصبح يحاول صعود السلالم والتسلق فوق الأثاث؟ إنه تطور حركي لا يعرف الكلل! احرصي على مراقبته دائمًا.'),
  ('dacf6637-c6dd-4427-9e89-1dc06f453ae5', 'ساعة الحكايات السحرية 🪄', 'أضفي لمسة مميزة إلى الروتين المسائي مع حكاية «أسرار نوم أصغر بطل» ضمن الحكايات الذكية.'),
  ('2d2e06b1-2d94-4883-a675-93637a17ca98', 'ذروة التذمر ☁️', 'هل لا يرضيه شيء ويبكي بسبب كل شيء؟ ربما بدأت أضراسه الخلفية بالظهور. حضّري له عضّاضات باردة.'),
  ('2eeb1f61-7042-48aa-9ecc-41443c68b4a8', 'نوبة الأب الليلية 👨‍🍼', 'عند الاستيقاظ ليلًا، تناوبا على النهوض؛ مرة أنتِ ومرة زوجكِ. أحيانًا لا يهدأ طفلكِ إلا بلمسات أبيه الإيقاعية.'),
  ('d1cf73d9-421b-4ad1-b114-e5025146d5b2', 'من سيقوم بالأعمال المنزلية؟ 🌪️', 'هل تراكمت الأعمال؟ دعيها تتراكم. اطلبي من شريك حياتكِ أن يتولى الأعمال المنزلية اليوم، وخذي أنتِ قسطًا من الراحة.'),
  ('18cb3df2-de24-43c0-a3d0-160051dc5202', 'يوميات المشاعر 📝', 'عندما تشعرين بالوحدة، دوّني مشاعركِ في يوميات المزاج. كل النساء يمررن بهذه التجارب، وأنتِ قوية.'),
  ('19c626ef-26a5-49ef-921f-4577f35ab653', 'هل حان وقت الفطام عن اللهاية/الرضّاعة؟ 🍼', 'هل تفكرين في فطام طفلكِ عن اللهاية بعد عمر 1 سنة؟ اسألي الأمهات في مجتمع Anacan عن ألطف الطرق لتحقيق ذلك.'),
  ('c6a284e9-0bba-433f-9823-bcc74708dbd9', 'الهواء النقي دواء 🌳', 'هل بكى طفلكِ طوال اليوم وكان منزعجًا؟ الحل بسيط جدًا: تحققي من الطقس وملابسه، وضعيه في عربته واخرجي فورًا إلى الحديقة.'),
  ('5f3d97d0-e211-488f-bb05-dd9ccce213a3', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي مع زوجكِ وجهًا لوجه وتحدثا عمّا يثقل قلبيكما. دعمكما لبعضكما يخفف العبء إلى النصف.'),
  ('92cb503c-c013-47cb-ab12-416c047b2693', 'فحص النمو والتطور 🤖', 'هل تحتاجين إلى معلومات عن المهارات الحركية لطفل بعمر 12 شهرًا؟ اطلبي من ذكاء Anacan الاصطناعي قائمة مختصرة ودقيقة ومعتمدة من أطباء الأطفال.'),
  ('f20aef27-fde2-489c-9dd8-fe28386cf1db', 'الأشكال الهندسية وألعاب الذكاء! 🧩', 'يحاول طفلكِ إدخال الدائرة أو المربع في الفتحات المطابقة. خلّدي هذه الاكتشافات التعليمية في ألبوم طفلكِ.'),
  ('0955065c-ecf1-48ed-9f6f-735958386a41', 'فيتامينات للأم 🥑', 'تفعلين كل ما بوسعكِ لإشباع طفلكِ. وماذا عنكِ؟ اختاري من قسم الوصفات الصحية وجبة غداء خفيفة غنية بالحديد والكالسيوم.'),
  ('1d781ae8-7800-48ae-b0ee-fe44c7f13291', 'هل تتغير القيلولة؟ 🥱', 'هل يرفض طفلكِ تمامًا إحدى قيلولتي النهار؟ يبدأ الانتقال إلى قيلولة واحدة بعد عمر سنة. أعيدي تنظيم روتينه تدريجيًا.'),
  ('61536a43-b97b-4fe8-8f6a-f358141baefc', 'ينام على وقع الحكايات 🪄', 'ابتكري في قسم الحكايات الذكية قصة عن حيوانات شجاعة ومحبوبة، وحوّلي الغرفة إلى مكان ساحر.'),
  ('76e3844a-efe7-4daa-855a-4cfd4d92bfc9', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل النوم بساعة. لا يُفرَز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('8b586560-e2d2-46b0-ba82-419bb7b56682', 'ضباب الذاكرة 🛒', 'أما زال النسيان يلازمكِ؟ لا تشغلي بالكِ بمشتريات المنزل الصغيرة؛ أضيفيها فورًا إلى قائمة التسوق ودعي شريككِ يتولى الأمر.'),
  ('b87394f8-5f2b-4eb7-a491-26b80560c8a3', 'رميات هادفة ⚾', 'يحاول طفلكِ عمدًا رمي اللعبة التي في يده نحو هدف محدد. يتطور التناسق بين عينيه ويديه بسرعة. تبادلا رمي الكرة والتقاطها معًا.'),
  ('159279c3-df89-49cf-a71c-bb577a8dd0c3', 'الوصول إلى مناطق خطرة ⚡', 'ازداد طول طفلكِ وأصبح قادرًا على بلوغ الرفوف التي لم يكن يصل إليها من قبل. أعيدي تقييم سلامة المنزل على الفور.'),
  ('3b6ac273-a759-45de-9492-87af2df8cac9', 'سكون الليل 🤫', 'إذا كانت أصوات السيارات أو الضوضاء الخارجية تزعجه، فتحققي من البيئة باستخدام مقياس الصوت، وأبقي ضوضاء بيضاء في الخلفية.'),
  ('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d', 'هل تحتاجين إلى لعبة جديدة؟ 🛒', 'إذا كنتِ تبحثين عن ألعاب تعليمية تناسب نمو طفلكِ وتنمّي ذكاءه، فألقي نظرة على قائمة المنتجات الموصى بها.'),
  ('10934358-ef97-4dab-87ad-73a62aee1231', 'التنظيف أم الراحة؟ 🛋️', 'عندما ينام طفلكِ، لا تسرعي إلى غسالة الصحون. تمدّدي على الأريكة، وأغمضي عينيكِ، واكتفي بالتنفس لمدة 15 دقيقة.'),
  ('58866969-75c5-44cd-a308-210945d7a2af', 'المحاولة والخطأ 🧱', 'يحاول طفلكِ وضع مكعبين أحدهما فوق الآخر، لكنهما يسقطان. ثم يعيد المحاولة بتركيز. راقبي محاولاته الهندسية في هدوء.'),
  ('94a9a306-04fb-42bb-9962-95b473b02f89', 'مذكّرة المشاعر 📝', 'عندما تشعرين بالوحدة، دوّني مشاعركِ في مذكّرة الحالة المزاجية. تمرّ جميع النساء بهذه التجارب، وأنتِ قوية.'),
  ('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5', 'لقصة المساء سحر خاص. 📖', 'قراءة قصة قصيرة قبل النوم تنمّي خيال طفلكِ وتقوّي الرابطة العاطفية بينكما.'),
  ('b28c4699-a204-48ae-80c2-bef5008fdffd', 'مهارة اللعب بشكل مستقل. 🧩', 'قدرة طفلكِ على اللعب بمفرده، ولو لفترة قصيرة، تدل على تطور قدرته على التركيز. في هذه اللحظات، راقبيه من بعيد بمحبة.'),
  ('e6b48652-88e0-49d8-b2cc-654a9f8eb626', 'نتابع نمو طفلكِ. 📏', 'هل بدأت ملابس طفلكِ تضيق عليه؟ أضيفي قياساته الجديدة إلى قسم متابعة الوزن وسجّلي نموه الصحي.'),
  ('05e8d5ea-453b-4a35-a697-81e0b9ca911a', 'تقليد الكبار 🧹', 'هل يمسك طفلكِ بقطعة قماش ويحاول تقليدكِ أثناء تنظيف المنزل؟ إنه مرآتكِ! فهو يقلّد كل ما تفعلينه.'),
  ('56403a92-c6d5-492f-b073-20bcd436f218', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ بالكامل. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('763e2885-6f82-4d6b-8ec4-680155ad7a5f', 'فضفضة الأمهات 💬', 'ألا تستطيعين التعامل مع نوبات الغضب؟ انضمّي فورًا إلى مجتمع Anacan، واقرئي تعليقات الأمهات الداعمة لتشعري بالارتياح.'),
  ('f47e2fcf-5030-43a8-a77b-79834cb3f95a', 'مشاعر كبيرة في جسد صغير 🛑', 'هل يرمي طفلكِ نفسه على الأرض عندما لا يحصل على ما يريد؟ انحني إلى مستواه وتحدّثي معه بهدوء لتتجاوزا نوبات الغضب.'),
  ('a0e7f0f6-1438-4f75-acb4-559e4df47974', 'الحاجة إلى الهدوء 🤫', 'حافظي على هدوء الغرفة باستخدام مقياس الصوت. فتقطّع النوم ليلًا يفسد مزاجكما معًا في الصباح.'),
  ('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95', 'مساحة خاصة للأم ☕', 'لقد استنزف البقاء في المنزل طاقتكِ. اختاري مقهًى يمكنكِ الجلوس فيه براحة من بين الأماكن الصديقة للأمهات، وخصّصي بعض الوقت لنفسكِ.'),
  ('f34137b7-333a-47bb-8fab-66dd8be52bfb', 'الرقص والإيقاعات 🎶', 'هل يبدأ طفلكِ بالرقص بمجرد سماع إيقاع من التلفاز أو الهاتف؟ لقد بدأ إدراكه الموسيقي يعمل بكامل طاقته، فانضمّي إليه وارقصا معًا!'),
  ('9dd82a43-7f3a-4a5e-9d01-a99d7d738015', 'محاولات ارتداء الملابس باستقلالية 👕', 'هل بدأ طفلكِ يحاول خلع جوربه أو ارتداءه بنفسه؟ ادعمي بصبر تطوّر هذه المهارات الحركية الدقيقة.'),
  ('ccf44d60-2dc0-447f-b1ea-dd06a80f0324', 'شرب الماء مهم جدًا 💧', 'يشعر الأطفال النشطون بالعطش سريعًا. لا تنسي أن تقدّمي لطفلكِ الماء خلال اليوم، ولا سيما بعد وجبة العشاء.'),
  ('b55b3812-173b-489f-a2ae-d2c78611fd35', 'مصادقة الظلام 🌙', 'لتساعدي طفلكِ على النوم بسرعة أكبر، أضيفي التعرّف إلى الظلام ضمن روتينه المسائي. أطفئي جميع الأضواء الإضافية في الغرفة.'),
  ('c9fb44a1-ad82-4f16-a316-50d99863130e', 'شكوك حول الحساسية 🤖', 'هل بدأتِ تقديم أطعمة جديدة بعد عمر سنة؟ إذا كانت لديكِ أي مخاوف، فتعرّفي فورًا إلى الخطوات الأولى من Anacan AI.'),
  ('0c105765-0e1a-42dd-bd14-0ca4153705c0', 'تتطور المهارات الحركية الدقيقة. 🖍', '️ قد يستمتع طفلكِ بالخربشة بالقلم على الورق. قدّمي له أقلام تلوين سميكة مناسبة وراقبي إبداعه.'),
  ('1b77ed52-4cf2-48a6-98fc-53d0a94dc968', 'روتين النوم يمنح الأمان. 🌙', 'سيساعده اتباع الخطوات نفسها وبالترتيب نفسه كل مساء (الاستحمام، قراءة قصة، تخفيف الإضاءة) على النوم براحة أكبر.'),
  ('795996e4-e3e1-4fa7-b442-27c8ffa35bff', 'آلام التسنين 🦷', 'هل احمرّت لثته مجددًا ولا يتوقف سيلان لعابه؟ سجّلي مراحل العملية في متتبّع التسنين وجهّزي له عضّاضات باردة.'),
  ('452e9fa3-8dba-4774-8bfe-d6afa50d161c', 'القائمة تنقذ الموقف 🛒', 'هل نفدت الفاكهة أو الشوفان المخصّص للوجبات؟ املئي قائمة التسوق فورًا وأرسلي الطلبات إلى هاتف شريككِ.'),
  ('8c12c251-a9b5-45cb-92ff-f145e2484025', 'يمشي مستندًا إلى الجدار 🧗‍♀️', 'المشي بخطوات جانبية مستندًا إلى حواف الأثاث هو تمرينه المفضّل. لم يتبقَّ سوى القليل على خطواته المستقلة! اطّلعي على متتبّع التطور.'),
  ('c7e52a2b-46d5-4446-b455-907f7523256e', 'التحكم في الأصوات 🤫', 'النصف ساعة الأولى بعد نومه هي الفترة الأكثر حساسية. تحققي من البيئة باستخدام مقياس الصوت واحذري من الضوضاء المفاجئة.'),
  ('bc24cbab-3bcd-4b5b-92fb-249b861079c2', 'ينثر كل ما يلعب به في كل مكان. 🌪️', 'راحتكِ أهم من التنظيف. ستظل الألعاب موجودة غدًا، لكن طفلكِ يحتاج الآن إلى أم مفعمة بالنشاط.'),
  ('0693172d-9675-431e-ae2b-b1d735f8da0f', 'ضعي كل التعب جانبًا.', 'لا تنسي هذا المساء، بعد أن ينام طفلكِ، أن تحتفلي مع شريككِ بانتصاركما كفريق!'),
  ('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125', 'لا تقارني نفسكِ بالآخرين 🛑', 'انسي عبارة: طفل فلانة بدأ الكلام مبكرًا. لكل طفل وتيرته الفريدة في النمو. ما عليكِ سوى أن تمنحيه الحب.'),
  ('b9520b22-b9b3-4ca3-a219-de05702404a8', 'نحو عمر عام ونصف! 📸', 'لقد أصبح عمره 12.5 شهرًا! ابدئي جلسة تصوير لطفلكِ، ووثّقي بالصور أطرف لحظات هذه المرحلة الحافلة بالحركة والمغامرات.'),
  ('078c86a9-a3c8-4f20-a27a-3aa00d3961ad', 'لنجعل وقت الطعام ممتعًا! 🥦', 'إذا كنتِ تواجهين ضعف شهية طفلكِ، فحضّري له أطباقًا ملوّنة وجذابة من قسم وصفات الرضّع الذين بدأوا بتناول الأطعمة التكميلية.'),
  ('3b7df91a-7022-4a50-9438-82f89b2240b8', 'يتعرّف إلى أعضاء جسمه 👀', 'عندما تسألينه: أين عينك؟ هل يلمسها بإصبعه ويشير إليها؟ قدرته على الاستيعاب الذهني في أوجها! سجّلي هذا الإنجاز بفخر في متتبّع النمو.'),
  ('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56', 'أنتِ تبذلين قصارى جهدكِ! 💖', 'تربية طفل أشبه بسباق ماراثون. خصّصي لنفسكِ بعض الوقت هذا المساء، وشاهدي فيلمًا تحبّينه أو استريحي فحسب.'),
  ('18eaf932-80c3-47ae-a394-f6ce083ef215', 'إصراره على أن يأكل بنفسه 🥦', 'يريد أن يأخذ الملعقة من يدكِ. دعيه يأخذها. ستتّسخ ملابسه، لكن شعوره بالاستقلالية مهم جدًا له.'),
  ('04429520-36d1-489e-8ec7-309a2c08ae92', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتبادلا الحديث عمّا يثقل كاهلكما. فدعم أحدكما للآخر يخفف العبء إلى النصف.'),
  ('05fff0e7-029c-401c-bfab-497bbc099997', 'يفهم معاني الكلمات 🗣️', 'عندما تطلبين منه إحضار الكرة، يذهب فعلًا للبحث عنها. حصيلته اللغوية تنمو بسرعة. تحدثي معه بجمل أكثر تعقيدًا.'),
  ('ec4b2f26-3631-4fed-9578-c9539a35a5c0', 'قائمتكِ في جيبكِ 🛒', 'وسط فوضى الحياة اليومية، هل نفد الشامبو أم الحفاضات؟ لا تعتمدي على ذاكرتكِ، بل دوّنيها في قائمة التسوق وزامنيها مع شريككِ.'),
  ('663824a2-b8fe-471a-b981-3eb69f3a2c7f', 'مشاعر كبيرة في جسد صغير. 🌪', '️ من الطبيعي أن يغضب ويبكي عندما يعجز عن التعبير عن نفسه. انحني إلى مستواه وأخبريه بصوت هادئ أنكِ تتفهمين مشاعره.'),
  ('8be96289-58a8-4a48-89ec-c4ba0488e973', 'اللعب بالماء يمنحه الهدوء. 💧', 'املئي حوضًا صغيرًا بالماء وضعي فيه أوعية بلاستيكية. يساعد اللعب بالماء الأطفال على تفريغ طاقتهم والاسترخاء.'),
  ('a70fb0ff-98b0-4735-ac10-846168dd5d60', 'هل لديكِ سؤال؟ 🤖', 'اطرحي أسئلتكِ المهمة، مثل: كيف أتعامل مع أزمة عمر السنة؟ على مساعد Anacan AI حتى في ساعات الليل، واحصلي على نصائح الخبراء.'),
  ('12139491-dd07-42f8-b056-98645d9880be', 'لقطة توقف الزمن 📸', 'إنه يكبر قليلًا كل يوم. افتحي جلسة تصوير الطفل الآن وخلّدي هذه اللحظة العفوية في ذاكرتكِ.'),
  ('302d3885-ce15-4277-a0cf-d95f95d7ed63', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء القوية والشاشات في المنزل قبل النوم بساعة واحدة. لا يُفرَز الميلاتونين إلا في بيئة هادئة.'),
  ('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0', 'الحديقة أم المنزل؟ ⛅', 'تريدين الخروج، لكن الجو عاصف. دعي مساعد الطقس والملابس يقترح عليكِ فورًا الإطلالة المناسبة.'),
  ('ecb2b9d1-a640-4303-b570-f3c7f463e0ab', 'ليالٍ صعبة 🥱', 'هل يقاوم النوم بكل قوته؟ راجعي مواعيد قيلولاته النهارية وروتين نومه.'),
  ('8a5f3751-2bcd-4454-bfef-74c90f1c3f85', 'نهاية اليوم، حان وقتكِ. 🛁', 'هل تعبتِ كثيرًا اليوم؟ خذي حمامًا دافئًا، واسترخي، واشكري نفسكِ على كل ما فعلتِه.'),
  ('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8', 'نتعلّم أعضاء الجسم! 👃', 'عندما تسألينه: أين أنفك؟ هل يشير إليه بإصبعه الصغير؟ استمتعي معه وحوّلي هذه الاكتشافات اللطيفة إلى لعبة أمام المرآة.'),
  ('e70adad3-3a0b-4d15-ab3c-9f286916a872', 'حان وقت وجبة خفيفة صحية. 🍎', 'تُعد شرائح الفاكهة أو أصابع الخضراوات خيارًا رائعًا للأطفال المفعمين بالطاقة. أتيحي له فرصة إمساكها وتناولها بنفسه.'),
  ('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3', 'الفنان الصغير منهمك في عمله! 🖍', '️ أعطيه أقلام تلوين سميكة ودعيه يخربش بحرية على الورقة. فهذا مفيد جدًا لتنمية المهارات الحركية الدقيقة والإبداع.'),
  ('ccb3a3d0-8dc5-450a-b184-37cf81a39c01', 'الهواء النقي مفيد لكليكما. 🌳', 'اكتشفي حديقة جديدة مناسبة للتنزه بعربة طفلكِ عبر خريطة الأماكن الصديقة للأمهات لدينا، واخرجا في نزهة.'),
  ('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5', 'روتين النوم يمنح طفلكِ شعورًا بالأمان. 🌙', 'إن تكرار الخطوات نفسها بالترتيب ذاته كل مساء (الاستحمام، قراءة قصة، تخفيف الإضاءة) سيساعده على النوم بسرعة أكبر.'),
  ('78f8f713-17f3-46f4-83f8-9cdbfd0c9894', 'وقت اللعب المستقل 🧸', 'أصبح طفلكِ قادرًا على تسلية نفسه بألعابه لمدة 10-15 دقيقة. راقبيه من بعيد واستمتعي بالهدوء.'),
  ('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd', 'استكشاف الطقس ⛅', 'هل الطقس في الخارج غير مستقر؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح والملابس المناسبة.'),
  ('bac8ff9b-6338-4b34-a5d6-84b7aefd251c', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحملي الاستيقاظ ليلًا بمفردكِ. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('c1daed2c-e22f-4c5a-8534-4ff90b6b866e', 'أجد لعبتي بنفسي 🧸', 'هل يذهب طفلكِ للعثور على اللعبة التي أبعدتِها عن ناظريه وأخفيتِها خلف شيء ما؟ هذا يعني أنه بدأ يدرك مفهوم بقاء الأشياء!'),
  ('2a991705-4255-4931-9ad5-cef8eb9bf0dd', 'مساعدكِ الصغير! 🧹', 'هل يقلّدكِ فيمسك منشفة ويحاول مسح الغبار؟ احرصي على إضافة مقطع فيديو لهذه اللحظات اللطيفة والتعليمية إلى ألبوم طفلكِ لتبقى ذكرى للمستقبل.'),
  ('813ebcca-fa4c-42de-926c-6ca1c1526de6', 'الهدوء مع الموسيقى. 🎶', 'في المساء، استمعي معه إلى موسيقى أكثر هدوءًا بدلًا من الألعاب الحركية، لتهيئيه للنوم وتهيئي نفسكِ للاسترخاء.'),
  ('ce071e13-068a-4c5a-8d4c-437e6f25658d', 'الانتقائية في الطعام. 🍲', 'إذا رفض طفلكِ أطعمة معينة، فلا تقلقي. قدّميها له مجددًا في أيام مختلفة وبأشكال متنوعة (مثل تقديمها كطعام يؤكل باليد بدلًا من هرسها).'),
  ('502b8118-151f-47c7-9476-eb53fa55cfd0', 'الأبراج ترتفع! 🧱', 'أصبح طفلكِ قادرًا على تكديس 3-4 مكعبات فوق بعضها. شجّعيه بالتصفيق لهذه اللعبة التي تتطلب التركيز والتنسيق بين العين واليد.'),
  ('af470a51-532a-4658-877a-26e61845210a', 'حان وقت التواصل الاجتماعي. 👶', 'هل يراقب الأطفال الآخرين في الحديقة باهتمام؟ حتى لو لم يلعبوا معًا بعد، فإن مرحلة اللعب جنبًا إلى جنب (اللعب المتوازي) هي أول خطوة كبيرة نحو التواصل الاجتماعي.'),
  ('ceb1c77d-c486-4755-b204-47ec200fcd34', 'يفهم نبرة صوتكِ 🗣️', 'هل يتوقف وينظر إليكِ عندما تقولين «لا» بنبرة حازمة؟ لقد بدأ بالفعل في فهم المشاعر والمحظورات!'),
  ('53cb1b60-78f0-41c1-a42e-b48a4324533b', 'حماس اليوم 400! 🌟', 'غدًا هو اليوم الكبير، اليوم 400! أي أكثر من عام وشهر! أضفي أجواء احتفالية بسيطة في المنزل، وأفرغي بعض المساحة في ذاكرة هاتفكِ.'),
  ('9e145532-f5a6-48ed-a07c-a3e9fc574858', 'حان وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، خصّصي مع شريككِ جلسة لتدليك الكتفين والتخلص من توتر اليوم. أنتما فريق واحد!'),
  ('fab52013-4ea8-458f-b397-01341fb91dad', 'أمسية للتسامح مع الذات 📝', 'هل شعرتِ اليوم بالانزعاج من كل شيء؟ عندما ينام طفلكِ، دوّني مشاعركِ في يوميات المزاج. غدًا يوم جديد وأجمل.'),
  ('165064a6-acf5-4848-b342-4a3782635921', '400 يوم رائع! 🎉', 'تهانينا! لقد قطعتما معًا هذا الطريق الحافل بالتحديات طوال 400 يوم بالضبط! احتفلي بهذه المناسبة المميزة الآن!'),
  ('894151c3-97b8-419f-9602-aa08da619716', 'دعيه يواصل تناول الطعام بنفسه. 🥄', 'حتى لو اتّسخت ملابسه وجسمه، دعيه يحاول تناول الطعام بملعقته بنفسه. فهذا يعزز ثقته بنفسه وينمّي التناسق العضلي لديه.'),
  ('8c8e0b49-c38c-485a-b336-5facb1258a02', 'أنتِ الأفضل! ✨', 'تفانيكِ على مدار 400 يوم لا يُقدّر بثمن. الآن خذي نفسًا عميقًا، واتكئي إلى الخلف واستريحي بهدوء.'),
  ('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c', 'اكتشفي مكانًا مناسبًا للأمهات ☕', 'لقد أرهقكِ البقاء بين جدران المنزل نفسها. اكتشفي من بين الأماكن الملائمة للأمهات مقهى يضم ركنًا لألعاب الأطفال. دعي طفلكِ يلعب واستمتعي بقهوتكِ.'),
  ('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b', 'اقرآ كتابًا معًا. 📖', 'أصبح طفلكِ الآن يرغب في تقليب الصفحات بنفسه. تُعدّ الكتب ذات الصفحات السميكة والقصص الصوتية مثالية لهذه المرحلة.'),
  ('d29d33a4-aed4-4635-9f37-3a7a39a378b0', 'يختبر الحدود. 🛑', 'هل ينظر طفلكِ في عينيكِ ويمد يده نحو ذلك الغرض مجددًا رغم أنكِ قلتِ له «لا»؟ هذا ليس عنادًا، بل مجرد اختبار يتعلم من خلاله الحدود. تحلّي بالصبر والثبات.'),
  ('f3355fe9-0c3b-41e2-9043-0a5cb8a61740', 'الاستيقاظ ليلًا. 😴', 'قد يؤدي التسنين أو طفرة النمو إلى اضطراب النوم. عند الحاجة، تابعي مؤقت النوم وسجّلي التغييرات التي تطرأ على الروتين.'),
  ('2e0b0129-5a3d-466c-a35f-ef4707dea065', 'حنان الأب المطمئن 🫂', 'احرصا على التناوب عند استيقاظ طفلكِ ليلًا. ففي بعض الأحيان، لا يهدئه في الظلام فورًا سوى ربتات أبيه المنتظمة ورائحته المألوفة.'),
  ('812159bf-a0a9-4bf9-8e7b-97d82abbaa80', 'مرآة تقلّد الكبار 🧹', 'حين تنظفين المنزل، يأخذ طفلكِ قطعة قماش ويحاول تقليدكِ. إنه نسختكِ الصغيرة! أعطيه غرضًا آمنًا وأشركيه في الأعمال المنزلية.'),
  ('9510e83b-c10c-4166-b921-d1cd3c8f203c', 'التغلب على النسيان 🛒', 'هل خانتكِ ذاكرتكِ مجددًا؟ أضيفي فورًا كل ما ينفد في المنزل، مهما كان بسيطًا، إلى قائمة التسوق ليشتريه شريككِ عند عودته من العمل.'),
  ('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c', 'ألعاب المنطق 🧩', 'هل يضع طفلكِ الألعاب داخل الصندوق ثم يفرغها كلها؟ هكذا يتعلم مفهومَي الداخل والخارج. راقبي محاولاته المتكررة بهدوء.'),
  ('05dbf09b-2a49-4886-a4e4-6f85e7cbea42', 'خارج الجدران الأربعة ⛅', 'ألا يستطيع طفلكِ تفريغ طاقته في المنزل فيصبح متذمرًا؟ الطبيعة أفضل مهدّئ. تحققي من الطقس والملابس، واختاري الزي المناسب ثم توجهي فورًا إلى الحديقة.'),
  ('3cf4affc-53f5-4c77-84f1-006d5732e36a', 'وقت اللعب مع الأب 👨‍👧', 'لقد أنهككِ الركض خلفه طوال اليوم. حان الآن وقت وضع الشريك. دعي الأب يتولى ألعاب التدحرج على الأرض والتظاهر بأنه حصان. استريحي أنتِ.'),
  ('f1269e86-21d6-4d2f-83e1-31926957408a', 'ماراثون بين الغرف 🏃‍♂️', 'لم يعد المشي كافيًا له، فقد بدأ يركض من غرفة إلى أخرى! يتطور توازنه أثناء الوقوف بشكل كامل. سجّلي هذا الإنجاز الكبير في مهاراته الحركية الكبرى ضمن متتبّع التطور.'),
  ('7df527b0-7bf7-42d6-b9f4-0f231186e70c', 'ديكتاتور قائمة الطعام 🥣', 'هل يبعد اليوم طعامًا كان يحبه بالأمس؟ الانتقائية في الطعام أمر طبيعي بعد عمر سنة. لا تقلقي، وابحثي عن بدائل متنوعة ضمن الوصفات الصحية.'),
  ('85bb394b-b9a2-4a30-a34a-98479663ff2d', 'مرحلة «ما هذا؟» ☝️', 'يشير إلى كل شيء بإصبعه ويصدر صوتًا خاصًا. إنه يريد منكِ أن تعرّفيه إلى أسماء الأشياء من حوله. أخبريه بصبر باسم كل شيء يشير إليه.'),
  ('f78a5d11-ba9f-41e9-8557-2840d12964be', 'تخلّصي من الشعور بالذنب 📝', 'لم أقرأ له ما يكفي اليوم، وشاهد الشاشة طويلًا... أسكتي هذه الأصوات! أنتِ تبذلين قصارى جهدكِ. اكتبي في يوميات مزاجكِ ملاحظة لطيفة ومتعاطفة مع نفسكِ.'),
  ('1167974e-3206-4f0f-b4e8-4d14f35444b6', 'الانتقال إلى قيلولة واحدة 🥱', 'لا يريد أخذ قيلولته الصباحية واختلّ الجدول بأكمله؟ إنه يكبر! قد تكون هذه مرحلة الانتقال من قيلولتين نهاريتين إلى قيلولة واحدة. أعيدي ضبط الروتين تدريجيًا.'),
  ('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2', 'الغرفة السحرية 🪄', 'أنشئي في القصص الذكية حكاية خاصة عن بطل شجاع يستكشف العالم. اجعلي الانتقال إلى وقت النوم أسهل بهذه الحكاية الجميلة.'),
  ('5d99a4ad-d33f-448d-9f7c-32943cbfa648', 'هل الأضراس في طريقها للظهور؟ 🦷', 'هل لثته متورمة ويقضم كل شيء؟ ربما بدأت أضراسه الخلفية بالظهور. ضعي عضّاضات التسنين الباردة في المجمّد.'),
  ('70d7d4ed-5c06-44bc-99e5-3871d07a9510', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل موعد النوم بساعة. لا يُفرَز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('aa9c9479-f8d5-4149-b7c4-99976958a17c', 'الوصول إلى مناطق خطرة ⚡', 'ازداد طوله وأصبح يصل إلى الرفوف التي لم يكن يستطيع بلوغها من قبل. حامل التلفاز، الزوايا... أعيدي تقييم سلامة المنزل بشكل عاجل.'),
  ('0872925d-e2d7-471e-ba13-22ee468f0a1f', 'استيقاظ مفاجئ 😭', 'هل يستيقظ في منتصف الليل صارخًا ولا يهدأ؟ شغّلي صوته في ميزة تحليل البكاء لمعرفة سبب المشكلة.'),
  ('1fe0720b-91d5-4dc9-ad61-71e5ff522246', 'وتيرة النمو. 📏', 'يمكنكِ ملاحظة نموه السريع حتى من خلال ملابسه. سجّلي وزنه وطوله في أداة التتبّع للاطمئنان إلى نموه الصحي.'),
  ('ca5a420a-5b8f-49ce-b884-6a219b8b71aa', 'مشاعر كبيرة في جسد صغير 🛑', 'هل يرمي نفسه على الأرض عندما لا يحصل على ما يريد؟ إنها نوبات الغضب الشهيرة في مرحلة الطفولة المبكرة. حافظي على هدوئكِ، وتواصلي معه بصريًا، وأشعريه بأنكِ إلى جانبه.'),
  ('005096a2-1549-4208-a331-7e39e1da9587', 'طبيب أطفال سريع 🤖', 'هل تحتاجين إلى معلومات حول طفرات النمو في عمر 13.5 شهرًا؟ لا ترهقي نفسكِ، واطلبي من Anacan AI قائمة دقيقة ومعتمدة من أطباء الأطفال.'),
  ('7de487db-11d1-4c22-8b8d-e58adb31344a', 'ينفّذ التعليمات البسيطة 🧸', 'عندما تطلبين منه إحضار الحذاء، هل يذهب فعلًا ويحضرُه؟ حصيلته اللغوية وقدرته على الفهم في ذروتهما! أشركيه أكثر في الألعاب.'),
  ('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec', 'حركات الأب المضحكة 🤡', 'أفضل طريقة لإضحاك طفلكِ هي أن يُصدر الأب أصواتًا غريبة. استمتعي هذا المساء باللحظات المرحة مع طفلكِ.'),
  ('3170ad10-66c6-4ca0-bf72-80b0daf91373', 'الروتين المسائي يهيئه للنوم. 🌙', 'تساعده العادات البسيطة التي تتكرر يوميًا في الوقت نفسه (تنظيف الأسنان، قراءة قصة) على الانتقال إلى النوم بسهولة أكبر.'),
  ('64832db8-28ac-41fb-8d33-21a72b48fa8c', 'مستكشف فضولي! 🔍', 'كل زاوية وكل خزانة في المنزل هي عالم جديد بالنسبة إليه. وفّري له بيئة آمنة ودعيه يستكشف المنزل بحرية.'),
  ('f283f219-7efa-4926-a360-3fb653057b9b', 'هواء نقي وطاقة وفيرة! 🌳', 'يساعد تفريغ الأطفال لطاقتهم في الخارج على الخلود إلى القيلولة بسهولة أكبر. اذهبا معًا إلى الحديقة.'),
  ('35a5e175-d9f9-4d9a-9445-a523d64bc595', 'يريد أن يأكل بنفسه. 🥦', 'حتى لو اتسخت ملابسه، دعيه يمسك الملعقة بنفسه. فهذا سينمّي لديه الشعور بالاستقلالية والتنسيق بين العين واليد.'),
  ('66beeaaa-0b78-4114-b41f-8d7e6f407c55', 'من حقكِ أن ترتاحي. 🛁', 'لقد قضيتِ اليوم كله واقفة على قدميكِ. بعد أن ينام طفلكِ، حضّري كوبًا من الشاي الساخن واستمتعي بالهدوء فحسب.'),
  ('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6', 'خطوات سريعة! 🏃‍♂', '️ أصبح الآن يتنقل بحرية بين الغرف، بل ويحاول الركض أيضًا. اللحاق به تمرين رياضي حقيقي للأمهات!'),
  ('1008f62b-ef11-490d-886c-a80a06e64454', 'أين عينك؟ 👀', 'لا تزال لعبة التعرّف إلى أجزاء الجسم من ألعابه المفضلة. اجعليها أكثر متعة باللعب أمام المرآة.'),
  ('302bafdb-c5ca-4389-a56e-16a2ddd6812b', 'قوة الروتين المسائي 🛀', 'الحمّام الدافئ مفيد دائمًا. لا تغيّري الروتين المسائي أبدًا، لأنه يرسل إلى دماغ طفلكِ إشارة واضحة بأن وقت النوم قد حان.'),
  ('309b39de-d5f5-4702-93e1-596dca9c9021', 'استعيدي طاقتكِ 🥑', 'بعد أن شبع طفلكِ، حان دوركِ. لا تتناولي غداءكِ على عجل وسط انشغالاتكِ اليومية. اختاري وجبة خفيفة تمنحكِ الطاقة من بين الوصفات الصحية، واسترخي على الأريكة.'),
  ('66b4bd9b-8226-4190-94c7-9d50f8db6c34', 'تحتاجين إلى الفضفضة 💬', 'هل تستنزفكِ فكرة: لماذا يتصرف طفلي هكذا؟ انضمي إلى مجتمع Anacan، واقرئي تجارب مماثلة لأمهات أخريات لتشعري بالطمأنينة.'),
  ('80e6be85-6917-46a0-b283-acc653cca6c1', 'ذكاء بين صفحات الكتب 📖', 'هل يقلّب طفلكِ صفحات الكتب ذات الصفحات السميكة ويتفاعل مع الصور؟ إن ذاكرته البصرية تتطور. اقرئي له الكثير من كتب الحكايات الملوّنة.'),
  ('df1f7c26-41ff-4081-9b25-dae8d38c75e8', 'الوقت جميل معكِ. ✨', 'كل يوم معه مغامرة مختلفة. حين ينام، انظري إلى يديه الصغيرتين وابتسمي فرحًا بإنجازاته الصغيرة اليوم.'),
  ('52e92eba-b885-4c30-891d-aa6e5379acf9', 'الإصرار على تناول الطعام باستقلالية 🥄', 'يأخذ الملعقة من يدكِ ويريد أن يأكل بنفسه. سيتناثر الطعام وسيتّسخ، لكن ذلك مهم لتطوير مهاراته الحركية. اسمحي له بالاستقلالية.'),
  ('a26c1e0d-7872-4f7e-9268-2fba22c9203a', 'هل لديكِ سؤال؟ 🤖', 'إذا كانت لديكِ أسئلة تشغلكِ حول سلوك طفلكِ في عمر 13-14 شهرًا أو تطوره، يمكنكِ الحصول فورًا على نصيحة من مساعدنا Anacan AI.'),
  ('eb8ab523-6225-489f-8a09-0f37ba40956a', 'تفريغ الطاقة! 🏃‍♂', '️ قبل موعد قيلولته، ساعديه على النوم براحة من خلال ممارسة ألعاب حركية تتعبه قليلًا، مثل المطاردة ورمي الكرة.'),
  ('2ca5e024-95be-449a-af7e-ee34228f8bca', 'التخطيط يمنحكِ الراحة. 📝', 'حضّري في ذهنكِ، من خلال ملاحظات صغيرة، ما ستفعلينه غدًا أو خطة الوجبات، ثم اخلدي إلى النوم وأنتِ مطمئنة.'),
  ('efb1280f-e8f0-4ecf-bb77-385f667aff5d', 'بحثًا عن الراحة. ☕', 'قد ترغبين أحيانًا في الخروج من المنزل وتغيير الأجواء. ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى قريب يمكنكِ الذهاب إليه بسهولة مع طفلكِ، واستمتعي بقهوتكِ.'),
  ('aa01a859-3ad0-4c64-9ef3-4423ccf76d24', 'هل يحب قول «لا»؟ 🛑', 'قد يقلّد اعتراضاتكِ ويقول «لا» لكل شيء. من المهم أن تتحلّي بالصبر خلال هذه المرحلة وأن تقدّمي له بدائل بسيطة.'),
  ('b8b7257f-64c5-46a3-b958-ded901da8e8d', 'اجعلي شرب الماء ممتعًا. 💧', 'قدّمي له الماء بانتظام في زجاجة ملوّنة، حتى لا يُصاب جسمه بالجفاف بعد الأنشطة الحركية.'),
  ('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c', 'موعد الحكاية مع الأب. 👨‍🍼', 'أوكلي إلى الأب اليوم مهمة قراءة حكاية المساء ووضع طفلكِ في السرير، وخذي استراحة قصيرة لنفسكِ.'),
  ('4484d3ee-8677-4454-8e65-371ba851a267', 'قوة الضوضاء البيضاء. 🎶', 'إذا لم يستطع النوم بسبب تأثير يوم حافل بالنشاط، فشغّلي صوت المحيط أو المطر من قسم الضوضاء البيضاء لخلق أجواء هادئة في الغرفة.'),
  ('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd', 'أحضان حلوة! 🤗', 'عندما يعانقكِ فجأة ويحاول تقبيلكِ، فهذه طريقته في التعبير عن حبه. استمتعي بلحظات الحب الفريدة هذه!'),
  ('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21', 'أشركيه في الحديث. 🗣', '️ اذكري أسماء الأشياء الموجودة في الغرفة وانتظري منه أن يكرّرها. فبهذه الألعاب الصغيرة تحديدًا تنمو حصيلته اللغوية.'),
  ('f39f5c34-c612-4758-a438-ed52b2d49ba8', 'نلوّح مودّعين 👋', 'عندما يخرج أحدهم من الباب، يلوّح بيده مودّعًا من تلقاء نفسه! إنها استجابة اجتماعية رائعة. شجّعيه كثيرًا.'),
  ('0dcb1657-4eeb-47c5-a193-84ed106d43bc', 'لا تترددي في السؤال 🤖', 'هل تعتقدين أنكِ ترتكبين أخطاءً في روتين النوم؟ اسألي Anacan AI فورًا عن كل ما يثير ترددكِ لتطمئني.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('10d800e4-c6bd-4325-b22e-385edaca8f7f'::uuid, 'هل ما زال يستيقظ ليلًا؟ 😴', 'إذا اضطرب نومه مجددًا في الأيام الأخيرة، فحلّلي جدوله باستخدام مؤقت النوم في Anacan وابحثي عن مواطن الخلل في روتينه.'),
  ('319cae50-0492-468a-98e4-1b38563ab7ea', 'نحو الشهر الرابع عشر! بقيت ١٠ أيام! 🎂', 'لا يُصدّق! بعد ١٠ أيام بالضبط، سيُكمل طفلكِ شهره الرابع عشر. ومع كل يوم يمضي، يصبح أكثر استقلالية.'),
  ('2064ec2b-0483-4d3b-9453-106b6b9f32f8', 'تجاربه الأولى مع أقلام التلوين. 🖍', '️ أعطيه أقلام تلوين سميكة مناسبة له، وراقبي بحب خربشاته على الورق. لعلّ فنان المستقبل ينمو أمامكِ!'),
  ('7f86b541-f24f-46cc-bf72-a538c8e62fa0', 'اللعب بمفرده بألعابه. 🧩', 'قدرته على اللعب بمفرده، ولو لفترة قصيرة، خطوة كبيرة نحو الاستقلالية. راقبيه من بعيد.'),
  ('f945146d-2bbb-40d9-95f6-29bdc7f3be6d', 'يواصل النمو. 📏', 'أصبحت ملابس طفلكِ صغيرة عليه! أضيفي قياسات الطول والوزن الجديدة في قسم متابعة النمو لتتابعي تطوره.'),
  ('241a81f3-8158-4d3c-a8b2-640a1b060696', 'التعامل مع الانتقائية في الطعام. 🍲', 'قد يرفض في بعض الأيام حتى طعامه المفضل. لا تجبريه، بل قدّمي له بدائل متنوعة فحسب.'),
  ('47368a03-c0f0-4e5c-a343-b4577d2ffa64', 'هدوء الليل 🛀', 'حمّام دافئ وتدليك وتعتيم الغرفة. الحفاظ على روتين النوم هو أهم أسرار الليالي الهادئة دون انقطاع.'),
  ('8edf71cc-a90b-4465-947f-070adc35b5f7', 'الرقص على الموسيقى 🎶', 'بمجرد أن يسمع إيقاعًا موسيقيًا من التلفاز، يبدأ بهزّ مؤخرته. لقد بدأ حسّه الموسيقي بالتطور، فانضمي إليه وارقصا معًا!'),
  ('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8', 'فضفضة الأمهات 💬', 'هل تشعرين بأنكِ لستِ أمًّا جيدة بما يكفي؟ انضمّي فورًا إلى مجتمع Anacan، واقرئي تعليقات الأمهات الداعمة لتشعري بالراحة.'),
  ('4a0eb59e-113c-42ab-af5f-e0f64f837b44', 'اكتشفي أماكن جديدة ☕', 'هل مللتِ من الروتين اليومي؟ استخدمي تطبيقنا للعثور على مقهى يسهل دخوله بعربة طفلكِ، واستمتعي باستراحة مع فنجان من القهوة.'),
  ('4c4da832-707f-472e-a209-374acff11d94', 'مساعدكِ في الأعمال المنزلية! 🧹', 'هل يتحمّس طفلكِ للإمساك بمنشفة ومسح الغبار أو اللعب بالمكنسة؟ تقليده لكِ مؤشر رائع على تطوره.'),
  ('ca45e311-dc2b-43fe-aa24-08a197d26f0a', 'هل لديكِ أسئلة عن نمو طفلكِ؟ 🤖', 'إذا كان هناك ما يشغل بالكِ بشأن مرحلة عمر 13-14 شهرًا، فاكتبي إلى مساعد Anacan AI حتى خلال ساعات الليل.'),
  ('0ffbde04-3193-4b21-aa17-136db5de3c72', 'مذكّرة المشاعر 📝', 'عندما تشعرين بالوحدة، دوّني مشاعركِ في مذكّرة المزاج. كل النساء يمررن بهذه المراحل، وأنتِ قوية.'),
  ('7cdfa7f4-2c92-497d-9290-43caf53d8a56', 'الحاجة إلى الهدوء 🤫', 'حافظي على هدوء الغرفة باستخدام مقياس الصوت. فتقطّع النوم ليلًا يفسد مزاجكما معًا في الصباح.'),
  ('4716a93b-966d-4c69-b174-c2a48e9a09fa', 'حمّام المساء. 🛁', 'الاستحمام بماء فاتر ممتع للتخلّص من غبار اليوم، كما يساعد طفلكِ على الاسترخاء ويهيّئه تمامًا للنوم.'),
  ('dbbcb16c-cf48-47f7-92ab-992ed2fab247', 'يتعرّف على أجزاء جسمه. 👃', 'العبي معه لعبة «أين أنفك؟» أو «أين أذنك؟». وعندما يشير إلى الجزء الصحيح، شجّعيه بالتصفيق له.'),
  ('0cc0cda4-4fef-4e92-9af2-cd065cfee008', 'أنتِ الأفضل! 💖', 'تربية طفل أشبه بسباق ماراثون. خصّصي لنفسكِ بعض الوقت هذا المساء، وشاهدي فيلمًا تحبّينه أو استريحي بهدوء فحسب.'),
  ('781ac9f7-7fd3-4466-9d70-0b41dd1e954a', 'يجرّ ألعابه! 🧸', 'أصبحت الألعاب التي تُسحب بحبل أو العربات الصغيرة التي يمكنه دفعها من وسائل التسلية المفضلة لديه الآن. وهذا تمرين رائع للحفاظ على التوازن!'),
  ('7dec83e1-5089-42b4-a2b5-f3d997eb1138', 'اهتمّي بتغذيتكِ أيضًا. 🥗', 'قد يكون مجاراة طفل مليء بالطاقة أمرًا شاقًا. حضّري لنفسكِ وجبة شهية وغنية بالفيتامينات من الوصفات الصحية للنساء لتستعيدي طاقتكِ.'),
  ('6942d3e7-d39d-4aee-b8a0-ef2313920693', 'إصراره على قول «سأفعلها بنفسي!». 🧦', 'إذا كان يحاول ارتداء جوربه بنفسه أو تناول طعامه باستقلالية، فلا تمنعيه. فشعوره بالاستقلال ينمو من خلال هذه المحاولات الصغيرة.'),
  ('c0c8236b-5e7c-45b1-a5c1-d45f005b603c', 'التنفيس عن المشاعر. 📝', 'قد تشعرين أحيانًا بأن كل شيء يفوق طاقتكِ. اكتبي في يوميات المزاج ما يدور في داخلكِ وما تشعرين به من إرهاق، لتتخلّصي من ضغوط اليوم.'),
  ('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb', 'استكشافات في الهواء الطلق. 🌳', 'لمس أوراق الأشجار وجمع الحصى في الحديقة يساعدان على تنمية حواس طفلكِ. اختاري حديقة جديدة للتنزّه.'),
  ('96b02483-42a2-4868-a751-d817b0144951', 'لا تنسي شرب الماء. 💧', 'أنتِ وطفلكِ على حد سواء! احرصا على شرب الماء بعد الألعاب المليئة بالحركة وبين الوجبات للحفاظ على ترطيب جسميكما.'),
  ('d89100dc-a7f8-49dd-8358-e3c63248fa5d', 'المساعد الصغير منهمك في العمل! 🧹', 'هل يقلّدكِ، فيمسك منشفة ويمسح الغبار أو يلعب بالمكنسة؟ يتعلم الأطفال أكثر ما يتعلمون بالمشاهدة.'),
  ('eea0806e-a72b-42f1-b1c3-b7a791619a96', 'هل تغيّر نظام النوم؟ 😴', 'إذا بدأت قيلولاته النهارية تقتصر على قيلولة واحدة، فقد تزداد ساعات نومه ليلًا خلال الفترة الانتقالية. تابعي جدول الأيام الأخيرة باستخدام مؤقت النوم.'),
  ('15bfc39a-e833-4e38-b7fc-bc13ef473b00', 'وقت اللعب المستقل 🧸', 'أصبح الآن قادرًا على الانشغال بألعابه بمفرده لمدة 10-15 دقيقة. وهذا دليل على تحسّن قدرته على التركيز لفترة أطول. استمتعي بالهدوء.'),
  ('99045f34-6450-4abd-856c-64fd61405e7b', 'يفهم نبرة صوتكِ 🗣️', 'هل يتوقف وينظر إليكِ عندما تقولين «لا» بنبرة جادة؟ لقد بدأ بالفعل في فهم المشاعر والممنوعات!'),
  ('dc953aca-0624-4e7e-a96b-11f2b35b9a14', 'قوة الموسيقى 🎶', 'جرّبي تهدئة نوبات الانزعاج التي تندلع بلا سبب في أواخر النهار بتشغيل موسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة المعجزات.'),
  ('1eee6b26-c3fa-460c-8e48-030eb1e5a77c', 'خربشات ملوّنة! 🖍', '️ ضعي له في إحدى زوايا الغرفة أقلام تلوين سميكة مناسبة وورقة كبيرة. ولا تنسي تخليد أولى أعماله الفنية في ألبوم الطفل!'),
  ('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69', 'هل تحتاجين إلى دعم خبير؟ 🤖', 'اطرحي على مساعدنا Anacan AI أسئلتكِ، مثل: «كيف أنمّي مهارات النطق لدى طفلي البالغ 14 شهرًا؟»، حتى خلال ساعات الليل.'),
  ('9052004a-46e9-4652-8de2-61f2a8f774d7', 'التعب والفخر💖', 'احتفلي هذا المساء مع زوجكِ بتعب ١٤ شهرًا وفخرهما. أنتما فريق رائع!'),
  ('dde3a118-6b4b-4b86-b077-744218b7fcd7', 'كم قطع طفلكِ من شوط! 📈', 'حلّت ثقتكِ القوية بنفسكِ كأم محل مخاوف الأيام الأولى. افتخري بنفسكِ!'),
  ('33a2089a-67cc-4441-bb79-483ad77a1a42', 'خصصي وقتًا لنفسكِ. 🛁', 'لقد أمضيتِ اليوم كله واقفة. خففي عن نفسكِ بتدوين شعوركِ بالتعب في مفكرة المزاج، واسترخي مع كوب من الشاي الدافئ.'),
  ('625bdfef-2359-4843-aaac-6c8411b1963b', 'فن رمي الأشياء. 🎾', 'إن رمي طفلكِ الألعاب أو الطعام على الأرض ثم مراقبتها ليس شقاوة، بل هو استكشاف للجاذبية. تحلّي بالصبر واسمحي له باللعب بأشياء غير قابلة للكسر.'),
  ('ee0ba9ab-4b88-462e-aae9-f9a207218204', 'خطوات إلى الخلف والجانبين! 🦀', 'لم يعد طفلكِ يجرّب المشي إلى الأمام فحسب، بل يجرّب أيضًا الخطو إلى الخلف والجانبين. إنه تمرين رائع للتوازن والمهارات الحركية!'),
  ('21478892-353c-43fd-ba31-59c9aeb8255d', 'جرعة طاقة للأمهات! 🥗', 'يتطلب الأطفال كثيرو الحركة من أمهاتهم ضعف الطاقة! كافئي نفسكِ باختيار طبق شهي من الوصفات الصحية وتحضيره.'),
  ('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e', 'مرحبًا، من معي؟ 📱', 'هل يضع طفلكِ جهاز التحكم عن بُعد أو الهاتف على أذنه ويحاول التحدث مثلكِ؟ لا تفوّتي لحظات التقليد اللطيفة هذه.'),
  ('ab819835-a2e1-481b-91b5-5391eb6051e8', 'تابعي نمط النوم. ⏱️', 'هل انخفض عدد قيلولات طفلكِ نهارًا إلى قيلولة واحدة؟ شغّلي مؤقت النوم عندما ينام رضيعكِ، وتابعي من خلال المخطط مدى تكيّفه مع النظام الجديد.'),
  ('f1854aec-f168-4789-a191-8a1fa96c3cd8', 'حان وقت تحديث إجراءات السلامة. 🛡', '️ مع بدء طفلكِ في التجول بحرية وفتح الخزائن، تزداد المخاطر. ألقي نظرة على قائمة المنتجات الموصى بها لأقفال حماية الأطفال.'),
  ('02d67440-3e37-4d1c-99f8-cbfa7aadda52', 'حان وقت وجبة خفيفة صحية. 🍎', 'تُعد شرائح الفاكهة أو أصابع الخضراوات خيارًا رائعًا للأطفال الذين لا تنفد طاقتهم. دعي طفلكِ يمسكها ويأكلها بنفسه.'),
  ('4a197291-3001-4afb-9a70-d4320bd260b2', 'مرحلة «ما هذا؟». ☝', '️ يشير طفلكِ إلى كل شيء بإصبعه ويسأل عن اسمه. أخبريه بصبر باسم كل شيء؛ فهذا سيساعده على توسيع حصيلته اللغوية بسرعة.'),
  ('8938f1b0-220a-48ac-b5f5-33db3613995c', 'موعد الحكاية مع الأب. 👨‍🍼', 'اتركي للأب اليوم مهمة قراءة حكاية المساء ومساعدة طفلكِ على النوم، وخذي استراحة قصيرة لنفسكِ.'),
  ('47ea2f2a-adf0-473a-a6a2-47218a354bbd', 'يتسلق كالقرد! 🧗‍♂', '️ يحاول طفلكِ التسلق بمفرده على الأريكة أو قطع الأثاث المنخفضة. أمّني المكان من حوله ودعيه يستكشف هذه الخطوات الحركية الجريئة تحت إشرافكِ.'),
  ('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d', 'قبلات في الهواء! 👋', 'هل أصبح طفلكِ يلوّح بيده مودعًا ويرسل القبلات لمن يغادرون؟ استمتعي بهذه الحركة اللطيفة والاجتماعية.'),
  ('ea4bc86f-6869-478f-98a6-52bb8dc4c40f', 'أصبح الانتقال إلى النوم أسهل. 🌙', 'سيساعد اتباع الروتين نفسه كل مساء، مثل الاستحمام وقراءة حكاية وخفض الإضاءة، طفلكِ على الاستغراق في النوم بسهولة أكبر.'),
  ('3d197dae-8e31-468d-8d92-41ba68985a62', 'أكمل 14 شهرًا بالتمام! 🎉', 'تهانينا! لقد مرّ 14 شهرًا كاملًا منذ الولادة! أنشئي الآن صورة ذات طابع مميز عبر جلسة تصوير الطفل، وشاركي هذه الفرحة في مجتمع Anacan!'),
  ('f5a87b81-5f64-4d75-abaf-6fd718e53fc5', 'وجبات خفيفة صحية. 🍎', 'تُعد شرائح الفاكهة أو الزبادي وجبة خفيفة رائعة لهذا العمر. اكتشفي أفكارًا متنوعة ولذيذة من وصفات الأطفال في تطبيقنا.'),
  ('0b365564-8d23-4572-9881-7a4b9e2159bf', 'أولى الروائع الفنية! 🖍', '️ يحب كثيرًا الخربشة على الورق باستخدام أقلام التلوين السميكة. احتفظي بأولى أعماله الفنية للمستقبل في قسم جلسة تصوير الطفل.'),
  ('c0638659-03fe-4ca5-b078-76057498811f', 'إصراره على البقاء بقرب أمه 🥰', 'حتى عندما تذهبين إلى الحمام، ينتظركِ خلف الباب ويبكي. لقد بلغ قلق الانفصال ذروته. طمئنيه في كل مرة.'),
  ('f2ba1614-ef41-4060-97ee-0fe66e58b884', 'اكتساب عادة شرب الماء مهم. 💧', 'كلما زاد نشاطه وحركته، زاد شعوره بالعطش. لا تنسي أن تقدمي له الماء أثناء اللعب وبعد الوجبات.'),
  ('1bf6a974-24ed-47b3-8587-a38235ea120e', 'استكشاف المطبخ! 🍳', 'أصبحت القدور والملاعق والأوعية البلاستيكية من ألعابه المفضلة. اتركي الخزائن الآمنة متاحة ليستكشفها.'),
  ('88b4c840-5c20-4f9f-8b89-4530da60297b', 'حان وقت تحديث تدابير السلامة! 🛡', '️ تزداد المخاطر مع تجوله بحرية وفتحه للخزائن. احرصي على الاطلاع على قائمة المنتجات الموصى بها لدينا لاختيار أقفال حماية الأطفال وواقيات الزوايا.'),
  ('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3', 'حمّام مهدئ. 🛁', 'الحمّام الفاتر ممتع لتفريغ طاقة اليوم، كما أنه يرخي العضلات ويهيئه تمامًا للنوم.'),
  ('409e6b49-8ccb-4975-92b1-c12021092540', 'لقصة المساء سحر خاص. 📖', 'قراءة قصة قصيرة قبل النوم تنمّي خياله وتقوّي الرابطة العاطفية بينكما.'),
  ('44b33bc4-3602-4265-9fe5-30b5609015de', 'حان وقت مشاركة الأب في الرعاية. 👨‍🍼', 'تكون الألعاب المسائية مليئة بالطاقة. دعي الأب هذا المساء يلعب مع طفلكِ لعبة المطاردة ويتولى مهمة تنويمه، وخذي أنتِ قسطًا من الراحة.'),
  ('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95', 'بدأ حس التعاطف يتفتح! 💖', 'هل يأتي طفلكِ ليربّت على شخص يبكي أو يشعر بالحزن؟ إن ذكاءه العاطفي يتطور بصورة رائعة.'),
  ('e569bdf3-a845-44dc-852b-5318a0cf6a72', 'طاقة لا تنفد في الهواء الطلق! 🌳', 'اكتشفي ضمن الأماكن الصديقة للأمهات حدائق جديدة وآمنة يسهل عليكِ الذهاب إليها، ليتمكن طفلكِ الذي يمشي بحرية من تفريغ طاقته.'),
  ('381afc75-3dbd-4716-b5ea-3af987c642dc', 'مقاومة القيلولة النهارية. 😴', 'اللعب أكثر متعة من النوم! أوقفي الألعاب الحركية قبل موعد النوم بنصف ساعة، وانتقلي إلى أنشطة أكثر هدوءًا.'),
  ('3ed2bd45-e711-4e56-bdc9-29b31e605069', 'هل لديكِ سؤال؟ 🤖', 'يمكنكِ طرح أسئلتكِ المهمة، مثل «لماذا لا يأكل طفلي شيئًا في بعض الأيام؟»، على مساعد Anacan بالذكاء الاصطناعي والحصول على الدعم حتى خلال ساعات الليل.'),
  ('718ac202-3ddd-463e-90fd-d1367161e2b5', 'التعامل مع انتقائية الطعام. 🍲', 'قد يرفض طفلكِ في بعض الأيام حتى طعامه المفضل. لا تجبريه، بل جرّبي ببساطة وصفات بديلة ومتنوعة من تطبيقنا.'),
  ('9693a098-adc4-4d19-ab73-4c5cc195a25e', 'سأنظف بنفسي! 🧽', 'هل يطلب طفلكِ منشفة عندما يراكِ تمسحين الطاولة؟ أوكلي إلى مساعدكِ الصغير مهمة آمنة، فهذا يعزز ثقته بنفسه بدرجة مذهلة.'),
  ('98ba1e51-63c6-4c73-891d-99f1b14f3495', 'قوة الضوضاء البيضاء. 🎶', 'إذا لم يستطع طفلكِ النوم بسبب يوم حافل بالنشاط أو بسبب التسنين، فشغّلي صوت المطر من أصوات الضوضاء البيضاء لتهيئة أجواء هادئة في الغرفة.'),
  ('6b7d6637-7328-44aa-b6c8-47c73df3a6f3', 'ينمو طفلكِ بسرعة. 📏', 'بدأت ملابس طفلكِ تضيق عليه من جديد! أضيفي قياسات الطول والوزن الجديدة إلى قسم متابعة النمو وسجّلي تطوره الصحي.'),
  ('807127b9-417f-43a0-9bca-9ef33fbdadb8', 'الاستجابة بلغة الجسد 🗣️', 'عندما تقولين: «هل نذهب؟» يرفع ذراعيه، أو يهز رأسه عندما تقولين: «لا». لقد تطورت قدرته على الفهم بشكل مذهل!'),
  ('356f85b5-b941-4e2e-8218-18498e652ff8', 'يبني قلعة بالمكعبات 🧱', 'يحاول وضع مكعبين أو ثلاثة من مكعبات اللعب فوق بعضها. راقبي بهدوء محاولاته الهندسية الصغيرة هذه.'),
  ('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3', 'قوة الضوضاء البيضاء. 🎶', 'إذا لم يستطع النوم بسبب يوم حافل بالنشاط أو التسنين، فشغّلي صوت المطر من قسم الضوضاء البيضاء لتهيئة أجواء هادئة في الغرفة.'),
  ('f73e2678-7057-466b-a01a-218bff7ab963', 'متعة تنظيف الأسنان. 🪥', 'هل يريد الإمساك بفرشاة الأسنان بنفسه؟ استخدمي فرشاة ناعمة ومناسبة له، ونظّفا أسنانكما معًا أمام المرآة حتى يكتسب هذه العادة.'),
  ('58b586ed-1396-42c6-81f5-29f087488332', 'الاستغراق في النوم بسهولة. 🌙', 'بعد يوم حافل بالنشاط، خفّفي إضاءة الغرفة واخفضي صوتكِ واقرئي له حكاية بنبرة هادئة وبطيئة لتهيئته للنوم.'),
  ('82b39d0a-8bac-4430-a17f-2937f0af35e1', 'قد تنفد طاقتكِ أنتِ أيضًا. 🥗', 'هل تشعرين بإرهاق شديد؟ حضّري عصير سموذي غنيًا بالفيتامينات من قسم الوصفات الصحية للنساء، ليستعيد جسمكِ طاقته سريعًا، وكافئي نفسكِ.'),
  ('917ef6a5-ae0d-4133-b145-53d60f762945', 'أحضر لي الكرة! 🧠', 'أصبح طفلكِ الآن يفهم التعليمات البسيطة جيدًا جدًا. وعندما تطلبين منه شيئًا، فإن إحضاره لكِ بسعادة يدل على أن ذكاءه يتطور بسرعة.'),
  ('2cca6125-c540-4b9b-9a06-6121b60507e5', 'مغامرة في الهواء الطلق! 🌳', 'ألا يستطيع طفلكِ تفريغ طاقته داخل المنزل؟ اختاري حديقة آمنة يمكنكِ التجول فيها بسهولة بعربة الأطفال، واستمتعا معًا بالهواء النقي.'),
  ('73b001a8-93ab-4798-bca3-094a519e468a', 'أطلقي العنان لمشاعركِ. 📝', 'ليست كل الأيام سهلة، وقد تشعرين أحيانًا بأن كل شيء يفوق طاقتكِ. اكتبي مشاعركِ في مفكرة المزاج لتخففي من توتر اليوم.'),
  ('d452b163-e134-4c64-90b8-7e561b20c6f9', 'نقلّد الكلمات! 🗣', '️ هل يحاول تقليد الكلمات التي تقولينها أو أصوات الحيوانات؟ شجّعي هذه المحاولات بحماس لتعزيز رغبته في التعبير عن نفسه.'),
  ('80913e3b-4640-4efe-ae49-ce789db16fd1', 'نهاية يوم مثالي. ✨', 'لقد قدّمتِ اليوم أيضًا أفضل ما يمكن لأم أن تقدّمه. أغمضي عينيكِ واستسلمي لنوم هادئ وأنتِ فخورة بنفسكِ.'),
  ('8e332da4-937a-4f7f-af67-edbe9e325d0e', 'خطواته أصبحت أكثر ثقة! 🏃‍♂', '️ أصبح الآن يتجول في المنزل بمفرده، بل ويحاول الركض أحيانًا. حركاته الجريئة هذه تجعلكِ تشعرين بالفخر وتُبقينكِ متيقظة باستمرار!'),
  ('b5982bde-910f-4d42-bc5f-8e5e9b2e683f', 'الاشتباه في الحساسية 🤖', 'هل قدّمتِ له طعامًا جديدًا ولاحظتِ احمرارًا على وجنتيه؟ قبل أن تقلقي، تعرّفي إلى الخطوات الأولى من Anacan AI.'),
  ('0deab7a8-9a3b-4827-969f-f24303c70419', 'آلام التسنين 🦷', 'هل احمرّت لثته مجددًا ولا يتوقف سيلان لعابه؟ حضّري العضّاضات الباردة.'),
  ('46166e0f-606a-46ff-86d4-07304bc93180', 'اعتياد شرب الماء مهم. 💧', 'كلما زاد نشاطه وحركته، زاد شعوره بالعطش. لا تنسي أن تقدّمي له الماء أثناء اللعب وبعد الوجبات.'),
  ('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e', 'أنتِ أيضًا بحاجة إلى الطاقة. 🥗', 'أنتِ تقضين اليوم كله واقفة. حضّري وجبة خفيفة لذيذة تعيد إليكِ نشاطكِ من وصفاتنا الصحية للنساء.'),
  ('6df61827-7605-47d2-aeef-a4e811b4d8c8', 'استكشافات سريعة! 🏃‍♂', '️ أصبح طفلكِ الآن يتنقل بثقة بين الغرف ويريد لمس كل شيء. تأكدي من أن المنزل آمن واستمتعي بهذه المرحلة الحافلة بالنشاط.'),
  ('c9b2a6a2-258b-4f8c-96f9-86282d8d8145', 'تنفيس عاطفي. 📝', 'بعد يوم مرهق، اكتبي مشاعركِ في مفكرة المزاج لتتخلصي من ضغوط اليوم. أنتِ أم رائعة!'),
  ('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267', 'أنتِ بطلة! ✨', 'إن الحب والرعاية اللذين منحتِهما طوال 450 يومًا لا يُقدّران بثمن. والآن استرخي واستسلمي بهدوء للنوم بعد هذا اليوم الجميل.'),
  ('4df5ec18-5365-45c2-a49d-90ce26310b0b', 'أتمّ طفلكِ 15 شهرًا! 🎉', 'ما أسرع مرور الوقت! لقد مرّ عام و3 أشهر بالضبط منذ قدوم صغيركِ إلى العالم. تهانينا.'),
  ('a50254b7-b2f0-44b3-8ee9-5246bba08038', 'سعادة حول مائدة العائلة. 🍲', 'أصبح بإمكان طفلكِ الآن تناول الأطعمة نفسها معكم. اكتشفي أطباقًا عائلية شهية من وصفات تطبيقنا واحتفلي بهذه المناسبة الصغيرة.'),
  ('157a98b7-1825-4699-b38d-85781cd21cf3', 'ماراثون بين الغرف 🏃‍♂️', 'لم يعد طفلكِ يمشي فحسب، بل يكاد يركض! ويتحسن توازنه يومًا بعد يوم. سجّلي هذه المرحلة الحافلة بالحركة بكل فخر في متتبع النمو.'),
  ('47ea1c98-c71a-45d9-b06c-d95aa3da437b', 'وقت اللعب مع الأب 👨‍👧', 'لقد أرهقكِ الركض خلف طفلكِ طوال اليوم. نوبة المساء على الأب! دعيه يتولى ألعاب التدحرج على الأرض والمطاردة.'),
  ('c0b75b28-86cb-44ea-8bc4-de62c31fae30', 'التخطيط يمنحكِ الراحة. 📝', 'حضّري في ذهنكِ، من خلال ملاحظات صغيرة، قائمة مهام الغد أو خطة الوجبات، ثم اخلدي إلى النوم وأنتِ مطمئنة.'),
  ('e47ea433-71bf-4c11-8e6e-6edbaec03292', 'يشير إلى كل شيء بإصبعه. ☝', '️ إنها النسخة الصامتة من سؤال: ما هذا؟ وللحفاظ على فضوله، كرري له بصبر اسم كل شيء يشير إليه.'),
  ('09564db7-642f-496e-b113-4fd15ad5aefe', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحملي الاستيقاظ ليلًا بمفردكِ تمامًا. أيقظي زوجكِ أيضًا؛ فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('30d6fd90-986c-491d-9a4a-39c6c9f48f69', 'متابعة التطور 🤖', 'هل تحتاجين إلى معلومات عن طفرات النمو في عمر 15 شهرًا؟ ألقي نظرة على تقويم الأزمات.'),
  ('661b0ef0-cce8-4702-8d5a-2f90901198ad', 'حب قراءة الكتب. 📖', 'إن تقليب صفحات الكتب المصورة والاستماع إليكِ وأنتِ تقرئين وسيلة رائعة لتنمية حصيلته اللغوية. اقرئي معه كتابًا كل يوم، ولو لمدة 10 دقائق فقط.'),
  ('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2', 'يفهم نبرة صوتكِ 🗣️', 'هل يتوقف وينظر إليكِ عندما تقولين «لا» بنبرة حازمة؟ لقد بدأ بالفعل في فهم المشاعر والممنوعات!'),
  ('553f302d-8ba0-44d9-9d9d-e356d494f003', 'روتين ما قبل النوم. 😴', 'سيمنحه الحمام الدافئ وملابس النوم النظيفة شعورًا بالراحة ويهيئانه تمامًا للنوم.'),
  ('ed9814d4-d919-40b0-833b-d118d90c1727', 'في رحلة البحث عن الاستقلالية. 🥣', 'عندما يرغب في إمساك وعائه أو ملعقته بنفسه، امنحيه الفرصة. فالفوضى أجمل جزء من التعلّم.'),
  ('258818a7-034e-4b93-86ea-97e8e01d3126', 'نوبات غضب؟ 🌪', '️ قد يغضب ويبكي عندما لا يستطيع التعبير عن نفسه. إذا كنتِ بحاجة إلى دعم في هذا الشأن، فاستشيري Anacan AI وتعرّفي إلى الأسلوب الصحيح للتعامل معه.'),
  ('ca5a1958-0c22-4c62-874b-c3b801f70118', 'مهارة فهم الكلمات. 🧠', 'هل يجد حذاءه ويحضرُه عندما تطلبين منه ذلك؟ يشير هذا إلى أن ذكاءه يتطور بسرعة. أكثري من مدحه!'),
  ('63bf2d84-bd96-49e0-9c51-b1f59bd85995', 'حان وقت الفاكهة! 🍎', 'حضّري له طبقًا ملوّنًا وجذابًا من فواكه الموسم ليستعيد طاقته.'),
  ('72ba71ca-1652-48f5-bc29-c321459f659a', 'قوة الضوضاء البيضاء. 🎶', 'إذا لم يستطع النوم بسبب تأثير يوم حافل بالنشاط، فاصنعي أجواءً هادئة في الغرفة بتشغيل صوت المحيط أو المطر من الضوضاء البيضاء.'),
  ('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea', 'متحكّم في قائمة الطعام 🥣', 'هل يرفض اليوم الطعام الذي أحبه بالأمس؟ الانتقائية في الطعام أمر طبيعي في هذا العمر. لا تقلقي، وابحثي عن بدائل متنوعة ضمن الوصفات الصحية.'),
  ('54788c72-cfe2-4f75-82f0-ba29d942e404', 'تقليد أصوات الحيوانات! 🐱', 'العبي معه لعبة «ما الصوت الذي تصدره القطة؟». هذه المحاكاة البسيطة والممتعة أساس رائع لبدء طفلكِ بالكلام.'),
  ('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa', 'استعيدي طاقتكِ 🥑', 'لقد شبع، والآن حان دوركِ. لا تتناولي غداءكِ واقفة وسط انشغالاتكِ اليومية. اختاري وجبة خفيفة تمنحكِ الطاقة من الوصفات الصحية، واسترخي على الأريكة.'),
  ('f3a87482-9f2e-4700-94d8-d413093ea00a', 'قوة الروتين المسائي 🛀', 'الحمّام الدافئ مفيد دائمًا. لا تغيّري روتينه المسائي أبدًا، لأنه يرسل إلى دماغه إشارة بأن وقت النوم قد حان.'),
  ('9e232723-1401-4819-8b29-1e4636b3edc3', 'أولى لوحاته الفنية! 🖍', '️ يحب كثيرًا الخربشة على الورق بأقلام التلوين السميكة. احتفظي بأولى أعماله الفنية للذكرى في قسم جلسة تصوير الطفل.'),
  ('2423bd81-d7d2-4b3e-b97a-32a10186bc3d', 'تبدأ ألعاب تقمّص الأدوار. 🧸', 'هل يحاول إطعام دبدوبه أو إعطاءه الماء؟ إنه ألطف دليل على مدى دقة مراقبته لكِ وتقليده إياكِ!'),
  ('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc', 'لديكِ سؤال؟ 🤖', 'اطرحي على مساعد Anacan AI أي سؤال يقلقكِ، مثل: هل من الطبيعي أن يكون طفلي انتقائيًا في طعامه؟ حتى خلال ساعات الليل.'),
  ('d4f6586e-25f9-4dd3-9a6b-1408627d49eb', 'مقاومة القيلولة النهارية. 😴', 'اللعب أكثر جاذبية دائمًا من النوم. إذا كان طفلكِ يواجه صعوبة في الاستغراق في النوم، فتابعي جدول الأيام الأخيرة باستخدام مؤقت النوم في Anacan وعدّلي روتينه وفقًا لذلك.'),
  ('13b16a71-31e8-44cf-bbf4-b97f55c8f45e', 'هل الطقس في الخارج غير واضح تمامًا؟ ⛅', 'دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا يمكنكِ ملاحظتها من النافذة.'),
  ('807a2e9f-2fb3-4378-94cf-0ad756854f25', 'حكاية مخصّصة 🪄', 'أنشئي في الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: الطفل الشجاع الذي تسلّق نحو النجوم.'),
  ('d08fdb3f-542d-478d-95e6-72b2d85a8a9a', '5 أيام حتى إتمام 15 شهرًا! 🎈', 'شارف العدّ التنازلي على الانتهاء! أنتِ الآن تشاركين المنزل مع طفل صغير يتجول في أرجائه ويفهم كل شيء. ابتسمي!'),
  ('25f37869-be99-4918-83ae-dd5fecd2f5ce', 'معًا في المطبخ. 🥦', 'أثناء إعداد الطعام، أعطيه وعاءً بلاستيكيًا غير قابل للكسر وملعقة خشبية، ودعيه يحضّر طعامه أيضًا.'),
  ('9b3b08e6-de82-413f-9e4b-6da904b304a3', 'لا تتوتري لأن المنزل فوضوي جدًا اليوم.', 'الأطفال لا يتذكرون المنازل المرتبة، بل الأمهات السعيدات. حضّري قهوتكِ واسترخي.'),
  ('67b35eea-eab9-41c5-88b7-f31e283eddd9', 'هل يعجز طفلكِ عن تفريغ طاقته في المنزل ويتذمر؟  ⛅', 'الطبيعة أفضل مهدّئ. تحققي من الطقس واختاري الملابس المناسبة، ثم توجهي فورًا إلى الحديقة.'),
  ('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9', 'مرحلة «ما هذا؟» ☝️', 'يشير بإصبعه إلى كل شيء ويُصدر صوتًا مميزًا. إنه يريد منكِ أن تعرّفيه إلى أسماء الأشياء من حوله. أخبريه بصبر باسم كل شيء يشير إليه.'),
  ('d4a833e4-9676-4c95-baa2-923b9117c325', 'نحتاج إلى الهدوء 🤫', 'النصف ساعة الأولى بعد نومه هي الفترة الأكثر حساسية. تحققي من مستوى الضوضاء بالديسيبل باستخدام مقياس الصوت، واحذري الأصوات المفاجئة.'),
  ('088ce5b1-9a8e-4d7d-8f55-017e0cc63605', 'هل لديكِ سؤال؟ 🤖', 'هل لديكِ تساؤلات بشأن بعض جوانب نمو طفلكِ في عمر 15 شهرًا؟ لا تتيهي في الإنترنت، بل اكتبي مباشرةً إلى Anacan AI واحصلي على إجابة موثوقة علميًا.'),
  ('b6c6ae0a-2aaa-45b3-b8de-d4785923503c', 'حكاية ساحرة 🪄', 'أنشئي ضمن الحكايات الذكية قصةً خاصة عن بطل شجاع يستكشف العالم. واجعلي الانتقال إلى النوم أكثر متعة.'),
  ('c4cd946e-4029-4937-a10b-6f87983c2067', 'الانتقال إلى قيلولة واحدة 🥱', 'هل يرفض أخذ قيلولته الصباحية واختل جدوله؟ إنه يكبر! لقد بدأ الانتقال من قيلولتين نهاريتين إلى قيلولة واحدة. عدّلي روتينه تدريجيًا.'),
  ('2517046a-f369-483a-b1e2-38f6320720ad', 'الحمّام الفاتر يساعد على الاسترخاء. 🛁', 'اللعب بالماء للتخلص من غبار اليوم وتعبه سيمتّعه، كما سيهيئه للنوم بشكل مثالي.'),
  ('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981', 'لحظات اليوم الجميلة. 📸', 'خلّدي أي حركة طريفة قام بها اليوم أو مهارة جديدة تعلّمها من خلال جلسة تصوير الطفل.'),
  ('21100889-9857-4170-a0a6-59c3dec113f8', 'يختبر الحدود. 🛑', 'هل ما زال يمدّ يده نحو ذلك الشيء رغم قولكِ «لا»؟ هذا ليس عنادًا، بل مجرد اختبار يتعلّم من خلاله القواعد. تحلّي بالصبر.'),
  ('66da2b8a-fe86-40dc-b027-d36d46f5091a', 'ذكاء يتصفّح الكتب 📖', 'هل يقلّب صفحات الكتب ذات الصفحات السميكة ويتفاعل مع الصور؟ إن ذاكرته البصرية تتطور. اقرئي له الكثير من كتب الحكايات الملوّنة.'),
  ('5991e165-7b36-40d5-be3a-c6729cd8e924', 'التنظيف أم الراحة؟ 🛋️', 'عندما ينام طفلكِ، لا تسرعي إلى غسالة الصحون. استلقي على الأريكة، وأغمضي عينيكِ، واكتفي بالتنفس لمدة 15 دقيقة. هل أنتِ روبوت؟ لا.'),
  ('67273a71-3d6d-40e2-b209-34b098335818', 'يكبر أكثر قليلًا كل يوم.📸', 'افتحي جلسة تصوير الطفل فورًا وخلّدي هذه اللحظة العفوية في ذاكرتكِ.'),
  ('d17f36fc-9cb8-4df2-a29e-60891f565b13', 'إصراره على تناول الطعام بنفسه 🥄', 'يأخذ الملعقة من يدكِ ويريد أن يأكل بنفسه. سيسكب الطعام ويتّسخ، لكن ذلك مهم لتطوّر مهاراته الحركية. اسمحي له بالاستقلالية.'),
  ('145c55e0-770c-4adc-a15b-4bd94389378f', 'الوصول إلى مناطق خطرة ⚡', 'ازداد طول طفلكِ وأصبح يصل إلى الرفوف التي لم يكن يستطيع بلوغها من قبل. حامل التلفاز، الزوايا... أعيدي تقييم سلامة المنزل على الفور.'),
  ('b6ac32de-f983-4a93-89fc-cb209586570b', 'هل الأضراس في طريقها للظهور؟ 🦷', 'هل لثته متورمة ويضع يده في فمه؟ قد تكون أسنانه الخلفية في طور الظهور. تحقّقي من متتبّع التسنين وقدّمي له عضّاضات باردة.'),
  ('9a860f2e-97a8-4151-9a68-ed86235ecd75', 'مرحلة «ما هذا؟». ☝', '️ يشير بإصبعه إلى كل شيء ويسألكِ عن اسمه. أخبريه بصبر بأسماء الأشياء كلها؛ فهذه طريقته في اكتشاف العالم من حوله.'),
  ('09bd2033-24ed-4376-ba68-6795f9e6d0fa', 'يرقص على أنغام الموسيقى! 🎶', 'هل يتمايل ويتراقص بمجرد سماع صوت ذي إيقاع؟ حمّلي مقطع فيديو لهذه اللحظات المفعمة بالحيوية إلى ألبوم طفلكِ.'),
  ('899ab05b-717c-4e03-b941-aadf4ad85007', 'مهارة اللعب بمفرده. 🧩', 'قدرته على اللعب بمفرده، ولو لفترة قصيرة، تدل على تطور انتباهه. راقبيه من بعيد بمحبة في هذه اللحظات.'),
  ('98938324-49d8-43fc-bdde-202849487b20', 'الحمّام الفاتر يساعد على الاسترخاء. 🛁', 'سيساعده اللعب بالماء على التخلص من آثار يومه وتعبه، كما سيُمتعه ويهيئه تمامًا للنوم.'),
  ('67d07afb-a906-4267-ae07-195da32a67d1', 'يختبر الحدود. 🛑', 'هل يمد يده إلى الشيء مجددًا رغم أنكِ قلتِ له لا؟ هذا ليس عنادًا، بل طريقته في اختبار القواعد وتعلّمها. كوني ثابتة وصبورة.'),
  ('71f533be-645b-4990-ac46-86ad77f1a038', 'حان وقت الفاكهة! 🍎', 'حضّري له طبقًا ملوّنًا وجذابًا من فواكه الموسم ليستعيد طاقته.'),
  ('cbf7129c-f3df-44ab-928f-9f74910675e9', 'لا تنسي نفسكِ! 💖', 'اجعلي الساعة الأولى بعد نوم طفلكِ لكِ وحدكِ. لا تقومي بأي عمل، بل استمتعي بشيء تحبينه واسترخي.'),
  ('569d0003-c871-435a-ae9b-f4e977441a16', 'لم يتبقَّ سوى 10 أيام ليبلغ 16 شهرًا! 🎂', 'لا يُصدّق! بعد 10 أيام بالضبط، سيُتم صغيركِ شهره 16. ابدئي بالتخطيط لكعكة صغيرة أو جلسة تصوير للاحتفال بهذه المناسبة.'),
  ('e84402f2-45d4-40ce-ae96-610f12a3e06b', 'المساعد الصغير في الخدمة! 🧹', 'هل يتحمّس للإمساك بقطعة قماش ومسح الغبار أو اللعب بالمكنسة؟ تقليده لكِ هو ألطف جزء من رحلة تعلّمه.'),
  ('ed63e2e3-10b5-4bd6-9b06-a81622e913eb', 'روتين النوم يمنحه الشعور بالأمان. 🌙', 'سيساعده تكرار الخطوات نفسها كل مساء وبالترتيب ذاته، مثل الاستحمام وقراءة قصة وخفض الإضاءة، على النوم بسهولة وهدوء أكبر.'),
  ('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35', 'مهارة فهم الكلمات. 🧠', 'هل يجد حذاءه ويحضره عندما تطلبين منه ذلك؟ هذا يدل على أن قدراته الذهنية تتطور بسرعة. أكثري من مدحه وتشجيعه!'),
  ('ce1fc21a-8f96-4c92-b928-5126f2240b1d', 'أنتِ أيضًا بحاجة إلى الطاقة. 🥗', 'أنتِ منشغلة طوال اليوم. لا تنسي أن تحضّري لنفسكِ وجبة خفيفة شهية وغنية بالفيتامينات.'),
  ('d8cf1dda-3655-48e8-9316-6481b7ea82ba', 'نوبات غضب؟ 🌪', '️ قد يغضب ويبكي عندما يعجز عن التعبير عن نفسه. إذا كنتِ بحاجة إلى الدعم في هذا الأمر، فاستشيري Anacan AI لتتعرفي على الأسلوب المناسب للتعامل معه.'),
  ('2b9c6af1-1706-4704-b2ce-29e57d4866f4', 'حان دور الأب. 👨‍🍼', 'اتركي للأب اليوم مهمة قراءة قصة المساء ومساعدة طفلكِ على النوم، وامنحي نفسكِ استراحة قصيرة.'),
  ('8db205c2-0561-48d8-8b6c-61fc68065e2a', 'فن بناء الأبراج. 🧱', 'يُعدّ رصّ 3-4 مكعبات فوق بعضها ثم إسقاطها من أكثر الأنشطة متعةً بالنسبة إليه. تساعد هذه اللعبة على تطوير التناسق بين العين واليد بسرعة.'),
  ('e513a042-7558-4dae-8bc5-5e2b5e5d74fa', 'الراحة خارج المنزل. ☕', 'هل سئمتِ من الروتين اليومي؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى يمكنكِ دخوله بسهولة بعربة طفلكِ، واستمتعي باستراحة لتناول القهوة.'),
  ('d2fd7757-cdd9-4cc6-b45c-347ada81b748', 'خفّفي الإضاءة 🌙', 'قبل النوم بساعة واحدة، أطفئي جميع الأضواء الساطعة والشاشات في المنزل. لا يُفرَز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182', 'الاستيقاظ المفاجئ 😭', 'هل يستيقظ طفلكِ في منتصف الليل صارخًا ولا يهدأ؟ دعي ميزة تحليل البكاء تستمع إلى صوته لتعرفي ما إذا كان السبب رعبًا ليليًا أم ألمًا.'),
  ('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1', 'مشاعر كبيرة في جسد صغير 🛑', 'هل يرمي طفلكِ نفسه على الأرض عندما لا يحصل على ما يريد؟ إنها نوبات الغضب الشهيرة في مرحلة الطفولة المبكرة. حافظي على هدوئكِ، وتواصلي معه بصريًا، وقولي له: أنا بجانبك.'),
  ('d33491b0-9722-4db2-ae48-c019740b7411', 'روح التضامن 🥂', 'تذكّري مع شريككِ الأيام الأولى وتلك الليالي التي لم تناما فيها، واضحكا معًا. لم تصلا إلى هذه المرحلة بسهولة! إنه انتصار لفريقكما.'),
  ('138aeaf3-e845-4d03-b6db-2a04410076a7', 'هل ما زال طفلكِ انتقائيًا في الطعام؟ 🥦', 'إذا كان يرفض بعض الأطعمة، فلا تقلقي. جرّبي من قسم الوصفات طرق تقديم متنوعة وممتعة تناسب الرضّع الذين بدأوا تناول الأطعمة التكميلية.'),
  ('2f302f24-3142-4182-84a0-2782c5ce8394', 'تنفيس المشاعر. 📝', 'هل كان يومكِ مرهقًا جدًا؟ بعد أن ينام طفلكِ، اكتبي مشاعركِ في يوميات المزاج لتتخلّصي من ضغوط اليوم.'),
  ('8b269aa5-a26e-4c52-b247-14a7194a3d35', 'ماراثون داخل المنزل! 🏃‍♂', 'لم يعد طفلكِ يكتفي بالمشي، بل يبدو كأنه يحاول الركض. استمتعي بصوت خطوات قدميه الصغيرتين، لكن لا ترفعي عينيكِ عنه!'),
  ('8ee97257-b3d6-4144-ad9a-91e2e54c967a', 'اللعب والركض في الهواء الطلق. 🌳', 'ألا يستطيع طفلكِ تفريغ طاقته داخل المنزل؟ اخرجا معًا إلى الهواء الطلق، ودعيه يتجوّل بحرية في الحديقة حتى يلعب ويتعب كما يشاء.'),
  ('6537418f-2c88-443b-b40f-e07f0ccd5801', 'قوة الضوضاء البيضاء. 🎶', 'إذا لم يستطع طفلكِ النوم بعد يوم حافل بالنشاط، فشغّلي في الغرفة صوت المحيط أو المطر من قسم الضوضاء البيضاء لتهيئة أجواء هادئة.'),
  ('c45968e1-c58f-48dd-a705-2dc4c22325e0', 'وتيرة النمو. 📏', 'ملابسه تضيق عليه مجددًا! أضيفي قياسات الطول والوزن الجديدة إلى قسم متابعة النمو وحدّثي مخطط نموه الصحي.'),
  ('f13027ff-0446-4962-9c51-398d40234b5a', 'أولى روائعه الفنية! 🖍', '️ يحب الخربشة على الورق بأقلام التلوين السميكة. تابعي أولى أعماله الفنية بحب كبير.'),
  ('3b86e3a2-b53e-4603-a4b1-a57fc531000c', 'يريد أن يأكل بنفسه! 🥄', 'اسمحي له بإمساك الملعقة بنفسه، حتى لو اتسخت ملابسه وما حوله. فهذا مهم جدًا لتناسق عضلاته واستقلاليته.'),
  ('ce4d24a9-fdbd-44df-93c0-058cf5d834aa', 'أحضان حلوة! 🤗', 'عندما يعانقكِ فجأة ويحاول تقبيلكِ، فهذه طريقته في التعبير عن الحب. استمتعي بهذه اللحظات الفريدة وخلّديها في جلسة تصوير طفلكِ.'),
  ('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7', 'شغف قراءة الكتب. 📖', 'اسمحي له بتقليب صفحات الكتب المصورة بنفسه. فالاستماع إلى القصص بصوتكِ يثري حصيلته اللغوية.'),
  ('1cb9115d-9cf4-466e-adbe-8fa808d6b45c', 'لنتابع نظام النوم. ⏱️', 'إذا أصبحت قيلولته النهارية مرة واحدة، فسيتعب في المساء أبكر من المعتاد. يمكنكِ تقديم موعد نومه ليلًا قليلًا.'),
  ('42c60ff7-6aed-4b88-96d2-512be311f08c', 'لا تنسي شرب الماء. 💧', 'كلما زاد نشاطه وحركته، زاد شعوره بالعطش. قدّمي له الماء بانتظام أثناء اللعب وبعد الوجبات.'),
  ('6f0da037-da86-424d-bd6d-1e6d3aefe4db', 'لا تترددي في السؤال 🤖', 'هل تعتقدين أنكِ ترتكبين بعض الأخطاء في روتين النوم؟ اسألي Anacan AI فورًا عن كل ما يثير حيرتكِ واطمئني.'),
  ('b0d45a27-101a-4c13-b494-715c8c48dda4', 'ضعي كل التعب جانبًا. 🥂', 'لا تنسي هذا المساء، بعد نوم طفلكِ، أن تحتفلي مع شريككِ بانتصاركما كفريق!'),
  ('8bf81bea-dee2-4f82-9f28-f1e6a128a812', 'عندما ينفد صبركِ. 📝', 'قد تستنزف طاقة طفلكِ كل قواكِ أحيانًا. افتحي مفكرة مزاجكِ واكتبي بحرية أكثر ما أتعبكِ اليوم.'),
  ('977f5267-192c-40d2-9215-420a5a54d255', 'بدء استخدام الشوكة. 🍴', 'أصبح الآن يحاول غرز الشوكة في قطع طعامه وتناولها. حضّري من قسم الوصفات الخاصة بالرضع الذين بدأوا الأطعمة التكميلية أطعمة يسهل التقاطها بالشوكة.'),
  ('c22aaf03-7bb2-467b-9c9d-ca82637af893', 'يخلع حذاءه بنفسه 👟', 'هل أصبح إلباسه أشبه بمباراة مصارعة؟ إنه يشد جواربه وحذاءه ويخلعهما بنفسه. أُعجبي بمهاراته الحركية!'),
  ('3f154cd8-81d2-425b-aa71-ec2864247772', 'إنه لي! 🧸', 'هل يعترض ويبكي عندما تأخذين شيئًا من يده؟ يتعزز لديه الشعور بالملكية. وهذا جزء مهم من تكوّن شخصيته.'),
  ('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27', 'حان دور الأب في الاستحمام. 👨‍🍼', 'أوكلي إلى الأب اليوم مهمة تحميم طفلكِ مساءً في مغطس مليء بالرغوة وألعاب الماء، ثم تنويمه، وخذي قسطًا من الراحة.'),
  ('b60defb6-6a44-41ab-8087-7dec23cd3f5c', 'حيرة ماذا أطبخ 🍲', 'هل نفدت أفكاركِ لقائمة الأطعمة التكميلية؟ لا تتيهي في الإنترنت، واكتشفي نكهات جديدة في قسم الوصفات الصحية.'),
  ('8878ea41-701a-4729-9437-858b0e0448ae', 'لعبة رمي الكرة! ⚽', 'لم يعد طفلكِ يكتفي بدحرجة الكرة، بل يرفع ذراعيه ويحاول رميها نحوكِ! أضيفي محاولاته الرياضية هذه فورًا إلى ألبوم الطفل كمقطع فيديو.'),
  ('d2eace3f-d381-45ba-bfbb-2db61f670769', 'مَن في ألبوم العائلة؟ 🖼', '️ عندما تتصفحان الصور وتسألينه: «أين الجدة؟»، هل يشير إليها بإصبعه بشكل صحيح؟ تتطور ذاكرته وقدرته على تمييز الوجوه بسرعة.'),
  ('f2055f25-61d4-4680-83b3-954a3f1a9671', 'محاولات هندسية 🧱', 'يحاول وضع مكعبين فوق بعضهما، لكنهما يسقطان. ثم يحاول مجددًا بتركيز. راقبي محاولاته بهدوء.'),
  ('458a103b-d07a-4e59-ac24-1d9dafc323f0', 'مساحة للأم ☕', 'لقد استنزف البقاء في المنزل طاقتكِ. اختاري مقهى مريحًا من الأماكن الصديقة للأمهات، وخصصي بعض الوقت لنفسكِ.'),
  ('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e', 'ذروة الانزعاج ☁️', 'لا شيء يرضيه ويبكي بسبب كل شيء؟ ربما بدأت أضراسه الخلفية بالبزوغ. سجّلي مراحل هذه العملية في متتبّع التسنين.'),
  ('ed11b132-51fc-4e86-99e0-021b6675020e', 'تهويدة المساء 🎶', 'لا يوجد صوت يبعث الطمأنينة مثل صوت الأم. ضمّيه إلى صدركِ هذا المساء وغنّي له بصوت خافت.'),
  ('07f52bf7-1174-455b-9c35-8391687a69fe', 'متابعة التطور 🤖', 'هل تحتاجين إلى معلومات حول طفرات النمو في عمر 16 شهرًا؟ اطلبي من Anacan AI قائمة مختصرة ودقيقة ومعتمدة من أطباء الأطفال.'),
  ('c016a9a1-5e0d-434a-ba4b-907c1125a45a', '5 أيام فقط حتى إتمام 16 شهرًا! 🎈', 'أوشك العد التنازلي على الانتهاء! هل طلبتِ الكعكة وجهّزتِ الملابس؟ ابدئي من الآن باستكشاف أفكار مرحة لجلسة تصوير طفلكِ.'),
  ('d94026ce-ef2a-4e93-b559-9f926c9f245d', 'أصوات تبعث على الهدوء. 🎶', 'إذا لم يستطع طفلكِ أن يهدأ بعد يوم حافل بالاكتشافات النشطة، فشغّلي صوت المطر من بين أصوات الضوضاء البيضاء في الغرفة لتهيئة أجواء مريحة.'),
  ('523911e7-6ac9-424d-9f11-0729711fb179', 'ألعاب حسية. 🌾', 'ضعي بعض الأرز أو المعكرونة في وعاء كبير، وأخفي بينهما بعض الألعاب. دعي طفلكِ يعثر عليها بيديه وينمّي حاسة اللمس لديه.'),
  ('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533', 'وقت اللعب المستقل 🧸', 'أصبح طفلكِ الآن قادرًا على الانشغال بألعابه بمفرده لمدة 10-15 دقيقة. وهذا دليل على زيادة مدة تركيزه. فاستمتعي بالهدوء.'),
  ('adb7bf26-343c-4ba5-8233-149cdef6b1f2', 'قوة الموسيقى 🎶', 'جرّبي تهدئة نوبات الانفعال المفاجئة في المساء بتشغيل موسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة المعجزات.'),
  ('35d30a24-8966-43d1-afce-6f79d49ebcec', 'دعم المتخصصين. 🤖', 'اسألي مساعدنا Anacan AI عن الأسئلة السلوكية الجديدة التي تقلقكِ، مثل: «طفلي يعضّني، فكيف أتعامل مع ذلك؟»'),
  ('5c715c5a-b613-43a0-9f22-5f59af3ae1fc', 'فن خلع الملابس. 🧦', 'ارتداء الملابس صعب، لكن خلعها ممتع للغاية! دعي طفلكِ يحاول خلع قبعته أو جواربه أو حذائه بنفسه.'),
  ('d3844bde-9596-474d-adfe-9c81a7e0ff26', 'أغراض الكبار مثيرة للاهتمام. 👜', 'العبث بحقيبتكِ أو محاولة ارتداء حذاء والده من أنشطته المفضلة. اسمحي له باستكشاف أغراضكِ الآمنة.'),
  ('17b19954-1449-474d-a0b9-d199021947cc', 'أم بصحة جيدة، طفل بصحة جيدة 🥑', 'لقد تضاءل مخزون جسمكِ من الحديد والكالسيوم. حضّري من وصفاتنا الصحية سلطة سريعة التحضير تمنحكِ الطاقة اللازمة لمواصلة يومكِ.'),
  ('24b47242-9a10-48f7-a928-0a19449b984a', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل النوم بساعة. لا يُفرَز الميلاتونين إلا في بيئة هادئة.'),
  ('2d66c314-cb67-48c8-93d1-be3249bad125', 'البحث عن كنوز الطبيعة. 🍂', 'اجمعي أوراقًا أو أكواز صنوبر متنوعة خلال التنزه في الحديقة. واكتشفي حدائق جديدة ذات مناظر طبيعية مختلفة عبر الأماكن الصديقة للأمهات.'),
  ('98db8b9f-36cd-4968-86c5-ed66999457de', 'أصوات الحيوانات 🐶', 'هل يحاول طفلكِ المواء عندما يرى قطة، أو النباح عندما يرى كلبًا؟ يبدأ اكتساب المفردات بأصوات الحيوانات. العبي معه هذه اللعبة.'),
  ('8e91be33-56a9-43aa-bf49-8aa525510abf', 'البحث عن كنوز الطبيعة. 🍂', 'اجمعي أوراقًا أو أكواز صنوبر متنوعة خلال التنزه في الحديقة. واكتشفي حدائق جديدة ذات مناظر طبيعية مختلفة عبر الأماكن الصديقة للأمهات.'),
  ('a9e6c327-e70b-4cd7-9bed-cb9d250622ba', 'أصوات تبعث على الهدوء. 🎶', 'إذا لم يتمكن طفلكِ من الهدوء بعد يوم حافل بالاكتشافات والأنشطة، فشغّلي صوت المطر من قسم الضوضاء البيضاء في الغرفة لتهيئة أجواء مريحة.'),
  ('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'حان وقت الملء والتفريغ! 📦', 'اجمعا الألعاب في صندوق كبير، ثم أفرغاها كلها معًا على الأرض! تساعد لعبة السبب والنتيجة هذه على تنمية التفكير المنطقي لدى طفلكِ.'),
  ('1705b7a5-fb30-4cc3-974a-91a4210ec2a2', 'هذا الوقت لكِ وحدكِ. 🛁', 'لقد نام طفلكِ وهدأ المنزل. ضعي هاتفكِ جانبًا الآن، وشغّلي فيلمًا تحبينه، واستمتعي ببساطة بألا تفعلي شيئًا.'),
  ('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb', 'المشي إلى الخلف وإلى الجانبين! 🦀', 'لم يعد طفلكِ يمشي إلى الأمام فحسب، بل يختبر توازنه أيضًا بخطوات إلى الخلف أو إلى الجانبين. احرصي على التقاط صور لهذه اللحظات الممتعة.'),
  ('68c3e726-41d6-481a-91d7-a89fa5795172', 'فن الخربشة 🖍️', 'هل يحاول طفلكِ الخربشة على الورق عندما تعطينه قلمًا؟ إنه تمرين رائع للمهارات الحركية الدقيقة. تأكدي من أن الأقلام آمنة.'),
  ('ab2f1bd1-caf0-41b5-b8ae-89ec60663539', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ تمامًا. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26', 'تحتاجين إلى الفضفضة 💬', 'هل ترهقكِ فكرة أنكِ لن تعودي أبدًا إلى شخصيتكِ السابقة؟ شاركي هذا الشعور العابر مع الأمهات في مجتمع Anacan.'),
  ('2980029e-45df-4043-851c-f7839d81a721', 'غدًا يُكمل 16 شهرًا! 🎉', 'هل أنتِ مستعدة؟ غدًا يُكمل طفلكِ 16 شهرًا بالتمام! أفرغي بعض المساحة في هاتفكِ، فستحتاجين إليها غدًا لالتقاط ألطف تعابيره في جلسة تصوير طفلكِ.'),
  ('5d958416-87e8-44f2-8b6e-cde98e63822d', 'اليوم في الحكايات الذكية 🪄', 'ابتكري في الحكايات الذكية قصة عن حيوانات شجاعة ولطيفة، وحوّلي الغرفة إلى مكان ساحر.'),
  ('679e2936-6a93-4a92-9069-b372c4d3f661', 'حكاية المساء ساحرة. 📖', 'أصبح طفلكِ الآن يشير لكِ أيضًا إلى الصور في الكتاب. قراءة قصة قصيرة معًا قبل النوم تقوّي الرابطة بينكما بصورة مذهلة.'),
  ('86b4bb0f-0f98-485c-9149-10540747f598', '16 شهرًا بالتمام! 🎂', 'أمر لا يُصدّق، أليس كذلك؟ لقد مرّ 16 شهرًا بالتمام منذ ذلك اليوم المفعم بالمشاعر حين حملتِ طفلكِ بين ذراعيكِ للمرة الأولى! حان الوقت للاحتفال بهذا النمو الرائع. اختاري موضوعًا لجلسة تصوير طفلكِ وخلّدي ألطف لقطة، ولا تنسي مشاركة هذا الفخر مع الأمهات الأخريات في مجتمع Anacan!'),
  ('fbb768fe-d41f-4451-8978-b683840f7855', 'مرحلة الملء والتفريغ! 📦', 'يجمع الألعاب في صندوق كبير، ثم يفرغها كلها على الأرض دفعة واحدة! تساعد لعبة السبب والنتيجة هذه على تنمية التفكير المنطقي لدى طفلكِ.'),
  ('f05a8717-d544-48fb-a529-17361118fee2', 'طفرة في النمو! 📏', 'هل تشعرين بأن طفلكِ يزداد طولًا؟ أدخلي قياساته الجديدة في قسم تتبّع الوزن وشاهدي كيف يرتفع منحنى نموه.'),
  ('75798a4e-e59c-4911-827e-b1622b37ae33', 'تمشيط الشعر وتنظيف الأسنان. 🪥', 'يقلّدكِ، فيمرّر المشط على شعره أو يضع فرشاة الأسنان في فمه. إنها أفضل مرحلة لغرس عادات العناية بالنفس من خلال اللعب.'),
  ('784b1d1b-2c53-42bf-a43b-d6b6e3121aba', 'عشاء عائلي. 🍲', 'ألا ترغبين في الطهي في المنزل هذا المساء؟ استخدمي الخريطة في تطبيقنا للعثور على مطاعم توفر قائمة طعام خاصة بالأطفال ومقاعد مخصصة لهم.'),
  ('b328273f-0602-46a6-a82b-54d47ec1b77d', 'خذي نفسًا عميقًا. ✨', 'قد لا يسير كل يوم كما خططتِ له، وقد يبقى المنزل فوضويًا أحيانًا. لستِ مضطرة إلى أن تكوني مثالية، فأنتِ الأفضل لطفلكِ.'),
  ('714f8ced-9ccc-40ff-a807-9428279f86d4', 'انتقال سهل إلى النوم. 🌙', 'بعد يوم حافل بالنشاط، خفّفي إضاءة الغرفة وغنّي له تهويدة بصوت هادئ لمساعدته على الاستغراق في نوم عميق.'),
  ('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4', 'امنحيه حرية الاختيار. 👕', 'هل سترتدي القميص الأحمر أم الأزرق؟ – إن منحه خيارات بسيطة يخفف من عناده ويعزز إحساسه بذاته.'),
  ('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe', 'لعبة غميضة أكثر تعقيدًا! 🙈', 'هل يستطيع العثور على لعبته بسهولة حتى عندما تخفينها تحت غطاءين مختلفين؟ لقد ترسّخ لديه تمامًا مفهوم بقاء الأشياء.'),
  ('373a30b7-4c10-4d16-b029-a2c123ab28b9', 'بدأت تمارين الجري! 🏃‍♂', '️ تحوّلت خطواته السريعة الآن إلى جولات قصيرة من الجري. قد تزداد صعوبة حماية ركبتيه، لكن مشاهدة فرحته بهذه الحرية تستحق كل شيء!'),
  ('5a23341a-91f5-4bdf-a760-e7b99f610283', 'منفتح على القوامات المختلفة. 🥦', 'حفّزي شهيته بتغيير ألوان طعامه وأشكاله. استلهمي أفكارًا من قسم وصفات للرضع الذين بدأوا الأطعمة التكميلية.'),
  ('6581c209-98c5-4f79-adf1-c7b985567899', 'أنتِ بطلة حقيقية. 🛁', 'لقد اعتنيتِ طوال اليوم بطفل لا يتوقف عن الركض. والآن اسكبي لنفسكِ كوبًا من الشاي الساخن واسترخي فحسب من دون التفكير في أي شيء.'),
  ('755229fb-26a0-4a27-af2c-49bb6a367386', 'روتين يبعث على الهدوء. 🌙', 'قبل الانتقال إلى النوم ليلًا، خفّفي إضاءة الغرفة وتحدثي بصوت هامس؛ فهذا سيساعده أيضًا على تهدئة وتيرته والاستعداد للنوم.'),
  ('ae949749-3a87-49dc-a4ae-057b9e3594b1', 'من الخربشة إلى الخطوط الهادفة! 🖍', '️ عندما يمسك قلمًا، يحاول رسم خطوط طويلة بدلًا من مجرد نقاط. صوّري هذا العمل الفني الصغير وأضيفيه فورًا إلى ألبوم طفلكِ.'),
  ('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9', 'البحث عن الكنوز في الطبيعة. 🍂', 'يُعد جمع أوراق الشجر والحصى الصغيرة واستكشافها في الفناء أو الحديقة نشاطًا رائعًا لنموه الحسي.'),
  ('1b65f6b1-f423-43f5-bc48-5ffb574c7c74', 'الاسترخاء بألعاب الماء. 🛁', 'اللعب بالألعاب التي يضعها في الماء أثناء الاستحمام بماء فاتر يخفف عنه توتر اليوم، كما أنه ممتع للغاية.'),
  ('bc0b7dcc-fdc0-4664-bff5-56183ea22258', 'يفهم التعليمات المكوّنة من خطوتين! 🧠', 'عندما تقولين له: «أحضر حذاءك وأعطني إياه»، هل ينفّذ الحركتين بالترتيب؟ إنها علامة على قفزة مذهلة في نموه الذهني!'),
  ('c18b2eee-ba78-43cc-89fd-423a464819d2', 'طاقة الأم مهمة جدًا. 🥗', 'لقد أرهقكِ الركض المتواصل وراءه. حضّري لنفسكِ وجبة لذيذة وغنية بالفيتامينات من قسم الوصفات الصحية للنساء.'),
  ('bf80d71f-c8bb-4983-b046-1ee91c367f20', 'دعم الخبراء. 🤖', 'هل يفهم الكلمات، لكنكِ تتساءلين لماذا يتحدث قليلًا؟ اطرحي الأسئلة التي تشغل بالكِ على مساعد Anacan بالذكاء الاصطناعي واطمئني.'),
  ('cd0e822c-b843-41fa-9a3e-f4b682a848ae', 'استخدام الملعقة باستقلالية. 🥄', 'أصبح يسكب كمية أقل من الطعام أثناء تقريب الملعقة من فمه. شجّعي هذه المهارة الحركية الدقيقة لديه وامنحيه فرصة للاعتماد على نفسه.'),
  ('d6374c1a-94a0-4de3-855d-6a8d4e9a29af', 'التعاطف مع الألعاب. 🧸', 'هل يربّت على دبدوبه أو يطعمه أو يغطيه؟ تُظهر ألعاب تقمّص الأدوار اللطيفة هذه مدى تطور ذكائه العاطفي بشكل رائع.'),
  ('299405ea-50dc-48c1-ba2a-233941bf627c', 'وقت الحكاية مع الأب. 👨‍🍼', 'دعي الأب يتولى اليوم قراءة حكاية المساء ومهمة تنويم طفلكِ، وامنحي نفسكِ استراحة قصيرة.'),
  ('7ad6ef35-e677-498c-8bc2-cc3e84535415', 'حان وقت تحديث إجراءات السلامة. 🛡️', 'أصبح فتح الخزائن والأدراج هوايته المفضلة. احرصي على الاطلاع على قائمة المنتجات الموصى بها لاختيار أقفال أمان الأطفال.'),
  ('ec2361c8-31f7-458e-ad6e-506355b447a5', 'يستكشف آفاقًا جديدة! 🧗‍♂', '️ أصبح الآن قادرًا على الوصول إلى أماكن أعلى وتسلق الأثاث بسهولة أكبر. حان الوقت لمراجعة إجراءات السلامة في المنزل مرة أخرى.'),
  ('21888245-7cf1-48e4-a08b-53389aa39131', 'اجعلي شرب الماء ممتعًا. 💧', 'يؤدي الركض واللعب بنشاط إلى الشعور بالعطش. قدّمي له الماء كثيرًا في زجاجته الملونة للحفاظ على ترطيب جسمه.'),
  ('4595ac68-2033-4a66-a4d9-1146030382ed', 'خلاصة اليوم. ✨', 'لستِ مضطرة إلى أن تكوني مثالية كل يوم. لا بأس إن لم تتمكني من إنجاز شيء ما اليوم. فأنتِ الأفضل بالنسبة إليه.'),
  ('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85', 'يتعزز إحساسه بالإيقاع! 🎶', 'هل يبدأ بالحركة والابتسام بمجرد سماع الثواني الأولى من أغنيته المفضلة؟ التقطي هذه اللحظات المفعمة بالحيوية عبر جلسة تصوير الطفل وأرسليها إلى مجموعة العائلة.'),
  ('33b8d80d-5434-483c-b198-c7b20c73321d', 'يتعرف إلى أجزاء جسمه بمزيد من التفصيل. 👂', 'إجابته الصحيحة عن أسئلة جديدة مثل «أين بطنك؟» و«أين أذنك؟» تدل على سرعة قدرته على التعلم.'),
  ('87029bf7-0808-4eac-a180-0abfa62f0b48', 'اقرآ كتابًا معًا. 📖', 'لم يعد يكتفي بتقليب الصفحات، بل يشير بإصبعه إلى الحيوانات أو الأشياء الموجودة في الكتاب وينتظر منكِ أن تذكري أسماءها.'),
  ('cc468aff-f9d2-4961-b955-bf2eaa13f7ef', 'كيف يسير معدل نموه؟ 📏', 'ها هي أكمام ملابسه وأرجل سراويله تقصر مجددًا! أدخلي قياساته الجديدة في قسم متتبع الوزن وتابعي صعود منحنى نموه.'),
  ('308b629a-7190-416d-8240-7f61a2fe4d68', 'الغضب الناتج عن عدم قدرته على التعبير عن نفسه. 🌪', '️ من الطبيعي أن يغضب ويبكي عندما لا يحصل على ما يريده أو يعجز عن التعبير عن نفسه. انحني لتصبحي في مستوى نظره وأخبريه أنكِ تتفهمين مشاعره.'),
  ('78541e65-2128-40ff-8cb4-1e0d54454519', 'أطلقي العنان لمشاعركِ. 📝', 'هل كان يومًا مرهقًا للغاية؟ بعد أن ينام طفلكِ، اكتبي مشاعركِ في مذكرات المزاج لتتخلصي من ضغوط اليوم.'),
  ('7ea95622-1f8d-4996-8638-aeeafe28a802', 'اكتشفي أماكن جديدة. ☕', 'هل سئمتِ من الروتين اليومي؟ ابحثي في قسم الأماكن الصديقة للأمهات عن مقاهٍ يمكنكِ ارتيادها براحة مع طفلكِ وتقدم قوائم طعام للأطفال.'),
  ('58ff14f8-978e-4eec-8b86-a777de1b33ba', 'لعبة جمع الأشياء وترتيبها. 🧺', 'طفلكِ الصغير الذي يحب إفراغ الألعاب من الصندوق يتعلم الآن إعادة بعضها إليه أيضًا. حوّلي المهمة إلى متعة من خلال غناء أغنية الترتيب معًا.'),
  ('17791a06-d7d3-466d-acee-c2689fa82589', 'ألعاب حسية. 🌾', 'ضعي الأرز أو الرمل في وعاء كبير، ثم أخفي بعض الألعاب داخله. إن بحث طفلكِ عنها بيديه مفيد للغاية لتنمية المهارات الحركية الدقيقة لأصابعه.'),
  ('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3', 'منحه حق اختيار ملابسه. 👕', 'هل تريد ارتداء القميص الأزرق أم الأخضر؟ إن منح طفلكِ خيارين يعزز إحساسه بذاته ويخفف من عناده قليلًا.'),
  ('e6632c98-233d-431d-adc3-c5f78c1c7a37', 'الاسترخاء بألعاب الماء. 🛁', 'سيساعد الحمام الدافئ وصوت خرير الماء على تبديد تعب اليوم كله. ضعي أوعية بأحجام مختلفة في الماء وعلّمي طفلكِ مفهوم الحجم والسعة.'),
  ('148de716-5fb6-4776-96cc-81e2d00b53b8', 'شاركي مشاعركِ. ✨', 'قد تتراكم عليكِ الأمور أحيانًا. وفي نهاية اليوم، مارسي هواية تحبينها لتستعيدي سلامكِ الداخلي.'),
  ('b3ddea65-cbd9-4fdd-900d-8914e021db1f', 'يرمي الكرة نحو الهدف! ⚽', 'لم يعد طفلكِ يكتفي بدحرجة الكرة، بل يحاول رميها في اتجاه محدد. وهذا مؤشر واضح على تطور التناسق بين عينيه ويديه.'),
  ('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3', 'اجعلي شرب الماء ممتعًا. 💧 A', 'يشعر الأطفال النشطون بالعطش بسرعة. قدّمي لطفلكِ الماء بانتظام في زجاجة ملوّنة وجذابة حتى لا يصاب جسمه بالجفاف.'),
  ('2f67b26a-192a-4bd5-87f9-5f376ff164e3', 'تعليمات من خطوتين. 🧠', 'خذ اللعبة وضعها في الصندوق. إن قدرة طفلكِ على تنفيذ هذه التعليمات المركبة تدل على تطور قدرته على الاستيعاب.'),
  ('bf0e882a-2f6d-4439-b170-c9adaeed59cd', 'يرقص على الموسيقى بإيقاعه الخاص. 🎶', 'لم يعد طفلكِ يتمايل فحسب، بل يصفق بيديه أو يدور وفقًا لإيقاع الموسيقى.'),
  ('c522fcf6-60fc-463a-b943-7933f5ac5c70', 'حكاية المساء ساحرة. 📖', 'دعي طفلكِ يروي الحكاية بطريقته الخاصة مستعينًا بالصور. فهذا يرسّخ لديه عادة قراءة الكتب مستقبلًا.'),
  ('19e05272-ac3b-430f-bbad-b5c770118fd3', 'احتفال بالذكرى! 🎈', 'احتفلي بهذا اليوم بكعكة صغيرة أو بإحدى فواكهه المفضلة. فرؤية مدى سرعة نموه هي أعظم مكافأة لكِ.'),
  ('52e84dda-8f2e-4dce-9b8e-b095190c1816', 'اشكري نفسكِ. ✨', 'اشكري نفسكِ على ما أظهرتِه من تفانٍ وحب وصبر طوال 500 يوم. والآن نامي بهدوء، فغدًا تبدأ مرحلة جديدة!'),
  ('7cc24719-4bcf-403b-9178-3f6a80317c26', '500 يوم رائع.🎉', 'هل تصدقين؟! لقد مرّ 500 يوم بالضبط منذ الولادة!'),
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee', 'شحن طاقة الأم 🔋', 'هل استنزف الركض طوال النهار طاقتكِ؟ إن تربية طفلكِ مع إهمال نفسكِ ليست بطولة. ضعيه في مكان آمن وخذي استراحة لشرب القهوة لمدة 10 دقائق.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'تجاوز حد السرعة 🏃‍♂️', 'لم يعد يمشي فحسب، بل يكاد يركض! وأصبح اللحاق به أكثر صعوبة. سجّلي رقم السرعة القياسي الجديد هذا في متتبّع النمو، وأزيلي العوائق من المنزل.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'تفاهم بلا كلمات 🫂', 'لقد تعبتِ كثيرًا اليوم. بعد أن ينام طفلكِ، اجلسي بجوار شريككِ على الأريكة من دون حديث، واستمتعا فقط بلحظات الهدوء.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'ما يحتاج إليه جسمكِ 🥑', 'هل تؤلمكِ ذراعاكِ أو ظهركِ؟ لقد أصبح طفلكِ أثقل وزنًا. ادعمي عضلاتكِ باختيار غداء خفيف غني بالكالسيوم والبروتين من بين الوصفات الصحية.'),
  ('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81', 'هل تتغير دورة النوم؟ ⏱️', 'إذا أصبح طفلكِ يأخذ قيلولة واحدة فقط خلال النهار، فقد يتغير موعد الانتقال إلى النوم الليلي قليلًا. تابعي جدول اليوم باستخدام مؤقت النوم في Anacan واضبطي الروتين الجديد.'),
  ('e71126af-730c-4cca-8daa-1682609e21a1', 'تركيب الأشكال (Puzzles). 🧩', 'يحاول وضع الدائرة في الفتحة الدائرية والمربع في الفتحة المربعة. تنمّي هذه الألعاب المنطقية صبره وتركيزه.'),
  ('069cc383-0002-41b5-ba19-4172c6d6b10f', 'هل أصبح الاستغراق في النوم أصعب؟ 😴', 'قد تُبقيه مغامرات الاستكشاف النشطة متحمسًا أحيانًا. شغّلي مؤقت النوم، وخفّفي إضاءة الغرفة إلى أدنى مستوى واقرئي له قصة قبل النوم.'),
  ('1beeca23-44cf-48f8-9b07-fc08412e7809', 'شكرًا ومن فضلك. 🙏', 'أصبح يومئ برأسه عند إعطاء شيء أو أخذه، أو يعبّر عن امتنانه بلغته الخاصة. إنه الوقت المثالي لتعليمه قواعد التعامل الاجتماعي!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('eb807359-495c-4338-a628-e4dd3e405226'::uuid, 'نتابع زيادة الطول والوزن. 📏', 'هل أصبحت ملابسه صغيرة عليه مجددًا؟ حدّثي القياسات الجديدة في قسم متابعة الوزن، وأنشئي مخطط نموه حتى اليوم 500.'),
  ('158d01ac-e4e7-4be6-959c-37e93007ee0b', 'يتعرّف على الحيوانات في الكتاب. 🐶', 'هل يشير بإصبعه عندما تسألينه: «أين الكلب؟» ابدئي أيضًا بذكر ألوان الأشياء الموجودة في الكتاب لتنمية حصيلته اللغوية.'),
  ('9e266e10-1251-4668-af5f-a58fe3b3f537', 'حان وقت تحديث إجراءات السلامة. 🛡️', 'أصبح الآن قادرًا على الوصول إلى أماكن أعلى. تحققي مجددًا من أغطية الطاولات والزوايا الحادة. وإذا لزم الأمر، ألقي نظرة على قسم المنتجات الموصى بها.'),
  ('ca40c713-93a7-4e51-9b1b-8465a3151e1f', 'وقت المرح مع الأب. 👨‍🍼', 'اتركي الجزء المليء بالنشاط من المساء للأب. فألعابهما المليئة بالضحك تقوّي علاقتهما وتمنحكِ فرصة للراحة.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'تبدأ الألعاب التخيّلية 🧸', 'هل يحاول إطعام دبه المحشو أو تنويمه؟ لقد بدأ خياله يتفتّح! راقبي بفخر محاولاته الرائعة للتعبير عن التعاطف.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'وقت اللعب مع الأب 👨‍👧', 'هل أوشك صبركِ على النفاد؟ دعي الأب يتولى هذا المساء ألعاب التدحرج على الأرض والدغدغة.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'استكشاف المطبخ. 🍎', 'اسمحي له بمساعدتكِ في غسل الفواكه. سيحافظ صوت الماء وألوان الفواكه على فضوله وحماسه.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'محاولات تكوين الجمل. 🗣', '️ هل يحاول الجمع بين كلمتين، مثل «ماما، أعطيني» أو «بابا، انظر»؟ إنها قفزة رائعة في تطور النطق واللغة!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'خلفية ليلية ساحرة 🪄', 'هل يجد صعوبة في الخلود إلى النوم؟ شغّلي له خلفية مهدئة من الضوضاء البيضاء تتكوّن من أصوات النهر فقط.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'الفنان الصغير منهمك في عمله 🖍️', 'هل يشخبط على الورق (أو الحائط) عندما تعطينه قلمًا؟ تتطور مهاراته الحركية الدقيقة بسرعة. حان الوقت لشراء ألوان قابلة للغسل.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'وقت الحكايات مع الأب. 👨‍🍼', 'أوكلي إلى الأب مهمة الألعاب النشطة الأخيرة في المساء. ستكون ضحكاتهما معًا أجمل خلفية لاسترخائكِ.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'استكشاف الطقس ⛅', 'هل الجو في الخارج عاصف أم بارد فحسب؟ لا تعتمدي على النظر من النافذة كي لا تخطئي. دعي أداة الطقس والملابس تقترح عليكِ الإطلالة المناسبة بدقة خلال ثوانٍ.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'وقت الأم الخاص 🎧', 'لا تسرعي إلى المطبخ بمجرد أن ينام طفلكِ. ضعي سماعاتكِ، وشغّلي أغنية تحبينها، وكوني أنتِ فقط لمدة 15 دقيقة.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'يصرّ على تناول الطعام بنفسه 🥄', 'إذا أخذ الملعقة من يدكِ، فلا تمنعيه. حتى لو اتّسخت ملابسه، فإن تناوله الطعام بنفسه أكبر دليل على استقلاليته.'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'انظري إليّ! ☝️', 'يُصدر أصواتًا لجذب انتباهكِ، ويشير بإصبعه إلى الشيء الذي يثير اهتمامه. شاركيه اكتشافاته وأكّدي له قائلةً: نعم، هذه كرة.'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'الإصرار على الملعقة 🥄', 'هل يريد تناول الطعام بنفسه ويسكب نصفه على ملابسه؟ لا تركّزي على النظافة. فهذه الأيام تضع أساس اعتماده على نفسه في تناول الطعام.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'حصيلة اليوم 📝', 'عندما تشعرين بأنكِ لستِ جيدة بما يكفي، اكتبي إنجازاتكِ الصغيرة اليوم في مفكرة المزاج. (مثلًا: أضحكته، وأشبعته). أنتِ رائعة.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'الحديث يصبح أكثر جدية 🗣️', 'هل يخبركِ بشيء بكلمات غير مفهومة، بل ويستخدم حركات يديه أيضًا؟ تحاوري معه بالجدية نفسها، فهذا ضروري لتطوّر النطق لديه.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'قوة الهواء النقي 🌙', 'هل يرفض النوم؟ افتحي النافذة وجدّدي هواء الغرفة بالكامل. فالهواء البارد والنقي يسهّل دائمًا الانتقال إلى النوم.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'هل تشتبهين في وجود حساسية؟ 🤖', 'هل قدّمتِ له فاكهة جديدة وظهر احمرار؟ قبل أن تقلقي، تعرّفي عبر Anacan AI إلى الخطوات الأولى للتعامل مع حساسية الطعام لدى الأطفال.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'عشق الكتب 📖', 'هل يقلب طفلكِ صفحات الكتاب بحرية ويلمس الصور بإصبعه؟ تبدأ عادة القراءة بالتكوّن منذ الآن. سمّيا معًا الأشياء الموجودة في الصور.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'هل استيقظ صارخًا فجأة؟', 'قد يكون ذلك رعبًا ليليًا. شغّلي صوته في محلّل البكاء لمعرفة ما إذا كان السبب جسديًا أم نفسيًا.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'يمكن للأعمال المنزلية أن تنتظر 🛑', 'لم تمسحي الأرضية؟ دعيها كما هي. يمكن تنظيف المنزل المتّسخ، لكن تعافي الأم المنهكة يستغرق وقتًا طويلًا. استلقي على الأريكة واستمتعي بالسكينة فحسب.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'ألعاب المنطق 🧱', 'هل يرصّ 3-4 مكعبات فوق بعضها ليبني برجًا؟ سجّلي هذا الإنجاز الحركي في متتبّع النمو! وصفّقي لمحاولاته الهندسية الصغيرة هذه.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'لنجعل الانتقال إلى النوم أسهل. 🌙', 'اخفضي إضاءة الغرفة إلى أدنى مستوى وتحدّثي بهدوء بصوت هامس. سيعطي ذلك جهازه العصبي إشارة إلى أن وقت الراحة قد حان.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'وقت استعادة الطاقة. 🍎', 'عندما ينام طفلكِ، أغمضي عينيكِ أنتِ أيضًا لمدة 20 دقيقة. الأعمال المنزلية لا تنتهي، لكن طاقتكِ قد تنفد. حافظي على نفسكِ.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'طفلكِ الصغير المحب للمساعدة. 🧺', 'عندما تجمعين الألعاب في الصندوق، هل يحضر طفلكِ واحدة منها ويضعها فيه؟ احرصي على الإشادة بهذه المساعدات الصغيرة واشكريه عليها.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'سحر الحكاية الذكية 🪄', 'ابتكري في الحكايات الذكية قصة خاصة يكون طفلكِ بطلها: صغير شجاع يتجوّل في الغابة السحرية.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'شاركي التجارب 💬', 'هل تسيطر عليكِ فكرة: «هل طفلي هكذا أيضًا؟» انضمي إلى مجتمع Anacan، واقرئي قصص أمهات الأطفال بعمر ١٦ شهرًا وخذي نفسًا عميقًا.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'حمّام مهدّئ 🛁', 'اللعب بالماء الفاتر قبل النوم يبدّد كل توتر اليوم. أضيفي قليلًا من الزيت العطري إلى الماء لخلق أجواء من السكينة.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'محاولة صعود الدرج بمفرده 🪜', 'أصبح طفلكِ يصعد بثقة أكبر ممسكًا بيدكِ. لا تمنعيه كي يقوّي عضلات ساقيه، واحرصي فقط على سلامته.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'قائمة في جيبكِ 🛒', 'وسط فوضى الحياة اليومية، هل نفد الشامبو أم المناديل المبللة؟ لا تحاولي تذكّر كل شيء؛ دوّنيه في قائمة التسوق وزامنيها مع شريككِ.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'هل لديكِ سؤال؟ 🤖', 'يمكنكِ سؤال مساعد Anacan بالذكاء الاصطناعي، حتى في ساعات الليل، عن أمور مثل: «لماذا ازدادت مرات الاستيقاظ ليلًا؟» والحصول على إجابة فورية.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'وجدتُكِ! 🙈', 'هل يغطي طفلكِ عينيه بيديه ويلعب الغميضة؟ إن إدراكه لمفهوم بقاء الأشياء في تحسّن مستمر.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتحدثا عمّا يثقل كاهلكما. فدعم كل منكما للآخر يخفف العبء الجسدي والنفسي إلى النصف.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'تساؤلات حول صحة طفلكِ 🤖', 'ما الذي ينبغي أن تتوقعيه في نمو طفلكِ بين عمر ١٦ و١٨ شهرًا؟ بدلًا من قراءة أخبار مخيفة على الإنترنت، اطلبي من Anacan AI ملخصًا دقيقًا يستند إلى رأي الخبراء.'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'لا تنسي نفسكِ! ☕', 'طاقتكِ من أهم ما يحتاج إليه طفلكِ. حضّري لنفسكِ سموذي لذيذًا ومغذيًا من وصفاتنا الصحية.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'مدونة وقهوة 📖', 'نام طفلكِ، والآن حان وقتكِ! اقرئي تدوينتنا الجديدة واكتشفي حقائق شيقة عن سيكولوجية الأطفال كثيري النشاط.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'نزهة مريحة 👟', 'هل تحتاجين أنتِ وطفلكِ إلى حذاء مريح لتتمكني من الركض خلفه في الحديقة؟ تصفّحي أفضل الخيارات في قسم المنتجات الموصى بها.'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'هل لديكِ سؤال؟ 🤔', 'هل تتساءلين كيف تتعاملين مع عناد طفلكِ المتزايد؟ Anacan AI جاهز للإجابة فورًا مستندًا إلى نصائح الخبراء!'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'خذي نفسًا عميقًا ✨', 'لا حاجة لأن يكون كل شيء مثاليًا. فأنتِ بالفعل أفضل أم! تخلّصي من ضغوط اليوم واسترخي مع مفكرة الحالة المزاجية.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'هل ازداد طول طفلكِ؟ 🦒', 'هل لاحظتِ أن ملابسه أصبحت ضيقة؟ أدخلي القياسات الجديدة في متتبّع النمو وتابعي تقدّمه على مخطط النمو.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'احتياجاته الغذائية 🥣', 'هل حصل اليوم على ما يكفي من البروتين؟ حلّلي قائمة طفلكِ الغذائية اليومية باستخدام أداة متابعة التغذية، وعوّضي العناصر الناقصة.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'صوت مهدّئ 🌧️', 'هل تمنعه أحداث اليوم من النوم؟ اختاري صوت المطر من قسم الضوضاء البيضاء وساعدي جهازه العصبي على الاسترخاء بصورة طبيعية.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'أحلام سعيدة 🌙', 'لقد تعبتِ كثيرًا اليوم. أثناء نوم طفلكِ، شغّلي صوت أمواج المحيط من قسم الضوضاء البيضاء لينام بهدوء وتحصلي أنتِ أيضًا على قسط من الراحة.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'مؤقت الوجبات ⏱️', 'أصبحت متابعة مواعيد الوجبات أسهل الآن! شغّلي مؤقت الرضاعة وتابعي بعناية احتياجات طفلكِ اليومية من الغذاء.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'بدأ الركض في كل مكان! 🏃‍♀️', 'هل يحوّل طفلكِ المستكشف ذو الـ17 شهرًا المنزل إلى ساحة مليئة بالحركة؟ ساعديه على تفريغ طاقته باكتشاف متنزه جديد قريب عبر قسم الأماكن الصديقة للأمهات.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'لذيذ ومختلف! 🥦', 'هل تفكرين في طبق مختلف تحضّرينه لطفلكِ اليوم؟ ستجدين أفكارًا لذيذة في قسم الوصفات المخصص للأطفال الذين بدأوا تناول الأطعمة التكميلية.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'دوّني مشاعركِ 📝', 'قد تكون الأمومة مرهقة أحيانًا، وهذا طبيعي جدًا. دوّني في مفكرة المزاج أكثر ما أتعبكِ اليوم لتشعري بالارتياح.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'مفاجأة الصباح 💩', 'هل غيّرتِ أول حفاض اليوم؟ لا تنسي تسجيله في متتبع الحفاضات داخل التطبيق حتى تتمكني من متابعة روتين النظافة بسهولة!'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'القيلولة النهارية 😴', 'شغّلي مؤقت النوم! حلّلي مدة القيلولة النهارية لطفلكِ البالغ 17 شهرًا لتضعي خطة نومه المسائية بدقة أكبر.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'بحثًا عن الراحة 🍼', 'هل تبحثين عن أفضل كوب مانع للانسكاب لتعزيز استقلالية طفلكِ؟ اطّلعي على الخيارات الأكثر إعجابًا لدى الأمهات في قسم المنتجات الموصى بها.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'ليكن هذا اليوم مختلفًا 🌟', 'هل مللتِ من روتين المنزل؟ افتحي خريطة الأماكن الصديقة للأمهات واعثري على مقهى جديد يمكنكِ الجلوس فيه براحة مع طفلكِ.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'طفل نجم! 📸', 'ابتسامته الجميلة لا تُقدَّر بثمن! خلّدي هذا اليوم باستخدام إطارات متنوعة عبر ميزة جلسة تصوير الطفل.'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'متابعة الجهاز الهضمي ⏱️', 'تساعد متابعة عدد الحفاضات المستخدمة يوميًا على تقييم جودة التغذية. هل سجّلتِ تغييرات الحفاض اليوم في تطبيقنا؟'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'مائدة العائلة 🍲', 'ماذا ستقدّمين له على العشاء؟ ستجدين في وصفات الأغذية التكميلية أفكارًا لوجبات صحية مشتركة تحبها العائلة بأكملها.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'قصتكِ مع الأمومة 📝', 'قصة كل أم فريدة من نوعها. اقرئي التجارب الواقعية وقصص الأمهات الأخريات في مدوناتنا واستلهمي منها.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'الجري في الحديقة 👟', 'بعد الخطوات الأولى تبدأ مغامرات الجري. لاختيار حذائه الأول، اطّلعي على الخيارات الصحية في قسم المنتجات الموصى بها.'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'السكينة في الغرفة 🌊', 'هل يصعب عليه النوم اليوم؟ شغّلي صوت أمواج المحيط من قسم الضوضاء البيضاء لتهدئة جهازه العصبي ومساعدته على الاستغراق في النوم.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'هل يحصل على ما يكفي من البروتين؟ 🍗', 'البروتين ضروري لنمو طفلكِ! استخدمي أداة متابعة التغذية لتقييم توازن غذائه اليومي وتعويض أي نقص.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'روتين مريح 🌙', 'إنها نهاية يوم جميل. شغّلي مؤقت النوم، واختاري تهويدة من الضوضاء البيضاء، واستمتعي بهدوء بنهاية اليوم.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'بحثًا عن الهواء النقي 🌳', 'هل تشعرين بالضيق من البقاء في المنزل؟ افتحي خريطتنا للأماكن الصديقة للأمهات، واكتشفي حديقة جديدة يمكنكِ التنزه فيها براحة مع رضيعكِ.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'حان وقت النوم ⏱️', 'هل بدأتِ في تنويمه؟ شغّلي مؤقت النوم وسجّلي مدى التزامكِ بالروتين لتحليل معدل نومه.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'كيف هي شهيته صباحًا؟ 🥣', 'من المهم أن يبدأ يومه بطريقة صحية! استخدمي أداة متابعة التغذية لحساب احتياجاته من الفيتامينات اليوم والتخطيط لقائمة طعامه.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'روتين الصباح 💩', 'هل غيّرتِ أول حفاض اليوم؟ يدل لون البراز وقوامه على صحة الأمعاء. سجّلي ذلك فورًا في متتبع الحفاضات!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'طاقة للنساء 🥗', 'الانشغال طوال اليوم متعب. لا تنسي نفسكِ! حضّري سلطة لذيذة تمنحكِ دفعة فورية من الطاقة، بالاستعانة بوصفاتنا الصحية للنساء.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'سحر الضوضاء البيضاء 🌧️', 'هل كان يومًا حافلًا بالنشاط؟ شغّلي صوت المطر من الضوضاء البيضاء في الغرفة، لينام رضيعكِ بسهولة وتلتقطي أنتِ أنفاسكِ.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'أحلى لحظة في اليوم 📸', 'هل قام اليوم بحركة غريبة ومضحكة؟ التقطي تلك اللحظة باستخدام الإطارات المرحة في جلسة تصوير الرضيع، وحوّليها إلى ذكرى تدوم مدى الحياة.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'هل مؤقت النوم مفعّل؟ ⏳', 'هل بدأتِ بتنويم طفلكِ؟ فعّلي المؤقت وحلّلي الوقت الذي يستغرقه للاستغراق في النوم، لتعرفي كيف يمكنكِ تحسين هذا الروتين.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'مساعدكِ الذكي 🤖', 'لماذا فقد طفلكِ شهيته فجأة؟ اكتبي هذا السؤال أو أي سؤال آخر يقلقكِ إلى Anacan AI، واحصلي فورًا على إجابة تستند إلى أسس علمية.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'اشحني طاقتكِ 🔋', 'هل أنتِ مستعدة ليوم حافل؟ اختاري لنفسكِ فطورًا شهيًا وغنيًا بالفيتامينات من بين الوصفات الصحية المخصصة للنساء.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'بحثًا عن الراحة 🍼', 'هل تبحثين عن أفضل كوب مانع للتسرب ليتمكن طفلكِ من الشرب باستقلالية؟ اطّلعي على الخيارات الأكثر تفضيلًا لدى الأمهات في قسم المنتجات الموصى بها.'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'أنتِ قادرة على ذلك! 💪', 'هل كان يومكِ صعبًا؟ أصغي إلى صوتكِ الداخلي في مفكرة الحالة المزاجية. تذكّري أن هذا مجرد يوم صعب، وليس حياة سيئة.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'تقرير التغذية 📊', 'سجّلي ما تناوله طفلكِ اليوم في أداة متابعة التغذية. لنرَ ما إذا كان قد حصل على جميع الفيتامينات الضرورية اليوم.'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'معجزة اليوم 🖼️', 'لمسة مميزة لليوم 520! حمّلي أغلى الصور وأكثرها طرافة إلى ألبوم طفلكِ، لتتذكريها بابتسامة بعد سنوات.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'طفرة في النمو؟ 📈', 'هل يبكي طفلكِ كثيرًا أو يعاني اضطرابًا في النوم؟ استشيري Anacan AI لمعرفة ما إذا كان يمر بأسبوع طفرة النمو في الشهر 17.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'يريد أن يأكل بنفسه! 🥦', 'هل يتوق طفلكِ إلى الاستقلالية؟ اختاري من قسم الوصفات وجبات شهية يسهل على الأطفال الذين بدأوا بتناول الأطعمة التكميلية إمساكها ولا تسبب الفوضى.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'التعامل مع العناد 🤖', 'هل يقول «لا» لكل شيء؟ إذا لم تعرفي كيفية التعامل مع نوبات الغضب في هذه المرحلة، فاستشيري Anacan AI فورًا.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'هل أصبحت الملابس ضيقة؟ 📏', 'هل تشعرين أن طفلكِ قد ازداد طولًا فجأة؟ أدخلي القياسات الجديدة في متتبع الوزن واطّلعي على مخطط النمو الصحي.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'مؤقت التغذية ⏱️', 'كم يستغرق طفلكِ في تناول الطعام؟ شغّلي مؤقت التغذية وراقبي نظام الوجبات لإتاحة الوقت الكافي لهضم الطعام بالكامل.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'قراءة مفيدة 📖', 'نام طفلكِ، فماذا ستفعلين الآن؟ اقرئي أحدث المقالات في قسم المدونات لتعزيز خبرتكِ في الأمومة.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'البحث عن كوب الشرب المثالي 🥤', 'هل تبحثين عن كوب شرب مريح ومقاوم للانسكاب؟ ألقي نظرة في قسم المنتجات الموصى بها على أكثر المنتجات التي جرّبتها الأمهات.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'استراحة قهوة ☕', 'هل ترغبين في الخروج من المنزل اليوم؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى يضم ركنًا للأطفال، وخصصي بعض الوقت لنفسكِ.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'التنفيس عن المشاعر 📝', 'ألم تَسِر الأمور اليوم وفق الخطة؟ لا تلومي نفسكِ. اكتبي ما يزعجكِ في دفتر يوميات المزاج لتخفيف ما يثقل ذهنكِ.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'لنراجع معدل النوم 😴', 'كيف نام طفلكِ ليلًا؟ راجعي سجلات مؤقت النوم لمعرفة ما إذا كان طفلكِ قد حصل على معدل نومه اليومي.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'ما الذي يقلقكِ؟ 🤖', 'هل لديكِ مخاوف بشأن نمو طفلكِ وتطوره؟ اكتبي إلى مساعدنا الخبير Anacan AI لتحصلي على إجابات علمية موثوقة وتطمئني.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'لكل وجبة مذاق مختلف 🍲', 'لا مزيد من الحيرة بشأن ما ستطبخينه اليوم. ستجدين في قسم الوصفات قوائم طعام متنوعة وصحية للأطفال الذين بدؤوا بتناول الأطعمة التكميلية.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'التقرير اليومي للإخراج 💩', 'لا تنسي تسجيل ذلك عند تغيير حفاض الصباح! تساعدكِ متابعة تغييرات الحفاض خلال اليوم على التأكد من أن طفلكِ يحصل على كمية كافية من السوائل.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'أنتِ أيضًا بحاجة إلى التغذية 🥗', 'هل أوشكت طاقتكِ على النفاد؟ حضّري عصير سموذي غنيًا بالفيتامينات من وصفاتنا الصحية للنساء. عليكِ أن تبقي قوية!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'ذكريات لا تُنسى 🖼️', 'حمّلي أجمل صوره إلى ألبوم طفلكِ واحتفظي بها في مكان آمن، لتبتسمي مستقبلًا وأنتِ تتأملين لحظاته اللطيفة اليوم.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'بماذا شعرتِ اليوم؟ 💖', 'مهما اشتد تعبكِ، يزول كل شيء حين تشمّين رائحته، أليس كذلك؟ دوّني مشاعركِ اليوم في يوميات المزاج وخذي قسطًا من الراحة.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'وجبات بالمؤقت ⏱️', 'هل يمكث طفلكِ طويلًا على مائدة الطعام؟ شغّلي مؤقت التغذية، والتزمي بالمدة المناسبة لتفادي فقدان الشهية.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'ألعاب الصباح 🧩', 'نتعلّم معًا! احرصي على قراءة مقالنا في قسم المدوّنة عن الألعاب التي تدعم التطور الذهني للأطفال بعمر 17.5 شهرًا.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', 'عناق «أحبكِ» 🫂', 'هل يأتي فجأة ليعانقكِ أو يداعب وجهكِ؟ لقد أصبح يعبّر عن حبه جسديًا. استمتعي بهذه اللحظة.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'مواساة الأب 🫂', 'عندما يستيقظ طفلكِ ليلًا، انهضي أنتِ مرة وليقم زوجكِ في المرة التالية. اقتسما المسؤولية بالتساوي تمامًا كفريق واحد.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'الاشتباه في الحساسية 🤖', 'هل قدّمتِ له طعامًا جديدًا ولاحظتِ احمرارًا على وجنتيه؟ قبل أن تقلقي، تعرّفي إلى الخطوات الأولى عبر Anacan AI.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'هل تشعرين بالضيق في المنزل؟☕', 'اعثري عبر الأماكن الصديقة للأمهات على أقرب مقهى يمكنكِ فيه تغيير الأجواء بينما يستمتع رضيعكِ بوقته.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'يفهم نبرة صوتكِ 🗣️', 'هل يتوقف وينظر إليكِ عندما تقولين «لا» بنبرة جادة؟ لقد أصبح يفهم المشاعر والمحظورات تمامًا. حافظي على الحدود.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل موعد النوم بساعة واحدة. لا يُفرَز الميلاتونين إلا في بيئة هادئة.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'معدل النوم الطبيعي ⏱️', 'حان وقت النوم! فعّلي مؤقت النوم. حلّلي المخطط للتأكد من أن طفلكِ يحصل على معدل نومه اليومي الطبيعي.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'ذكريات جميلة 📸', 'أضيفي أطرف حركة قام بها اليوم إلى ألبوم طفلكِ. بعد سنوات، ستتصفحين هذه اللقطات وتضحكين كثيرًا.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'كوب مانع للانسكاب 🥤', 'هل يحب شرب الماء أثناء الركض لكنه يبلّل ملابسه؟ تصفّحي في قسم المنتجات الموصى بها أكواب الشرب العملية التي اختارتها الأمهات.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'الملابس تصغر! 📏', 'هل أصبحت أكمام ملابس صغيركِ قصيرة مجددًا؟ أدخلي القياسات الجديدة في متتبّع الوزن، وتابعي بفخر زيادة الطول والوزن على مخطط النمو.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'وقت اللعب المستقل 🧸', 'أصبح الآن قادرًا على الانشغال بألعابه بمفرده لمدة 10-15 دقيقة. وهذا دليل على ازدياد مدة تركيزه. استمتعي بالهدوء.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'الطقس في الخارج غير واضح؟ ⛅', 'دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا يمكنكِ تقديرها من النافذة، وبالملابس المناسبة لطفلكِ.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي مع شريككِ تدليك الكتفين للتخلص من توتر اليوم. أنتما فريق واحد!'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'التحكم في الأصوات 🤫', 'النصف ساعة الأولى بعد استغراقه في النوم هي الفترة الأكثر حساسية. تحققي من مستوى الضوضاء باستخدام مقياس الصوت، واحذري الأصوات المفاجئة.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'طبيب أطفال سريع 🤖', 'هل تشعرين بالقلق بشأن التطور اللغوي لطفلكِ في عمر 18 شهرًا؟ اسألي الذكاء الاصطناعي من Anacan لتعرفي الكلمات المتوقعة في هذا العمر.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'اعتني بنفسكِ 🥗', 'هل أرهقكِ الركض وراء طفلكِ؟ اكتشفي سلطة شهية تمنحكِ طاقة فورية ضمن الوصفات الصحية للنساء.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'نظافة الصباح 🧻', 'كيف سار أول تغيير للحفاض اليوم؟ سجّلي بيانات الإخراج في التطبيق لتتبعي بسهولة أداء جهاز طفلكِ الهضمي.'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'كنز من الفيتامينات 🥦', 'راجعي قائمة طعام اليوم باستخدام أداة تتبّع التغذية. تنتظركِ في وصفات الأطفال حصص ملوّنة لتعويض الفيتامينات الناقصة!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'هل طفلكِ عنيد جدًا؟ 🤖', 'هل لا تفارق كلمة «لا» لسانه؟ احصلي من مساعد Anacan AI على نصائح نفسية قائمة على أسس علمية للتعامل مع نوبات غضب طفلكِ في عمر 17.5 شهرًا.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'أمسية مفعمة بالسكينة 🌊', 'حان وقت إضفاء الهدوء على الغرفة. شغّلي صوت أمواج المحيط من قسم الضوضاء البيضاء لمساعدة جهاز طفلكِ العصبي على الانتقال إلى النوم العميق.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'تحدّي مائدة الطعام ⏱️', 'هل تستغرق الوجبة وقتًا طويلًا؟ شغّلي مؤقّت التغذية للالتزام بالمدة المناسبة وتحليل أسباب ضعف الشهية.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'علاجكِ اليومي 📝', 'الأمومة أحيانًا أشبه برحلة حافلة بالتقلبات العاطفية. افتحي مفكرة المزاج، وعبّري في سطورها عن تعبكِ اليوم لتشعري بالراحة.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'حان وقت القهوة ☕', 'هل سئمتِ البقاء بين جدران المنزل؟ ابحثي ضمن الأماكن الملائمة للأمهات عن مقهى يمكنكِ زيارته براحة برفقة طفلكِ، وكافئي نفسكِ بوقت ممتع.'),
  ('e59af63b-a407-459e-a6f1-a0263d9f74f5', 'نجم صغير 🌟', 'لا تفوّتي هذه الابتسامة الجميلة! خلّدي مزاج طفلكِ اليوم باستخدام القوالب الممتعة في أداة جلسة تصوير الطفل.'),
  ('f71b2bf0-976d-4844-8538-db17781ce999', 'خصّصي وقتًا لنفسكِ 🍵', 'نام طفلكِ، والآن حان دوركِ لاستعادة عافيتكِ. حضّري شاي أعشاب مهدئًا من قسم الوصفات الصحية.'),
  ('4f770f32-235d-4481-acc9-8a3353f11910', 'ما الذي يشغل بالكِ؟ 🤔', 'هل يرفض طفلكِ الطعام فجأة؟ اطرحي أي سؤال عن الأمومة على Anacan AI، واحصلي فورًا على إجابة بدقة الخبراء.'),
  ('996b9423-cc50-4ec2-bbf6-02866083bb10', 'نوم هادئ بسهولة 🎶', 'ألا يستطيع طفلكِ النوم بعد يوم حافل بالاستكشاف والنشاط؟ اختاري صوت تهويدة من قسم الضوضاء البيضاء، واصنعي في الغرفة أجواءً من السكون الساحر.'),
  ('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b', 'استكشاف الطبيعة 🍂', 'سيكون الهواء النقي مفيدًا لكليكما. اعثري على حديقة جديدة في قسم الأماكن الملائمة للأمهات، ودعي طفلكِ يركض بحرية ويفرّغ طاقته.'),
  ('19f1aa58-50a6-4acf-b375-1d03850cfcb6', 'صوتكِ الداخلي 💖', 'لستِ مضطرة إلى أن تكوني أمًا مثالية؛ فأنتِ الأفضل لطفلكِ. دوّني مشاعركِ اليوم في مفكرة المزاج لتشعري بالراحة.'),
  ('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98', 'تجربة تناول الطعام باستقلالية ⏱️', 'هل يحاول طفلكِ تناول الطعام بنفسه؟ لا تقلقي بشأن الفوضى! شغّلي مؤقت التغذية، وتابعي المدة التي تستغرقها هذه التجربة المستقلة.'),
  ('f869363f-52a1-4240-a759-b2b999d347e4', 'حلوى صحية 🍪', 'لا حاجة إلى الحلويات الجاهزة من المتجر. حضّري من قسم الوصفات بسكويتًا سهلًا ولذيذًا وخاليًا من السكر لطفلكِ الذي بدأ بتناول الأطعمة التكميلية.'),
  ('91d67474-6689-4302-b69e-a9b260aedef7', 'اللعبة المناسبة 🧩', 'هل تبحثين عن لعبة تنمّي مهارات طفلكِ المنطقية؟ اكتشفي في قسم المنتجات الموصى بها خيارات مفيدة من الأحجيات (puzzle) المناسبة لعمره.'),
  ('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2', 'روتين الليل 🌙', 'يساعد وضع طفلكِ في الفراش في الموعد نفسه يوميًا على تكوين عادة نوم منتظمة. فعّلي مؤقت النوم، وتحققي من حصوله على القدر المناسب من النوم، واستمتعي بنوم هانئ.'),
  ('e8b020dc-c4fe-4f5b-946a-28ae84382a39', 'ننمو بصحة جيدة 📈', 'لم يتبقَّ الكثير على إتمام الشهر 18! حلّلي معدل نمو طفلكِ باستخدام أداة تتبع الوزن، وتحققي من أن طوله ووزنه ضمن المعدلات الطبيعية.'),
  ('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17', 'ختام يوم رائع 🖼️', 'خلّدي هذا اليوم المميز (540 يومًا!) بإضافة أكثر صورة مرحة ودافئة التقطتماها معًا إلى ألبوم طفلكِ.'),
  ('c1dc4453-41a2-40e6-812c-73fb934ccc70', 'أنتِ بطلة! ✨', 'إنه اليوم 540 من رحلة الأمومة! اكتبي إنجازكِ اليوم في Anacan AI، لتحصلي على جرعة تحفيز خاصة تضفي جمالًا على يومكِ.'),
  ('fa1d5820-5e14-435d-81d1-df116bd7de6f', 'مائدة العائلة 🍲', 'أصبح بإمكان طفلكِ الآن تناول الأطعمة نفسها التي تتناولينها. احسبي بسهولة القيمة الغذائية لوجباتكم المشتركة باستخدام أداة متابعة التغذية.'),
  ('ae531928-8e01-4e71-961a-63a517eaee5a', 'الانتقال إلى النوم العميق 🌙', 'فعّلي مؤقت النوم. إذا زاد استيقاظ طفلكِ ليلًا، فهدّئي جهازه العصبي بصوت أمواج المحيط من قسم الأصوات البيضاء.'),
  ('bacdcc71-8211-4dd5-b3af-c5af34fb468a', 'مفاجأة الصباح 💩', 'سجّلي ملاحظاتكِ عند تغيير حفاض اليوم الأول! فهذه أفضل طريقة لمتابعة صحة الجهاز الهضمي لطفلكِ خلال نموه ومدى حصوله على السوائل.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'ينفّذ الأوامر البسيطة 🧸', 'هل يذهب فعلًا لإحضار حذائه عندما تطلبين منه ذلك؟ مفرداته وقدرته على الفهم في ذروتهما! أشركيه أكثر في الألعاب.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'قدّري نفسكِ 👏', 'لا تنظري إلى فوضى الغرفة، بل إلى مدى سعادته اليوم. أنتِ أم رائعة بطريقة لا يمكن لأي كتاب أن يعلّمكِ إياها.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'تحليل النوم بالمؤقّت ⏱️', 'هل أصبحت قيلولته أقصر؟ شغّلي مؤقّت النوم، وحلّلي جدول هذا الأسبوع لإعادة ضبط موعد نومه مساءً.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'تبادلي الدعم مع شريككِ! 💖', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتحدّثا عمّا يثقل كاهلكما. دعمكما لبعضكما يخفّف العبء إلى النصف.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'شهية وقت الظهيرة 🥣', 'هل تناول طفلكِ ما يكفي من البروتين اليوم؟ أدخلي الأطعمة في أداة متابعة التغذية، وتأكدي من استيفاء احتياجه اليومي.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'قفزة في الذكاء 🧠', 'ما الذي يحدث في دماغ طفلكِ؟ اقرئي في قسم المدونة أحدث مقال عن التطور المعرفي لدى الأطفال بعمر 17-18 شهرًا.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'جدول النوم ⏱️', 'هل تغيّرت أوقات استيقاظ طفلكِ؟ راجعي إحصاءات مؤقّت النوم لتحليل التوازن بين نومه نهارًا وليلًا بدقة.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'تقرير الصباح 💩', 'الجهاز الهضمي هو أول مؤشر على الصحة. عند تغيير الحفاض، أضيفي ملاحظات الإخراج إلى التطبيق وتابعي التغيّرات على مدار اليوم.'),
  ('e207d666-c361-4203-8076-7ba835d4f015', 'ألا تفارق الملعقة يده؟ 🥄', 'فعّلي مؤقت التغذية. حلّلي المدة التي تستغرقها محاولات طفلكِ لتناول الطعام بمفرده، واطّلعي على احتياجاته الغذائية اليومية.'),
  ('35587de2-b62b-435c-aca4-01e72314423a', 'عبّري عمّا بداخلكِ 📝', 'ليست كل الأيام مثالية، وهذا طبيعي. اكتبي مشاعركِ اليوم في مفكرة المزاج، وتحرّري من التوتر واستريحي بهدوء.'),
  ('6dca6700-52a0-4818-812b-80dcc5c42de9', 'أتمّ طفلكِ 1.5 سنة رسميًا! 🎈', 'ينمو طفلكِ بسرعة خلال هذه الأشهر. أدخلي أحدث قياساته في متتبع النمو، وألقي نظرة بفخر على مخطط تطوره.'),
  ('da88924f-9b7a-4cc5-9b9e-429e9d903edd', 'كافئي نفسكِ ☕', 'الأمومة طوال 18 شهرًا ليست سهلة أبدًا! اعثري على مقهى مريح عبر خريطة الأماكن الصديقة للأمهات، واطلبي لنفسكِ كوبًا من القهوة الساخنة.'),
  ('6b77a02d-8882-4aed-be91-5f8ce3841671', 'هل أنتِ مستعدة للركض؟ 👟', 'الحذاء المناسب ضروري لخطوات طفلكِ الأولى الواثقة في الركض! اكتشفي في المنتجات الموصى بها موديلات الأحذية الطبية الأكثر إعجابًا لدى الأمهات.'),
  ('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e', 'لقطات لطيفة 📸', 'هل سقط وضحك أثناء الركض؟ أضيفي هذه اللحظة اللطيفة فورًا إلى ألبوم طفلكِ، وحوّليها إلى ذكرى ملوّنة تدوم مدى الحياة.'),
  ('e2aefd08-9263-41a3-87d4-c2d0378c7526', 'كيف هو مخزون الحديد؟ 🥩', 'استخدمي أداة متابعة التغذية للتحقق مما إذا كان طفلكِ قد حصل اليوم على ما يكفي من الحديد. وإذا كان هناك نقص، فاطّلعي على وصفات طفلكِ.'),
  ('48983c78-1769-4320-a7cf-ba470eef1415', 'حكاية خاصة 🪄', 'أنشئي في الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: مغامرات مستكشف بعمر 1.5 سنة.'),
  ('ffe1377d-426e-4c3f-a06d-3551b2ee446b', 'ألعاب تنمّي الذكاء 🧩', 'عمر 18 شهرًا هو الوقت المثالي للألعاب المنطقية. استكشفي في قسم المنتجات الموصى بها أحجيات ومكعبات مناسبة لعمره لتنمية ذكائه.'),
  ('10d89b1a-052c-42d7-9604-a8aa080e3159', 'بركة مائدة العائلة 🍲', 'يمكنه الآن أن يتناول الطعام معكم تمامًا! اختاري من قسم الوصفات عشاءً صحيًا مشتركًا مناسبًا للأطفال الذين بدؤوا بتناول الأطعمة التكميلية.'),
  ('25077620-39e7-49c9-abd7-7ee3d4c9f4a5', 'متابعة الأمعاء ⏱️', 'سجّلي التغيّرات على مدار اليوم في متتبّع الحفاضات، لتتمكّني بسهولة من تقييم ما إذا كان يحصل على ما يكفي من السوائل والألياف.'),
  ('94fb4891-ca2e-4e41-b663-ea23a832df89', 'سكينة صوت المطر 🌧️', 'قد يُرهق اليوم الحافل دماغه. شغّلي صوت المطر من قسم الضوضاء البيضاء لتهيئي في الغرفة أجواءً مثالية هادئة ومحفّزة على النوم.'),
  ('02d8aef9-6d63-4748-9f41-c063ee842eb2', 'أنتِ قادرة! 💖', 'عندما تشعرين بالتعب، افتحي مفكرة المزاج. اكتبي فيها ببساطة أنا قادرة على تجاوز كل شيء، ثم استريحي.'),
  ('04fca8dd-97bb-4af2-93b5-030f318cd3da', 'استكشاف الطبيعة 🌳', 'هل ضاق طفلكِ بجدران المنزل؟ ابحثي في قسم الأماكن الملائمة للأمهات عن حديقة واسعة وآمنة، وساعديه على تفريغ طاقته.'),
  ('7306940e-101e-4de4-af72-da4ab6736ad8', 'مؤقّت الوجبات ⏱️', 'هل يلهو بالطعام كثيرًا؟ شغّلي مؤقّت الرضاعة والتغذية، وقيّمي مدى ملاءمة الوقت الذي يقضيه على المائدة وشهيته للمعدلات الطبيعية.'),
  ('07b5d33a-c674-4dcc-a023-81e3746cb054', 'ألعاب المنطق 🧱', 'هل يضع 4-5 مكعبات فوق بعضها ويبني برجًا؟ سجّلي هذا الإنجاز الحركي في متتبّع النمو! ولا تنسي تشجيع محاولاته الهندسية الصغيرة.'),
  ('1bf2c33f-3711-4208-8da6-0a931502b566', 'ظلام تام 🌙', 'هل يقاوم طفلكِ النوم؟ حتى الضوء الخافت في الغرفة قد يشتت انتباهه. أطفئي الشاشات واجعلي الغرفة مظلمة تمامًا لتحفيز إفراز الميلاتونين.'),
  ('5f000b16-6031-438b-92a6-3ea1d69ae68b', 'هل خانتكِ ذاكرتكِ مجددًا؟ 🛒', 'هل نفدت حفاضات طفلكِ أم الزبادي؟ لا ترهقي ذهنكِ، بل أضيفي ما تحتاجينه فورًا إلى قائمة التسوق ليشتريه شريككِ عند عودته من العمل.'),
  ('8593e3b3-5794-49a0-a5ef-d04af1bd53a7', 'تفاصيل الكتب 📖', 'هل يقلب طفلكِ صفحات الكتاب ويشير بإصبعه إلى أدق التفاصيل في الصورة، مثل طائر صغير؟ سجّلي هذا الانتباه المعرفي في متتبع النمو. ذاكرته البصرية تعمل بشكل ممتاز!'),
  ('5df90283-8938-4f2c-bc5d-95fad0d0249f', 'لنراجع نظام النوم ⏱️', 'هل يرفض طفلكِ النوم مساءً؟ حلّلي مخطط مؤقت النوم. ربما تحتاجين إلى تقصير مدة قيلولته قليلًا.'),
  ('eb685812-a20b-4dfa-8dcd-a8c0865f1a25', 'طاقة الأم 🔋', 'لا تنسي نفسكِ! اختاري من الوصفات وجبة شهية غنية بالبروتين وسريعة التحضير لوجبة الصباح.'),
  ('f80fa225-e7f6-4b7d-a7da-b651f5688ba0', 'نوبات «لا!» 🛑', 'هل يعترض طفلكِ على كل شيء؟ استشيري مساعد Anacan AI حول عناد عمر 1.5 سنة لتحصلي على دعم نفسي وحلول مناسبة.'),
  ('bd224607-0812-4b81-8b5d-af59d7d7cc10', 'قنبلة من الفيتامينات 🥗', 'يجب ألا تنفد طاقة الأم! حضّري من وصفات النساء الصحية سموذي لذيذًا يمنحكِ طاقة فورية.'),
  ('c9435c7a-e56d-449f-9eb8-fae0dc263176', 'طقوس الاستعداد للنوم 🌙', 'شغّلي مؤقت النوم وأظلمي الغرفة. ومن خلال تحليل المخطط، يمكنكِ بسهولة تعويد طفلكِ على النوم في الوقت نفسه كل مساء.'),
  ('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0', 'يواصل النمو! 🌟', 'لقد تجاوز عمره 18 شهرًا! تبدأ مرحلة جديدة مع طفل يمشي بمفرده، ويعبّر عن مشاعره، وعنيد لكنه مفعم بالحب!'),
  ('cdca9fee-71e1-4e46-aea7-41734d6fa68a', 'انتكاسة النوم في عمر 18 شهرًا؟ 🥱', 'هل يقاوم النوم أو يستيقظ ليلًا؟ إنها انتكاسة النوم الشائعة في هذه المرحلة. احصلي من الذكاء الاصطناعي في Anacan على معلومات علمية حول هذه العملية البيولوجية.'),
  ('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03', 'إصرار «سأفعلها بنفسي!» 🛑', 'يريد أن يأخذ كل شيء بنفسه، حتى الأشياء الخطرة. كوني مستعدة لنوبة غضب عندما تنتزعينها منه. بدلًا من منعه، حاولي تحويل انتباهه إلى شيء أكثر إثارة للاهتمام.'),
  ('d6508b29-e914-4995-93c3-58c73e271159', 'التدليك والهدوء 💆‍♀️', 'هل يؤلمكِ ظهركِ من الركض طوال اليوم؟ بعد أن ينام طفلكِ، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. فأنتِ تستحقين ذلك!'),
  ('dd068a2e-5d54-49f1-be6d-02db7c690974', 'أنتِ على مضمار للركض 🏃‍♂️', 'هل يركض بسرعة من غرفة إلى أخرى ولا يتوقف؟ خلال هذه الفترة يكتمل تطور قدرته على التوازن أثناء الوقوف. أزيلي المخاطر الصغيرة من المنزل، واستمتعي بمشاهدة هذه اللحظات المفعمة بالطاقة من بعيد.'),
  ('d14775e1-8a41-4689-87c3-351bcaa01c87', 'ساحة الأب 👨‍👧', 'هل نفد صبركِ؟ أغلقي باب الغرفة واتركي طفلكِ مع والده. دعيه يتولى هذا المساء إدارة ساحة اللعب في المنزل.'),
  ('e1121d1f-a680-4fb9-9a1f-6792cb16e172', 'عداء الفاكهة 🍎', 'هل يرمي اليوم التفاحة التي أحبها بالأمس على الأرض؟ الانتقائية في الطعام من أكثر مشكلات هذا العمر شيوعًا. بدلًا من الضياع في الإنترنت، شاهدي أفكارًا ممتعة لتقديم الفاكهة ضمن الوصفات الصحية.'),
  ('ef76ecee-5471-407a-a72c-9593be1406af', 'حديث لا ينتهي 🗣️', 'هل يبدأ فور استيقاظه صباحًا بالثرثرة طويلًا بلغته الخاصة؟ يشهد مركز النطق لديه طفرة كبيرة. أنصتي إليه بجدية وأجيبيه: «حقًا؟» و«ماذا حدث بعد ذلك؟».'),
  ('be5acfb3-03f0-4bea-9e14-40b38bca8262', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا بمفردكِ تمامًا. أيقظي شريككِ أيضًا، فالعمل كفريق يعني تقاسم المسؤولية بالتساوي. هذه الليلة، دوره في تهدئة طفلكِ.'),
  ('fa9c7680-afc6-4095-9ec3-d56ad432d989', 'الحديقة أم المنزل؟ ⛅', 'تريدين الخروج، لكن الطقس متقلب. دعي مساعد الطقس والملابس يخبركِ ليس فقط بدرجة الحرارة، بل أيضًا بما ينبغي أن تُلبسيه لطفلكِ ليحميه من الرياح.'),
  ('b62665c0-5b12-4c5d-adfa-7b34000204cf', 'أصداء الضحكات 📸', 'تذكّري تلك اللحظة اللطيفة التي أضحكتكِ أكثر من غيرها اليوم، واحرصي على إضافتها إلى ألبوم طفلكِ في صورة أو مقطع فيديو قصير.'),
  ('e16b58bb-af8f-43a3-bf1f-c1d132a221a5', 'لا تقلقي 🤖', 'هل لاحظتِ سلوكًا غريبًا لدى طفلكِ؟ لا تنتظري حلول الليل، بل اكتبي فورًا إلى Anacan AI واطمئني.'),
  ('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4', 'احتياجكِ إلى الكالسيوم 🦷', 'استخدمي أداة متابعة التغذية لحساب كمية الكالسيوم التي حصلتِ عليها اليوم. واحرصي على تناول الكمية الموصى بها من منتجات الألبان لصحة العظام والأسنان.'),
  ('72bb2391-6fc4-4ef8-9352-3ae963d61f5b', 'الآن حان دوركِ 🥗', 'إذا نام طفلكِ، فتوجّهي إلى المطبخ! اكتشفي ضمن الوصفات الصحية للنساء سلطة غنية بالبروتين تمنحكِ الطاقة بسرعة.'),
  ('7c893844-8335-47b4-baf7-b21329be4554', 'أفرغي ما في داخلكِ 📝', 'هل كان يومكِ حافلًا بالضجيج؟ ستساعدكِ كتابة مشاعركِ في يوميات المزاج على تخفيف العبء الذهني.'),
  ('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a', 'هل صغرت الملابس مجددًا؟ 📏', 'من المتوقع حدوث طفرة في الطول بعد عمر 18 شهرًا. أدخلي القياسات الجديدة في متتبّع الوزن، وتأمّلي منحنى النمو بفخر.'),
  ('22efa7bf-186e-41c7-b46c-b75ce17b0a09', 'نظافة الصباح 💧', 'هل غيّرتِ أول حفاض اليوم؟ سجّلي بيانات الإخراج في التطبيق لتتمكّني بسهولة من متابعة ما إذا كان طفلكِ يحصل على ما يكفي من السوائل.'),
  ('37e7b0b1-141f-488d-99c8-a87bde73955f', 'معارك وقت الطعام 🥣', 'هل يرفض طفلكِ تناول الطعام؟ بدلًا من إجباره على الأكل، ضعي في طبقه خضراوات بألوان مختلفة لإثارة اهتمامه، واستلهمي أفكارًا جديدة من الوصفات الصحية.'),
  ('5ae1647c-ec81-4db7-838c-66f57619dd06', 'التحكّم في الضوضاء 🤫', 'عند الاستعداد للنوم، حافظي على مستوى مناسب من الضوضاء في الغرفة باستخدام مقياس الصوت. فتقطّع النوم ليلًا يؤثر في نمو طفلكِ وفي مزاجكِ صباحًا.'),
  ('2e177a88-e995-4df3-ae19-8a1044979006', 'أمسيات موسيقية 🎶', 'أسهل طريقة لتهدئة نوبات التذمّر في المساء هي تشغيل أغنية يحبها طفلكِ واحتضانه والرقص معه.'),
  ('82b5cb21-ea7e-4957-9166-81471c0b098a', 'لماذا يتصرّف هكذا؟ 🤖', 'هل بدأت نوبات الغضب المفاجئة من دون سبب واضح؟ استشيري Anacan AI فورًا وتعرّفي إلى الأساليب النفسية التي يوصي بها الخبراء.'),
  ('8aa141ab-420e-4a45-9eba-7dddd2430cb1', 'طاقة بلا سكر 🍌', 'هل يشتهي طفلكِ الحلوى بعد الظهر؟ حافظي على نظامه الغذائي باختيار وجبات خفيفة صحية من الموز والشوفان ضمن وصفات الأطفال.'),
  ('284e490f-ef18-407e-b320-432395edf56f', 'قائمة الاحتياجات لا تنتهي 🛒', 'هل نفد الشامبو أو الحفاضات أو الشوفان؟ لا تعتمدي على ذاكرتكِ؛ دوّنيها في قائمة التسوّق وزامنيها مع زوجكِ.'),
  ('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd', 'حان وقت الخروج من المنزل ☕', 'هل مللتِ من الروتين؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى يضم ركنًا للأطفال، واستمتعي بفنجان قهوة ساخن.'),
  ('ee049a04-c690-49d6-a1c7-d2c603be49d5', 'الاستغراق في النوم مع حكاية 🪄', 'أنشئي حكاية مميزة في قسم الحكايات الذكية، واقرئيها لطفلكِ.'),
  ('46fbf80f-0604-494d-b68e-60f85488090d', 'يأكل بنفسه! 🥣', 'ألا يترك الملعقة من يده؟ شغّلي مؤقت التغذية لتتبّعي مدة الوجبة وتتأكدي من تناوله الكمية المناسبة.'),
  ('5174db8a-22d1-41db-af86-5a575522337a', 'الرسومات الأولى 🖍️', 'هل بدأ طفلكِ بالشخبطة؟ اطّلعي على أفضل خيارات الألوان الآمنة والقابلة للغسل في قسم المنتجات الموصى بها.'),
  ('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b', 'الفنان الصغير 📸', 'هل تلطخت ملابسه بالألوان؟ بدلًا من الانزعاج، خلّدي هذه اللحظة الطريفة باستخدام الإطارات المرحة في قسم جلسة تصوير الطفل.'),
  ('2d802010-e9c4-4370-b595-862f19214f3d', 'مخزون الكالسيوم 🧀', 'الكالسيوم ضروري للأسنان والعظام. استخدمي أداة متابعة التغذية للتأكد من حصول طفلكِ اليوم على الكمية الموصى بها من منتجات الألبان.'),
  ('739069ab-a4c7-4cc9-ae84-572e67836bd2', 'أجمل لحظات اليوم 🖼️', 'هل تتذكرين الحركة التي أضحكتكِ أكثر من غيرها اليوم؟ حمّليها الآن إلى ألبوم طفلكِ واحتفظي بها للمستقبل.'),
  ('faac9718-e68e-455d-90e4-e34b7b38a24e', 'تطوّر الذكاء 🧠', 'احرصي على قراءة المقال الجديد في قسم المدوّنات عن العمليات المذهلة التي تحدث في أدمغة الأطفال بعمر 1.5 سنة.'),
  ('2155f722-dd8c-49ec-a515-ecee85476474', 'توازن الصباح 🧻', 'هل سجّلتِ أول حفاض لطفلكِ اليوم في التطبيق؟ يساعد لون الإفرازات وقوامها على معرفة ما إذا كان طفلكِ يحصل على كمية كافية من السوائل.'),
  ('1e433a5c-ee68-4089-bf86-5ce74fde7136', 'ألعاب المنطق 🧩', 'مع اقتراب طفلكِ من عمر 18.5 شهرًا، يحين الوقت المثالي لألعاب المنطق. اكتشفي في قسم المنتجات الموصى بها أحجيات ومكعبات مناسبة لعمره.'),
  ('9d69d283-cfae-47a2-a874-8fabcc20a7f1', 'معدل النمو 📈', 'حلّلي معدل نمو طفلكِ باستخدام أداة متتبع النمو، وتابعي عبر الرسم البياني مدى توافق طوله ووزنه مع المعدلات الطبيعية.'),
  ('a242b14e-b434-493a-ab87-b2064aedfc9e', 'مغامر حقيقي 📸', 'أضيفي إلى ألبوم الطفل أطرف صورة التقطتِها لطفلكِ أثناء التسلق أو اللعب والركض، وحوّليها إلى ذكرى جميلة.'),
  ('465d0258-9df5-4a0a-9902-79a09218dcc5', 'أتمَّ 19 شهرًا! 🎂', 'تهانينا! لقد مرّ 19 شهرًا كاملًا منذ الولادة! اختاري الآن ملصقًا مميزًا من جلسة تصوير الطفل وشاركي هذه الفرحة في مجتمع Anacan!'),
  ('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4', 'أصداء الضحكات 📸', 'أضيفي إلى ألبوم الطفل أطرف صورة التقطتِها لطفلكِ أثناء التسلق أو اللعب والركض، وحوّلي تعب اليوم إلى ابتسامة.'),
  ('ccbbf1c0-789d-4a84-96bd-cdb04c618d13', 'لنتابع نموه 📈', 'ازداد نشاط طفلكِ البدني، لكن هل زيادة وزنه ضمن المعدل الطبيعي؟ حلّلي معدل نموه باستخدام أداة متتبع الوزن وبدّدي مخاوفكِ.'),
  ('0671a41f-8a24-4dff-87f0-008aa3abfc3d', 'كيف حال جهازه الهضمي؟ 💩', 'عند تغيير الحفاض، أضيفي سجلات التبرز إلى التطبيق. وراقبي بسهولة تأثير الأطعمة الغنية بالألياف في هضمه على مدار اليوم.'),
  ('d414aad6-2d3e-4a62-a555-9241874e68b3', 'جدول النوم ⏱️', 'حان وقت النوم! شغّلي مؤقت النوم وحلّلي نمط طفلكِ للتأكد من حصوله على عدد ساعات النوم اليومية الموصى بها.'),
  ('67ef78f2-7b35-47be-a6f4-6368c3a37a84', 'تحدّي مائدة الطعام ⏱️', 'هل يمكث طفلكِ طويلًا على المائدة ويلعب بالطعام؟ فعّلي مؤقّت الوجبات وابدئي بتحليل أسباب فقدان الشهية.'),
  ('d9b69a33-09da-4d7d-98e9-ac3acd553715', 'انتكاسة النوم؟ 🤖', 'هل يستيقظ طفلكِ كثيرًا ليلًا؟ اكتشفي فورًا ما إذا كان السبب طفرة في النمو عبر مراسلة خبير الذكاء الاصطناعي في Anacan.'),
  ('283507fe-ca12-4764-a828-61d9a9f30424', 'أنتِ بطلة 💖', 'لستِ مضطرة إلى أن تكوني مثالية. اكتبي ببساطة أنا قادرة على التعامل مع كل شيء في مذكّرات المزاج، ثم استريحي.'),
  ('290e0f59-3a24-4f74-9a01-c478f55efce5', 'مغامرة في الهواء الطلق 🌳', 'لم تعد جدران المنزل تتّسع لطاقته. ابحثي عن حديقة واسعة وآمنة ضمن الأماكن الملائمة للأمهات، وساعديه على تفريغ طاقته.'),
  ('d9528425-30f7-4a4a-ac0d-053206658d00', 'حافظي على طاقتكِ 🔋', 'هل أرهقكِ الركض؟ اختاري من الوصفات الصحية للنساء فطورًا شهيًا يمنحكِ الطاقة فورًا.'),
  ('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b', 'القيلولة ⏱️', 'فعّلي مؤقّت النوم. حدّدي مواعيد القيلولة بدقة لتتمكّني من تنظيم الانتقال إلى النوم مساءً بسهولة.'),
  ('1b9ea296-6f6b-4447-9f45-4c6548d5e543', 'مائدة العائلة 🍲', 'أصبح بإمكان طفلكِ الآن تناول الأطعمة نفسها التي تتناولونها. احسبي بسهولة القيمة الغذائية لوجباتكم المشتركة باستخدام أداة متابعة التغذية.'),
  ('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0', 'أمواج تبعث على الهدوء 🌊', 'هل يعجز طفلكِ عن النوم بعد يوم حافل بالاكتشافات النشطة؟ اختاري صوت أمواج المحيط من الضوضاء البيضاء، واصنعي في الغرفة سكونًا ساحرًا.'),
  ('fbbb1355-d1ac-4efe-b9c7-1746b97b1656', 'لا يريد المشاركة؟ 🤖', 'هل يرفض مشاركة لعبته في الحديقة ويصرخ؟ تعرّفي مع Anacan AI إلى كيفية التعامل مع هذا الموقف وطبّقي النصائح.'),
  ('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e', 'مفاجأة الصباح 💩', 'هل غيّرتِ أول حفاض اليوم؟ سجّلي بيانات الإخراج في التطبيق لمتابعة صحة الجهاز الهضمي وكمية السوائل التي يتناولها طفلكِ عن كثب.'),
  ('b32e8863-be99-483a-aff4-94fc82f554bc', 'بدأ مؤقّت النوم! ⏱️', 'حان وقت الروتين المسائي. شغّلي المؤقّت وحلّلي بسهولة كيف يؤثر اليوم الحافل بالنشاط في الوقت الذي يستغرقه طفلكِ حتى ينام.'),
  ('f0fc96ac-776c-4e66-bacf-461eff128cbc', 'أطباق ملوّنة 🥦', 'ألا يأكل طفلكِ الخضراوات؟ إذا كان قد بدأ بتناول الأطعمة التكميلية، فاستفيدي من طرق التقديم الجذابة في الوصفات لإكمال الحصة الموصى بها في أداة متابعة التغذية بطريقة ممتعة.'),
  ('4673b81e-675b-4232-a5ca-c06aa26d504d', 'طاقة الأم 🔋', 'هل استنزف الركض طوال اليوم طاقتكِ؟ لا تنسي نفسكِ! حضّري من وصفاتنا الصحية عصير سموذي غنيًا بالبروتين يمنحكِ دفعة فورية من الطاقة.'),
  ('7a2ab463-526e-46c6-a246-3494b6c46fa9', 'صباح صعب؟ 🌪️', 'نوبات العناد مرهقة. خذي نفسًا عميقًا واسألي Anacan AI فورًا عن كيفية التعامل مع هذا الموقف.'),
  ('c995af30-30f9-4eaf-a66c-3d0d65fc825b', 'أنصتي إلى صوتكِ الداخلي 📝', 'نام طفلكِ. افتحي الآن مفكرة المزاج، وأفرغي مشاعركِ اليوم في تلك السطور التي لن يقرأها أحد لتشعري بالارتياح.'),
  ('0aa2cefc-f18c-4c10-98d6-e4dfda22198e', 'صوت مهدّئ 🌧️', 'ألا يستطيع طفلكِ النوم بعد يوم حافل بالاكتشافات الجديدة؟ شغّلي صوت المطر من قسم الضوضاء البيضاء لتهدئة جهازه العصبي بصورة طبيعية.'),
  ('a57c041d-751b-4413-a98e-ee1564a86127', 'هواء نقي وطاقة متجددة 🌳', 'هل أصبحت جدران المنزل تضيق بطفلكِ؟ ابحثي ضمن الأماكن الصديقة للأم عن حديقة جديدة تضم ألعابًا متنوعة، وساعديه على تفريغ طاقته.'),
  ('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc', 'قفزة ذهنية 🧠', 'ماذا يحدث في دماغ طفلكِ في عمر 18.5 شهرًا؟ اقرئي أحدث مقال في قسم المدونات واكتشفي مراحل تطوره.'),
  ('108adc32-ab84-4dcd-be8c-e7597e84aa99', 'هل يمكث طويلًا على المائدة؟ ⏱️', 'بدأت مرحلة اللعب بالطعام. فعّلي مؤقت الوجبات وحلّلي مدة تناول الطعام للمساعدة على تجنب فقدان الشهية.'),
  ('36ae8436-7cda-46ec-b16d-44295bf2f7bc', 'هل صغرت ملابسه مجددًا؟ 📏', 'هل تشعرين بأنه ازداد طولًا فجأة؟ أدخلي القياسات الجديدة في متتبع النمو، وشاهدي بفخر منحنى نموه وهو يرتفع.'),
  ('909b1a9f-36d9-4ba3-a481-ae0e711ea145', 'لقطات لطيفة 📸', 'هل يحاول القفز أو الرقص؟ زيّني هذه اللحظة بالإطارات المرحة في جلسة تصوير الطفل، واصنعي ذكرى تدوم مدى الحياة.'),
  ('049ab226-ff27-4f2f-a64f-85d2b588c035', 'هل يمكن أن يكون ألم التسنين؟ 🤖', 'هل يعاني طفلكِ من فقدان الشهية أو البكاء دون سبب واضح؟ اطلبي رأي Anacan AI المتخصص حول علامات ظهور الأضراس.'),
  ('0e73fb38-1702-4d44-8a47-bf821e795ce5', 'خطوات آمنة 👟', 'أصبح يركض بسرعة أكبر! تصفحي أفضل موديلات أحذية تقويم العظام في قسم المنتجات الموصى بها، لدعم خطواته الأولى الواثقة.'),
  ('2606521b-da76-4e40-8b9b-74eaed8f4900', 'إرث للمستقبل 🖼️', 'هل أضفتِ إلى ألبوم الطفل تلك الحركة التي أضحكتكِ كثيرًا اليوم؟ حتى لو امتلأت ذاكرة هاتفكِ، ستظل ذكرياتكِ محفوظة دائمًا.'),
  ('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7', 'انتكاسة النوم؟ ⏱️', 'هل يستيقظ طفلكِ كثيرًا ليلًا؟ راجعي مخطط مؤقت النوم. إذا كانت قيلولته النهارية طويلة جدًا، فقد حان الوقت لتقليل مدتها قليلًا.'),
  ('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9', 'مخزون الكالسيوم 🧀', 'الكالسيوم ضروري للأسنان والعظام. استخدمي أداة متابعة التغذية للتأكد من تناولكِ الحصة اليومية الموصى بها من منتجات الألبان.'),
  ('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11', 'التوازن اليومي 💧', 'لا تنسي تسجيل ذلك عند تغيير حفاض طفلكِ ظهرًا! يشير معدل التبول والتبرز إلى احتياجاته من السوائل المرتبطة بنشاطه، وإلى حالة جهازه الهضمي.'),
  ('44008632-a96c-4f5e-a936-9b65273a2264', 'الآن حان دوركِ 🥗', 'هل خلد طفلكِ إلى قيلولته النهارية؟ توجهي إلى المطبخ! حضّري لنفسكِ وجبة شهية من وصفاتنا الصحية المخصصة للنساء.'),
  ('868f8ace-292a-4cf1-9abe-4b2da08aca3f', 'استراحة قهوة ☕', 'هل أرهقتكِ الأعمال المنزلية والروتين؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى يحتوي على ركن للأطفال. فمن حقكِ الطبيعي تمامًا أن تستمتعي بفنجان قهوة ساخن.'),
  ('f7b08a7d-5067-40df-81d3-421be952c00e', 'لا وجود للأم المثالية 💖', 'إذا لم يسر كل شيء اليوم وفقًا للخطة، فلا تلومي نفسكِ. دوّني ما يثقل صدركِ في مفكرة المزاج وخذي نفسًا عميقًا.'),
  ('58a79bee-96dd-429b-a570-14dc6d97d91a', 'أمواج مهدئة 🌊', 'يحتاج دماغ طفلكِ بعد فرط التحفيز إلى بعض الهدوء. هدّئيه بتشغيل صوت أمواج المحيط من مجموعة الضوضاء البيضاء في الغرفة.'),
  ('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1', 'مرحلة «ما هذا؟» 🤖', 'هل تدهشكِ أسئلة طفلكِ التي لا تنتهي وشغفه بالاكتشاف؟ تعرّفي إلى هذه القفزة المعرفية من خلال مساعدنا Anacan AI.'),
  ('f8ad5a51-f4c3-4fc4-8170-0775df79fe84', 'يريد أن يأكل بنفسه 🥣', 'ألا يترك الملعقة من يده؟ شغّلي مؤقت التغذية، وتابعي مدة الوجبة، واختاري من وصفات الأطفال أطعمة يسهل عليه إمساكها.'),
  ('995604f6-97b2-4fe5-91ea-98f2248c1b28', 'مخزون البروتين 🥚', 'البروتين ضروري لعضلات طفلكِ الصغير كثير الحركة! استخدمي أداة متابعة التغذية لتقييم توازن غذائه اليومي وتعويض أي نقص.'),
  ('ec6ff433-9523-4a66-a427-b2548807345b', 'الانتباه والذاكرة 🧠', 'كيف يتعلم طفلكِ؟ اقرئي في قسم المدونات بتطبيقنا المقالة التي تتناول تطور الانتباه والذاكرة بعد عمر 1.5 سنة.'),
  ('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855', 'نهاية اليوم 🌙', 'حان وقت النوم! شغّلي مؤقت النوم، وسجّلي نمط نوم طفلكِ للتأكد من حصوله على كفايته اليومية، ثم استريحي.'),
  ('0bcc42e9-f88e-427d-8d6d-562c3e7e7138', 'مهمة البروكلي! 🥦', 'هل يرفض الخضراوات؟ لا تقلقي. اكتشفي في وصفات الأطفال كيف تُخفين البروكلي داخل فطائر شهية.'),
  ('2e502c2f-240e-4506-a102-a80013f7742b', 'صارحي نفسكِ 🛋️', 'هل شعرتِ اليوم بإرهاق شديد ورغبتِ في ترك كل شيء؟ هذا طبيعي! افتحي يوميات المزاج، واكتبي أحتاج إلى الراحة، وخصّصي هذا المساء لنفسكِ فقط.'),
  ('530196ff-adb2-4ae9-a06d-67bb4bfd998f', 'هل يظل الحفاض جافًا مدة أطول؟ 🧻', 'تحققي من حفاض الصباح. إذا ظل جافًا لأكثر من 2 ساعتين، فقد تكون هذه أول إشارة إلى استعداد طفلكِ للتدريب على استخدام المرحاض! أدخلي ملاحظاتكِ في متتبع الحفاضات وراجعي الإحصاءات.'),
  ('057998e1-6566-4f75-aa40-70a38d334aee', 'توازن السوائل لدى الأم 💧', 'هل نسيتِ شرب الماء وأنتِ تركضين خلف طفلكِ؟ قد يكون هذا سبب الصداع. استعيدي طاقتكِ بتحضير مياه الديتوكس من قسم الوصفات الصحية.'),
  ('fec1f9db-8b95-410a-b753-aded5a7dc606', 'هل يخاف من الظلام؟ 🌌', 'هل يبكي أو يشعر بالقلق عند إطفاء نور الغرفة؟ شغّلي له صوت الرحم (نبضات القلب) من قسم الضوضاء البيضاء، لتمنحيه ذلك الشعور المألوف والدافئ بالأمان.'),
  ('5c635a69-e5ff-42eb-9277-29e39d9986fa', 'تنظيف الأسنان ممتع! 🪥', 'ألا يسمح لكِ بتقريب الفرشاة من فمه؟ تصفّحي فراشي الأصابع أو النماذج المضيئة والموسيقية في قسم المنتجات الموصى بها، وحوّلي روتين النظافة هذا إلى لعبة ممتعة.'),
  ('f2a19104-ece3-4a8f-9966-8cad392a68af', 'هدوء الليل 🍵', 'نام طفلكِ وتوقّف المؤقّت. الآن ليس وقت الركض، بل وقت الراحة. حضّري شاي البابونج من قسم الوصفات الصحية، واستمتعي بالهدوء التام.'),
  ('f524b282-4173-4386-b8dd-255261b77d1d', 'سأرتدي ملابسي بنفسي! 👕', 'هل تتحول لحظات ارتداء الملابس صباحًا إلى معركة كبيرة؟ اقرئي في قسم المدوّنات طرقًا عملية للتعامل مع نوبات الغضب أثناء ارتداء الملابس من خلال منح طفلكِ خيارات.'),
  ('46919051-4727-4a43-8ba3-d5a1f5451c16', 'نوبة صراخ كبيرة في المتجر؟ 🛒', 'هل يرتمي طفلكِ على الأرض في مكان عام لأنكِ لم تشتري له ما يريد؟ لا تكترثي لنظرات الآخرين، وتحدّثي إلى Anacan AI لتحصلي على الدعم وتتمكّني من الحفاظ على هدوئكِ في تلك اللحظة.'),
  ('874df706-e26e-4b72-a02c-7f8309fc95d5', 'جمل من كلمتين! 🗣️', 'هل كوّن اليوم عبارة جديدة مثل «ماما تعالي» أو «ارمي الكرة»؟ سجّلي هذا التطور اللغوي الرائع فورًا في ألبوم طفلكِ على هيئة مقطع فيديو بالصوت.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('af368cd3-f751-4611-9e47-9c8fda037ebd'::uuid, 'مهارات الأصابع الحركية قيد التطور! 🧩', 'دعيه يتناول البازلاء أو الذرة أو قطع الفاكهة بنفسه. فهذا ينمّي المهارات الحركية الدقيقة. تابعي حجم الحصة باستخدام أداة متابعة التغذية.'),
  ('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323', 'دعم المناعة! 🍊', 'هل يتغير الطقس؟ احسبي كمية فيتامين C التي تناولها طفلكِ اليوم باستخدام أداة متابعة التغذية، وأضيفي إلى قائمته الحمضيات أو الكيوي أو الفلفل الملوّن.'),
  ('031932e3-d91b-494c-9f35-dc03d53026b4', 'هل أصبح حذاؤه ضيقًا؟ 👟', 'هل يتعثر كثيرًا أثناء الركض مؤخرًا؟ ربما كبرت قدمه! أدخلي مقاس حذائه الجديد وقياسات طوله في متتبع الوزن لتحليل معدل نموه.'),
  ('db0a30ff-e18a-4830-abdc-881dc8827a75', 'غذاء الدماغ: أوميغا-3 🐟', 'السمك مهم لتعزيز نمو الذكاء. إذا كان رضيعكِ قد بدأ بتناول الأطعمة التكميلية، فحضّري له من قسم الوصفات أقراص سمك شهية خالية من العظام ومخبوزة في الفرن.'),
  ('eb71840a-d8fc-43f9-897d-715c008b72b7', 'حان وقت التهدئة! 🌙', 'لقد وصل يومه المليء بالنشاط إلى نهايته. فعّلي مؤقت النوم، وأوقفي ألعاب الركض والمطاردة وانتقلي إلى أنشطة مهدئة، مثل تركيب الأحجية.'),
  ('36d9b82f-d63f-40d9-bafa-df3b3dc844b9', 'وجبة شهية في 5 دقائق! 🥗', 'هل تتناولين وجبة خفيفة على عجل وقت الظهيرة؟ حضّري من قسم الوصفات الصحية للنساء خبزًا محمصًا بالأفوكادو والبيض ليمنحكِ الشبع والطاقة.'),
  ('5db92d40-f36e-4671-8f65-a3cb3f1c91ed', 'اكتشافات فيزيائية في حوض الاستحمام 🛁', 'أضيفي إلى ألبوم طفلكِ صورة لتعبيره الجاد والمركّز وهو يسكب الماء من كوب بلاستيكي إلى آخر، فلحظات الاكتشاف الصغيرة هذه لا تُنسى!'),
  ('e18f3a19-4a7e-44e4-9703-5c88f6dda037', 'هل يقضي وقتًا طويلًا أمام الشاشة؟ 📱', 'هل يؤدي أخذ الهاتف من يده إلى نوبة غضب كبيرة؟ تعلّمي من Anacan AI كيفية الحد من وقت الشاشة دون توتر ووضع حدود صحية.'),
  ('2c1e9be8-ccf0-412a-a942-30cea5075e5b', 'حان وقت التواصل الاجتماعي! 👶', 'بات طفلكِ يتوق إلى الوجود مع أطفال آخرين في المكان نفسه. استكشفي من قسم الأماكن الملائمة للأمهات مكانًا يضم مركزًا لألعاب الأطفال وأسعديه.'),
  ('cb4b4d68-2b36-4d3f-aa77-92d10314464f', 'طعام جديد، ورد فعل جديد 💩', 'هل تناول بالأمس طعامًا مختلفًا أو قد يسبب الحساسية؟ راقبي برازه عند تغيير حفاضه صباحًا، وسجّلي في التطبيق أي تغيّرات في اللون أو القوام لمتابعة حالته.'),
  ('29452fba-ed37-4bde-8e72-45e1f9c46d4d', '10 دقائق حتى النوم... ⏱️', 'شغّلي مؤقت النوم وأظلمي الغرفة. اختاري أصوات الغابة من قسم الضوضاء البيضاء، واجعلي الانتقال إلى النوم تجربة ساحرة لطفلكِ ولكِ أيضًا.'),
  ('fa637a9e-0a58-4301-a5dd-89fb27cdb46b', 'وحش المعكرونة! 🍝', 'هل اتّسخت ملابسه وحتى شعره بينما كان يأكل بمفرده؟ لا تفوّتي هذه اللحظة الطريفة! زيّني الصورة بالإطارات المرحة في جلسة تصوير طفلكِ وأضيفيها إلى الألبوم.'),
  ('44418a3d-932e-44e2-832c-c9fdeea34df1', 'الضرب والعضّ؟ 🛑', 'قد تتحول المشاعر التي لا يستطيع التعبير عنها أحيانًا إلى سلوك عدواني. اسألي Anacan AI عن كيفية التعامل مع العضّ والضرب في هذه المرحلة العمرية.'),
  ('4a287257-0f36-49cd-93f7-28a1154386a6', 'كيف ينشأ حب الكتب؟ 📖', 'هل تقرئين لطفلكِ قبل النوم؟ اقرئي في قسم المدونات قواعدنا الذهبية التي تساعدكِ على تحبيب الكتب إليه والحفاظ على تركيزه في صفحاتها.'),
  ('f9f77164-bd35-4d6c-83ca-1991fcf7701a', 'اكتشافات جديدة ومخاطر ⚠️', 'لقد أصبح يتسلق كل شيء! لتعزيز سلامة المنزل، احرصي على الاطلاع على واقيات حواف الأثاث الناعمة في قسم المنتجات الموصى بها.'),
  ('66297752-072e-4e90-afa0-bfdfc587176c', 'كيف هو مخزون الحديد؟ 🥩', 'حتى لا يصاب طفلكِ النشيط بفقر الدم ويحافظ على طاقته، تحققي من كمية الحديد التي تناولها اليوم عبر أداة متابعة التغذية، واستكملي أي نقص.'),
  ('802d0f46-e525-43d0-8f5c-440b82228035', 'العلاج بالرمل وأوراق الشجر 🍂', 'اخرجي من بين جدران المنزل الأربعة! ابحثي في قسم الأماكن الصديقة للأم عن حديقة تضم مساحة رملية أو مسطحات خضراء واسعة، وادعمي نمو طفلكِ الحسي.'),
  ('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618', 'تخلّي عن السعي إلى الكمال ✨', 'هل رفعتِ صوتكِ على طفلكِ اليوم؟ لا تؤنّبي ضميركِ. اكتبي ما يثقل صدركِ في يوميات المزاج، وسامحي نفسكِ واستعدّي ليوم جديد غدًا.'),
  ('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee', 'مصمم الأزياء الصغير في العمل! 👗', 'هل يرغب طفلكِ في اختيار ملابسه بنفسه ويرتدي ألوانًا غير متناسقة؟ زيّني هذه الإطلالة الطريفة بالملصقات المرحة في جلسة تصوير الطفل، وحوّليها إلى أطرف لقطة في الألبوم.'),
  ('f830cd97-a8bb-4789-bdc5-7806bcd89cfe', 'فرط الاستثارة 🎇', 'قد يصعب على الدماغ شديد النشاط نهارًا أن يهدأ ليلًا. شغّلي صوت مجفف الشعر أو المروحة من قسم الضوضاء البيضاء، ولاحظي كيف يساعد هذا الصوت الرتيب طفلكِ على الهدوء.'),
  ('f8565841-4602-47d5-af45-99f7dea5b129', 'أعسر أم أيمن؟ 🤚', 'بأي يد يمسك الملعقة؟ احرصي على الاطلاع على مقالنا العلمي الجديد في قسم المدونات لمعرفة كيف ومتى تتحدد اليد المهيمنة.'),
  ('1915583e-53f5-46af-8212-835dfd587e22', 'هل ما زال شعركِ يتساقط؟ 💇‍♀️', 'لا يزال جسمكِ في مرحلة التعافي. اعتني بنفسكِ اليوم باختيار وجبة فطور غنية بالزنك والبيوتين من قسم الوصفات الصحية للنساء.'),
  ('cfbeabf3-def0-4cbe-a106-fd34987dd776', 'مرحلة الآلات الموسيقية 🥁', 'هل يحب طفلكِ قرع الأواني بالملاعق الخشبية؟ اطلعي في قسم المنتجات الموصى بها على آلات الإكسليفون والطبول ذات مستوى الصوت الآمن لأذن الطفل.'),
  ('daa6a0d6-25d4-401e-ba81-8a8ca5108695', 'أولى محاولات تقليد أصوات الحيوانات 🐮', 'هل يحاول طفلكِ تقليد صوت الكلب أو القطة عند رؤيتهما؟ أضيفي هذا التطور المعرفي الرائع إلى ألبوم الطفل في مقطع فيديو قصير لتخليد هذه الذكرى.'),
  ('2ed7fd17-90ba-451d-9c88-a1f94a180fe0', 'انخفضت الشهية، فماذا عن الوزن؟ 📉', 'يزداد الانتقائية في الطعام خلال هذه الأشهر. أدخلي القياسات الحالية في متتبع الوزن، واطمئني فورًا عندما ترين أن نمو طفلكِ يسير ضمن المعدل الطبيعي تمامًا.'),
  ('50209dd4-d2d7-4719-bf4e-21df8c72686a', 'طقوس الاستعداد للنوم 🧸', 'اتبعي الترتيب نفسه كل مساء! شغّلي مؤقت النوم، وساعدي طفلكِ على توديع دبه المحبوب قبل النوم، ولاحظي كيف يسهّل هذا الروتين الثابت الانتقال إلى النوم.'),
  ('cc01349a-6eef-4c61-aa08-b3f505c2eb5f', 'معركة «سآكل بنفسي!» 🥣', 'إذا سمحتِ له بالأكل بنفسه، تناثر الطعام في كل مكان، وإذا لم تسمحي له، بدأ بالصراخ. تعلّمي فورًا كيفية التعامل مع هذه المرحلة بلا توتر من خلال النصائح النفسية التي يقدمها Anacan AI.'),
  ('3abde512-ebd4-4cf1-986e-fb1953695f78', 'درع مناعة ملوّن 🛡️', 'استخدمي أداة متابعة التغذية للتحقق مما إذا كان طفلكِ قد حصل اليوم على ما يكفي من فيتامين C. واستعيني بوصفات الرضّع لتحضير أطباق بالخضراوات البرتقالية والحمراء.'),
  ('56129e04-2f90-42b1-b51e-b835940e284e', 'تحرّري من العبء الذهني 🧘‍♀️', 'عليّ فعل هذا أيضًا، ويجب أن أطهو ذاك أيضًا... هل لا يتوقف ذهنكِ؟ اكتبي جميع خططكِ ومخاوفكِ في مفكرة المزاج. فتدوينها في قائمة يخفف التوتر فورًا.'),
  ('deb6cbd4-3a89-4915-9bdf-626d87829918', 'حب الماء والطين 💦', 'لا تخشي أن تتسخ ملابسه! ابحثي عن مكان مفتوح في قسم الأماكن الصديقة للأمهات، ودعيه يتواصل مع الطبيعة ويستمتع بتجربة حسية ثرية تدعم نموه.'),
  ('1576f605-27d8-4159-b3bd-3dd9e63c91dd', 'سوائل وفيرة لهضم أسهل 💧', 'قد يؤدي الانتقال الكامل إلى الأطعمة الصلبة أحيانًا إلى صعوبة الهضم. دوّني ملاحظاتكِ في متتبّع الحفاضات لتحددي بسهولة ما إذا كان طفلكِ بحاجة إلى زيادة شرب الماء.'),
  ('93141c59-a17f-414d-9f6c-c865a0650eeb', 'ليبدأ مسرح الظلال! 🐰', 'أطفئي نور الغرفة واستخدمي مصباحًا يدويًا لصنع أشكال من الظلال على الحائط. واحرصي على تصوير تعبير الدهشة اللطيف على وجه طفلكِ وهو يشاهد هذا السحر، لتحتفظي به في ألبوم طفلكِ.'),
  ('a14c30d1-ff1f-46da-8b1e-98116e38ee0d', 'هل يحب تمزيق الصفحات؟ 📖', 'هل يريد تمزيق الكتب بدلًا من قراءتها؟ اقرئي النصائح الجديدة في قسم المدوّنات حول أهمية الكتب الكرتونية والكتب اللمسية في هذا العمر.'),
  ('8e7d531f-d445-43eb-a4d5-05ffff377c4f', 'من الضجيج إلى الهدوء 🎶', 'قد يخيف الأطفالَ الانتقالُ المفاجئ من أصوات التلفاز أو الألعاب إلى الصمت. شغّلي صوت القطار من قسم الضوضاء البيضاء في الغرفة لتهيئة انتقال هادئ إلى أجواء النوم.'),
  ('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf', 'مشكلة المشاركة 🧸', 'هل يركض نحو ألعاب الأطفال الآخرين في الحديقة، لكنه يرفض إعطاءهم ألعابه؟ تعرّفي من Anacan AI على كيفية تعليم طفلكِ البالغ من العمر 1.5 سنة مفهوم اللعب بالتناوب.'),
  ('ca671510-91c4-4377-9f69-b4bd47b292a2', 'استراحة مع فنجان ☕', 'كيف حال طاقتكِ؟ توقّفي قليلًا عن الأعمال المنزلية. حضّري كعكة زبدة الفول السوداني الغنية بالطاقة من وصفات النساء الصحية، واستمتعي فقط بصوت قهوتكِ.'),
  ('38141003-a43c-4589-a477-21da541a08db', 'سحر الرمال الحركية 🏖️', 'ما رأيكِ في إنشاء شاطئ صغير في المنزل؟ اطّلعي على المنتجات الموصى بها للعثور على مجموعات الرمال الحركية التي تقوّي عضلات الأصابع ويسهل تنظيفها.'),
  ('75f9f2e1-a04a-4711-9125-3d8c610326d9', 'بدأ يتعرّف إلى جسمه! 👃', 'هل يشير بفخر إلى أنفه عندما تسألينه: أين أنفك؟ نظّمي جلسة تصوير صغيرة في الغرفة باستخدام ميزة تصوير طفلكِ، واحفظي تلك الوضعية اللطيفة في الألبوم فورًا.'),
  ('ae036003-f237-47e6-8031-7feeb47126cc', 'كيف نعرف أنه شبع؟ ⏱️', 'إذا بدأ طفلكِ برمي الطعام أو بصقه، فهذا يعني أنه شبع. أوقفي مؤقت التغذية، وسجّلي أنه تناول الكمية المعتادة ثم حلّلي شهيته.'),
  ('05bc3cfd-c566-4963-b6b2-87889d369e27', 'أنتِ أيضًا بحاجة إلى التواصل 💬', 'سيكون التواصل مع أمهات أخريات مفيدًا لكِ أيضًا! اختاري من الأماكن الصديقة للأمهات مركزًا يوفّر مجموعات للعب، وامنحي كليكما فرصة للتواصل الاجتماعي.'),
  ('5b6366a9-6eb4-4593-8335-c41fd3447da1', 'ما إنجازكِ اليوم؟ 🏆', 'هل نجحتِ في تنويم طفلكِ من دون بكاء؟ أم في إطعامه وعاءً كاملًا؟ دوّني حتى أصغر إنجازاتكِ في مفكرة الحالة المزاجية، وصفّقي لنفسكِ بحرارة.'),
  ('98a39354-24f3-4f3c-9cfb-1e084764a56b', 'النمو يبدأ من الحذاء 📏', 'قد يكون رفض طفلكِ ارتداء حذائه علامة على أنه أصبح ضيقًا! تحقّقي من جدول المقاسات في أداة تتبّع الوزن، وتابعي تطوره الجسدي.'),
  ('28cf8172-0a76-4afd-b2de-765879c7939a', 'اشكري نفسكِ! 💖', 'يا لكِ من أم متفانية ورائعة! افتحي مفكرة المزاج، ودوّني حتى أصغر عمل جيد قمتِ به اليوم من أجل طفلكِ، وافتخري بنفسكِ.'),
  ('f00a5e44-ed12-4c77-9249-e4246b2b108d', 'التعرّف الأول إلى النونية 🚽', 'رغم أن الوقت لا يزال مبكرًا، فإن وضع النونية في الحمام يساعد طفلكِ على التآلف معها بصريًا. تصفّحي المنتجات الموصى بها واختاري من بين النماذج المريحة والجذابة التي ستلفت انتباهه.'),
  ('6d72635f-ba12-4c8b-b7ef-f626dd634dce', 'لطاقة الصباح طابع مختلف! ⚡', 'هل يرفض عصيدة الشوفان؟ اكتشفي في وصفات الأطفال سموذي بالفواكه وزبدة الفول السوداني، وحققي بسهولة هدف السعرات الحرارية في أداة متابعة التغذية.'),
  ('9867089b-80a4-4895-985d-1e1d5fa3df95', 'هل تغالبكِ عيناكِ؟ 😴', 'استلقي أنتِ أيضًا عندما ينام طفلكِ. وإذا لم تتمكني من النوم، فحضّري من قسم الوصفات الصحية للنساء شايًا أخضر غنيًا بمضادات الأكسدة واستعيدي نشاطكِ.'),
  ('a5fedf21-2dca-46ed-9476-0b415ced68a5', 'هل يقاوم النوم؟ 🛌', 'يشتهر الشهر التاسع عشر بانتكاسات النوم. شغّلي مؤقت النوم وراجعي الجدول؛ فربما حان الوقت تمامًا لتقليص مدة القيلولة!'),
  ('39db43fc-07a0-417e-90da-c0bbbd5f14a4', 'هل تشتبهين في وجود ألم بالبطن؟ 💩', 'أدخلي ملاحظات البراز عند تغيير الحفاض صباحًا. وإذا كان هناك خطر للإصابة بالإمساك، فاسألي الذكاء الاصطناعي من Anacan عن حلول طبيعية سريعة وتقنيات للتدليك وطبّقيها.'),
  ('613cd9e2-958a-41bd-b191-0de3ff8ec07f', 'كم مرة سمعتِ «لا»؟ 🙉', 'يتطلب التعامل مع طفل صغير عنيد الكثير من الصبر. اكتبي توتركِ الداخلي في مفكرة المزاج، وعبّري عن مشاعركِ من دون أن تحكمي على نفسكِ.'),
  ('e893b0aa-e3fc-4f78-a970-b681a0ed0450', 'بطل التسلّق! 🧗', 'ألم يعد أثاث المنزل كافيًا؟ ابحثي في الأماكن الملائمة للأمهات عن مركز ترفيهي داخلي يضم مسارات حواجز مبطنة، ودعيه يشبع رغبته في التسلّق بأمان.'),
  ('a0570819-b575-49b5-bbf4-bc21cf5fc939', 'القفز بكلتا القدمين 🦘', 'هل يحاول القفز بكلتا قدميه في الوقت نفسه وهو واقف على الأرض؟ يبدو طريفًا جدًا، أليس كذلك؟ احرصي على تخليد هذه اللحظة من خلال جلسة تصوير الطفل.'),
  ('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d', 'يرفض النوم؟ 🥱', 'هل يرفض أخذ قيلولته النهارية ويقاوم النوم؟ اطلبي من Anacan AI معلومات دقيقة وجدولًا يوميًا حول فترات الاستيقاظ والنوم للأطفال بعمر 20 شهرًا.'),
  ('2edb626b-eafe-49c0-a743-e6dae9f9eddd', 'سكينة على أنغام الموسيقى 🎶', 'أسهل طريقة للتعامل مع نوبات التذمر في أواخر النهار هي تشغيل لحنه المفضل واحتضانه والرقص معه بهدوء.'),
  ('b174df30-8e63-488e-ae9b-4d227f3136f1', 'وليمة للأم 🥑', 'تفعلين كل ما بوسعكِ لإشباعه. لكن ماذا عنكِ؟ اختاري من الوصفات الصحية وجبة غداء غنية بالحديد تمنحكِ الطاقة، واجلسي بهدوء واستمتعي بها.'),
  ('5d951093-5ada-49f6-9750-d303bcf8d918', 'الأضراس الكبيرة؟ 🦷', 'هل يقضم كل شيء ويبكي دون سبب واضح؟ ربما تكون الأضراس الخلفية في طريقها إلى الظهور. سجّلي تطور العملية في متتبّع التسنين وجهّزي عضّاضات باردة.'),
  ('9fe66081-4fad-49c8-891d-2ca85484f87d', 'بطل الحكاية 🪄', 'أنشئي هذا المساء ضمن الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: صغير شجاع يحب تنظيف أسنانه بالفرشاة.'),
  ('c638741f-2af1-4bf3-a4de-09ffcb406144', 'شجاعة الخروج ⛅', 'هل بقيتِ في المنزل لأن الطقس متقلب؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا يمكنكِ ملاحظتها من النافذة وبالملابس المناسبة، ثم توجهي إلى الحديقة بثقة.'),
  ('3d75b744-8440-4e62-83c6-4a08b865c0f7', 'قناع الزبادي! 🥣', 'هل لطّخ وجهه وشعره بالطعام؟ بدلًا من الانزعاج، أضيفي هذه التحفة الفنية العبقرية إلى ألبوم الطفل، وزيّنيها بملصقات مرحة لتظل ذكرى لا تُنسى.'),
  ('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1', 'لشعركِ وبشرتكِ 🥑', 'اعتني بجسمكِ الذي أرهقه الروتين اليومي. حضّري سلطة الشباب بالأفوكادو والجوز، الغنية بمضادات الأكسدة، من بين الوصفات الصحية للنساء.'),
  ('a832a387-bccf-4a1a-823c-3930e73e4c07', 'أعطني ماءً، تعالي يا ماما 🗣️', 'هل بدأ طفلكِ يحاول الجمع بين كلمتين وتكوين جمل قصيرة؟ يا لها من قفزة رائعة في تطور اللغة! شجّعي محاولاته باستمرار وحفّزيه على الكلام.'),
  ('d1f9f7f1-6831-4583-9dbd-fab805703b8d', 'طاقة لا تنفد 🔋', 'ألا يتعب طفلكِ من الركض؟ شغّلي مؤقت النوم وخفّفي إضاءة الغرفة. وساعديه على الانتقال تدريجيًا إلى وضع النوم مع حفيف الغابة من الأصوات البيضاء.'),
  ('34104368-1e25-46df-8c68-910d16cd40b1', 'كيف تسير عملية الهضم؟ 🚽', 'هل يعاني طفلكِ من الإمساك؟ دوّني ذلك عند تغيير حفاضه صباحًا، واحرصي على إضافة أطعمة غنية بالألياف (الكمثرى، الشوفان) إلى قائمة طعامه باستخدام أداة متابعة التغذية.'),
  ('79b083b6-1c72-4250-a120-ca8846206ce5', 'كيف تشعرين؟ 🧘‍♀️', 'هل قلتِ «لا!» كثيرًا اليوم؟ لا تشعري بالذنب. عبّري عما بداخلكِ في مفكرة المزاج، وتذكّري مدى تفانيكِ كأم.'),
  ('bfb35c45-0163-48f3-be24-eff4697cb9e8', 'فنانو الطبيعة 🍂', 'الأوراق والحجارة والأغصان هي أفضل الألعاب! ابحثي عن حديقة غنّاء في الأماكن الملائمة للأمهات، وانطلقي مع طفلكِ في مغامرة استكشافية حقيقية في الهواء الطلق.'),
  ('01861a89-1cc1-4443-8c58-c79d90402305', 'نوبات الغضب في المتجر 🛒', 'هل ألقى طفلكِ بنفسه على الأرض لأنكِ لم تشتري له ما أراد؟ لا تفزعي. تجاهلي نظرات الآخرين، وانحني بهدوء حتى تصبحي في مستوى عينيه.'),
  ('32e724db-ca0f-4d6b-9d07-716443a9dcdd', 'تخلّصي من العبء العاطفي 📝', 'هل كان يومًا صعبًا؟ أفرغي ما في داخلكِ بكتابة ضغوط اليوم في مفكرة المزاج. جميع الأمهات يمررن بهذه التجارب، ولستِ وحدكِ.'),
  ('e6ec7f70-00dc-438b-af17-5f764a9d8216', 'هل أصبحت القيلولة أقصر؟ ⏱️', 'هل يرفض طفلكِ أخذ قيلولة بعد الظهر؟ تابعي إحصاءات مؤقّت النوم. ربما حان الوقت للانتقال تمامًا إلى نظام القيلولة الواحدة وتقديم موعد نومه مساءً.'),
  ('46ef9700-c667-4312-ac63-98bd03625249', 'العناد في اختيار الحذاء 👟', 'هل يصرّ طفلكِ عند الخروج على ارتداء ذلك الحذاء الشتوي في الصيف؟ اسمحي له أحيانًا باتخاذ خياراته، فهذا يعزّز إرادته.'),
  ('5541587a-ad73-4e1d-9174-d4fe1c028c3e', 'هل يقاوم النوم؟ 🛌', 'إنه يرفض الذهاب إلى الفراش لأن اللعب أكثر متعة من النوم! شغّلي مؤقّت النوم وساعدي دماغه على الاسترخاء تدريجيًا عبر صوت أمواج المحيط من قسم الضوضاء البيضاء.'),
  ('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'هل بدأ يهتم بالمرحاض؟ 🚽', 'هل يريد مرافقتكِ إلى الحمّام؟ هذا نوع من الاستعداد البصري. اقرئي في قسم المدوّنات عن الوقت والطريقة المناسبين لبدء التدريب على استخدام النونية، وكوني مستعدة.'),
  ('3b603489-95c3-4a32-b0e0-5191fc844b75', 'معركة ارتداء الملابس بنفسه 👕', 'هل بدأ عناده بعبارة: لا أريد هذا القميص! اسألي Anacan AI عن طرق الحدّ من أزمات ارتداء الملابس صباحًا ومنحه حرية الاختيار.'),
  ('89933e6a-484e-4f2e-bf20-8262f6a74c72', 'مخزون أوميغا-3 🐟', 'نمو الدماغ لا يتوقف. تحقّقي عبر أداة متابعة التغذية مما إذا كان طفلكِ قد تناول كمية كافية من السمك أو الجوز هذا الأسبوع، واحرصي على تسجيل أي نقص.'),
  ('fa46cf0a-85f0-484c-8aa5-b60eb52b320b', 'كيف نفرّغ طاقته في المنزل؟ 🏃‍♂️', 'ألا تستطيعين الخروج؟ وجّهي طاقته بطريقة مفيدة من خلال الاطّلاع في قسم المنتجات الموصى بها على ترامبولين صغير أو زحلوقة مخصّصة للاستخدام داخل المنزل.'),
  ('00691751-d785-4fc6-8036-d313adccdad6', 'فحص مفاجأة الصباح 🧻', 'هل يزداد عدد الحفاضات الجافة، أم أن الهضم أصبح أبطأ؟ سجّلي تغيير حفاض الصباح في متتبّع الحفاضات لتحليل احتياجات طفلكِ من السوائل والألياف فورًا.'),
  ('69c1e419-f8f2-4b2f-90e3-9b51e78ff197', 'توقّف المؤقت، فاستريحي 🍵', 'أوقفتِ مؤقت النوم وغادرتِ الغرفة. لا تقتربي من الأعمال المنزلية الآن! حضّري لنفسكِ شاي البابونج، ودعي تعب اليوم يتبدّد مع بخاره الدافئ.'),
  ('934796d5-42af-4c49-9cb9-67f18b657e36', 'هل تؤلمه أسنانه؟ 🦷', 'قد تكون الأضراس الأخيرة في طريقها إلى الظهور. لتخفيف حكة اللثة، حضّري من وصفات الأطفال مصاصات فواكه مثلجة (آيس بوبس)، باردة وخالية من السكر ومفيدة.'),
  ('06d75280-127a-43d4-a7f0-42d2871b24c5', 'طاهٍ مستقل! 👨‍🍳', 'ألا يريد إعطاءكِ الملعقة؟ حضّري من وصفات الأطفال كرات لحم يسهل إمساكها باليد. استخدمي مؤقت التغذية لتحليل مدة تناوله الطعام باستقلالية ومتابعة شهيته.'),
  ('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb', 'تعابير وجه مضحكة 🤪', 'هل يصنع طفلكِ تعابير مضحكة أمام المرآة؟ لا تفوّتي هذه اللحظة الممتعة! زيّني الصورة بالملصقات المرحة في جلسة تصوير الطفل، واجعليها أطرف لقطة في الألبوم.'),
  ('739af07d-8466-4c3f-a164-5e408385ca93', 'هل يتسلّق كل شيء؟ 🧗‍♀️', 'الأريكة، الطاولة، الخزانة... إنه متسلّق حقيقي! اقرئي في قسم المدوّنات كيفية تلبية هذه الحاجة الحركية الخطرة والضرورية في الوقت نفسه، بطريقة آمنة داخل المنزل.'),
  ('8ac7016a-7613-48aa-a952-59cc5f8a6354', 'هل أصبحت ساقا البنطال قصيرتين؟ 👖', 'طفرة النمو مستمرة بأقصى سرعتها! أدخلي قياسات الطول والوزن الحالية في متتبّع الوزن، وشاهدي بفخر كيف يرتفع منحنى نمو طفلكِ.'),
  ('db467018-0ec9-41a9-a3a3-3ef1c48cda53', 'البحث عن لعبة تعليمية 🧩', 'يحتاج طفلكِ إلى ألعاب تحفّزه على التفكير، لا إلى ألعاب تُصدر الأصوات فحسب. احرصي على الاطلاع في قسم المنتجات الموصى بها على ألعاب المنطق وتركيب الأشكال (بازل) المناسبة لعمر 1.5 سنة فما فوق.'),
  ('df8f7402-1277-45bd-a743-5c24bdaf48e1', 'عضّات غاضبة؟ 🦖', 'هل يضرب أو يعض عندما يغضب؟ إنها مشاعر لا يستطيع التعبير عنها بالكلمات. تعلّمي من Anacan AI كيفية تغيير هذا السلوك بلطف.'),
  ('45af46ac-18bf-499b-a5c7-56bbe71e4564', 'الانتقال إلى الهدوء 🎶', 'حان وقت إراحة القدمين الصغيرتين اللتين ظلّتا تركضان طوال اليوم. شغّلي صوت مقصورة السيارة من قسم الضوضاء البيضاء لتصنعي بإيقاعه الرتيب بيئة مثالية للنوم.'),
  ('47b68bdb-a1fd-4da7-9316-dcca5fdae94f', 'أنتِ أيضًا بحاجة إلى صديقات 👯‍♀️', 'هل ترغبين في التحدث مع أمهات أخريات بينما يلعب طفلكِ في الحديقة؟ اكتشفي المراكز التي تضم مجموعات للعب عبر قسم الأماكن الصديقة للأمهات، واستمتعي بالتواصل معهن.'),
  ('49af58d4-c188-43d7-a0b2-43f4cd255337', 'قهوة الصباح لا تكفي! ☕', 'بدء يومكِ بالقهوة على معدة فارغة سيستنزف طاقتكِ سريعًا. اختاري من الوصفات الصحية للنساء كعكة الشوفان الغنية بالطاقة، التي يمكن تحضيرها في 5 دقائق.'),
  ('869af623-de96-421f-808b-d64172a8f765', 'أحسنتِ! 👏', 'هل بقي المنزل غير مرتب اليوم؟ لا تهتمي إطلاقًا! فاللحظات المليئة بالضحك التي قضيتِها مع طفلكِ أكثر قيمة. ولا تنسي أن تثني على نفسكِ في مفكرة الحالة المزاجية.'),
  ('aaf473f6-79bc-44cf-97f4-687dfa4eb293', 'ألا يحب شرب الماء؟ 💧', 'هل كانت حفاضته جافة جدًا صباحًا؟ يجب زيادة كمية السوائل التي يحصل عليها. سجّلي ذلك في متتبع الحفاضات، واطّلعي في التطبيق على وصفات المياه المنكّهة بالفواكه وتصاميم أكواب الشرب المختلفة.'),
  ('ff614b36-4091-473e-b7fa-91411bd4e2a9', 'العظام تزداد قوة! 🦴', 'استخدمي أداة متابعة التغذية لحساب ما إذا كان طفلكِ قد حصل اليوم على ما يكفي من الكالسيوم وفيتامين D. فهذان العنصران ضروريان معًا لنموه الجسدي السريع.'),
  ('348430a9-4730-49e1-90ac-91076b5c5d7c', 'لنفرز الألوان! 🔴🔵', 'ضعي الألعاب الحمراء في جهة، والزرقاء في جهة أخرى. اقرئي في قسم المدونات عن الألعاب المنزلية التي تعزز الانتباه والمنطق لدى الأطفال بعمر 19.5 شهرًا، وجرّبيها مع طفلكِ.'),
  ('907f2a4d-a45c-43e1-8024-d6c91a18d072', 'نوبة صراخ كبيرة في المتجر؟ 🛒', 'هل ألقى طفلكِ بنفسه على الأرض وبكى في مكان عام؟ تجاهلي نظرات الآخرين. تحدثي إلى Anacan AI وتعرّفي إلى طرق تساعدكِ على التعامل مع مثل هذه النوبات بهدوء.'),
  ('80e71246-05ae-4bc6-857d-5ce3af704b5e', 'مصدر طاقة الأم 🥗', 'هل أنهككِ الركض طوال الوقت؟ اتجهي إلى البروتين بدلًا من الحلويات! حضّري سموذي زبدة الفول السوداني الذي يمنحكِ طاقة فورية، من قسم الوصفات الصحية للنساء.'),
  ('145211fa-74d2-4e28-8a64-c14921db5185', 'أثني على نفسكِ! 🌟', 'هل نجحتِ اليوم في إطعام طفلكِ من دون أن يبكي؟ دوّني حتى أصغر إنجازاتكِ في مفكرة المزاج، وصفّقي لنفسكِ تقديرًا لمهاراتكِ كأم.'),
  ('4f60f5e8-df5e-4892-aa2e-dcffda8f877b', 'توازن السوائل ضروري للحياة 💧', 'الحركة والركض المستمران يعرّضان الجسم للجفاف. سجّلي بيانات الصباح في متتبع الحفاضات، وتصفحي في المنتجات الموصى بها زجاجات المياه الرياضية التي يمكن لطفلكِ فتحها بسهولة.'),
  ('edd993f1-ac76-4300-8ed0-6009d7897f2b', 'دردشة مع أمهات أخريات ☕', 'هل تعبتِ من التحدث مع طفلكِ فقط؟ ابحثي في الأماكن الصديقة للأمهات عن مقاهي الأطفال التي تتردد إليها الأمهات بكثرة، وامنحي نفسكِ فرصة للتواصل الاجتماعي أيضًا.'),
  ('6f516c4d-5db5-4d3e-8fca-8c461e614752', 'هل مخزون الحديد كافٍ؟ 🥩', 'لحماية طفلكِ كثير الحركة من فقر الدم، تحققي من كمية الحديد التي تناولها اليوم، مثل اللحوم والبقوليات، عبر أداة متابعة التغذية، وعدّلي قائمة طعامه وفقًا لذلك.'),
  ('b003834c-8ce3-4da4-a17e-0b837c04f7f7', 'لنتحقق من مخزون الكالسيوم 🧀', 'تحتاج العظام التي تنمو بسرعة إلى الكالسيوم! استخدمي أداة متابعة التغذية للتحقق من حصة طفلكِ اليوم من الجبن والزبادي، واستكملي أي نقص.'),
  ('b5cae897-2c37-4223-8c5a-201bd9d0229a', 'أصوات الغابة الساحرة 🍃', 'هل كان يومًا صاخبًا ومليئًا بنوبات الغضب؟ شغّلي صوت حفيف الأوراق من قسم الضوضاء البيضاء لتهدئة جهاز طفلكِ العصبي وجهازكِ العصبي أيضًا.'),
  ('20cf6725-2fdc-45bb-965b-09069424fe0a', 'وجبة خفيفة خالية من السكر 🍪', 'لا حاجة إلى بسكويت المتاجر. اكتشفي في وصفات الأطفال حلويات صحية بالتمر والشوفان، يمكنكِ تحضيرها في المنزل خلال 10 دقائق.'),
  ('0bde6683-6d18-4d98-bc39-b122396c0b17', 'حان وقت الراحة الآن 🍵', 'انتهى الركض والانشغال! حضّري مشروبًا من الوصفات الصحية، واستلقي على الأريكة واستمتعي فقط بطعم الهدوء.'),
  ('0eecf770-9ba2-463c-9b39-bbe24d01b4e1', 'صرخات «إنها لي!» 🧸', 'هل ينتزع ألعاب الآخرين في الحديقة؟ تعلّمي من Anacan AI أكثر الأساليب النفسية فاعلية للتعامل مع نوبات التمركز حول الذات في هذا العمر.'),
  ('0a81bd63-014b-4d25-b347-1808455aea49', 'الهروب من بين الجدران الأربعة 🏃‍♀️', 'من الصعب تفريغ طاقته في المنزل. ابحثي ضمن الأماكن الصديقة للأمهات عن مركز ألعاب آمن يمكنكِ فيه احتساء القهوة بينما يركض طفلكِ ويلعب.'),
  ('657f4585-c7bb-41c0-9574-51e8f943398b', 'فوضوي، لكنه مستقل! 🥣', 'هل يصرّ على تناول الطعام بنفسه؟ شغّلي مؤقت التغذية، وتابعي مدة الوجبة، وسجّلي كيف تفيد هذه الاستقلالية مهاراته الحركية الدقيقة.'),
  ('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4', 'هل عادت الاستيقاظات الليلية؟ ⏱️', 'قد يكون السبب تراجع النوم في عمر ٢٠ شهرًا. راجعي مخطط مؤقت النوم، وتحققي مما إذا كان الوقت قد حان لتقليل مدة قيلولته النهارية بمقدار ١٥ دقيقة.'),
  ('385a8205-8e28-4c23-94fa-a2a8fe32e28c', 'لا تشعري بالذنب 📝', 'هل ارتفع صوتكِ قليلًا اليوم؟ لا تلومي نفسكِ. أفرغي ما يثقل صدركِ في يوميات المزاج، وتذكّري أنه لا توجد أم أفضل منكِ.'),
  ('49b18c8f-b30b-4368-9445-6af88b1d8115', 'جمل من كلمتين! 🗣️', '«ماما تعالي»، «هاتِ الكرة» — حصيلته اللغوية تنمو بسرعة. أضيفي محاولاته اللطيفة للكلام فورًا إلى ألبوم الطفل في مقطع فيديو بصوته، وحوّليها إلى ذكرى تدوم مدى الحياة.'),
  ('5d516faa-7c77-4db9-b201-49bff969e3d8', 'الكالسيوم للعظام 🦴', 'يحتاج صغيركِ كثير الحركة إلى عظام قوية. تحققي في أداة متابعة التغذية من كمية الكالسيوم التي تناولها اليوم، مثل الجبن والزبادي، وأكملي احتياجه اليومي.'),
  ('ad033330-a436-4b30-84e7-2df370198c16', 'البحث عن لعبة ذكية 🧩', 'هل يحب إدخال الأشكال في فتحاتها؟ اكتشفي في قسم المنتجات الموصى بها أحجيات خشبية مناسبة لعمره، تساعد على تنمية ذكائه أكثر.'),
  ('d22a5573-d857-4918-90d2-9def6a084f6f', 'فن تهدئة الدماغ 🎶', 'قد لا يستطيع الطفل الذي يتعرض للكثير من المحفزات النوم ليلًا. عتّمي الغرفة وشغّلي صوت أمواج المحيط من قسم الضوضاء البيضاء، لتهيئيه برفق لنوم عميق.'),
  ('fb035079-cf24-4146-9049-8d721e68f53f', 'فنان غارق في الألوان! 🎨', 'هل لطّخ ملابسه بالألوان أثناء الخربشة؟ بدلًا من الانزعاج، زيّني هذه اللحظة الطريفة بالملصقات المرحة في جلسة تصوير طفلكِ، ثم حمّليها إلى الألبوم.'),
  ('0b2c56b1-a7a8-4553-8880-13254eeb155b', 'هل أصبحت ملابسه قصيرة؟ 📏', 'إذا أصبحت ساقا سرواله قصيرتين، فهذه طفرة نمو! أدخلي قياساته الحالية في متتبع الوزن، وشاهدي بفخر منحنى نموه وهو يرتفع.'),
  ('9f2ceaa6-0d99-46a0-884c-3460db78351b', 'يفهمكِ، لكنه لا يتكلم؟ 🧠', 'تنمو حصيلة الكلمات التي يفهمها الطفل أسرع من الكلمات التي يستخدمها. احرصي على قراءة المقال في قسم المدونات عن الألعاب المنزلية التي تساعد على تطوير النطق لدى الطفل في عمر 20 شهرًا.'),
  ('f641f443-9a8d-4060-a2b5-fe5d5562fa9d', 'مهمة الفيتامينات السرية 🥕', 'هل يدفع الخضراوات الورقية وبقية الخضراوات جانبًا؟ تعلّمي في وصفات الأطفال كيف تُخفين السبانخ والجزر ببراعة داخل فطائر شهية.'),
  ('68ef19de-c144-4be9-8878-9cc1b34a6483', 'كم يستغرق حتى ينام؟ ⏱️', 'هل يتقلب كثيرًا في السرير؟ فعّلي مؤقت النوم وسجّلي المدة التي يستغرقها حتى يغفو. ربما ينبغي إنهاء ألعاب المساء في وقت أبكر.'),
  ('70a3e410-6335-466b-99bc-28ac0c3d913f', 'لماذا يبكي فجأة؟ 🤖', 'هل يستيقظ ليلًا وهو يصرخ ولا يهدأ؟ اكتبي فورًا إلى خبير Anacan AI عن شكوككِ بشأن الرعب الليلي، وتعرّفي إلى الخطوات الصحيحة.'),
  ('9a0a29d7-d513-4158-b204-99c831639c23', 'معًا، ولكن كلٌّ على حدة 👶', 'ألا يلعب طفلكِ مع الأطفال في الحديقة، بل يكتفي بمشاهدتهم من بعيد؟ هذا هو اللعب الموازي! اسألي Anacan AI عن حقائق شيقة حول هذه المرحلة من التطور الاجتماعي.'),
  ('f527de5c-afa8-4884-a173-da37070a2826', 'مساعد المنزل الصغير 🧹', 'هل يمسح طفلكِ الطاولة بقطعة قماش بينما تكنسين المنزل؟ صوّري لحظة تحمّله المسؤولية اللطيفة هذه فورًا، واجعليها من أكثر اللقطات التي تبعث على الفخر في ألبوم طفلكِ.'),
  ('18518788-d8e2-4971-93f7-6fbf0592ca33', 'الضرب أو الدفع 🛑', 'هل يرفع طفلكِ يده فجأة عندما يغضب؟ استعيني بـ Anacan AI لتتعرّفي إلى كيفية التعامل من خلال اللعب مع هذا السلوك المميز للشهر العشرين.'),
  ('a6200253-33e2-4142-a4a9-811aa67d4feb', 'أنتِ بطلة اليوم 🧘‍♀️', 'نام طفلكِ. توقفي عن جميع الأعمال المنزلية. دوّني مشاعركِ في مذكّرة المزاج، وشغّلي موسيقى هادئة، وخصّصي هذه الأمسية لنفسكِ فقط.'),
  ('eefd67fd-3835-4f65-abf3-9ced6b705e30', 'اختبار الصبر على مائدة الطعام ⏱️', 'هل يستغرق طفلكِ ٥ دقائق لتناول ملعقة واحدة؟ شغّلي مؤقّت التغذية، وتحلّي بالصبر، وحلّلي تطوّر شهيته بدقة من خلال التقرير الموجود في التطبيق.'),
  ('070b2f75-0440-4e85-b828-292900301f9e', 'بدأت ألعاب الخيال 🧸', 'هل يسقي طفلكِ دميته الدب أو يتظاهر بعلاجكِ؟ احتفظي بلحظات التعاطف الرائعة هذه للمستقبل عبر إضافتها إلى ألبوم طفلكِ كمقاطع فيديو بالصوت.'),
  ('388f83f4-0bb5-4306-abf6-b75f9dc65017', 'فحص مخزون الحديد 🥩', 'الوقاية من فقر الدم ضرورية لعضلات نشطة ونمو صحي. تحققي من كمية الحديد التي تناولها طفلكِ اليوم (اللحوم والبقوليات) باستخدام أداة متابعة التغذية، وعوّضي أي نقص فورًا.'),
  ('9cb7efe6-c6c0-4032-89de-12eeec5119ee', 'الانتقال من الأصوات إلى الهدوء 🎶', 'قد يُخيف طفلكِ الصمت المفاجئ بعد أصوات التلفاز والألعاب. شغّلي صوت مجفف الشعر من قسم الضوضاء البيضاء في الغرفة، ولاحظي كيف يؤثر الصوت الرتيب إيجابيًا في أجواء النوم.'),
  ('af623bf2-6a45-452d-a9c0-bd16d67bf74d', 'وحش البان كيك 🥞', 'هل يرفض تناول وجبة الإفطار؟ جرّبي وصفة البان كيك بالموز دون سكر في قسم وصفات الأطفال. سيتمكن من إمساكه وتناوله بنفسه، كما ستتحسن شهيته.'),
  ('a7786d73-a362-4a32-a77f-3c09e4ab2ffb', 'درس فيزياء بالماء 🛁', 'ألا يملّ من سكب الماء من كوب إلى آخر في الحمّام؟ تصفّحي قسم المنتجات الموصى بها لاكتشاف ألعاب مائية ممتعة ومهدّئة.'),
  ('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793', 'درع الكالسيوم 🦴', 'الكالسيوم ضروري للأسنان والعظام. استخدمي أداة متابعة التغذية للتأكد من حصوله اليوم على الكمية المناسبة من الزبادي والجبن.'),
  ('e8d46282-de1c-4981-9242-f0dff7014b1d', 'لنحلّل روتينه ⏱️', 'هل طالت فترة بقائه مستيقظًا في المساء؟ شغّلي مؤقت النوم وتابعي الجدول. ربما حان الوقت تمامًا لتقليل مدة قيلولته النهارية بمقدار 15 دقيقة.'),
  ('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f', 'إشارات الجهاز الهضمي 💩', 'قد يؤدي الانتقال الكامل إلى الأطعمة الصلبة إلى صعوبة الهضم. أضيفي ملاحظة الصباح إلى متتبع الحفاضات، وتحققي بسهولة مما إذا كان توازن السوائل والألياف يحتاج إلى تعديل.'),
  ('c4d895de-4842-4a9b-ae46-1557c6e3d2cc', 'مهدّئ طبيعي 🍃', 'هل كان يومًا حافلًا بنوبات الغضب والضجيج؟ شغّلي صوت حفيف الأوراق من قسم الضوضاء البيضاء، وامنحي جهازه العصبي وجهازكِ العصبي بعض الاسترخاء.'),
  ('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3', 'معركة ارتداء الملابس 👗', 'ألا ينتهي عناده قائلًا: «لا أريد هذا القميص!»؟ خفّفي أزمات ارتداء الملابس صباحًا بتحويل الأمر إلى لعبة، وأخبريه بأنكِ ستلتقطين له صورًا في جلسة تصوير طفلكِ.'),
  ('0daafb47-5c27-4a37-935b-b3612abf5506', 'بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها يوميًا هي ثمرة جهدكِ. افتحي يوميات المزاج، واكتبي حتى أصغر شيء جميل فعلتِه من أجله اليوم، وافتخري بنفسكِ!'),
  ('e61cda6e-e7ca-46f3-a40c-42185a9f8216', 'طاقة في ٥ دقائق ⚡', 'عندما ينام طفلكِ ظهرًا، لا تسارعي إلى أداء الأعمال المنزلية. حضّري سموذي غنيًا بمضادات الأكسدة من قسم الوصفات الصحية وجدّدي نشاط جسمكِ.'),
  ('733a062a-9528-4b89-8399-8894cdcd37ab', 'قراءة كتاب معًا 📖', 'هل يريد طفلكِ تقليب صفحات الكتاب بنفسه؟ اقرئي في قسم المدونات مقالًا رائعًا عن كيفية غرس حب القراءة لديه في هذا العمر من خلال اللعب.'),
  ('840a48c0-60b0-4169-a7a4-bfd97c049d9d', 'استكشاف الطبيعة 🌳', 'هل يشعر طفلكِ بالضيق بين جدران المنزل؟ ابحثي في قسم الأماكن الملائمة للأمهات عن حديقة واسعة وآمنة، وساعديه على تفريغ طاقته في أحضان الطبيعة.'),
  ('fc70b034-70d7-48ac-b093-b541c3d08e54', 'فحص الصباح وتسجيل البيانات 💧', 'هل غيّرتِ أول حفاض لطفلكِ اليوم؟ سجّلي بيانات الإخراج في التطبيق لتتمكني بسهولة من متابعة مدى كفاية السوائل التي يتناولها وسلامة عملية الهضم لديه.'),
  ('8139b24d-f8c3-4b60-b4f1-38bd25e609a6', 'لا يترك الملعقة من يده؟ 🥄', 'شغّلي مؤقت الرضاعة والتغذية. حلّلي المدة التي تستغرقها محاولاته لتناول الطعام بمفرده، وتحققي في التطبيق من احتياجاته الغذائية اليومية.'),
  ('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91', 'العلاج بالرمل 🏖️', 'لا تخافي من اتساخ طفلكِ! اكتشفي فورًا في قسم المنتجات الموصى بها أفضل الأدوات للرمل الحركي أو الألعاب الحسية.'),
  ('f71cc78c-d1eb-4694-b94a-1843f80e2db1', 'أمواج مهدّئة 🌊', 'هل يعجز طفلكِ عن النوم بعد يوم حافل بالاستكشاف النشط؟ اختاري صوت أمواج المحيط من قسم الضوضاء البيضاء، واصنعي في الغرفة هدوءًا ساحرًا يساعده على الاستعداد للنوم.'),
  ('3787f491-d618-4351-acd6-86ff87689c17', 'الضرب والدفع 🛑', 'هل يرفع طفلكِ يده فجأة أو يعضّ عندما يغضب؟ اسألي Anacan AI عن كيفية التعامل بحب مع هذا السلوك الشائع في الشهر الحادي والعشرين.'),
  ('847e9a71-981a-4920-b6be-a1986674dd92', 'عرض لا ينتهي على المائدة ⏱️', 'يلعب بالطعام ويرميه على الأرض، لكنه لا يأكل. شغّلي مؤقت الوجبة، وتحلّي بالصبر، وحلّلي بدقة تطور شهيته خلال مرحلة الاستقلال هذه باستخدام الرسم البياني في التطبيق.'),
  ('890ee8d7-3315-4b7a-994a-c41900d8c960', 'البحث عن لعبة ذكية 🧩', 'هل أتقن إدخال الأشكال في فتحاتها؟ اكتشفي الآن في قسم المنتجات الموصى بها أحجيات مناسبة لعمره تساعد على تنمية ذكائه أكثر.'),
  ('8ad462c4-33b5-4c76-be29-aa192feb14a1', 'هل أصبح حذاؤه ضيقًا؟ 📏', 'هل بات يتعثر كثيرًا أثناء الركض مؤخرًا؟ ربما كبرت قدمه! أدخلي طوله ومقاساته الحالية في متتبع النمو وتابعي تطوره البدني.'),
  ('2e662854-2d0b-4e0d-be84-f71f33b1ed5b', 'لماذا يبكي فجأة؟ 🤖', 'هل تغيّر مزاجه فجأة وبدأ بالبكاء بينما كان يلعب بسعادة؟ راسلي مساعدنا الخبير Anacan AI لمعرفة أسباب هذه التقلبات العاطفية.'),
  ('b30cbe06-794a-4924-bc78-63ebe289b716', 'تطور الذكاء لا يتوقف 🧠', 'إنه يحب تصنيف كل شيء! احرصي على قراءة المقال في قسم المدونات عن الألعاب المنزلية التي تعزز إدراك الألوان والأشكال لدى الأطفال بعمر 20-21 شهرًا.'),
  ('dcfe0150-6b59-46be-be17-cba289272768', 'طاقة لخمس دقائق 🔋', 'شرب القهوة على معدة فارغة سيستنزف طاقتكِ بحلول الظهر. اختاري من الوصفات الصحية كعكة شوفان لذيذة وسريعة التحضير تمنحكِ الشبع.'),
  ('41523bc6-ac22-4b48-a7b5-8663ed9c74c3', 'العلاج بالرمل 🏖️', 'لا تخافي من الاتساخ! ابحثي في قسم الأماكن الصديقة للأمهات عن مكان يضم حوضًا رمليًا. فملامسة الرمل أكثر فائدة لنمو الحواس من الألعاب باهظة الثمن.'),
  ('863859ae-c920-41fe-b876-915ee50bba17', 'فنان مغطى بالألوان! 📸', 'هل لوّن نفسه والجدار؟ بدلًا من الغضب، حمّلي هذه اللحظة الطريفة من الشخبطة إلى ألبوم طفلكِ وأضيفي إليها ملصقات مرحة.'),
  ('205f33e0-59b6-4cce-bdf2-72feb1805167', 'البحث عن حلوى صحية 🍪', 'هل تحتاجين إلى وجبة خفيفة لذيذة وخالية من السكر؟ اكتشفي في وصفات الأطفال بسكويت الموز والتمر الذي يُحضَّر خلال 10 دقائق.'),
  ('db60a4c8-3ab7-4727-9545-2ff3fea13946', '«لا» العنيدة! 🛑', 'هل يعترض طفلكِ على كل شيء ويصرخ؟ استشيري مساعد Anacan بالذكاء الاصطناعي حول عناد الشهر الحادي والعشرين، وتعلّمي كيفية التعامل مع نوبات الغضب.'),
  ('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36', 'لنراجع نظام النوم ⏱️', 'هل يستيقظ طفلكِ كثيرًا ليلًا؟ حلّلي مخطط مؤقت النوم. ربما تحتاجين إلى تقصير قيلولته النهارية قليلًا ليكون أكثر تعبًا بحلول المساء.'),
  ('87662f03-ab51-47a9-bb0d-dc1172cdf859', 'كنز من الفيتامينات 🥗', 'احسبي احتياجات اليوم من الفيتامينات وخططي لقائمة الطعام باستخدام أداة متابعة التغذية. احرصي على التحقق من توازن أوميغا-3 وفيتامين D.'),
  ('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7', 'ألعاب التفكير المنطقي 🧩', 'هذا العمر مثالي لألعاب التفكير المنطقي. اكتشفي في قسم المنتجات الموصى بها أحجيات وألعاب فرز الأشكال المناسبة لعمر طفلكِ، وساعديه على تنمية ذكائه.'),
  ('b4b68202-2497-420c-9cf0-d0f43130a249', 'عبّري عما بداخلكِ 📝', 'ليس كل يوم مثاليًا، وهذا أمر طبيعي. اكتبي في يوميات المزاج ما يثقل صدركِ اليوم، وتخلّصي من التوتر واستريحي بهدوء.'),
  ('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94', 'طفرة في الطول! 📏', 'هل تشعرين بأن طفلكِ قد ازداد طولًا فجأة؟ أدخلي القياسات الجديدة في متتبع النمو، وتأملي بفخر مخطط نموه الصحي.'),
  ('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677', 'حان وقت استعادة طاقتكِ 🔋', 'لا تنسي نفسكِ! اختاري من الوصفات الصحية عصير سموذي لذيذًا وغنيًا بالبروتين وسريع التحضير للفطور، واستعيدي نشاطكِ.'),
  ('3b1eb831-8b25-40be-89a6-b50384eeb49b', 'يريد الكلام، لكن... 🗣️', 'هل مفرداته التي يفهمها أكثر من تلك التي يستخدمها؟ حتى إن لم ينطق الكلمات نطقًا صحيحًا، اقرئي في قسم المدوّنات كيف يمكنكِ دعم هذه الطفرة اللغوية الرائعة.'),
  ('a4477b67-ebfc-489b-b2e5-165c0ebb273f', 'البحث عن الاستقلالية 🥣', 'ألا يعطيكِ الملعقة؟ شغّلي مؤقت التغذية وحلّلي الوقت الذي تستغرقه تجربة الاستقلالية هذه. أما الطعام المتناثر، فاكتفي بالابتسام له.'),
  ('527e5a17-444d-47c4-8578-4ebb1ee870b1', 'نوم هانئ أم معركة؟ 🛌', 'إذا أصبح الذهاب إلى السرير أزمة كبيرة، فاسألي Anacan AI فورًا عن طقوس الانتقال إلى النوم والحيل النفسية المناسبة للأطفال بعمر ٢١ شهرًا.'),
  ('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6', 'كيف كانت الليلة؟ 🌙', 'إذا كان الحفاض ثقيلًا جدًا في الصباح، فقد تحتاجين إلى تنظيم تناول السوائل ليلًا. دوّني ذلك في متتبّع الحفاضات وراجعي توازن السوائل خلال اليوم.'),
  ('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4', 'المهارات الحركية الدقيقة للأصابع 🧩', 'لقد أتقن وضع الأشكال في أماكنها. اكتشفي الآن في قسم المنتجات الموصى بها أحجيات مناسبة لعمره تساعده على تنمية ذكائه أكثر.'),
  ('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60', 'حان وقت الاسترخاء 🎶', 'قد يُرهق اليوم الحافل دماغه. شغّلي صوت حفيف الغابة من قسم الضوضاء البيضاء لتصنعي في الغرفة أجواءً مثالية هادئة ومحفّزة على النوم.'),
  ('d93eedfc-78de-4d26-810d-89c2b8c71690', 'دلّلي نفسكِ بفنجان قهوة ☕', 'لقد أنهككِ الركض طوال اليوم! ابحثي في خريطة الأماكن الصديقة للأمهات عن مقهى يضم مساحة للعب الأطفال، وامنحي نفسكِ استراحة صغيرة.'),
  ('fcfa5044-061e-4832-8787-ddd94f46ab93', 'اكتشاف كلمة جديدة 🗣️', 'ما الكلمة الجديدة التي قالها اليوم؟'),
  ('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce', 'كيف هو مخزون البروتين؟ 🍗', 'البروتين ضروري لنمو طفلكِ! استخدمي أداة متابعة التغذية لتقييم توازن غذائه اليومي وتعويض أي نقص.'),
  ('e90a6ec1-ff62-4f86-8635-bb93512c7c35', 'تحليل النوم باستخدام المؤقت ⏱️', 'حان وقت النوم! شغّلي مؤقت النوم، وحلّلي نمط طفلكِ للتأكد من حصوله على كفايته اليومية من النوم، ثم استريحي.'),
  ('0ac93f21-93e2-449d-b93b-ae00befc33f7', 'هل يخاف من الظلام؟ 🌌', 'هل يشعر بالقلق عند إطفاء ضوء الغرفة؟ شغّلي صوت الرحم (نبضات القلب) من قسم الضوضاء البيضاء لتمنحيه شعورًا دافئًا بالأمان.'),
  ('5831d6e0-9735-485f-be90-56915bc7047f', 'الآن حان دوركِ 🥗', 'إذا نام طفلكِ، فتوجّهي إلى المطبخ! اكتشفي ضمن الوصفات الصحية للنساء سلطة غنية بالبروتين تمنحكِ طاقة فورية، أو مشروب ديتوكس منعشًا.'),
  ('5c1e8139-b38e-4666-8558-f6706af826d7', 'الفنان الصغير منهمك في الإبداع 🖍️', 'هل يحب الخربشة؟ لا تنزعجي حتى لو تلطخت ملابسه بالألوان! أضيفي هذه اللحظة الإبداعية فورًا إلى ألبوم طفلكِ وحوّليها إلى ذكرى تدوم مدى الحياة.'),
  ('04f3e5a5-25b9-471b-9c8e-e6c96050313b', 'درع مناعة ملوّن 🛡️', 'استخدمي أداة متابعة التغذية للتحقق مما إذا كان طفلكِ قد حصل اليوم على ما يكفي من فيتامين C. واستعيني بوصفات الأطفال لتحضير أطباق غنية بالخضراوات الملوّنة.'),
  ('41231bd2-e2dd-4432-bc31-3952982f012e', 'هل ينظّف أسنانه؟ 🪥', 'هل يهرب بمجرد رؤية فرشاة الأسنان؟ تصفّحي الفرش الموسيقية أو فرش الأصابع ضمن المنتجات الموصى بها، وحوّلي هذه الخطوة المهمة للعناية بالنظافة إلى لعبة ممتعة.'),
  ('9603c325-693c-472c-b02b-2c75bd255571', 'أنتِ بطلة اليوم! 🌟', 'رغم كل نوبات الغضب والإرهاق، فأنتِ رائعة! افتحي يوميات المزاج واكتبي اليوم ملاحظة تستحقين أن تصفّقي لنفسكِ بحرارة من أجلها.'),
  ('03d03133-0370-4630-9d2e-153f9459d86d', 'هل يستيقظ صارخًا من النوم؟', 'من دون تشغيل ضوء الغرفة، شغّلي صوت الرحم من قسم الضوضاء البيضاء لتمنحيه شعورًا بالأمان وتساعديه على العودة إلى النوم.'),
  ('8ed6f8ef-f210-4aaa-96f8-4667b80d657e', 'لا لكل شيء! 🛑', 'هل يعترض على كل اقتراحاتكِ؟ بدلًا من مقاومة عناده، اسألي Anacan AI فورًا عن كيفية تقديم الخيارات المناسبة له.'),
  ('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c', 'شرب السوائل ليلًا 🚰', 'إذا كانت حفاضته ثقيلة جدًا في الصباح، فقد تحتاجين إلى تنظيم شربه للماء مساءً. سجّلي ذلك في متتبّع الحفاضات وراجعي الإحصاءات اليومية.'),
  ('0b3896bc-de1d-4dd2-b68d-bd0aa3890750', 'هل تطول قيلولته؟ ⏱️', 'هل يقاوم الذهاب إلى الفراش مساءً؟ شغّلي مؤقت النوم وتابعي الجدول. لعلّه يستيقظ من قيلولته في وقت متأخر جدًا؟'),
  ('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d', 'الكالسيوم والعظام 🦴', 'يتطلب النمو الجسدي السريع الكالسيوم. استخدمي أداة متابعة التغذية لحساب حاجته من الجبن والزبادي، وإذا كان هناك نقص، فتصفّحي وصفات الأطفال.'),
  ('c7f42861-81dc-4ed2-b93f-7c30709d92ed', 'هل تشعرين بالإنهاك؟ 🔋', 'هل نفدت طاقتكِ؟ لا تلجئي إلى الحلويات. أعيدي شحن طاقتكِ بتحضير كرات طاقة خالية من السكر وسريعة المفعول من قسم الوصفات الصحية للنساء.'),
  ('2ecfbac7-2e44-4661-8705-95fe2f59e9a9', 'تخلّي عن السعي إلى الكمال 🧘‍♀️', 'هل المنزل فوضوي؟ لا بأس! اكتبي مشاعركِ في يوميات المزاج. تذكّري أن الأم السعيدة أهم من المنزل المثالي.'),
  ('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1', 'أنتِ أيضًا بحاجة إلى استراحة ☕', 'اخرجي من المنزل والتقطي أنفاسكِ قليلًا! استخدمي قسم الأماكن الملائمة للأمهات للعثور على مقهى قريب يضم ركنًا للأطفال، واستمتعي بقهوتكِ الساخنة في هدوء.'),
  ('4bdcd931-fb36-41ca-9759-7a92226d97f9', 'كيف نعرف أن طفلكِ قد شبع؟ ⏱️', 'إذا بدأ برمي الطعام أو بصقه، فهذا يعني أنه شبع. أوقفي مؤقت التغذية، وسجّلي أنه تناول الكمية الموصى بها وحلّلي شهيته.'),
  ('be36c558-6f81-4ee5-9a59-f79497bbff2d', 'معركة تنظيف الأسنان 🪥', 'هل يهرب بمجرد رؤية فرشاة الأسنان؟ حوّلي هذه الخطوة المهمة للعناية بالنظافة إلى لعبة ممتعة بالاطلاع على فرش الأسنان الموسيقية أو فرش الأصابع ضمن المنتجات الموصى بها.'),
  ('cd9296b3-74e7-4229-8871-9f5ee4fe977a', 'توازن السوائل لدى الأم 💧', 'هل تعانين من الصداع؟ ربما أصابكِ الجفاف وأنتِ تركضين خلف طفلكِ. حضّري مياه الديتوكس من الوصفات الصحية للنساء لتنعشي جسمكِ.'),
  ('2fbfd933-5095-452a-808e-4209aab75b80', 'أنتِ أيضًا بحاجة إلى التواصل الاجتماعي 👯‍♀️', 'هل سئمتِ من التحدث مع طفلكِ فقط؟ ابحثي في قسم الأماكن الملائمة للأمهات عن مراكز تضم مجموعات للعب، وتعرّفي إلى أمهات أخريات.'),
  ('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc', 'المقلّد الصغير 📱', 'هل يتظاهر بالتحدث عبر الهاتف مثلكِ ويقلّد حركات يديكِ وجسمكِ؟ الأطفال مرآة تعكسنا بوضوح!'),
  ('bf157f3f-185f-45b5-aae0-091b2cf00653', 'معًا، ولكن كلٌّ على حدة 👶', 'ألا يلعب مع الأطفال الآخرين في الحديقة، بل يكتفي بمشاهدتهم؟ هذا هو اللعب المتوازي! اكتشفي في قسم المدوّنات حقائق شيقة عن هذه المرحلة من التطور الاجتماعي.'),
  ('9faf82e4-78ff-4782-a4bb-0d745a808c97', 'رفض اللون الأخضر 🥦', 'هل يرفض الخضراوات؟ اكتشفي ضمن وصفات الرضّع الذين بدأوا تناول الأطعمة التكميلية كيف يمكنكِ إخفاء الخضراوات داخل فطائر شهية.'),
  ('c2142ff9-9553-4737-9602-95ee907b4599', 'لا تستسلمي للإرهاق 🛋️', 'هل شعرتِ اليوم برغبة في ترك كل شيء؟ هذا طبيعي! افتحي يوميات المزاج، ودوّني ما يثقل صدركِ، وخصّصي هذا المساء لنفسكِ فقط.'),
  ('f9b61a4f-eba1-4cee-bf4a-958278a9300c', 'طاهي المنزل الصغير 👩‍🍳', 'هل يساعدكِ في المطبخ ويحرّك ما في القدور؟ زيّني هذه اللحظة الطريفة، وثيابه مغطاة بالدقيق، بملصقات الطاهي في جلسة تصوير الطفل.'),
  ('2c0cd78a-df37-49ab-8eae-44063551c7d9', 'خبير الأحجيات 🧩', 'هل أصبح بارعًا في مطابقة الأشكال؟ اكتشفي في قسم المنتجات الموصى بها الأحجيات الهندسية المخصصة للأطفال بعمر 21 شهرًا لتنمية ذكائه.'),
  ('eeefba30-2a67-4d29-87df-2dbd7f03271f', 'شغف بتمزيق الكتب 📖', 'هل يمزّق الصفحات بدلًا من القراءة؟ اقرئي الآن في قسم المدوّنات كيفية التعامل مع هذه المشكلة دون التأثير في عادة القراءة لديه.'),
  ('f7f548f7-29ae-4098-8eb1-12f16f94c4b9', 'مرحلة اللعب بالطعام 🥣', 'هل يرمي الملعقة جانبًا ويلمس الطعام بيديه؟ شغّلي مؤقت التغذية، وحلّلي تطور شهيته، وتعاملي بصبر مع هذه المرحلة من النمو الحسي.'),
  ('3512adbc-96b2-42e9-8a54-b673dc404876', 'ضحكات المساء 📸', 'لا تفوّتي تلك الحركة المضحكة التي يقوم بها قبل النوم! صوّري مقطع فيديو فورًا وأضيفيه إلى ألبوم الطفل لتحوّلي تعب اليوم إلى ابتسامة.'),
  ('42cda594-bd4d-4a45-a1f6-1f894ad11fe7', 'كلمات جديدة في الطريق! 🗣️', 'هل يصدر الكثير من الأصوات لكنه لا ينطق كلمات كاملة؟ تعرّفي عبر Anacan AI إلى أكثر الألعاب المنزلية وتمارين المقاطع فاعلية لتحويل مفرداته السلبية إلى مفردات نشطة.'),
  ('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54', 'هل أصبح حذاؤه ضيقًا؟ 👟', 'هل يتعثّر كثيرًا أثناء الركض مؤخرًا؟ ربما كبرت قدماه! أدخلي قياساته الحالية في متتبّع النمو لمتابعة تطوره.'),
  ('8ae66558-ee37-4cd1-9102-46bab1a97b21', 'وجبة شهية في 5 دقائق! 🥗', 'هل تتناولين وجبة خفيفة على عجل وقت الظهيرة؟ حضّري خبزًا محمّصًا بالأفوكادو من قسم الوصفات الصحية للنساء، ليمنحكِ الشبع والطاقة الفورية.'),
  ('a3eb6f02-e9da-422e-a243-1f395cf4661e', 'هل يتغيّر موعد النوم؟ ⏱️', 'هل طالت مدة بقائه مستيقظًا في المساء؟ فعّلي مؤقت النوم، وحلّلي الجدول لإعادة حساب فترات الاستيقاظ المناسبة بين أوقات النوم.'),
  ('aac102d8-edd5-4708-bab2-8cf3fcc9802c', 'هل تباطأت عملية الهضم؟ 🚽', 'راقبي براز طفلكِ عند تغيير حفاضه صباحًا. إذا كان يعاني من الإمساك، فلا تنسي تسجيل ذلك في التطبيق وإضافة أطعمة غنية بالألياف إلى قائمته، مثل الكمثرى والشوفان.'),
  ('5bf406ee-d6c9-4691-8b5e-2df617ed2939', 'استكشاف الطبيعة 🌳', 'هل أصبح المنزل ضيقًا عليه؟ ابحثي ضمن الأماكن الصديقة للأمهات عن حديقة آمنة تضم صندوق رمل واسعًا وأراجيح، واخرجا للاستمتاع بالهواء النقي.'),
  ('ad873c49-3118-429c-a9cf-3328699e514f', 'مغامرة المعكرونة! 🍝', 'ألا يريد الجلوس إلى مائدة الطعام؟ تصفّحي وصفات الأطفال لاكتشاف أفكار لمعكرونة ملوّنة بالخضراوات، وأعيدي جذب انتباهه إلى طبقه.'),
  ('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42', 'قوة الصوت الرتيب 🌬️', 'هل يخيفه الصمت؟ شغّلي من قسم الضوضاء البيضاء صوت مجفف الشعر أو المروحة في الغرفة، ولاحظي كيف يمنحه ذلك شعورًا بالأمان في بيئة النوم.'),
  ('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5', 'أثني على نفسكِ! 🌟', 'هل نجحتِ اليوم في إلباسه من دون أن يبكي؟ دوّني حتى أصغر إنجازاتكِ في يوميات المزاج، وصفّقي لنفسكِ بحرارة تقديرًا لمهاراتكِ كأم.'),
  ('5d85dda7-f62e-4490-8b4e-2ca037fd60ac', 'درع المناعة 🛡️', 'هل أنتِ مستعدة لتغيّر الفصول؟ استخدمي أداة متابعة التغذية للتحقق مما إذا كان طفلكِ قد حصل اليوم على ما يكفي من فيتامين C، وحدّثي قائمته الغذائية.'),
  ('680f971c-231a-40e8-a772-413975915698', 'الضرب والدفع 🛑', 'هل يضرب أو يدفع عند غضبه فجأة؟ اسألي Anacan AI عن كيفية التعامل مع هذا السلوك الصعب في عمر 21.5 شهرًا من خلال تحويله إلى لعبة.'),
  ('cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'هل تبقى الحفاضة جافة؟ 🧻', 'فحص الصباح! إذا ظلت الحفاضة جافة مدة طويلة، فقد اقترب وقت التدريب على استخدام النونية. سجّلي ذلك في متتبّع الحفاضات وراجعي الإحصاءات.'),
  ('3e9ffaf8-f631-4e99-946e-651b683eab7f', 'جمل «ماما، تعالي!» 🗣️', 'هل بدأ طفلكِ يحاول جمع كلمتين لتكوين جملة؟ إنها قفزة كبيرة في تطور اللغة! سجّلي جمَله القصيرة الأولى في متتبّع التطور لتبقى ذكرى جميلة.'),
  ('473def83-9d3b-4698-becd-a16f81aed11d', 'نوبات الغضب في المتجر 🛒', 'هل ألقى طفلكِ بنفسه على الأرض لأنكِ لم تشتري له ما أراد؟ لا تقلقي. تجاهلي نظرات الآخرين وانحني بهدوء لتصبحي في مستوى عينيه.'),
  ('fdbb311e-3b42-4723-986f-c65a632fb53e', 'تخلّصي من العبء العاطفي 📝', 'هل كان يومًا صعبًا؟ أفرغي ما بداخلكِ بكتابة ضغوط اليوم في يوميات الحالة المزاجية. جميع الأمهات يواجهن نوبات الغضب هذه أمام الناس، ولستِ وحدكِ.'),
  ('6b045729-7aac-44f1-99aa-a2dbeb7985f2', 'القائمة تنقذ يومكِ 🛒', 'هل خانتكِ ذاكرتكِ مجددًا؟ لا تحاولي تذكّر كل غرض صغير نفد من المنزل؛ أضيفيه فورًا إلى قائمة التسوق ودعي شريككِ يتولى الأمر.'),
  ('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba', 'ركل الكرة ⚽', 'هل يحاول طفلكِ ركل الكرة الموضوعة على الأرض بقدمه؟ يتطور توازنه وتناسق حركة ساقيه. العبي معه لعبة تمرير بسيطة.'),
  ('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1', 'أجواء ليلية ساحرة 🪄', 'هل يواجه طفلكِ صعوبة في النوم؟ أنشئي حكاية مبتكرة في قسم الحكايات الذكية واقرئيها له.'),
  ('51155148-f9ec-40a7-99a1-3f09cffe59c1', 'ساحة الأب 👨‍👧', 'هل نفد صبركِ؟ أغلقي باب الغرفة واتركي طفلكِ بمفرده مع والده. دعيه يتولى هذا المساء إدارة ساحة اللعب المنزلية.'),
  ('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739', 'العناد في اختيار الملابس 👗', 'هل يريد ارتداء كنزة سميكة في الصيف أو قميص صيفي في الشتاء؟ إرادته بدأت تتشكل. أخرجي قطعتين مناسبتين من الملابس واسأليه: أيهما تريد؟ ثم اتركي له حرية الاختيار.'),
  ('c6ce4007-ba3b-4772-8fba-7c4797ad17dd', 'الهواء النقي دواء 🌳', 'هل طفلكِ شديد الانزعاج ولا يطيق البقاء في المنزل؟ تحققي من الطقس وملابسه، ثم توجهي فورًا إلى الحديقة. فالطبيعة أسرع وسيلة لتهدئته.'),
  ('02902252-366d-405a-a62b-9c6f129b4a84', 'كيف يتطور الذكاء؟ 🧠', 'احرصي على قراءة المقال في قسم المدونات حول الألعاب المنزلية التي تحفز الدماغ وتعزز إدراك الألوان والأشكال لدى الأطفال بعمر 21.5 شهرًا.'),
  ('08bbbba1-9e53-4379-a09e-82d1079f7df6', 'فحص مخزون الحديد 🥩', 'يجب الوقاية من فقر الدم للحفاظ على نشاط العضلات. تحققي من كمية الحديد التي تناولها طفلكِ اليوم باستخدام أداة متابعة التغذية، وعوضي أي نقص فورًا.'),
  ('cd9b8bec-56d4-42a3-a245-f71b148a61ef', 'الانتقال من الضوضاء إلى الهدوء 🎶', 'قد يخيفه الصمت المفاجئ بعد الألعاب الصاخبة. شغّلي صوت مجفف الشعر من قسم الضوضاء البيضاء في الغرفة، ولاحظي التأثير الإيجابي للصوت الرتيب في نومه.'),
  ('54f26234-4c50-45b3-9088-6a5b0c08fcd2', 'توازن السوائل لدى الأم 💧', 'هل تعانين من الصداع؟ ربما أصابكِ الجفاف وأنتِ تركضين خلف طفلكِ. حضّري مياه الديتوكس من قسم الوصفات الصحية لتنعشي جسمكِ.'),
  ('a27861d3-4efc-4b58-bec5-f3117fe589e3', 'ألعاب التصنيف 🔴🔵', 'هل يحب جمع الأشياء الحمراء في جهة والزرقاء في جهة أخرى؟ اطلبي من ذكاء Anacan الاصطناعي أفكارًا لألعاب تجعل هذا التطور المنطقي أكثر متعة.'),
  ('d5617275-bfe2-4829-8f3f-d3b94dc34cfe', 'لنحلل الروتين ⏱️', 'هل طالت مدة بقائه مستيقظًا مساءً؟ شغّلي مؤقت النوم وتابعي الجدول. ربما حان الوقت تمامًا لتقليص قيلولته النهارية بمقدار 15 دقيقة.'),
  ('53a89401-1ea0-43b5-9469-65a0d422f72c', 'عرض لا ينتهي على المائدة 🥣', 'يلعب بالطعام ويرميه على الأرض، لكنه لا يأكل. شغّلي مؤقت التغذية وحلّلي تغيّرات شهيته بدقة من خلال الرسم البياني في التطبيق.'),
  ('86da0f7a-f021-4c65-aed2-e8e15433a92d', 'شغف التدوير 🌀', 'هل يدير العجلات أو الأغطية بلا توقف؟ اقرئي في المدونات عن هذه الحاجة الحركية المحددة ودورها في نموه المعرفي.'),
  ('9ea6bc21-5003-4afe-8fca-e2eebb549250', 'العلاج بالرمل 🏖️', 'لا تخافي من الاتساخ! ابحثي ضمن الأماكن الصديقة للأمهات عن مكان يحتوي على حوض للرمل. فملامسة الرمل ممتازة للنمو الحسي.'),
  ('081299bb-b5c9-4af5-8361-9fa39bbdf0bf', 'هل يعاني من الإمساك؟ 🚽', 'راقبي برازه عند تغيير حفاضه صباحًا. إذا كان يعاني من الإمساك، فسجّلي ذلك في التطبيق واختاري من وصفات الرضع الذين بدؤوا بتناول الأطعمة التكميلية أطعمة غنية بالألياف، مثل الكمثرى والشوفان.'),
  ('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb', 'الفنان منهمك في عمله 🎨', 'هل يلوّن نفسه أيضًا أثناء الخربشة؟ اطّلعي ضمن المنتجات الموصى بها على أكثر المنتجات التي تختارها الأمهات من الألوان الآمنة والقابلة للغسل.'),
  ('f9d59314-c8fe-45fa-9d77-efb82ec57626', 'ضحكات المساء 📸', 'لا تفوّتي تلك الحركة المضحكة التي يقوم بها قبل النوم!'),
  ('34d9fbb9-7747-4964-9067-399afa7f0a7c', 'مهدئ طبيعي 🍃', 'نام طفلكِ. انسي الأعمال المنزلية! حضّري شاي المليسة من وصفات النساء الصحية، واستلقي على الأريكة واستمتعي بالهدوء فحسب.'),
  ('e79393de-a250-4c25-b9a8-93a1bc3692aa', 'درع فيتامين C 🍊', 'يجب الحفاظ على مناعة قوية. استخدمي أداة متابعة التغذية لتحسبي ما إذا كان قد حصل اليوم على ما يكفي من فيتامين C، وأضيفي ألوانًا متنوعة إلى قائمته الغذائية.'),
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031', 'الاستيقاظ ليلًا ⏱️', 'شغّلي مؤقت النوم! حلّلي فورًا من الرسم البياني لإحصاءات المؤقت ما إذا كان طفلكِ يعاني من الذعر الليلي أو انتكاسة النوم.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'الحاجة إلى الحديد 🥩', 'غذّي عضلاته النشيطة! تحقّقي باستخدام أداة متابعة التغذية مما إذا كان قد حصل اليوم على ما يكفي من الحديد، وعدّلي قائمته الغذائية وفقًا لذلك.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'أصداء الضحكات 📸', 'هل يعبس بوجهه أم ينظر إليكِ ويقهقه؟ زيّني هذه اللحظة الجميلة بملصقات جلسة تصوير طفلكِ، وأضيفيها إلى الألبوم لتبقى ذكرى خالدة.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'قوة الرتابة 🎶', 'قد يخيفه الصمت المفاجئ بعد يوم صاخب. شغّلي صوت مجفف الشعر من قسم الضوضاء البيضاء لتمنحيه شعورًا بالأمان في بيئة نومه.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'بطارية الأم 🔋', 'هل نفدت طاقتكِ؟ لا تلجئي إلى الحلويات! حضّري من وصفات النساء الصحية سموذي بزبدة الفول السوداني، غنيًا بالبروتين ويمنحكِ دفعة فورية من الطاقة.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'هل ضاقت الملابس مجددًا؟ 📏', 'إنها طفرة في النمو الجسدي! أدخلي طوله الحالي ومقاس حذائه في متتبّع النمو، وشاهدي بفخر كيف يرتفع منحنى نموه.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'البحث عن المنطق 🧩', 'هل ملّ من ألعابه المعتادة؟ اكتشفي في قسم المنتجات الموصى بها أحاجي مناسبة لعمره وآمنة تساعد على تنمية ذكائه.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'الضرب والعضّ المفاجئان 🦖', 'هل يصبح عدوانيًا عندما يغضب؟ تعلّمي مع Anacan AI كيف تحوّلين هذا السلوك إلى لعبة وتغيّرينه بلطف.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'لعبة الخضراوات الخفية 🥕', 'هل يرفض الجزر والسبانخ؟ اكتشفي في وصفات الأطفال كيف يمكنكِ إخفاء هذه الفيتامينات بمهارة داخل فطائر لذيذة.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'لا تشعري بالذنب 💖', 'هل رفعتِ صوتكِ اليوم؟ لا تلومي نفسكِ. اكتبي مشاعركِ في يوميات المزاج، فأنتِ أفضل أم له مهما حدث.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'عرض لا ينتهي على مائدة الطعام ⏱️', 'هل يلعب بالطعام بدلًا من تناوله؟ شغّلي مؤقت التغذية، وتابعي مدة الوجبة، وحلّلي تطور شهيته بدقة.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'أنتِ بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها يوميًا هي ثمرة جهودكِ. افتحي يوميات المزاج واكتبي اليوم ملاحظة تستحقين عليها تصفيقًا حارًا!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'معًا، ولكن كلٌ على حدة 👶', 'هل يكتفي بمشاهدة الأطفال الآخرين في الحديقة ولا يلعب معهم؟ هذا هو اللعب المتوازي! اقرئي في قسم المدونات عن هذه المرحلة الصحية من التطور الاجتماعي.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'وجبة خفيفة بلا سكر 🍪', 'لا حاجة إلى البسكويت الجاهز من المتجر. اكتشفي في وصفات الأطفال حلويات صحية بالتمر والتفاح يمكنكِ تحضيرها في المنزل خلال 10 دقائق.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'هل تمتلئ حفاضات الليل؟ 🧻', 'إذا كانت الحفاضة ثقيلة جدًا في الصباح، فقد يتأثر نوم طفلكِ ليلًا. سجّلي الإخراج في متتبع الحفاضات، وحلّلي الإحصاءات لتنظيم تناوله للسوائل مساءً.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'مستكشف صغير في المطبخ 🥦', 'هل يريد أن يشارككِ الطهي؟ اكتشفي في قسم الوصفات وصفات سهلة ولذيذة لكعكات الخضراوات، يمكنكِ تحضيرها معه إذا كان قد بدأ بتناول الأطعمة التكميلية.'),
  ('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7', 'معركة ارتداء الملابس 👗', 'هل بدأ عناد «لا أريد هذا القميص!»؟ تعرّفي من Anacan AI إلى طرق الحد من أزمات اختيار الملابس صباحًا ومنح طفلكِ حرية الاختيار.'),
  ('2a640acf-5bf6-44d4-b56f-00e902c2ddd2', 'البحث عن الاستقلالية 🥣', 'ألا يعطيكِ الملعقة؟ شغّلي مؤقت التغذية وحلّلي الوقت الذي تستغرقه تجربة الاستقلالية هذه. وابتسمي فحسب للطعام المتناثر.'),
  ('cb94164a-0ea2-471c-9c17-a09778ea707c', 'الخوف من الانفصال؟ 🌌', 'هل يبكي خلفكِ بمجرد مغادرتكِ الغرفة؟ شغّلي صوت الرحم (نبضات القلب) من قسم الضوضاء البيضاء لتمنحيه ذلك الشعور القديم والدافئ بالأمان.'),
  ('d3ae908a-552f-4504-a171-436173eaeceb', 'معركة تنظيف الأسنان 🪥', 'هل يطبق فمه بمجرد رؤية الفرشاة؟ تصفّحي الفُرش الموسيقية أو فُرش الإصبع في قسم المنتجات الموصى بها، وحوّلي روتين النظافة هذا إلى لعبة ممتعة.'),
  ('4932b8a8-d024-498c-ba06-d790b59bc198', 'ارفقي بنفسكِ 🧘‍♀️', 'هل سارت الأمور كلها على نحو سيئ اليوم؟ اكتبي صوتكِ الداخلي في يوميات المزاج، وسامحي نفسكِ، وخذي نفسًا عميقًا واستريحي.'),
  ('ed014436-2469-48a6-b579-7bce93de1ae7', 'اتساع الحصيلة اللغوية 🗣️', 'هل بدأ طفلكِ يستخدم المزيد من الجمل المكوّنة من كلمتين؟ اسألي Anacan AI فورًا عن كيفية دعم هذا التطور اللغوي الرائع والتحاور معه.'),
  ('ed579060-f78c-4890-b8e4-2bb0c7729792', 'لون البراز 💩', 'سجّلي لونه عند تغيير الحفاض! استعيني بأداة متابعة التغذية لتتبّع توازن السوائل والألياف والوقاية من الإمساك.'),
  ('15f9bb81-a16f-4753-a3f5-a2b604b16a46', 'النوم في الهواء الطلق 🌳', 'ألا يستطيع النوم في المنزل؟ ابحثي في قسم الأماكن الصديقة للأمهات عن حديقة هادئة كثيرة الأشجار. سيساعد الهواء النقي على تحسين شهيته ونومه معًا.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('e02612f3-415f-450d-9411-e60c3bd32d09'::uuid, 'صوت الصمت 🌧️', 'بعد يوم حافل بالنشاط، يحتاج الدماغ إلى الهدوء. شغّلي صوت المطر من الأصوات البيضاء في الغرفة لتهيئة أجواء طبيعية وهادئة للنوم.'),
  ('3dca59c4-0add-4ccb-919d-3806c0dfdbf4', 'مهدّئ طبيعي 🍃', 'هل كان يومًا مليئًا بنوبات الغضب والضجيج؟ شغّلي صوت حفيف الأوراق من الأصوات البيضاء لتهدئة جهازه العصبي وجهازكِ العصبي معًا.'),
  ('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8', 'طاقة في 5 دقائق ⚡', 'لا تسارعي إلى الأعمال المنزلية صباحًا. حضّري شوفان التوت الغني بمضادات الأكسدة من الوصفات الصحية، وجدّدي نشاط جسمكِ.'),
  ('e5117ef0-d242-45f1-b114-50b3bfca72d9', 'أنتِ أيضًا بحاجة إلى التواصل الاجتماعي ☕', 'هل سئمتِ من التحدث مع طفلكِ فقط؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقاهي الأطفال التي ترتادها الأمهات بكثرة، واستمتعي بالتواصل الاجتماعي.'),
  ('622216cc-100d-4e85-95dc-7d70e41c5761', 'يريد أن يأكل بنفسه 🥣', 'ألا يعطيكِ الملعقة؟ شغّلي مؤقت التغذية وحلّلي المدة التي تستغرقها تجربة الاستقلال هذه. وابتسمي فحسب أمام الطعام المتناثر.'),
  ('9387504c-dde1-4fdb-977d-53c3dfbb83a2', 'استكشاف آمن ⚠️', 'الخزائن والأدراج... قد تكون خطرة على مستكشفكِ الصغير! اطّلعي ضمن المنتجات الموصى بها على واقيات الأثاث وأقفال الأمان.'),
  ('bdef77ef-7476-4b14-a4a3-51d31635951f', 'لنحلّل الروتين ⏱️', 'هل طالت مدة بقائه مستيقظًا مساءً؟ شغّلي مؤقت النوم. لعل الوقت قد حان لتقليل قيلولته النهارية بمقدار 15 دقيقة.'),
  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'آلام ظهر الأم 🧘‍♀️', 'هل يؤلمكِ ظهركِ من كثرة حمله؟ اعتني بجسمكِ بتحضير الشاي الأخضر بالزنجبيل المضاد للالتهاب والداعم للتعافي من الوصفات الصحية.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'معركة الكوب الخطأ؟ 🥤', 'هل ثارت ثائرته لأنكِ قدّمتِ له الماء في الكوب الأزرق بدلًا من الأحمر؟ اسألي Anacan AI فورًا عن كيفية التعامل بهدوء مع نوبات الغضب هذه التي تبدو غير منطقية.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'أفرغي ما في داخلكِ 📝', 'بكى اليوم بلا توقف وشعرتِ بإرهاق شديد. لا تلومي نفسكِ. دوّني كل ما تشعرين به من تعب في مفكرة المزاج، وأريحي ذهنكِ واستجمّي.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'دعيه يروي الحكاية 📖', 'هل ينظر إلى الصور في الكتاب ويروي أشياء بلغته الخاصة؟ أضيفي لحظة الخيال الرائعة هذه فورًا إلى ألبوم طفلكِ في مقطع فيديو بصوته، واحتفظي بها للمستقبل.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'تحرّرا من الجدران الأربعة 🌳', 'هل يعجز عن تفريغ طاقته في المنزل ويبعثر كل شيء؟ افتحي خريطة الأماكن الملائمة للأمهات، وابحثي عن حديقة تضم مساحة آمنة للركض، واخرجا لاستنشاق الهواء النقي.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'لا يريد المشاركة؟ 🧸', 'هل يرفض إعطاء ألعابه لأي شخص في الحديقة؟ احرصي على قراءة المقال العملي في قسم المدونات، الذي يعلّم الأطفال في عمر 22 شهرًا مفهوم تبادل الأدوار في اللعب.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'درع الكالسيوم 🦴', 'الكالسيوم ضروري للعظام والأسنان. استخدمي أداة متابعة التغذية للتأكد من حصوله اليوم على الكمية الموصى بها من الزبادي والجبن.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'هل حذاؤه ضيق؟ 📏', 'هل يتعثر كثيرًا أثناء الركض مؤخرًا؟ ربما كبرت قدمه! أدخلي طوله وقياساته الحالية في متتبّع الوزن لمتابعة نموه الجسدي.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'هل يرمي الطعام على الأرض؟ 🥣', 'إذا بدأ يرمي الملعقة والطعام من على الطاولة، فربما شبع أو شعر بالملل. أوقفي مؤقت التغذية، وحلّلي تغيّرات شهيته عبر الرسم البياني، ثم أنهي الوجبة.'),
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182', 'طاقة في ٥ دقائق ⚡', 'لا تتعجّلي في بدء الأعمال المنزلية صباحًا. حضّري شوفان التوت الغني بمضادات الأكسدة من قسم الوصفات الصحية للنساء، وجدّدي نشاط جسمكِ.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'الاستيقاظ ليلًا ⏱️', 'فعّلي مؤقت النوم! حلّلي بدقة مخطط إحصاءات المؤقت لمعرفة ما إذا كان طفلكِ يعاني من الذعر الليلي أو انتكاسة النوم، ثم اضبطي روتينه.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'تطوّر الذكاء لا يتوقف 🧠', 'يحب طفلكِ تصنيف كل شيء! اكتشفي الآن ضمن المنتجات الموصى بها ألعاب الألغاز الهندسية (puzzle) التي تعزز إدراك الألوان والأشكال وتحفّز الدماغ.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'أنتِ بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها طفلكِ يوميًا هي ثمرة جهودكِ. افتحي يوميات المزاج، واكتبي اليوم ملاحظة تجعلكِ تصفقين لنفسكِ بحرارة!'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'فنان غارق في الألوان! 📸', 'هل لوّن نفسه والجدار؟ بدلًا من الغضب، زيّني لحظة الشخبطة المضحكة هذه بالملصقات المرحة في جلسة تصوير الطفل، ثم حمّليها إلى الألبوم لتبقى ذكرى خالدة.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'هل يعاني من الإمساك؟ 💩', 'راقبي برازه عند تغيير حفاضه صباحًا. إذا كان يعاني من الإمساك، فسجّلي ذلك في التطبيق، واحرصي على إضافة الأطعمة الغنية بالألياف إلى قائمته باستخدام أداة متابعة التغذية.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'الشعور بالأمان 🌌', 'هل يخاف طفلكِ عند إطفاء ضوء الغرفة؟ شغّلي صوت الرحم (دقات القلب) من قسم الضوضاء البيضاء، لتمنحيه ذلك الشعور الدافئ والمألوف بالأمان وتهيّئيه للنوم.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'أنتِ أيضًا بحاجة إلى التواصل الاجتماعي ☕', 'هل سئمتِ من التحدث مع طفلكِ فقط؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقاهي الأطفال التي ترتادها الكثير من الأمهات، وامنحي نفسكِ فرصة للتعرف إلى محيط اجتماعي جديد.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'الخيال بلا حدود 🧸', 'هل يطعم دبدوبه أم يعالجكِ؟ أضيفي هذا التطور في قدرته على التعاطف إلى ألبوم طفلكِ في مقطع فيديو قصير، واصنعي ذكرى تدوم مدى الحياة.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'استكشافات آمنة ⚠️', 'الخزائن والأدراج... قد تكون خطرة على مستكشفكِ الصغير! احرصي على الاطلاع على واقيات الأثاث وأقفال الأمان في قسم المنتجات الموصى بها.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'تخلّصي من إرهاق اليوم 🛋️', 'لقد أرهقكِ الركض خلفه. نام طفلكِ الآن، فاكتبي كل ما يسبب لكِ التوتر في يوميات المزاج، ثم حضّري لنفسكِ كوبًا من شاي الأعشاب.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'هل ظهرت علامات الاستعداد لاستخدام النونية؟ 🚽', 'هل تبقى حفاضته جافة تمامًا في الصباح؟ قد يكون هذا الوقت المثالي لبدء التدريب. دوّني ذلك في متتبع الحفاضات، واطّلعي على مقالات الاستعداد في التطبيق.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'لا يريد تناول اللحم؟ 🥩', 'هل يحتاج إلى البروتين لكنه يرفض اللحم؟ جرّبي كرات الدجاج اللذيذة وسهلة المضغ من وصفات الأطفال، وسجّليها لاستكمال احتياجه في أداة متابعة التغذية.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'خطة للهروب من السرير 🏃‍♂️', 'هل يهرب من الغرفة عندما يحين موعد النوم؟ شغّلي مؤقت النوم، واختاري صوت حفيف الغابة من الأصوات البيضاء، وحوّلي الغرفة إلى كهف هادئ.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'عناد الصباح 🛑', 'لن أرتدي هذا، ولن آكل ذاك! هل تجعل نوبات الرفض صباحكِ أكثر صعوبة؟ اكتبي فورًا إلى Anacan AI لتتعرّفي على كيفية التعامل مع اختبار الحدود في هذه المرحلة العمرية.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'يقفز من الحائط إلى الأريكة! 🧗‍♂️', 'إنه مؤدّي حركات خطرة بحق! لمساعدته على تفريغ طاقته خارج المنزل، ابحثي في الأماكن الصديقة للأمهات عن مراكز تضم صالات لعب واسعة، ودعيه ينطلق بحرية.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'الضرب أو الدفع 🛑', 'هل يرفع يده فجأة عندما يغضب؟ استعيني بـ Anacan AI لتتعلمي كيف تحوّلين مشاعر الغضب الشديدة في هذا العمر إلى لعبة وتعدّلين هذا السلوك بلطف.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'قفزة في التفكير المنطقي 🧩', 'لقد بدأ يفهم العلاقة بين السبب والنتيجة. اقرئي في قسم المدونات عن أفضل الألعاب المنزلية التي تعزز التطور المعرفي لدى الأطفال بعمر 22 شهرًا، وطبّقيها.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'لنحلّل الروتين ⏱️', 'هل طالت مدة بقائه مستيقظًا مساءً أكثر من اللازم؟ شغّلي مؤقت النوم وتابعي الجدول. ربما حان الوقت تمامًا لتقليص قيلولته النهارية بمقدار 15 دقيقة.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'فحص مخزون الحديد 🥩', 'تحتاج العضلات النشطة إلى الوقاية من فقر الدم. تحققي من كمية الحديد التي تناولها اليوم باستخدام أداة متابعة التغذية، وعوّضي أي نقص فورًا.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'وجبة خفيفة بلا سكر 🍪', 'لا حاجة إلى بسكويت المتاجر. اكتشفي ضمن وصفات الأطفال حلويات صحية بالتمر والتفاح يمكن تحضيرها في المنزل خلال 10 دقائق، وشجّعيه على تناولها.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'قفزة في الطول! 📏', 'هل أصبحت أكمام قمصانه قصيرة مجددًا؟ إن نموه الجسدي يتسارع. أدخلي قياساته الحالية في متتبع النمو، وتأملي مخطط نموه بفخر.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'كلمات جديدة في الطريق! 🗣️', 'هل يصدر أصواتًا كثيرة لكنه لا ينطق كلمات كاملة؟ لتنشيط مفرداته الكامنة، أضيفي محاولاته الطريفة لنطق المقاطع كتسجيلات صوتية إلى ألبوم الطفل وتابعي تطورها.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'مساعد صغير في التنظيف 🧹', 'أصبح الآن يرغب في المشاركة في الأعمال المنزلية. اقرئي في قسم المدونات كيف تغرسين الشعور بالمسؤولية من خلال اللعب لدى طفلكِ بعمر 22.5 شهرًا، وطبّقي ذلك.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'تحفة فنية على الحائط 🎨', 'أمسك طفلكِ قلمًا ولوّن الحائط؟ لا تغضبي! أضيفي هذه المشاغبة اللطيفة إلى الألبوم باستخدام الإطارات المضحكة في جلسة تصوير الطفل، واكتفي بالابتسام.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'هل عادت الاستيقاظات المفاجئة؟ ⏱️', 'هل يستيقظ طفلكِ باكيًا في منتصف الليل؟ راجعي مخطط مؤقت النوم. إذا انتهت قيلولته متأخرة جدًا، فسيصعب عليه الدخول في نوم عميق مساءً.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'استراحة الأم لتناول القهوة ☕', 'لا تنسي نفسكِ! حضّري وجبة خفيفة بالشوفان تعزز طاقتكِ من قسم الوصفات الصحية للنساء، واستمتعي بقهوتكِ.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'اختيار القصرية المناسبة 🚽', 'حان وقت الاستعداد البصري للتدريب على استخدام المرحاض! لا تفوّتي الاطلاع في قسم المنتجات الموصى بها على أكثر موديلات القصرية راحة وجاذبية، والتي جرّبتها الأمهات.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'كيف هو مخزون أوميغا-3؟ 🐟', 'السمك أو الجوز ضروريان لنمو الدماغ السريع! تحققي من كمية أوميغا-3 التي تناولها طفلكِ هذا الأسبوع باستخدام أداة متابعة التغذية، وحدّثي قائمته الغذائية فورًا.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'لستِ مضطرة إلى أن تكوني مثالية 💖', 'ساد المنزلَ بعض الفوضى اليوم وتأخر الطعام؟ لا بأس! دوّني صوتكِ الداخلي في يوميات المزاج، وتذكري أن طفلكِ يحبكِ في جميع أحوالكِ.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'ماء أكثر، وهضم أسهل 💧', 'كيف تعمل أمعاء طفلكِ النشيط؟ سجّلي ملاحظاتكِ عند تغيير الحفاض. وإذا كان هناك خطر للإصابة بالإمساك، فاطّلعي في التطبيق على توصيات الأطعمة الطبيعية الغنية بالألياف.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'انتهت معركة الطعام ⏱️', 'هل يلقي طفلكِ الملعقة جانبًا على المائدة؟ أوقفي مؤقت التغذية، فقد شبع. حلّلي مخطط الشهية لتتجنبي إجباره على تناول الطعام.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'التعرّف إلى أمهات أخريات 👯‍♀️', 'دعي طفلكِ يلعب واستمتعي أنتِ بالدردشة! ابحثي في خريطة الأماكن الصديقة للأمهات عن مركز يضم مجموعات للعب واخرجي من المنزل.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'هل تُنظَّف الأسنان؟ 🪥', 'هل يطبق فمه فور رؤية الفرشاة؟ احصلي على نصائح عملية من Anacan AI لتتعلمي كيف تحوّلين روتين النظافة هذا إلى لعبة ممتعة.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'مهدّئ طبيعي 🍃', 'هل كان يومكِ صاخبًا جدًا؟ انتهى المؤقت. انسي الأعمال المنزلية، وحضّري شاي المليسة من قسم الوصفات الصحية، واستمتعي فقط بمذاق الهدوء.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'البحث عن حلوى صحية 🍎', 'وداعًا لبسكويت المتاجر! اكتشفي ضمن وصفات الأطفال بسكويتًا صحيًا بالتمر والتفاح، يمكنكِ تحضيره في المنزل خلال 10 دقائق، وافتحي شهية طفلكِ.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'هل عاد قلق الانفصال؟ 🌌', 'هل يبكي خلفكِ بمجرد خروجكِ من الغرفة؟ شغّلي صوت نبضات القلب من قسم الضوضاء البيضاء لتمنحيه شعورًا بالأمان وتهيّئيه للنوم.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'أصبح البنطال قصيرًا مجددًا! 📏', 'هل بدأت أكمام القمصان تضيق؟ إنها طفرة في النمو الجسدي. أدخلي القياسات الحالية في متتبّع الوزن، وانظري بفخر إلى مخطط النمو.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'نُطق طريف للكلمات 🗣️', 'ينطق بعض الكلمات بطريقة خاطئة ولطيفة للغاية! لا تفوّتي هذه اللحظات الثمينة. حمّليها إلى ألبوم طفلكِ على هيئة مقطع فيديو بالصوت، واضحكا عليها معًا في المستقبل.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'هل يحصل على ما يكفي من البروتين؟ 🍗', 'البروتين ضروري للعضلات النشطة. قيّمي توازن غذائه اليومي باستخدام أداة متابعة التغذية، وأثري قائمة طعامه.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'سأفعل ذلك بنفسي! 👕', 'هل يتحول ارتداء الملابس صباحًا إلى أزمة كبيرة؟ تعرّفي الآن من Anacan AI على أسرار التعامل مع العناد ومنح طفلكِ حق الاختيار.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'لنقرأ الكتاب بدلًا من تمزيقه 📖', 'هل يمزّق طفلكِ الصفحات في وقت حكاية المساء؟ اقرئي الآن في قسم المدونات كيف يمكنكِ حل هذه المشكلة دون الإضرار بعادة القراءة لديه.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'لنحلّل الروتين ⏱️', 'هل طالت مدة الاستيقاظ مساءً أكثر من اللازم؟ شغّلي مؤقت النوم وتابعي الجدول. ربما حان الوقت تمامًا لتقليل القيلولة النهارية بمقدار ١٥ دقيقة.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'العلاج بالرمل والطين 🏖️', 'لا تخافي من الاتساخ! اكتشفي الآن أفضل الأدوات للرمل الحركي أو الألعاب الحسية في قسم المنتجات الموصى بها.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'هذا ثمرة جهدكِ 🌟', 'كل مهارة جديدة يتعلمها طفلكِ يوميًا، وكل خطوة واثقة يخطوها، هي ثمرة جهدكِ. افتحي يوميات المزاج واكتبي اليوم ملاحظة تجعلكِ فخورة بنفسكِ!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'كم مرة قلتِ «لا» اليوم؟ 💆‍♀️', 'أنتِ متعبة جدًا، أليس كذلك؟ خذي نفسًا عميقًا. أفرغي كل مشاعركِ في يوميات المزاج، وضعي الشعور بالذنب جانبًا واستريحي فحسب.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'هل استيقظ بحفاض جاف؟ 🩲', 'هل لاحظتِ أن حفاض طفلكِ جاف عند تغييره صباحًا؟ اسألي Anacan AI الآن عن أنسب وقت لبدء التدريب على استخدام النونية والأساليب النفسية الصحيحة لذلك.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'حب الكعك 🧁', 'هل يشتهي طفلكِ الحلوى؟ لا تسرعي إلى المتجر. حضّري من وصفات الأطفال كعكًا منزليًا بالموز والشوفان ومن دون سكر خلال ١٠ دقائق، وحافظي على تقييم صحي مرتفع في أداة متابعة التغذية.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'معركة ارتداء الملابس! 👗', 'هل يتحول ارتداء الملابس صباحًا إلى أزمة كبيرة؟ امنحي طفلكِ حرية الاختيار بعرض قميصين مختلفين عليه.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'هل يفرك عينيه؟ 🥱', 'إنها إشارات النعاس! شغّلي مؤقت النوم، وساعديه على الاستعداد للنوم بهدوء عبر تشغيل حفيف الغابة من قسم الضوضاء البيضاء، وتابعي جدول نومه.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'حان وقت قهوة الأم ☕', 'حان وقت الاستراحة. بينما يلعب طفلكِ بمفرده، استعيدي نشاطكِ بكوب من الشاي الأخضر الغني بمضادات الأكسدة أو القهوة الخفيفة، من قسم الوصفات الصحية للنساء.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'هل يتسلق جدران المنزل؟ 🧗', 'لا بد من تفريغ طاقته! افتحي خريطة الأماكن الصديقة للأمهات، واكتشفي متنزهًا جديدًا يضم مساحة آمنة للجري وزحليقة، ودعيه يلعب بحرية.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'الهروب من المائدة! 🏃‍♂️', 'هل يترك طعامه في منتصف الوجبة ويهرب؟ أوقفي مؤقت التغذية. وبدلًا من إجباره على تناول الطعام، اقرئي في قسم المدونات أسرار تحفيز الشهية طبيعيًا.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'لماذا أصبح الحذاء ضيقًا؟ 👟', 'هل يتعثر كثيرًا أثناء الجري؟ ربما كبرت قدمه! أدخلي قياساته الحالية في متتبع النمو، وتحققي فورًا من طفرة النمو لتحليل تطوره.'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'هل يطابق الأشكال بشكل صحيح؟ 🧩', 'لدعم نموه المنطقي، ابحثي الآن في قسم المنتجات الموصى بها عن أحاجي الأشكال الهندسية المناسبة لعمره والألعاب الخشبية التعليمية.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'هل يحصل على ما يكفي من البروتين؟ 🥚', 'البروتين ضروري لعضلاته التي تنمو بسرعة. احسبي احتياجه اليومي باستخدام أداة متابعة التغذية، وعدّلي قائمة طعامه إذا كان هناك نقص.'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'البحث عن الأم المثالية 💖', 'هل ارتفع صوتكِ قليلًا اليوم؟ لا تشعري بالذنب. اكتبي مشاعركِ في مفكرة المزاج، فأنتِ بالفعل أفضل أم لطفلكِ.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'لنحلّل الروتين ⏱️', 'هل طالت فترة الاستيقاظ مساءً أكثر من اللازم؟ شغّلي مؤقت النوم وتابعي الجدول. ربما حان الوقت تمامًا لتقليل مدة القيلولة النهارية بمقدار 15 دقيقة.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'العلاج بالرمل والطين 🏖️', 'لا تخافي من الاتساخ! ابحثي ضمن الأماكن الصديقة للأمهات عن حديقة آمنة تضم مساحة رملية، ودعي طفلكِ يستمتع بالطبيعة لتنمية حواسه.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'أفضل صديق للحديد 🥩', 'فيتامين C ضروري لامتصاص الجسم للحديد! راجعي قائمة طعام اليوم باستخدام أداة متابعة التغذية، وأضيفي إلى اللحم سلطة غنية بعصير الليمون.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'هل لا يأكل سوى الخبز؟ 🍞', 'هل يبعد البروتينات والخضراوات ولا يريد سوى الكربوهيدرات؟ استخدمي أداة متابعة التغذية لحساب كمية الأطعمة المفيدة التي تناولها اليوم، واضبطي المقدار وفق احتياجاته.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'الرغبة في تمزيق الصفحات 📖', 'هل يحاول تمزيق صفحات الكتاب أثناء حكاية المساء؟ اقرئي في قسم المدونات كيف تتعاملين مع هذه المشكلة من دون التأثير سلبًا في عادة القراءة لديه.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'العضّ عند الغضب 🦖', 'هل يعض أصدقاءه أو يعضكِ عندما يغضب؟ اسألي فورًا مساعدنا الخبير Anacan AI عن كيفية التعامل مع هذا السلوك الصعب بحب.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'هل يؤلمكِ ظهركِ؟ 🧘‍♀️', 'ليس من السهل حمل صغيركِ الذي يزن 12+ kq مرارًا وتكرارًا. حضّري شاي الزنجبيل المضاد للالتهاب والمريح للعضلات من وصفاتنا الصحية للنساء، وخذي قسطًا من الراحة.'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'عضّات غاضبة 🦖', 'هل يعضّ أصدقاءه أو يعضّكِ عندما يغضب؟ اسألي مساعدنا الخبير Anacan AI الآن عن كيفية التعامل مع هذا السلوك الصعب بحب.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'هل يأكل الخبز فقط؟ 🍞', 'هل يرفض البروتينات والخضراوات ولا يريد سوى الكربوهيدرات؟ استخدمي أداة متابعة التغذية لحساب كمية الطعام المفيد التي تناولها اليوم وضبط الكمية وفق احتياجاته.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'شغف تمزيق الصفحات 📖', 'هل يحاول تمزيق صفحات الكتاب أثناء حكاية المساء؟ اقرئي في قسم المدوّنات كيفية التعامل مع هذه المشكلة من دون التأثير سلبًا في عادة القراءة لديه.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'تحفة فنية على الحائط 🎨', 'هل أمسك قلمًا ورسم على الحائط؟ لا تغضبي! أضيفي هذه الشقاوة اللطيفة إلى الألبوم باستخدام الإطارات المضحكة في جلسة تصوير الطفل، واكتفي بالابتسام.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'هل يؤلمكِ ظهركِ؟ 🧘‍♀️', 'ليس من السهل حمل صغيركِ الذي يزيد وزنه على 12 كغ باستمرار. حضّري من قسم الوصفات الصحية شاي الزنجبيل المضاد للالتهاب والمساعد على إرخاء العضلات، وخذي قسطًا من الراحة.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'خطة الهروب من السرير 🏃‍♂️', 'هل يتسلّق سريره ويخرج منه عندما يحين موعد النوم؟ شغّلي مؤقّت النوم واختاري من الأصوات البيضاء صوت القطار الرتيب لتهيئته للنوم بهدوء.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'هل ظهرت إشارات الاستعداد للنونية؟ 🚽', 'هل تبقى حفاضته جافة تمامًا في الصباح؟ قد يكون هذا الوقت المثالي لبدء التدريب على استخدام المرحاض. سجّلي ذلك في متتبّع الحفاضات واطّلعي في قسم المنتجات الموصى بها على خيارات النونية المريحة والمصممة بما يلائم جسم طفلكِ.'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'هل يريد اللعب بمفرده؟ 👶', 'هل يراقب الأطفال الآخرين من بعيد في الحديقة ولا ينضم إليهم؟ اكتشفي في قسم المدوّنات أكثر الحقائق العلمية تشويقًا عن اللعب المتوازي الصحي.'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'يهرب عند رؤية الخضراوات؟ 🥦', 'هل بدأ طفلكِ ينتقي الطعام حسب لونه؟ اكتشفي في وصفات الأطفال كيف تُخفين السبانخ والجزر بمهارة داخل فطائر لذيذة وتفتحين شهيته.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'الفنان الصغير منهمك في عمله 🎨', 'لا تنزعجي حتى لو تلطخت ملابسه بالألوان! زيّني هذه اللحظة الإبداعية فورًا بالملصقات المرحة في جلسة تصوير الطفل، وأضيفيها إلى الألبوم وابتسمي.'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'الضرب أو الدفع 🦖', 'هل يرفع يده فجأة أو يدفع أصدقاءه عندما يغضب؟ تعلّمي من الذكاء الاصطناعي في Anacan كيف تتعاملين بلطف مع المشاعر العدوانية التي تظهر في هذا العمر.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'عظامه تزداد قوة 🦴', 'يتطلب النمو السريع الكالسيوم. استخدمي أداة متابعة التغذية للتأكد من حصوله اليوم على الكمية المناسبة من الجبن والزبادي، واستكملي أي نقص.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'مهدئ طبيعي 🍃', 'هل كان يومكِ صاخبًا للغاية؟ انتهى المؤقت. انسي الأعمال المنزلية، وشغّلي صوت خرير الشاي من قسم الأصوات البيضاء، ثم استلقي على الأريكة واسترخي.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'الكتب للقراءة لا للتمزيق 📖', 'هل يمزق الصفحات أثناء حكاية المساء؟ اقرئي الآن في قسم المدونات كيف تعالجين هذه المشكلة من دون الإضرار بعادة القراءة لديه.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'عرض لا ينتهي في السرير 🛌', 'هل يقفز على السرير بدلًا من النوم؟ شغّلي مؤقت النوم وتابعي الجدول. حلّلي ما إذا كان لم يفرغ طاقته بالكامل أم أنه مُجهد أكثر من اللازم.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'معركة تنظيف الأسنان 🪥', 'هل يطبق فمه فور رؤية الفرشاة؟ تصفحي الفُرش الموسيقية أو فُرش الأصابع في قسم المنتجات الموصى بها، واكتشفي كيف تحوّلين هذا الروتين الضروري إلى لعبة ممتعة.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'أولى المحادثات الجدية 🗣️', 'هل يناقش طفلكِ معكِ أمورًا كثيرة ومطوّلة بلغته الخاصة؟ احفظي هذه اللحظة الطريفة التي لا تُقدّر بثمن في ألبوم طفلكِ على شكل فيديو بالصوت.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'نوبات صراخ مفاجئة! 🛑', 'هل يرتمي طفلكِ على الأرض عندما لا يحصل على ما يريد؟ اسألي مساعدنا الخبير بالذكاء الاصطناعي من Anacan عن طرق لتحويل هذه النوبات الانفعالية، التي تزداد قرب الشهر 23، إلى لعبة.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'لا تدعيه ينسى شرب الماء 💧', 'كيف تعمل أمعاء طفلكِ الصغير كثير الحركة؟ سجّلي برازه عند تغيير الحفاض. وإذا كان هناك خطر للإصابة بالإمساك، فاحرصي على الاطلاع على توصيات التطبيق بشأن الأطعمة الطبيعية الغنية بالألياف.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'هل يخاف من الظلام؟ 🌌', 'هل يبكي طفلكِ عندما تطفئين ضوء الغرفة؟ شغّلي له صوت الرحم (دقات القلب) من قسم الأصوات البيضاء، وامنحيه ذلك الشعور القديم بالأمان التام.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'حافظي على طاقتكِ الصباحية ⚡', 'لا تبدئي يومكِ على معدة فارغة! اعتني بنفسكِ واختاري من وصفات النساء الصحية كعكة شوفان شهية ومشبعة يمكن تحضيرها في 5 دقائق.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'أنتِ أيضًا بحاجة إلى صديقات 👯‍♀️', 'هل تعبتِ من التحدث مع طفلكِ فقط؟ ابحثي في الأماكن الصديقة للأمهات عن مراكز تضم مجموعات للعب، وتواصلي مع أمهات أخريات وتبادلي معهن الخبرات.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'هل أصبحت القيلولة أقصر؟ ⏱️', 'هل استغرق طفلكِ وقتًا طويلًا لينام ليلًا؟ شغّلي مؤقت النوم وتابعي الجدول. ربما حان الوقت المناسب لتقليل مدة القيلولة بمقدار 15-20 دقيقة.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'أنتِ بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها طفلكِ، وكل خطوة واثقة يخطوها، هي ثمرة جهودكِ. افتحي مفكرة المزاج واكتبي اليوم ملاحظة ملهمة تجعلكِ فخورة بنفسكِ!'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'تحفة فنية على الحائط 🎨', 'أمسك قلمًا ولوّن الحائط؟ لا تغضبي! أضيفي هذه المشاغبة اللطيفة إلى الألبوم باستخدام الإطارات المضحكة في جلسة تصوير طفلكِ، واكتفي بالابتسام.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'خطة للهروب من السرير 🏃‍♂️', 'هل يتسلق سريره ويخرج منه عندما يحين موعد النوم؟ شغّلي مؤقت النوم، واختاري صوت القطار الرتيب من «الضوضاء البيضاء» لتهيئته للنوم بهدوء.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'القفز بكلتا القدمين 🦘', 'هل يحاول القفز بكلتا قدميه في الوقت نفسه وهو واقف على الأرض؟ يبدو مضحكًا جدًا، أليس كذلك؟ احرصي على تخليد هذه اللحظة.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'سكينة على أنغام الموسيقى 🎶', 'أسهل طريقة لتهدئة نوبات التذمر في أواخر النهار هي تشغيل لحنه المفضل واحتضانه والرقص معه ببطء.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'يرفض النوم؟ 🥱', 'هل يرفض أخذ قيلولته ويقاوم النوم؟ اطلبي من Anacan AI معلومات دقيقة وجدولًا روتينيًا لمواعيد النوم المناسبة مع اقترابه من عمر 2 سنوات.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'البحث عن حلوى صحية 🍎', 'وداعًا لبسكويت المتاجر! اكتشفي ضمن وصفات الأطفال حلويات صحية بالتمر والتفاح تُحضَّر في المنزل خلال 10 دقائق، وشجّعي طفلكِ على تناول الطعام.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'معركة تنظيف الأسنان 🪥', 'هل يطبق فمه فور رؤية الفرشاة؟ احصلي على نصائح عملية من Anacan AI لتتعلمي كيفية تحويل هذا الروتين الصحي المهم إلى لعبة ممتعة.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'طريقة نطق مضحكة 🗣️', 'إنه ينطق بعض الكلمات بطريقة خاطئة ولطيفة جدًا! لا تفوّتي هذه اللحظات الثمينة. حمّليها إلى ألبوم طفلكِ كمقطع فيديو بالصوت، واضحكا عليها معًا في المستقبل.'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'هل بقيتِ في المنزل لأن الطقس متقلب؟', 'دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح والملابس المناسبة، وانطلقي إلى الحديقة بثقة.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'الأضراس الأخيرة؟ 🦷', 'هل يقضم كل شيء بلا سبب وأصبح أكثر عدوانية؟ قد تكون الأضراس الخلفية في طريقها إلى الظهور. سجّلي تطور العملية في متتبع التسنين، وجهّزي عضّاضات باردة.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'بطل الحكاية 🪄', 'أنشئي هذا المساء في «الحكايات الذكية» قصة مميزة يكون طفلكِ بطلها: صغير شجاع يحب تنظيف أسنانه.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'خصصي وقتًا لنفسكِ 🛋️', 'لقد أرهقكِ الركض خلفه. نام طفلكِ الآن، فاكتبي كل ما يسبب لكِ التوتر في «مفكرة الحالة المزاجية»، واسكبي لنفسكِ كوبًا من شاي المليسة.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'هل هو جائع أم عطشان؟ 💧', 'يُخلط أحيانًا بين العطش وفقدان الشهية. تحققي من سجلات الإخراج في متتبع الحفاضات لتتأكدي فورًا من أن طفلكِ يحصل على ما يكفي من السوائل.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'المغني الصغير 🎤', 'هل يغني الأغنية نفسها بلا توقف؟ يساعد ذلك على تنمية إحساسه بالإيقاع وتطور مهاراته اللغوية.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'الخيال لا يعرف حدودًا 🧸', 'هل يطعم دبه أم يتظاهر بعلاجكِ؟ تصفحي «المنتجات الموصى بها» للعثور على أطقم الطبيب أو المطبخ التي تدعم هذا التطور الرائع في التعاطف.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'هل عاد قلق الانفصال؟ 🌌', 'هل يبكي خلفكِ بمجرد مغادرتكِ الغرفة؟ شغّلي صوت نبضات القلب من «الضوضاء البيضاء» لتمنحيه شعورًا بالأمان وتساعديه على الاستعداد للنوم.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'السراويل أصبحت قصيرة مجددًا! 📏', 'هل بدأت أكمام القمصان تضيق؟ إنها طفرة في النمو الجسدي. أدخلي القياسات الحالية في متتبّع النمو وشاهدي مخطط النمو بفخر.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'مخزون الأم من البروتين ⚡', 'ليس من السهل الركض خلف طفلكِ كثير الحركة. حضّري سموذي غنيًا بالبروتين والفواكه من قسم الوصفات الصحية للنساء، واستعيدي طاقتكِ.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'سأفعل ذلك بنفسي! 👕', 'هل يتحول ارتداء الملابس صباحًا إلى أزمة كبيرة؟ تعرّفي فورًا من Anacan AI إلى أسرار التعامل مع العناد ومنح طفلكِ حق الاختيار.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'كيف نعرف أنه شبع؟ ⏱️', 'إذا بدأ طفلكِ برمي الطعام أو بصقه، فهو يخبركِ بأنه شبع. أوقفي مؤقت التغذية، وسجّلي أنه تناول الكمية المعتادة، ثم حلّلي شهيته.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'حب الكتب 📖', 'هل يجلب طفلكِ كتاب الحكايات المفضل لديه ويجلس في حضنكِ؟ هذا يعني أن مدة انتباهه تزداد. اقرئي معه وسمّيا الأشياء التي تظهر في الصور.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'هل بدأت المخاوف؟ 👻', 'هل أصبح طفلكِ يخاف الآن من المكنسة الكهربائية رغم أنه لم يكن يخاف منها من قبل؟ مع تطور الخيال قد تظهر مخاوف غير مبررة. احتضنيه وأخبريه بأنه بأمان.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'الحاجة إلى الهواء الطلق 🌳', 'هل طفلكِ شديد التململ ولا يطيق البقاء في المنزل؟ تحققي من الطقس والملابس وتوجهي فورًا إلى الحديقة. فالطبيعة أسرع وسيلة لتهدئته.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'أنتِ أيضًا بحاجة إلى صديقات 👯‍♀️', 'هل تعبتِ من التحدث مع طفلكِ وحده؟ ابحثي في الأماكن الصديقة للأمهات عن المراكز التي تضم مجموعات للعب، وتواصلي مع أمهات أخريات وتبادلن الخبرات.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'متسلّق الأريكة! 🧗', 'هل المشي فوق الأثاث هوايته المفضلة؟ زيّني استعراضه الحركي الجريء والمضحك بالملصقات المرحة في جلسة تصوير الطفل، ثم حمّليه إلى الألبوم.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'هل نفدت طاقة الأم؟ 🔋', 'هل تكادين تغفين واقفةً عند الظهيرة؟ حضّري من قسم الوصفات الصحية للنساء سموذي زبدة الفول السوداني الغني بالبروتين، ليمنحكِ دفعة فورية من الطاقة من دون الحاجة إلى الكافيين.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'هل كان كل شيء صعبًا اليوم؟ 💆‍♀️', 'هل سمعتِ صراخًا وبكاءً متواصلين؟ خذي نفسًا عميقًا، وتوقفي عن لوم نفسكِ، فأنتِ رائعة!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'هل كل أواني المطبخ على الأرض؟', 'اللعب بالأغراض الآمنة ينمّي تفكيره المنطقي. دعيه يستكشف كنوزه بحرية.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'الحاجة إلى الهدوء 🤫', 'النصف ساعة الأول بعد خلوده إلى النوم هو الوقت الأكثر حساسية. تحققي من مستوى الديسيبل في المكان باستخدام مقياس الصوت، وتجنّبي الضوضاء المفاجئة.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'وهم المثالية 🛋️', 'لا تلومي نفسكِ عند رؤية الأمهات اللواتي يبدون سعيدات دائمًا على وسائل التواصل الاجتماعي. فتعبكِ وغرفتكِ غير المرتبة جزء طبيعي تمامًا من الواقع.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'من الكلمات إلى الجمل 🗣️', 'هل بدأ بالفعل بتكوين جمل طريفة من 3 كلمات؟ سجّلي هذه القفزة اللغوية الرائعة وطريقته اللطيفة في النطق في مقطع فيديو بالصوت، واحتفظي به للمستقبل.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'الصفحات تنبض بالحياة 📖', 'هل يقلّد أصوات الحيوانات في الكتاب عندما تقرئين له قصة؟ احرصي على قراءة تقنيات القراءة التفاعلية التي تدعم نمو خياله في قسم المدونات.'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'مساعدكِ الصغير في التنظيف 🧹', 'أصبح طفلكِ يرغب في المشاركة في الأعمال المنزلية. اقرئي في قسم المدونات كيف تغرسين الشعور بالمسؤولية لدى طفل في عمر السنتين تقريبًا من خلال اللعب، ثم طبّقي ما تعلّمتِه.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'افتخري بنفسكِ! 🌟', 'كل مهارة جديدة يتعلمها طفلكِ يوميًا، وكل خطوة واثقة يخطوها، هي ثمرة جهودكِ. افتحي يوميات المزاج واكتبي اليوم ملاحظة ملهمة تجعلكِ فخورة بنفسكِ!'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'مهمة الخضراوات السرية 🥦', 'هل يدفع الطبق بعيدًا بمجرد أن يرى البروكلي؟ اكتشفي في وصفات الأطفال كيف تُخفين هذه الفيتامينات بمهارة داخل فطائر لذيذة وتفتحين شهيته.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'اللعب لا ينتهي ⏱️', 'هل يركض ويختبئ بدلًا من الذهاب إلى السرير؟ شغّلي مؤقت النوم واختاري صوت أمواج المحيط من قسم الضوضاء البيضاء لتحوّلي الغرفة إلى كهف هادئ للنوم.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'هل يستيقظ مبكرًا جدًا؟ 🌅', 'هل يستيقظ قبل شروق الشمس مفعمًا بالطاقة؟ احصلي الآن على نصائح من مساعدنا الخبير Anacan AI لتعرفي كيف تنقلين مواعيد نومه واستيقاظه إلى ساعات أكثر ملاءمة.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'ألعاب المنطق 🧩', 'هل يضع الألعاب في الصندوق ثم يفرغه بالكامل؟ هكذا يتكوّن لديه مفهوم الداخل والخارج. سجّلي هذه المهارة المعرفية في متتبّع التطور.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'العناد في اختيار الحذاء 👟', 'هل يُصرّ عند الخروج على ارتداء حذائه الشتوي في الصيف؟ اسمحي له أحيانًا باتخاذ خياراته بنفسه، فهذا يقوّي إرادته.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'لديكِ سؤال؟ 🤖', 'هل تخيفكِ المعلومات التي قرأتِها عن أزمات عمر السنتين؟ لا تتوّهي بين صفحات الإنترنت؛ اكتبي مباشرةً إلى Anacan AI وتعلّمي كيف تتجاوزين هذه المرحلة بسهولة أكبر.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'سحر الرتابة 🌬️', 'هل يزعجه الصمت المفاجئ بعد إطفاء التلفاز؟ شغّلي صوت المروحة أو مجفف الشعر من قسم الضوضاء البيضاء، ولاحظي كيف يمنحه شعورًا بالأمان في بيئة نومه.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'فن الأيدي الملطخة بالألوان 🎨', 'هل لطّخ وجهه بالكامل أثناء اللعب بالألوان؟ بدلًا من الانزعاج، التقطي فورًا صورة لهذه اللحظة الطريفة والمبدعة، وأضيفيها إلى الألبوم بوصفها أجمل ذكرى ملوّنة.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'طقوس الليل 🧸', 'هل ينام كل مساء وهو يعانق اللعبة نفسها؟ خلّدي لحظة الأمان الجميلة هذه بكتابتها كوصف فقط، من دون صورة، في قسم الملاحظات بألبوم طفلكِ.'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'محاولات الصداقة الأولى 👶', 'هل يُبدي اهتمامًا بلعبة طفل آخر في الحديقة ويُصدر أصواتًا؟ اكتشفي كيفية دعم هذه المرحلة من التطور الاجتماعي عبر التحدث مع أمهات أخريات في الأماكن الصديقة للأمهات.'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'الطبيب الصغير منهمك في عمله 🩺', 'هل يعطي دُبّه حقنة أو يفحص بطنه؟ بلغ اللعب التخيلي ذروته! اقرئي في قسم المدونات عن التأثير المذهل لألعاب تقمّص الأدوار في تنمية الذكاء.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'هل استيقظ وحفاضه جاف تمامًا؟ 🩲', 'هل لاحظتِ أن حفاضه جاف عند تغييره صباحًا؟ هذه إحدى أهم علامات استعداده الجسدي لاستخدام القصرية! سجّلي ذلك في متتبّع الحفاضات وراقبي الإحصاءات بعناية.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'من دون سكر، لكنه حلو 🍪', 'هل يرغب في وجبة خفيفة بعد الظهر؟ لا حاجة إلى بسكويت المتاجر. اكتشفي ضمن وصفات الأطفال حلويات صحية بالتمر والشوفان يمكن تحضيرها في 10 دقائق.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'لنحلّل روتينه بالكامل ⏱️', 'هل استغرق النوم مساءً 40 دقيقة؟ راجعي الرسم البياني لمؤقّت النوم. ربما حان الوقت تمامًا لتقصير قيلولته النهارية 20 دقيقة وتقديم موعد نومه مساءً.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'دفعة من الطاقة 💥', 'لم تعد جدران المنزل الأربعة تتسع لكل هذا الركض. افتحي خريطة الأماكن الصديقة للأمهات، واعثري على حديقة آمنة ذات أرضية لينة وزحلوقة كبيرة، ودعي طفلكِ ينطلق بحرية.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'سأنظف أسناني بنفسي! 🪥', 'هل يأخذ طفلكِ فرشاة الأسنان منكِ محاولًا تنظيف أسنانه بنفسه، لكنه لا ينظفها فعليًا؟ ابحثي الآن ضمن المنتجات الموصى بها عن فرش موسيقية ومريحة التصميم تجعل هذه العملية أسهل.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'شرب السوائل والإمساك 💧', 'هل يركض طفلكِ كثيرًا ولا يشرب ما يكفي من الماء؟ راقبي برازه عند تغيير الحفاض. إذا كان هناك خطر للإصابة بالإمساك، فسجّلي ذلك في التطبيق وأضيفي فورًا أطعمة غنية بالألياف باستخدام أداة متابعة التغذية.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'اختبار الصبر على المائدة 🥣', 'هل يلعب طفلكِ بالطعام ويتسبب في فوضى في كل مكان؟ شغّلي مؤقت الوجبات، وحلّلي نمط شهيته عبر الرسم البياني، وتابعي بدقة المدة التي تستغرقها الوجبة.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'الرغبة في رمي كل شيء على الأرض 🛑', 'هل يلوّح طفلكِ بما في يده ثم يرميه عندما يغضب أو يشعر بالملل؟ اسألي Anacan AI عن كيفية توجيه هذه الاستجابات العاطفية بلطف.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'القمصان أصبحت قصيرة! 📏', 'هل لاحظتِ عند إلباس طفلكِ أن الأكمام أصبحت ضيقة؟ مع اقترابه من عمر سنتين، يمر طفلكِ بطفرة في النمو الجسدي! أدخلي قياس طوله الحالي في متتبع النمو، وتأملي منحنى نموه بفخر.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'شاي ساخن وهدوء 🍵', 'توقف المؤقت ونام طفلكِ. لا تسارعي إلى القيام بالأعمال المنزلية! حضّري شاي المليسة من قسم الوصفات الصحية للنساء، وسجّلي إنجازاتكِ الصغيرة لهذا اليوم في مفكرة الحالة المزاجية.'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'قوة الحديد 🥩', 'حتى لا يُصاب طفلكِ النشيط بفقر الدم ويحافظ على طاقته، تحققي من كمية الحديد التي تناولها اليوم عبر أداة متابعة التغذية، وعدّلي قائمته الغذائية إذا كان هناك نقص.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'أزمات الصباح 👗', 'هل يجعل إصرار طفلكِ قائلًا: «لا أريد هذا الحذاء!» صباحكِ أكثر صعوبة؟ تعرّفي من Anacan AI إلى أكثر الأساليب النفسية فاعلية لمنحه حرية الاختيار عبر تقديم بدائل له.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'مخزون الأم من البروتين ⚡', 'ليس من السهل الركض خلف طفلكِ كثير الحركة. لا تستنزفي طاقتكِ! حضّري من الوصفات الصحية سموذي غنيًا بالبروتين والفاكهة لاستعادة نشاطكِ.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'مهدّئ طبيعي 🍃', 'هل كان يومًا حافلًا بالضجيج والركض؟ لقد توقّف المؤقّت. خفّفي إضاءة الغرفة، وشغّلي خرير الماء من الأصوات البيضاء لتهدئة ذهن طفلكِ وذهنكِ معًا.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'معركة الاستقلالية! 👕', 'هل يريد طفلكِ ارتداء ملابسه بنفسه ويرفض مساعدتكِ؟ اسألي فورًا مساعدنا الخبير Anacan AI عن كيفية تحويل هذا العناد إلى نمو صحي.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'فحص مخزون الحديد 🥩', 'حتى لا يُصاب طفلكِ النشيط بفقر الدم، تحقّقي من كمية الحديد التي تناولها اليوم، مثل اللحوم والبقوليات، باستخدام أداة متابعة التغذية، وحدّثي قائمة طعامه.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'التهدئة الليلية 🎶', 'ألا يتعب طفلكِ من الركض ويرفض الذهاب إلى السرير؟ شغّلي مؤقّت النوم، واختاري صوت أمواج المحيط من الأصوات البيضاء لتهيئة أجواء هادئة ومناسبة للنوم في الغرفة.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'دعيه يروي الحكاية 📖', 'هل ينظر طفلكِ إلى صور الكتاب ويتحدث عنها بلغته الخاصة؟ سجّلي لحظة الخيال الرائعة هذه فورًا في مقطع فيديو بالصوت، وأضيفيها إلى ألبوم الطفل للاحتفاظ بها للمستقبل.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'مساحة آمنة للركض 🏃‍♀️', 'ألا يستطيع طفلكِ تفريغ طاقته داخل المنزل فيبعثر كل شيء؟ افتحي خريطة الأماكن الملائمة للأمهات، وابحثي عن متنزه يوفر مساحة آمنة للركض، واخرجا للاستمتاع بالهواء النقي.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'معركة الكوب الخطأ؟ 🥤', 'هل قامت القيامة لأنكِ قدّمتِ الماء في الكوب الأزرق بدلًا من الأحمر؟ تعلّمي من Anacan AI كيف تتعاملين بهدوء مع نوبات الغضب التي تبدو غير منطقية.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'الاستيقاظ ليلًا ⏱️', 'شغّلي مؤقت النوم! حلّلي بدقة الرسم البياني لإحصاءات المؤقت لمعرفة ما إذا كان طفلكِ يعاني من الذعر الليلي أو تراجع النوم، ثم عدّلي روتينه.'),
  ('91af8067-4bf1-4cab-af7f-58a96c7e04b3', 'أنتِ أيضًا بحاجة إلى استراحة ☕', 'اخرجي من المنزل والتقطي أنفاسكِ قليلًا! استخدمي «الأماكن الصديقة للأمهات» للعثور على مقهى قريب يضم ركنًا للأطفال، واستمتعي بقهوتكِ الساخنة في هدوء.'),
  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'هل يعاني طفلكِ من الإمساك؟ 🚽', 'راقبي برازه عند تغيير حفاض الصباح. إذا كان يعاني من الإمساك، فسجّلي ذلك في التطبيق، ثم أضيفي الأطعمة الغنية بالألياف فورًا باستخدام أداة متابعة التغذية للحفاظ على التوازن الغذائي.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'نوبة غضب بسبب الشاشة 📱', 'هل يرمي طفلكِ نفسه على الأرض عندما تأخذين الهاتف منه؟ تعلّمي من Anacan AI كيف تحدّين من وقت الشاشة دون توتر وتضعين حدودًا صحية.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'أنتِ بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها طفلكِ يوميًا هي ثمرة جهدكِ. افتحي «مذكرات المزاج» واكتبي اليوم ملاحظة تستحقين أن تصفّقي لنفسكِ من أجلها!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'معركة تنظيف الأسنان 🪥', 'هل يهرب طفلكِ بمجرد أن يرى فرشاة الأسنان؟ تصفّحي في «المنتجات الموصى بها» فراشي الأسنان الموسيقية أو الدوّارة للأطفال، وحوّلي هذه الخطوة الأساسية للنظافة إلى لعبة ممتعة.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'مهدّئ طبيعي 🍃', 'هل كان يومًا حافلًا بالضجيج والركض؟ لقد توقّف المؤقت. خفّفي إضاءة الغرفة، وشغّلي صوت خرير النهر من «الضوضاء البيضاء» لتمنحي ذهن طفلكِ وذهنكِ استرخاءً عميقًا.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'قفزة منطقية 🧩', 'بدأ طفلكِ يفهم العلاقة بين السبب والنتيجة. اقرئي في قسم المدوّنات عن أفضل الألعاب المنزلية التي تعزّز التطور المعرفي لدى الأطفال في عمر السنتين تقريبًا، وجرّبيها معه.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'درع الكالسيوم 🦴', 'الكالسيوم ضروري للأسنان والعظام. استخدمي أداة متابعة التغذية للتأكد من حصول طفلكِ اليوم على الكمية المناسبة من الزبادي والجبن.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'وحش البان كيك 🥞', 'هل يرفض تناول الإفطار؟ اطّلعي على وصفة البان كيك الخالي من السكر والمحضّر بالموز في قسم وصفات الأطفال. سيتمكن من إمساكه وتناوله بنفسه، كما سيساعد على تحفيز شهيته.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'اختبار الصبر على المائدة 🥣', 'هل يلعب بالطعام ويُحدث فوضى في كل مكان؟ شغّلي مؤقت التغذية، وحلّلي تطور شهيته عبر الرسم البياني، وتابعي بدقة المدة التي تستغرقها الوجبة.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'العلاج بالرمل والطين 🏖️', 'لا تخافي من الاتساخ! اكتشفي الآن أفضل الأدوات للرمل الحركي أو الألعاب الحسية في قسم المنتجات الموصى بها.'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'فن تفريغ الطاقة 🧗', 'لم تعد جدران المنزل تتسع لطاقته. افتحي خريطة الأماكن الملائمة للأمهات، وابحثي عن مكان يضم منطقة لعب آمنة بأرضية لينة، حيث يمكنه القفز والركض.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'شهية انتقائية 🥦', 'هل لا يريد سوى المعكرونة أو الخبز؟ حلّلي قائمته الغذائية باستخدام أداة متابعة التغذية، وعوّضي الفيتامينات الناقصة بحصص شهية ومبتكرة من قسم وصفات الأطفال.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء الساطعة والشاشات في المنزل قبل موعد النوم بساعة واحدة. لا يُفرز الميلاتونين إلا في بيئة هادئة وخافتة الإضاءة.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'ألعاب ذكية 🧩', 'يحتاج عقل طفلكِ في عمر 2 سنة إلى ألعاب تعليمية، لا إلى ألعاب تُصدر أصواتًا فحسب. اكتشفي في المنتجات الموصى بها أحاجي خشبية تنمّي التفكير المنطقي.'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'تحضير كعكة خالية من السكر 🎂', 'تحتاجين إلى كعكة صحية لمناسبة الغد المميزة! اكتشفي ضمن وصفات الأطفال وصفات كعك بالفواكه، خالية من السكر المكرر ومناسبة تمامًا للأطفال.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'مصدر طاقة الأم 🥗', 'لا تنسي إعادة شحن طاقتكِ! حضّري من الوصفات الصحية سموذي غنيًا بالبروتين وزبدة الفول السوداني يمنحكِ طاقة فورية.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'أصبح عمره رسميًا 2 سنة! 🎈', 'عامان من الجهد المتواصل والحب والليالي بلا نوم. دوّني في يوميات المزاج مدى فخركِ بكل يوم من هذه الأيام الـ730. أنتِ حقًا أم رائعة!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'لقد نجحتِ 🥂', 'عامان من التفاني! إذا نام طفلكِ، فاتركي الأعمال المنزلية. افتحي يوميات المزاج، واكتبي لنفسكِ رسالة شكر، ثم استريحي فحسب.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', 'مرحلة العناد في عمر 2 سنة؟ 🌪️', 'هل ازدادت كلمة «لا» ونوبات الصراخ؟ احصلي فورًا من Anacan AI على أساليب لإدارة نوبات الانفعال، كي تتجاوزي هذه المرحلة الشائعة بهدوء.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'لا يريد الجلوس إلى المائدة 🥣', 'هل يملّ سريعًا من الطعام ويهرب؟ شغّلي مؤقت التغذية، وسجّلي مدة الوجبة، وتجنّبي تمامًا إجباره على تناول الطعام.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'الحاجة إلى الهدوء 🤫', 'بعد ضوضاء الأمس، حافظي على هدوء الغرفة باستخدام مقياس الصوت. فتقطّع النوم ليلًا يفسد مزاجه ومزاجكِ معًا.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'فوضى ما بعد عيد الميلاد 🌪️', 'هل يعمّ المنزلَ الدمار بعد حفلة الأمس؟ لا تتعجّلي التنظيف. خصّصي هذا اليوم للراحة برفقة طفلكِ الذي أتمّ عامه الثاني للتو.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'فنان الطبيعة 🍂', 'اخرجا من المنزل! أوراق الشجر والحجارة في الحديقة من أفضل المواد لتحفيز الحواس. ابحثي ضمن الأماكن الصديقة للأمهات عن مكان ذي مساحة خضراء واسعة.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'ماء وفير، وهضم أسهل 💧', 'هل ينسى شرب الماء لكثرة ركضه؟ دوّني ملاحظة الصباح في متتبّع الحفاضات، وحلّلي فورًا توازن السوائل والألياف للوقاية من خطر الإمساك.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'عادة حكاية المساء 📖', 'هل يعيد سرد الحكاية التي قرأتِها بكلماته الخاصة؟ سجّلي هذه القفزة اللغوية الرائعة فورًا في مقطع فيديو بالصوت، وأضيفيه إلى ألبوم طفلكِ للاحتفاظ به للمستقبل.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', 'مرحلة «إنها لي!» 🧸', 'هل يرفض مشاركة لعبته في الحديقة ويصرخ؟ تعلّمي من Anacan AI كيفية التعامل مع تمركز الطفل حول ذاته في عمر السنتين بطريقة صحية، من دون أن يتحول إلى سلوك عدواني.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'قوة مضادة للالتهاب 🍵', 'هل يؤلمكِ ظهركِ وذراعاكِ من حمل طفلكِ؟ حضّري شاي الزنجبيل والليمون من بين الوصفات الصحية للنساء لمساعدة جسمكِ على التعافي.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'لنحلّل الروتين ⏱️', 'هل طالت فترة بقائه مستيقظًا في المساء؟ شغّلي مؤقّت النوم وتابعي الجدول. ربما حان الوقت لتقليل قيلولته النهارية بمقدار 20 دقيقة!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'يواصل التقليد 🦜', 'عندما تتحدثين عبر الهاتف، هل يمسك هو أيضًا جهاز التحكّم عن بُعد ويضعه على أذنه؟ إنه يقلّدكِ بنسبة 100%! حاولي أن تكوني قدوة حسنة له.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', 'قوة كلمة «لا» 🛑', 'عندما تعرضين عليه شيئًا، يهز رأسه ويقول لا! هذا ليس عنادًا، بل طريقة للتعبير عن رأيه. هدّئيه من خلال منحه خيارات.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'لحظات الأب المرحة 🤡', 'أفضل طريقة لإضحاك طفلكِ هي أن يصدر والده أصواتًا غريبة. استمتعي معه بلحظات المرح هذا المساء.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'من دون سكر، لكنه لذيذ 🥞', 'هل يشتهي الحلوى؟ لا تذهبي إلى المتجر. جرّبي وصفات البان كيك بالموز والتفاح ضمن وصفات الأطفال، فهي تُحضَّر في 10 دقائق فقط وستفتح شهيته.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'معركة فرشاة الأسنان 🪥', 'هل أصبح تنظيف أسنانه معركة كبيرة؟ تصفّحي في المنتجات الموصى بها فُرَش الأسنان الموسيقية أو المزيّنة بشخصياته الكرتونية المفضلة، وحوّلي الأمر فورًا إلى لعبة.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'مهدّئ طبيعي 🍃', 'هل كان يومًا حافلًا بالضجيج والركض؟ حان وقت التوقف. خفّفي إضاءة الغرفة، وشغّلي صوت خرير الجدول من قسم الضوضاء البيضاء، وامنحي ذهنكِ بعض الاسترخاء أيضًا.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'درع الحديد 🥩', 'هل انخفضت طاقته أم أنه متعب فحسب؟ استخدمي أداة متابعة التغذية للتحقق من كمية الحديد التي تناولها اليوم، مثل اللحوم والبقوليات، وعوّضي أي نقص فورًا.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'بدأت لعبة الطبيب 🩺', 'هل يعطي دبدوبه حقنة؟ بلغت ألعاب التخيّل ذروتها. التقطي هذه اللحظة الجميلة عبر جلسة تصوير طفلكِ واحتفظي بها كذكرى لا تُنسى.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'أنتِ أيضًا بحاجة إلى استراحة ☕', 'ابتعدي عن طفلكِ للحظة وخذي نفسًا عميقًا! ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى يضم ركنًا للأطفال، واستمتعي بقهوتكِ الساخنة في هدوء.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'درع الحديد 🥩', 'لحماية طفلكِ النشيط من فقر الدم والحفاظ على طاقته، اكتشفي في وصفات الأطفال كرات اللحم اللذيذة بالخضراوات وسهلة المضغ، وساعديه على فتح شهيته.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'شغف تمزيق الصفحات 📖', 'هل يمزق طفلكِ صفحات الكتاب بدلًا من قراءته؟ اسألي Anacan AI الآن عن كيفية التعامل مع هذه المشكلة دون التأثير في عادة القراءة لديه.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', 'طاقة في 5 دقائق ⚡', 'هل تكادين تغفين وأنتِ واقفة عند الظهيرة؟ حضّري من قسم الوصفات الصحية للنساء شوفانًا بالتوت، غنيًا بمضادات الأكسدة ويمنحكِ طاقة فورية، وجدّدي نشاط جسمكِ.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'من الكلمات إلى الجمل 🗣️', 'هل بدأ طفلكِ بتكوين جمل طريفة من 3-4 كلمات؟ اقرئي في قسم المدونات عن أفضل الألعاب المنزلية وتمارين المقاطع الصوتية التي تدعم هذه الطفرة اللغوية الرائعة.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'وقت التدليك 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي مع شريككِ تدليك الكتفين للتخلص من توتر اليوم. أنتما فريق واحد!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'قيادة سيارة خيالية 🚗', 'هل يمسك طفلكِ صندوقًا فارغًا أو لعبة ويديرها كأنها مقود ويصدر أصواتًا؟ إن قدرته على اللعب التخيلي تتطور على أكمل وجه!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'فضفضة الأمهات 💬', 'هل يرهقكِ التفكير: لماذا يتصرف طفلي هكذا؟ انضمي إلى مجتمع Anacan واقرئي تجارب مماثلة لأمهات أخريات.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'مخزون الكالسيوم 🦴', 'الكالسيوم ضروري للأسنان والعظام. استخدمي أداة متابعة التغذية للتحقق من تناولكِ الكمية الموصى بها اليوم من الزبادي والجبن، واستكملي ما ينقصكِ.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'خطة الهروب من السرير 🏃‍♂️', 'هل يهرب ويختبئ عندما يحين موعد النوم؟ فعّلي مؤقت النوم، وشغّلي أصوات الغابة من قسم الضوضاء البيضاء، وحوّلي الغرفة إلى كهف هادئ.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'من اللعب المتوازي إلى اللعب معًا 👶', 'يزداد اهتمامه باللعب مع الأطفال الآخرين في المكان نفسه. اكتشفي في قسم المدونات أسرار تنمية المهارات الاجتماعية لدى الأطفال بعمر سنتين وسيكولوجية اللعب في الحديقة.'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'رفض ارتداء الملابس 👗', 'هل يبكي قائلًا: «لا أريد هذا البنطال!»؟ تعرّفي من Anacan AI إلى طرق الحد من أزمات ارتداء الملابس صباحًا ومنحه حرية الاختيار.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'الطاهي الصغير منهمك في العمل 👨‍🍳', 'هل يساعدكِ في المطبخ ويعجن العجين؟ سجّلي هذه اللحظة الطريفة، بينما يغطيه الدقيق من رأسه إلى قدميه، في مقطع فيديو بالصوت لتصنعي ذكرى تدوم مدى الحياة.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'نوبة صراخ في المتجر 🛒', 'هل ارتمى على الأرض في مكان عام لأنكِ لم تشتري له ما أراده؟ تجاهلي نظرات الآخرين وتحدّثي مع Anacan AI لتعرفي كيف تتعاملين بهدوء مع أزمات عمر السنتين.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'هل قضيتِ ليلة بلا نوم؟ ☕', 'هل استنزف الاستيقاظ ليلًا طاقتكِ؟ استعيدي نشاطكِ بتحضير سموذي غني بالبروتين مع زبدة الفول السوداني، يمنحكِ دفعة فورية من الطاقة من دون الحاجة إلى الكافيين، ضمن الوصفات الصحية للنساء.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'الاستيقاظ المفاجئ 🌌', 'هل يستيقظ باكيًا في منتصف الليل ولا يهدأ؟ راسلي خبير Anacan AI لتفهمي الفرق بين الفزع الليلي والكوابيس وتعرفي كيفية التدخل بالشكل الصحيح.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'وداعًا لمعركة فرشاة الأسنان 🪥', 'هل يطبق فمه بمجرد رؤية فرشاة الأسنان؟ ابحثي فورًا في قسم المنتجات الموصى بها عن موديلات موسيقية ومريحة تجعل العملية أسهل، وحوّلي هذا الروتين إلى لعبة.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', 'إصرار «سآكل بنفسي» 🥦', 'يريد طفلكِ أن يأخذ الملعقة من يدكِ. دعيه يأخذها. ستتسخ ملابسه، لكن شعوره بالاستقلالية مهم جدًا له.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'أنتِ بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها يوميًا، وكل خطوة يخطوها باستقلالية، هي ثمرة جهودكِ.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'ألعاب ذكية 🧩', 'عقل الطفل في عمر 2 عام يحتاج إلى ألعاب تعليمية، لا ألعاب تُصدر أصواتًا فحسب. اكتشفي في المنتجات الموصى بها الأحجيات الخشبية وألعاب الأشكال التي تنمّي التفكير المنطقي.'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'هل يعاني من الإمساك؟ 🚽', 'هل ينسى شرب الماء لانشغاله بالركض؟ راقبي برازه عند تغيير الحفاض. إذا كان معرّضًا للإمساك، فسجّلي ذلك في التطبيق وأضيفي فورًا أطعمة غنية بالألياف باستخدام أداة متابعة التغذية.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'لنحلّل روتينه ⏱️', 'هل استغرق نومه مساءً 40 دقيقة؟ اطّلعي على مخطط مؤقت النوم. ربما حان الوقت تمامًا لتقليل قيلولته النهارية بمقدار 20 دقيقة وتقديم موعد نومه مساءً.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'بلا سكر، لكنه حلو 🍪', 'هل يريد وجبة خفيفة بعد الظهر؟ لا حاجة إلى البسكويت الجاهز من المتجر. حضّري من وصفات الأطفال حلوى صحية بالتمر والشوفان في 10 دقائق.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'تعابير وجه مضحكة 🤪', 'هل يصنع طفلكِ وجوهًا مضحكة أمام المرآة؟ لا تفوّتي هذه اللحظة الممتعة! زيّني الصورة فورًا بالإطارات المرحة في جلسة تصوير الطفل، ثم أضيفيها إلى الألبوم.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'أنتِ أيضًا بحاجة إلى استراحة ☕', 'اخرجي من المنزل واستنشقي بعض الهواء! ابحثي في الأماكن الملائمة للأمهات عن مقهى قريب يضم ركنًا للأطفال، واستمتعي بقهوتكِ الساخنة وتعرّفي إلى أمهات أخريات.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'الطبق ذو اللون الخطأ! 🎨', 'هل دخل طفلكِ في نوبة غضب لأنكِ قدّمتِ الطعام في طبق أحمر بدلًا من الأخضر؟ اقرئي النصائح في قسم المدونات لتتعلمي كيفية التعامل مع عناده غير المنطقي في هذا العمر.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'آلام ظهر الأم 🧘‍♀️', 'هل يؤلمكِ ظهركِ من حمل طفلكِ الذي يزن 13+ kq؟ اعتني بنفسكِ وحضّري شاي الزنجبيل الذي يساعد على إرخاء العضلات، من قسم الوصفات الصحية للنساء.'),
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696', 'المقلّد الصغير 📸', 'هل يتحدث طفلكِ بالهاتف مثلكِ أو يقلّد حركاتكِ؟ زيّني هذه اللحظة الطريفة بالملصقات المرحة في جلسة تصوير الطفل، ثم أضيفيها إلى الألبوم.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'شغف رمي كل شيء على الأرض 🛑', 'هل يقذف طفلكِ ما في يده عندما يغضب أو يشعر بالملل؟ اقرئي مقالات قسم المدونات لتتعلمي كيفية توجيه ردود الفعل العاطفية هذه بلطف.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'فن الأيدي الملطخة بالألوان 🎨', 'هل لطّخ طفلكِ وجهه بالكامل أثناء اللعب بالألوان؟ بدلًا من الانزعاج، التقطي فورًا صورة لهذه اللحظة المرحة والمبتكرة، وأضيفيها إلى ألبوم الطفل بوصفها أكثر الذكريات تنوعًا بالألوان.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'مهدّئ طبيعي 🍃', 'توقف المؤقت. نام الطفل. كافئي نفسكِ! حضّري شاي المليسة من قسم الوصفات الصحية للنساء، واستلقي على الأريكة واستمتعي بالهدوء بعد هذا اليوم المتعب.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', 'سأغتسل بنفسي! 🧽', 'هل يأخذ طفلكِ الفرشاة أو المنشفة من يدكِ في الحمّام؟ ابحثي في قسم المنتجات الموصى بها عن مستلزمات استحمام آمنة للأطفال تدعم سعيه إلى الاستقلالية.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', 'طاقة في 5 دقائق ⚡', 'هل أنهككِ الركض؟ استعيدي نشاطكِ بتحضير سموذي زبدة الفول السوداني الغني بالبروتين، الذي يمنحكِ طاقة فورية، من قسم الوصفات الصحية للنساء.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'أنتِ بطلة اليوم 🌟', 'كل مهارة جديدة يتعلمها طفلكِ يوميًا هي ثمرة جهودكِ.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'توازن فيتامين C 🍊', 'يجب الحفاظ على قوة المناعة. استخدمي أداة متابعة التغذية لحساب ما إذا كان طفلكِ قد حصل اليوم على ما يكفي من فيتامين C، وعدّلي قائمة طعامه وفقًا لذلك.'),
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45', 'مرحلة «لماذا؟» التي لا تنتهي 🤔', 'ما هذا؟ لماذا هو هكذا؟... لقد بدأ طفلكِ يستكشف العالم بالأسئلة! أجيبيه بصبر، فهذه هي اللحظات التي تحتفل فيها الخلايا العصبية في دماغه.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'اكسري دائرة السعي إلى الكمال 🛑', 'لم يأخذ طفلكِ قيلولته اليوم والبيت في فوضى عارمة؟ لا بأس! خذي نفسًا عميقًا، فلا يمكنكِ السيطرة على كل شيء في الوقت نفسه. دعي الأمور تسير ببساطة.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'هل نفد صبركِ؟', 'أغلقي باب الغرفة واتركي طفلكِ مع والده. دعيه يتولى هذا المساء إدارة ساحة اللعب المنزلية.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'هل تشعرين أن جدران المنزل تضيق عليكِ؟', 'اكتشفي ضمن الأماكن الصديقة للأمهات مقهًى يضم ركنًا لألعاب الأطفال. دعي طفلكِ يلعب واستمتعي أنتِ بقهوتكِ.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'سأرتدي ملابسي بنفسي 👕', 'لا تعيقي محاولات طفلكِ لارتداء ملابسه، حتى لو حاول وضع سرواله على رأسه. فرغبته في الاستقلال بلغت ذروتها! سجّلي هذا الانتصار الصغير في متتبع النمو.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'سكينة مع الموسيقى 🎶', 'أسهل طريقة لتهدئة نوبات التذمر في آخر النهار هي تشغيل لحن يحبه طفلكِ، ثم احتضانه والرقص معه ببطء.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'تحليل روتين النوم ⏱️', 'هل يتقلّب كثيرًا في السرير مساءً؟ راجعي مخطط مؤقت النوم. لعل الوقت قد حان لتقليل قيلولته النهارية بمقدار 20 دقيقة وتقديم موعد نومه مساءً.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'خلفية الهدوء الساحرة 🌊', 'هل كان يومًا حافلًا بنوبات الغضب والضجيج؟ شغّلي صوت أمواج المحيط من «الضوضاء البيضاء» لتهدئة جهازه العصبي وجهازكِ العصبي معًا.')
) AS v(id, t, b)
WHERE x.id = v.id;
